window.HOLUS_DATA=window.HOLUS_DATA||{};window.HOLUS_DATA["ap"]={"id":"ap","num":6,"name":"Anatomy & Physiology","area":"Body systems","lessons":[{"n":1,"title":"The Human Body","kicker":"Lesson 1 of your course, built from Chapter 1 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"70–85 minutes","steps":[{"id":"ap1-1","chapter":"Anatomy, physiology and pathology","title":"Anatomy, physiology and pathology","teach":["Anatomy is the study of the body’s structure: what the parts are and how they’re organized. Physiology is the study of what those parts do and how they do it. Pathology is the study of the body’s diseases.","Anatomy and physiology are hard to separate. Your mouth is a good example: teeth break food down mechanically (structure doing a job), the tongue tastes and moves food, and saliva contains enzymes that start breaking complex carbohydrates into simple sugars.","People have studied the body for a long time. Leonardo da Vinci was the first to draw the whole skeleton correctly, Andreas Vesalius wrote a book on the human body, and William Harvey worked out how blood circulates."],"keyPoints":["Anatomy = structure","Physiology = function","Pathology = disease"],"mnemonic":{"cue":"Anatomy is what it IS, physiology is what it DOES","explanation":"Ask \"what is it made of and where is it?\" for anatomy, and \"what does it do?\" for physiology."},"act":{"type":"sort","prompt":"Sort each statement into the right field of study.","categories":["Anatomy","Physiology","Pathology"],"items":[{"label":"The heart has four chambers","category":0,"feedback":"That describes structure, so it’s anatomy."},{"label":"The heart pumps blood to the lungs and body","category":1,"feedback":"That describes what the heart does, so it’s physiology."},{"label":"How a heart attack damages heart muscle","category":2,"feedback":"That’s about disease, so it’s pathology."},{"label":"The femur is the longest bone in the body","category":0,"feedback":"Size and shape are structure: anatomy."},{"label":"Saliva enzymes break starch into sugars","category":1,"feedback":"That’s a process, so it’s physiology."},{"label":"What happens to bones in osteoporosis","category":2,"feedback":"That’s a disease, so it’s pathology."}]}},{"id":"ap1-2","chapter":"Anatomic position","title":"Anatomic position","teach":["To keep everyone using the same language, scientists use four reference systems: directions, planes, cavities and structural units.","All of them assume the body is in anatomic position: standing upright and facing forward, arms at the sides, palms and feet facing forward. Even if a patient is lying down, you describe locations as if they were standing this way."],"goodToKnow":"\"Left\" and \"right\" always mean the patient’s left and right, not yours.","act":{"type":"choice","prompt":"Which describes anatomic position?","options":[{"label":"Standing upright, facing forward, arms at the sides, palms facing forward","correct":true,"feedback":"Right. Palms forward is the detail people often miss."},{"label":"Standing upright, arms at the sides, palms facing the thighs","correct":false,"feedback":"Close, but in anatomic position the palms face forward."},{"label":"Lying on the back, arms by the sides","correct":false,"feedback":"That’s lying down. Anatomic position is standing and facing forward."}]}},{"id":"ap1-3","chapter":"Directional terms, part 1","title":"Directional terms, part 1","teach":["Superior means above (the head is superior to the neck). Inferior means below (the foot is inferior to the ankle).","Anterior means toward the front; ventral, the belly side, means the same thing. Posterior means toward the back; dorsal, the back side, means the same thing. The esophagus is posterior to the trachea.","Cephalad or cranial means toward the head, so it’s another word for superior. Caudal means toward the tail, and is sometimes used for inferior. Humans only have a tail as embryos."],"visual":{"kind":"hub","title":"Pairs of opposites","items":[{"label":"Superior / inferior","detail":"Above / below"},{"label":"Anterior / posterior","detail":"Front / back (ventral / dorsal)"},{"label":"Cephalad / caudal","detail":"Toward the head / toward the tail"},{"label":"Medial / lateral","detail":"Toward the midline / toward the side"},{"label":"Proximal / distal","detail":"Near / far from the point of attachment"}]},"act":{"type":"choice","prompt":"The vertebral column is ______ to the digestive tract.","options":[{"label":"Posterior (dorsal)","correct":true,"feedback":"Right. The spine sits behind the gut."},{"label":"Anterior (ventral)","correct":false,"feedback":"Anterior means in front. The spine is behind the gut."},{"label":"Superior","correct":false,"feedback":"Superior means above. Here the spine is behind, not above."}]}},{"id":"ap1-4","chapter":"Directional terms, part 2","title":"Directional terms, part 2","teach":["Medial means closer to the midline of the body: the nose is medial on the face, and the ulna is on the medial side of the forearm. Lateral means toward the side: the ears are lateral, and the radius is lateral to the ulna.","Proximal means near the point of attachment or origin. Distal means away from it. These are used mostly for limbs: the elbow is proximal to the wrist, and the wrist is distal to the elbow."],"mnemonic":{"cue":"Proximal = proximity, distal = distance","explanation":"Proximal parts are close to where the limb joins the trunk; distal parts are a long distance from it."},"act":{"type":"sort","prompt":"Pick the right term for each statement.","categories":["Proximal","Distal","Medial","Lateral"],"items":[{"label":"The knee, compared with the ankle","category":0,"feedback":"The knee is closer to the hip, where the leg attaches."},{"label":"The fingers, compared with the wrist","category":1,"feedback":"Fingers are farther from the shoulder attachment."},{"label":"The nose on the face","category":2,"feedback":"The nose sits on the midline."},{"label":"The radius, compared with the ulna","category":3,"feedback":"The radius is on the thumb side, away from the midline."},{"label":"The ears on the face","category":3,"feedback":"The ears are toward the sides."},{"label":"The wrist, compared with the elbow","category":1,"feedback":"The wrist is farther from the attachment, so it’s distal."}]}},{"id":"ap1-5","chapter":"Body planes","title":"Body planes","teach":["Planes are imaginary flat surfaces passing through the body. They’re most useful when describing dissections or scans.","A midsagittal (median) plane divides the body down the middle into equal left and right halves. Any sagittal plane runs parallel to it and divides the body into unequal left and right parts.","A horizontal or transverse plane divides the body into superior and inferior portions. A frontal or coronal plane divides it into anterior and posterior portions, at right angles to the sagittal plane.","When an organ is cut, a cut along its long axis is a longitudinal section, and a cut across it is a transverse or cross section."],"visual":{"kind":"flow","title":"Three planes","items":[{"label":"Sagittal (midsagittal)","detail":"Left and right parts. Midsagittal gives equal halves."},{"label":"Frontal (coronal)","detail":"Front (anterior) and back (posterior) parts."},{"label":"Transverse (horizontal)","detail":"Upper (superior) and lower (inferior) parts."}]},"act":{"type":"choice","prompt":"A CT scan slice that separates the chest from the abdomen is cut along which plane?","options":[{"label":"Transverse (horizontal)","correct":true,"feedback":"Right. It splits the body into upper and lower parts."},{"label":"Frontal (coronal)","correct":false,"feedback":"A frontal plane splits front from back."},{"label":"Midsagittal","correct":false,"feedback":"A midsagittal plane splits left from right."}]}},{"id":"ap1-6","chapter":"The dorsal cavity","title":"The dorsal cavity","teach":["The body has two major cavities, the dorsal cavity and the ventral cavity. The organs inside any cavity are called the viscera.","The dorsal cavity holds the nervous system organs that coordinate the body. It has two parts: the cranial cavity, which holds the brain, and the spinal cavity, which holds the spinal cord."],"act":{"type":"choice","prompt":"The spinal cord sits in the:","options":[{"label":"Spinal cavity, part of the dorsal cavity","correct":true,"feedback":"Right. The dorsal cavity is the cranial cavity plus the spinal cavity."},{"label":"Thoracic cavity, part of the ventral cavity","correct":false,"feedback":"The thoracic cavity holds the heart and lungs."},{"label":"Abdominopelvic cavity","correct":false,"feedback":"That holds digestive, urinary and reproductive organs."}]}},{"id":"ap1-7","chapter":"The ventral cavity","title":"The ventral cavity","teach":["The ventral cavity holds organs that keep the internal environment steady (homeostasis). Its first part is the thoracic cavity, surrounded by the rib cage.","Inside the thoracic cavity, the heart sits in the pericardial sac (the pericardial cavity) and each lung is covered by a pleural membrane (the pleural cavities). Between the two pleural cavities is the mediastinum, which holds the heart, thymus, lymph and blood vessels, trachea, esophagus and nerves.","The diaphragm separates the thoracic cavity from the abdominopelvic cavity. That second part holds the kidneys, stomach, liver and gallbladder, small and large intestines, spleen, pancreas, and in women the ovaries and uterus.","Parietal refers to the wall of a cavity (the parietal peritoneum lines the abdominal wall). Visceral refers to the covering of an organ (the visceral peritoneum covers the abdominal organs)."],"visual":{"kind":"flow","title":"Cavities of the body","items":[{"label":"Dorsal cavity","detail":"Cranial cavity (brain) and spinal cavity (spinal cord)."},{"label":"Thoracic cavity","detail":"Pericardial cavity (heart), pleural cavities (lungs), mediastinum."},{"label":"Diaphragm","detail":"The muscle that separates the chest from the abdomen."},{"label":"Abdominopelvic cavity","detail":"Stomach, liver, intestines, kidneys, spleen, pancreas, and in women the ovaries and uterus."}]},"mnemonic":{"cue":"Parietal = partition wall, visceral = viscera","explanation":"The parietal layer lines the wall; the visceral layer hugs the organ (the viscera)."},"act":{"type":"sort","prompt":"Put each organ in its cavity.","categories":["Cranial","Thoracic","Abdominopelvic"],"items":[{"label":"Brain","category":0,"feedback":"The brain is in the cranial cavity."},{"label":"Heart","category":1,"feedback":"The heart is in the pericardial cavity, inside the thoracic cavity."},{"label":"Lungs","category":1,"feedback":"Each lung is in a pleural cavity in the thorax."},{"label":"Esophagus (in the chest)","category":1,"feedback":"It runs through the mediastinum."},{"label":"Liver","category":2,"feedback":"The liver is below the diaphragm."},{"label":"Kidneys","category":2,"feedback":"The textbook lists the kidneys in the abdominopelvic cavity."},{"label":"Uterus","category":2,"feedback":"The uterus is in the pelvic part."}]}},{"id":"ap1-8","chapter":"Levels of organization","title":"Levels of organization","teach":["All living material is made of cells, the smallest units of life. Cells form tissues, tissues form organs, organs form systems, and all the systems together make the organism.","Below the cell are atoms (like carbon, hydrogen and oxygen) and molecules (like water, sugars and amino acids), but these aren’t alive. The cell is the smallest living unit and the basic unit of biologic organization.","The fluid part of a cell is protoplasm. It’s surrounded by the cell (plasma) membrane, which controls what enters and leaves, and it contains organelles such as mitochondria, ribosomes and lysosomes."],"act":{"type":"order","prompt":"Put the levels of organization in order, smallest first.","items":[{"label":"Atoms","detail":"Smallest units of elements"},{"label":"Molecules","detail":"Atoms joined by chemical bonds"},{"label":"Cells","detail":"Smallest living units"},{"label":"Tissues","detail":"Similar cells doing similar jobs"},{"label":"Organs","detail":"Different tissues working together"},{"label":"Systems","detail":"Groups of organs"},{"label":"Organism","detail":"All systems together"}]}},{"id":"ap1-9","chapter":"The four tissue types","title":"The four tissue types","teach":["Every tissue in the body fits one of four groups.","Epithelial tissue covers and protects surfaces (outside, like skin, and inside, like the intestine lining), forms glands and lines cavities. Its cells sit close together with almost no material between them.","Connective tissue binds and supports other tissues. Its cells make fibers (collagen and elastin) set in a nonliving matrix. Blood, bone and lymphatic tissue are specialized connective tissues.","Muscle tissue has long cells (muscle fibers) that generate movement by contracting forcefully. There are three types: skeletal (voluntary, pulls on bones), smooth (involuntary, in the intestines and blood vessels) and cardiac (involuntary, only in the heart).","Nervous tissue is made of nerve cells that link the sensory and motor structures of the body into one coordinating system."],"keyPoints":["4 tissue types: epithelial, connective, muscle, nervous","3 muscle types: skeletal, smooth, cardiac"],"act":{"type":"sort","prompt":"Match each description to its tissue.","categories":["Epithelial","Connective","Muscle","Nervous"],"items":[{"label":"Lines the intestine and forms glands","category":0,"feedback":"Covering, lining and glands are epithelial jobs."},{"label":"Bone and blood","category":1,"feedback":"Both are specialized connective tissues."},{"label":"Contracts forcefully to create movement","category":2,"feedback":"That’s muscle."},{"label":"Pushes food along the digestive tract","category":2,"feedback":"Smooth muscle does this."},{"label":"Carries signals between sensory and motor structures","category":3,"feedback":"That’s nervous tissue."},{"label":"Cells make collagen and elastin fibers in a matrix","category":1,"feedback":"Fibers in a matrix is the mark of connective tissue."}]}},{"id":"ap1-10","chapter":"Body systems: covering, support and movement","title":"Body systems: covering, support and movement","teach":["The integumentary system is the skin (epidermis and dermis) plus hair, nails, sebaceous glands and sweat glands. It insulates and protects the body, helps control temperature and water, and has receptors for temperature and pressure.","The skeletal system is bones, cartilage and the membranes around bones. It protects and supports, acts as levers for movement, makes blood cells in red marrow, stores fat in yellow marrow, and stores minerals like calcium and phosphorus.","The muscular system is muscles, fasciae, tendon sheaths and bursae. Skeletal muscle moves bones, smooth muscle moves food and blood, and cardiac muscle makes the heart contract."],"act":{"type":"choice","prompt":"Red bone marrow making blood cells is a job of which system?","options":[{"label":"Skeletal","correct":true,"feedback":"Right. Bones make blood cells and store fat and minerals."},{"label":"Cardiovascular","correct":false,"feedback":"The cardiovascular system moves blood, but bones make the cells."},{"label":"Lymphatic","correct":false,"feedback":"Not in this textbook’s list. Blood cells come from red bone marrow."}]}},{"id":"ap1-11","chapter":"Body systems: control and transport","title":"Body systems: control and transport","teach":["The nervous system (brain, spinal cord, cranial and peripheral nerves) controls and coordinates the other systems, interprets stimuli and handles the special senses.","The endocrine system is the ductless glands. The pituitary, the \"master gland\", controls the thyroid, adrenals, ovaries and testes. Hormones regulate the body chemically, and the hypothalamus links this system with the nervous system.","The cardiovascular system (heart, arteries, veins, capillaries) pumps blood carrying oxygen, nutrients and wastes.","The lymphatic (immune) system (lymph nodes, thymus, spleen, lymph vessels) drains extra fluid from tissues, carries absorbed fats from the intestine to the blood, and protects against disease."],"act":{"type":"sort","prompt":"Which system does each job?","categories":["Nervous","Endocrine","Cardiovascular","Lymphatic"],"items":[{"label":"Interprets sight, hearing, taste and smell","category":0,"feedback":"The special senses are nervous system work."},{"label":"Regulates the body with hormones","category":1,"feedback":"Hormones come from endocrine glands."},{"label":"Pumps blood through arteries, veins and capillaries","category":2,"feedback":"That’s the cardiovascular system."},{"label":"Carries absorbed fats from the intestine","category":3,"feedback":"Lymph vessels pick up fats."},{"label":"Drains extra fluid from tissue spaces","category":3,"feedback":"That’s a lymphatic job."},{"label":"Pituitary controls other glands","category":1,"feedback":"The pituitary is the endocrine master gland."}]}},{"id":"ap1-12","chapter":"Body systems: exchange, processing and reproduction","title":"Body systems: exchange, processing and reproduction","teach":["The respiratory system (nasal cavities, pharynx, larynx, trachea, bronchi, lungs) brings oxygen into the blood and removes carbon dioxide.","The digestive system is the alimentary canal (mouth to anus) plus the salivary glands, liver and pancreas. It breaks food into simpler substances that cells can absorb and gets rid of what can’t be digested.","The urinary system (two kidneys, two ureters, bladder, urethra) chemically regulates the blood, makes and removes urine, and helps maintain homeostasis.","The reproductive system is the ovaries, uterine tubes, uterus and vagina in women, and the testes, vas deferens, seminal vesicles, prostate, penis and urethra in men. It maintains sexual characteristics and continues the species."],"act":{"type":"sort","prompt":"Which system does each organ belong to?","categories":["Respiratory","Digestive","Urinary","Reproductive"],"items":[{"label":"Larynx","category":0,"feedback":"The larynx is part of the airway."},{"label":"Pancreas","category":1,"feedback":"It’s an associated gland of the digestive system."},{"label":"Ureters","category":2,"feedback":"They carry urine from the kidneys to the bladder."},{"label":"Prostate gland","category":3,"feedback":"It’s part of the male reproductive system."},{"label":"Bronchi","category":0,"feedback":"They lead into the lungs."},{"label":"Liver","category":1,"feedback":"The textbook lists it as a digestive gland."}]}},{"id":"ap1-13","chapter":"Homeostasis","title":"Homeostasis","teach":["Homeostasis is keeping the body’s internal environment within narrow limits. Claude Bernard was one of the first scientists to explain why it matters. Blood sugar, body temperature, heart rate and the fluid around cells are all kept in range.","Blood sugar: after a carbohydrate meal, blood glucose rises. The pancreas releases insulin, which moves extra glucose into the liver to be stored as glycogen. Between meals, when glucose drops, the pancreas releases glucagon, which breaks glycogen back down into glucose.","Temperature: when you overheat, the hypothalamus makes you sweat and widens blood vessels near the skin to lose heat. When you’re cold, it makes you shiver and narrows those vessels to hold heat in.","If homeostasis isn’t maintained, the body becomes diseased and eventually dies."],"visual":{"kind":"cycle","title":"Blood sugar balance","items":[{"label":"Meal raises glucose","detail":"Carbohydrates are broken down into glucose."},{"label":"Insulin released","detail":"The pancreas sends extra glucose to the liver."},{"label":"Stored as glycogen","detail":"The liver stores it for later."},{"label":"Glucose drops between meals","detail":"Cells keep using glucose."},{"label":"Glucagon released","detail":"Glycogen is broken back into glucose."}]},"act":{"type":"choice","prompt":"Between meals, blood glucose falls. What does the pancreas release?","options":[{"label":"Glucagon, which turns stored glycogen back into glucose","correct":true,"feedback":"Right. Glucagon raises blood glucose."},{"label":"Insulin, which moves glucose into the liver","correct":false,"feedback":"Insulin lowers blood glucose. That’s the response after a meal."},{"label":"Sweat, to cool the body","correct":false,"feedback":"Sweating is for temperature, not blood sugar."}]}},{"id":"ap1-14","chapter":"Negative and positive feedback","title":"Negative and positive feedback","teach":["The body keeps checking itself and correcting changes using negative feedback: a change triggers a response that reverses it. A home thermostat works the same way: when it gets cold, the furnace turns on; when it’s warm enough, it turns off. Body temperature control is negative feedback.","Positive feedback is the opposite: a stimulus leads to more of the same response. In labour, after the first contraction, the uterus keeps contracting harder and more often."],"mnemonic":{"cue":"Negative = \"no more\", positive = \"more, more\"","explanation":"Negative feedback shuts the change down. Positive feedback builds it up until an end point (like birth)."},"act":{"type":"sort","prompt":"Negative or positive feedback?","categories":["Negative feedback","Positive feedback"],"items":[{"label":"Sweating when body temperature rises","category":0,"feedback":"It brings temperature back down."},{"label":"Contractions growing stronger during labour","category":1,"feedback":"Each contraction leads to a stronger one."},{"label":"Insulin release after a meal","category":0,"feedback":"It brings blood glucose back down."},{"label":"Shivering in the cold","category":0,"feedback":"It brings temperature back up to normal."},{"label":"A furnace switching off when the room is warm","category":0,"feedback":"That’s the thermostat example of negative feedback."}]}}],"flashcards":[{"front":"Anatomy","back":"The study of the body’s structure and how its parts are organized."},{"front":"Physiology","back":"The study of what body parts do and how they do it."},{"front":"Pathology","back":"The study of the diseases of the body."},{"front":"Anatomic position","back":"Standing upright, facing forward, arms at the sides, palms and feet facing forward."},{"front":"Superior / inferior","back":"Above / below."},{"front":"Anterior (ventral) / posterior (dorsal)","back":"Toward the front / toward the back."},{"front":"Cephalad (cranial) / caudal","back":"Toward the head / toward the tail."},{"front":"Medial / lateral","back":"Toward the midline / toward the side."},{"front":"Proximal / distal","back":"Near / away from the point of attachment or origin."},{"front":"Midsagittal plane","back":"Divides the body into equal left and right halves (also called the median plane)."},{"front":"Transverse (horizontal) plane","back":"Divides the body into superior and inferior portions."},{"front":"Frontal (coronal) plane","back":"Divides the body into anterior and posterior portions."},{"front":"Viscera","back":"The organs inside any body cavity."},{"front":"Dorsal cavity","back":"Cranial cavity (brain) and spinal cavity (spinal cord)."},{"front":"Thoracic cavity","back":"Holds the heart in the pericardial cavity and the lungs in the pleural cavities, with the mediastinum between them."},{"front":"Mediastinum","back":"Space between the pleural cavities holding the heart, thymus, trachea, esophagus, vessels and nerves."},{"front":"Parietal / visceral","back":"Lining the wall of a cavity / covering an organ."},{"front":"Protoplasm","back":"The fluid part of a cell."},{"front":"Four tissue types","back":"Epithelial, connective, muscle and nervous."},{"front":"Three muscle types","back":"Skeletal (voluntary), smooth (involuntary, gut and vessels), cardiac (heart only)."},{"front":"Homeostasis","back":"Keeping the internal environment within narrow limits."},{"front":"Negative feedback","back":"A response that reverses a change, like temperature control."},{"front":"Positive feedback","back":"A response that increases the change, like labour contractions."}],"quiz":[{"q":"The organs of any cavity are referred to as the viscera.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says the organs of any cavity are called the viscera. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"A __________________ is any plane that divides the body into superior and inferior portions.","o":["frontal","mid-sagittal","coronal","transverse"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 says a horizontal or transverse plane divides the body into superior and inferior portions. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The heart is located within the _______________ cavity.","o":["pleural","pericardial","abdominal","cranial"],"a":1,"e":"Checked answer, not from an official key. Chapter 1 says the heart sits in the pericardial sac, called the pericardial cavity, inside the thoracic cavity. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The wrist is _____________________ to the elbow.","o":["proximal","superior","distal","superficial"],"a":2,"e":"Checked answer, not from an official key. Distal means away from the point of attachment. The textbook’s own example is \"the wrist is distal to the elbow\". Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What are the smallest living units of biologic organization?","o":["Atoms","Cells","Organelles","Systems"],"a":1,"e":"Checked answer, not from an official key. Table 1-1 says cells are the smallest living units of biologic organization. Atoms and molecules are smaller but not alive. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"Skin, hair, and nails belong to the ________________________ system.","o":["integumentary","muscular","digestive","endocrine"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says the integumentary system includes the skin, hair, nails, sebaceous glands and sweat glands. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What term is used for the maintenance (within varying narrow limits) of the internal environment of the body?","o":["physiology","homeostasis","pathology","epithelium"],"a":1,"e":"Checked answer, not from an official key. Chapter 1 defines homeostasis as the maintenance, within varying narrow limits, of the internal environment of the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What type of muscle is found along the digestive tract?","o":["smooth","cardiac","skeletal","vascular"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says smooth (involuntary) muscle is found in the intestines, where it pushes food along the digestive tract. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"Body temperature control is an example of, _______________________ a process by which the body responds to a stimulus by correcting the change and bringing the body back to the original setting.","o":["positive feedback","endocrinology","negative feedback","pathology"],"a":2,"e":"Checked answer, not from an official key. Chapter 1 uses body temperature control as its example of negative feedback, which corrects a change and brings the body back to normal. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The first contraction during labor results in stronger and stronger contractions of the uterus. This process is an example of _____________________________.","o":["negative feedback","endocrinology","pathology","positive feedback"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 gives labour as the example: after the first contraction, the uterus keeps contracting with more strength and frequency. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The study of the diseases of the body is called ___________________.","o":["anatomy","physiology","endocrinology","pathology"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 says pathology is the study of the diseases of the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What type of tissue generates movement by contracting in a forcible manner?","o":["muscle","nervous","connective","epithelial"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says muscle tissue generates movement by shortening or contracting in a forcible manner. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"Anatomy is the study of diseases in the body.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Anatomy is the study of structure. The study of disease is pathology. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"There are four types of muscle in the human body.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. There are three types of muscle tissue: skeletal, smooth and cardiac. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The prostate gland, penis, and urethra belong to the male reproductive system.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 lists the prostate gland, penis and urethra as part of the male reproductive system. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."}],"caseStudy":{"title":"From a warm room to a whole-body response","scenario":"During a classroom demonstration, a learner becomes warm and begins sweating. They say the skin alone is “fixing” temperature.","prompts":["Which structures detect and coordinate the change?","Which tissue and organ-system responses help release heat?","Why is this an example of negative feedback rather than a single-organ action?"],"takeaway":"Thermoregulation illustrates the course’s central idea: structure, signalling, circulation and effectors cooperate to keep a variable within a workable range."},"perStepChapter":true},{"n":2,"title":"The Chemistry of Life","kicker":"Lesson 2 of your course, built from Chapter 2 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"80–95 minutes","steps":[{"id":"ap2-1","chapter":"Why chemistry matters","title":"Why chemistry matters","teach":["Every cell, tissue and organ is made of chemicals, and the body works through chemical reactions. Digestion, for example, breaks complex food into simple sugars, which cells then turn into ATP, the fuel they run on.","All matter is made of elements: basic substances that can’t be broken down into anything simpler. 92 elements occur naturally."],"act":{"type":"choice","prompt":"What is an element?","options":[{"label":"A basic substance that can’t be broken down into anything simpler","correct":true,"feedback":"Right. Carbon, oxygen and hydrogen are examples."},{"label":"Any substance made of two or more kinds of atoms","correct":false,"feedback":"That’s a compound."},{"label":"The smallest living unit","correct":false,"feedback":"That’s the cell, from Lesson 1."}]}},{"id":"ap2-2","chapter":"Inside an atom","title":"Inside an atom","teach":["Atoms are the smallest particles of an element that still have all its properties. They take part in chemical reactions through their electrons.","Each atom has a heavy, compact nucleus made of protons (positive charge) and neutrons (no charge). Hydrogen is the exception: its nucleus is a single proton. Much lighter electrons (negative charge) orbit the nucleus.","Protons and neutrons each weigh about 1,800 times more than an electron, so an atom’s weight comes almost entirely from its nucleus. Like charges repel and unlike charges attract."],"visual":{"kind":"hub","title":"Parts of an atom","items":[{"label":"Proton","detail":"In the nucleus. Positive charge, 1 unit of weight."},{"label":"Neutron","detail":"In the nucleus. No charge, 1 unit of weight."},{"label":"Electron","detail":"Orbits the nucleus in energy levels. Negative charge, almost weightless."}]},"act":{"type":"sort","prompt":"Where is each particle, and what charge does it carry?","categories":["In the nucleus","Orbits the nucleus"],"items":[{"label":"Proton (+)","category":0,"feedback":"Protons are in the nucleus."},{"label":"Neutron (no charge)","category":0,"feedback":"Neutrons are in the nucleus too."},{"label":"Electron (−)","category":1,"feedback":"Electrons orbit in energy levels."}]}},{"id":"ap2-3","chapter":"Elements, isotopes and the periodic table","title":"Elements, isotopes and the periodic table","teach":["An element is a substance whose atoms all have the same number of protons and the same number of electrons. Because protons and electrons match, atoms are electrically neutral. The atomic number is that number of protons (or electrons).","Isotopes are atoms of the same element with different numbers of neutrons. Carbon has three: C12, C13 and C14, all with six protons and six electrons but six, seven or eight neutrons. C14 is mildly radioactive and is used to date fossil remains. Radioactive iodine is used to treat thyroid disorders.","Carbon is the element found in all living matter. The study of carbon compounds is organic chemistry.","Dmitri Mendeleev noticed that elements could be grouped by similar properties, which gave us the periodic table, arranged by increasing atomic number. John Dalton proposed the atomic theory in 1808."],"mnemonic":{"cue":"Isotopes: same Protons, different Neutrons","explanation":"Change the protons and you have a different element. Change only the neutrons and you have an isotope."},"act":{"type":"choice","prompt":"C12 and C14 are both carbon because they have the same number of:","options":[{"label":"Protons","correct":true,"feedback":"Right. Six protons makes it carbon. They differ only in neutrons."},{"label":"Neutrons","correct":false,"feedback":"Neutrons are what differ between isotopes."},{"label":"Energy levels filled with electrons","correct":false,"feedback":"The defining feature is the number of protons."}]}},{"id":"ap2-4","chapter":"Energy levels","title":"Energy levels","teach":["You can’t know exactly where an electron is, but you can describe the area where it’s likely to be: its orbital. Orbitals group into energy levels drawn as rings around the nucleus.","Hydrogen has one electron in its first level. Carbon has two in the first level and four in the second. Oxygen has two in the first and six in the second. The outer level is what takes part in bonding, and eight electrons fill it."],"act":{"type":"number","prompt":"How many electrons does oxygen have in its second (outer) level?","answer":6,"tolerance":0,"unit":"electrons","explanation":"Oxygen has 2 electrons in its first level and 6 in its second, so it needs 2 more to fill its outer level. That’s why it bonds with two hydrogens in water."}},{"id":"ap2-5","chapter":"Ionic bonds","title":"Ionic bonds","teach":["Atoms bond by transferring or sharing their outermost electrons. When atoms of two or more different elements combine this way, they form a compound. A molecule is the smallest particle that keeps all the properties of the compound (H₂O is both).","In an ionic bond, one atom gains electrons and the other loses them. Atoms that gain electrons become negative; atoms that lose electrons become positive. These charged atoms are ions, and the attraction between opposite charges holds them together.","Table salt is the classic example: sodium has one outer electron, chlorine has seven. Sodium gives its electron to chlorine, making Na⁺ and Cl⁻. Ionic compounds dissociate (split into ions) in water. Many mineral salts the body needs, like sodium, chloride, potassium, calcium and phosphate, exist as ions."],"act":{"type":"choice","prompt":"When sodium gives an electron to chlorine, sodium becomes:","options":[{"label":"A positive ion (Na⁺)","correct":true,"feedback":"Right. Losing a negative electron leaves a positive charge."},{"label":"A negative ion (Na⁻)","correct":false,"feedback":"Gaining electrons makes an ion negative. Sodium loses one."},{"label":"An isotope of sodium","correct":false,"feedback":"Isotopes differ in neutrons, not electrons."}]}},{"id":"ap2-6","chapter":"Covalent and hydrogen bonds","title":"Covalent and hydrogen bonds","teach":["In a covalent bond, atoms share electrons to fill their outer levels. Covalent molecules don’t dissociate in water. Carbon, oxygen, hydrogen and nitrogen form covalent bonds, and together they make up about 95% of the material in cells.","Hydrogen bonds are very weak. They hold water molecules together by forming a bridge between the negative oxygen of one molecule and the positive hydrogens of another. They also help fold molecules like proteins into their 3D shape.","Atoms that give up electrons in a reaction are electron donors (like sodium); those that take them are electron acceptors (like chlorine). Electron carriers accept electrons briefly and use their energy to make ATP."],"act":{"type":"sort","prompt":"Which type of bond is described?","categories":["Ionic","Covalent","Hydrogen"],"items":[{"label":"Electrons are transferred from one atom to another","category":0,"feedback":"Transfer = ionic."},{"label":"Electrons are shared","category":1,"feedback":"Sharing = covalent."},{"label":"Splits into ions in water","category":0,"feedback":"Ionic compounds dissociate in water."},{"label":"Holds one water molecule to the next","category":2,"feedback":"That’s the hydrogen bond bridge."},{"label":"Joins the C, H, O and N in large cell molecules","category":1,"feedback":"These elements bond covalently."},{"label":"Helps fold a protein into its shape","category":2,"feedback":"Hydrogen bonds shape proteins."}]}},{"id":"ap2-7","chapter":"Water","title":"Water","teach":["Water is the most abundant substance in cells, about 60% to 80%. Blood plasma is 91% water.","Water is two hydrogens covalently bonded to one oxygen. Oxygen pulls electrons harder, so water is polar: slightly negative at the oxygen and slightly positive at the hydrogens. That’s why salt dissociates in it: Cl⁻ is drawn to the hydrogens and Na⁺ to the oxygen.","Water’s jobs: it takes part in reactions (digestion uses water to break molecules apart, called hydrolysis); it’s the \"universal solvent\" where reactions happen; it carries hormones and enzymes in plasma; it absorbs and releases heat, steadying body temperature; it cushions the fetus (amniotic fluid) and the brain and spinal cord (cerebrospinal fluid); and it’s the base of body lubricants like mucus and synovial fluid."],"keyPoints":["Most abundant substance in cells (60–80%)","Polar molecule","Solvent, transport, temperature control, protection, lubrication"],"act":{"type":"choice","prompt":"Why does table salt dissolve (dissociate) in water?","options":[{"label":"Water is polar, so its charged ends pull the Na⁺ and Cl⁻ ions apart","correct":true,"feedback":"Right. The unequal sharing of electrons in water is the key."},{"label":"Salt is held together by covalent bonds","correct":false,"feedback":"Salt is ionic. Covalent compounds don’t dissociate in water."},{"label":"Water is a base","correct":false,"feedback":"Pure water is neutral, pH 7."}]}},{"id":"ap2-8","chapter":"Carbon dioxide, oxygen and ammonia","title":"Carbon dioxide, oxygen and ammonia","teach":["Carbon dioxide (CO₂) is a waste product of cellular respiration. If it builds up, it reacts with water to form carbonic acid, which is toxic, so we breathe it out quickly. Plants use it in photosynthesis, and it’s the source of the carbon in all organic compounds.","Molecular oxygen (O₂) is needed by everything that breathes air. Cells use it to turn the energy in glucose into ATP. Plants keep the atmosphere at about 21% oxygen.","Ammonia (NH₃) comes from breaking down proteins and amino acids. Even a little is harmful, so the liver uses enzymes to convert it to urea, which the kidneys remove in urine."],"visual":{"kind":"flow","title":"Getting rid of ammonia","items":[{"label":"Protein breakdown","detail":"Amino acids are used for energy."},{"label":"Ammonia (NH₃)","detail":"Toxic nitrogen waste."},{"label":"Liver","detail":"Enzymes convert ammonia to urea."},{"label":"Kidneys","detail":"Urea is filtered out in urine."}]},"act":{"type":"choice","prompt":"Which organ turns toxic ammonia into urea?","options":[{"label":"Liver","correct":true,"feedback":"Right. The kidneys then excrete the urea."},{"label":"Kidneys","correct":false,"feedback":"The kidneys remove urea, but the liver makes it."},{"label":"Lungs","correct":false,"feedback":"The lungs get rid of carbon dioxide."}]}},{"id":"ap2-9","chapter":"Mineral salts (electrolytes)","title":"Mineral salts (electrolytes)","teach":["Mineral salts, or electrolytes, are small ions that cells need to survive. They’re parts of enzymes or of the environment enzymes need to work.","Calcium is needed for muscle contraction, nerve transmission and strong bones; it’s the fifth most abundant element in the body. Phosphate is needed to make ATP. Chloride is needed for nerve transmission. Sodium and potassium are needed for muscle contraction and nerve transmission."],"act":{"type":"sort","prompt":"Match each mineral to a job the textbook gives it.","categories":["Calcium","Phosphate","Sodium and potassium"],"items":[{"label":"Building strong bones","category":0,"feedback":"Calcium."},{"label":"Making ATP","category":1,"feedback":"Phosphate is part of ATP."},{"label":"Muscle contraction and nerve signals","category":2,"feedback":"Sodium and potassium (calcium helps too)."}]}},{"id":"ap2-10","chapter":"Carbohydrates","title":"Carbohydrates","teach":["Carbohydrates are made of carbon, hydrogen and oxygen in a 1:2:1 ratio, like glucose (C₆H₁₂O₆). The smallest are simple sugars, usually chains of five or six carbons.","Important five-carbon sugars are ribose and deoxyribose, part of RNA and DNA. Important six-carbon sugars are glucose and fructose. Glucose and fructose together make sucrose (table sugar), a disaccharide.","Many glucose molecules bonded together make starch, glycogen (animal starch), cellulose (plant fiber) and chitin. Carbohydrates have two main jobs: storing energy (the more common job) and strengthening cells (cellulose, chitin)."],"act":{"type":"sort","prompt":"Five-carbon or six-carbon sugar?","categories":["Five-carbon","Six-carbon"],"items":[{"label":"Ribose","category":0,"feedback":"Ribose is in RNA."},{"label":"Deoxyribose","category":0,"feedback":"Deoxyribose is in DNA."},{"label":"Glucose","category":1,"feedback":"C₆H₁₂O₆."},{"label":"Fructose","category":1,"feedback":"Fructose is a six-carbon sugar."}]}},{"id":"ap2-11","chapter":"Lipids","title":"Lipids","teach":["Lipids don’t dissolve in water. They include fats, phospholipids, steroids and prostaglandins. About 95% of the fat in the body is triglycerides, now called triacylglycerols: one glycerol (a three-carbon molecule) plus fatty acids.","A fatty acid is saturated if its carbons are joined only by single bonds. Saturated fats (whole milk, butter, eggs, beef, pork, coconut and palm oils) tend to be solid at room temperature, and too much contributes to cardiovascular disease.","An unsaturated fatty acid has one or more double bonds. These fats (sunflower, corn and fish oils) tend to be liquid at room temperature.","Fats store energy, insulate the body under the skin, and cushion organs like the kidneys."],"act":{"type":"sort","prompt":"Saturated or unsaturated?","categories":["Saturated","Unsaturated"],"items":[{"label":"Only single bonds between carbons","category":0,"feedback":"Single bonds only = saturated."},{"label":"One or more double bonds","category":1,"feedback":"Double bonds = unsaturated."},{"label":"Butter","category":0,"feedback":"Solid at room temperature."},{"label":"Fish oil","category":1,"feedback":"Liquid at room temperature."},{"label":"Coconut oil","category":0,"feedback":"The textbook lists coconut and palm oils as saturated."},{"label":"Corn oil","category":1,"feedback":"Unsaturated."}]}},{"id":"ap2-12","chapter":"Proteins","title":"Proteins","teach":["Proteins are made of carbon, hydrogen, oxygen and nitrogen, and most also contain sulfur. Their building blocks are 20 amino acids. Each amino acid has a carboxyl group, an amine group, a hydrogen and a variable R group.","The covalent bonds that join amino acids into a protein are called peptide bonds.","Proteins do a lot: they build membranes and muscle (actin and myosin); enzymes are protein catalysts that speed up reactions without being changed; antibodies are proteins that fight foreign antigens; and proteins can be broken down for energy.","Structure: primary is the amino acid sequence; secondary is coiling into helices or pleated sheets from hydrogen bonds; tertiary is further folding, partly from bonds between sulfur atoms; quaternary is how separate units fit together. Heat or a pH change can break hydrogen bonds and stop a protein from working."],"act":{"type":"order","prompt":"Put the levels of protein structure in order.","items":[{"label":"Primary","detail":"The sequence of amino acids"},{"label":"Secondary","detail":"Coiling into helices or pleated sheets (hydrogen bonds)"},{"label":"Tertiary","detail":"Further folding (including sulfur bonds)"},{"label":"Quaternary","detail":"How separate units fit together"}]}},{"id":"ap2-13","chapter":"Nucleic acids and ATP","title":"Nucleic acids and ATP","teach":["DNA is the genetic material in the nucleus and controls everything the cell does. RNA is related to it; messenger RNA and transfer RNA are needed to make proteins.","Both are chains of nucleotides. A nucleotide is a sugar (deoxyribose in DNA, ribose in RNA), a nitrogen base and a phosphate group. DNA is a double helix; RNA is single-stranded.","Purines have a double ring: adenine and guanine. Pyrimidines have a single ring: thymine, cytosine and uracil. DNA uses A, T, G and C. RNA swaps uracil in for thymine. In DNA, A pairs with T and C pairs with G.","ATP (adenosine triphosphate) is the cell’s fuel: ribose + adenine + three phosphates, with energy stored in the second and third phosphate bonds. ADP + phosphate + energy makes ATP; breaking ATP back to ADP releases energy for repair, reproduction, assimilation and transport."],"mnemonic":{"cue":"Pure As Gold; CUT the Py","explanation":"Purines are Adenine and Guanine. Pyrimidines are Cytosine, Uracil and Thymine."},"act":{"type":"sort","prompt":"Sort the bases.","categories":["Purines (double ring)","Pyrimidines (single ring)"],"items":[{"label":"Adenine","category":0,"feedback":"Purine."},{"label":"Guanine","category":0,"feedback":"Purine."},{"label":"Thymine","category":1,"feedback":"Pyrimidine, DNA only."},{"label":"Cytosine","category":1,"feedback":"Pyrimidine."},{"label":"Uracil","category":1,"feedback":"Pyrimidine, RNA only."}]}},{"id":"ap2-14","chapter":"Diffusion","title":"Diffusion","teach":["Diffusion is the movement of molecules from an area of high concentration to an area of low concentration. Open a perfume bottle and the molecules randomly collide with air molecules until they spread through the room. These random collisions are called Brownian movement.","Temperature affects diffusion: the higher the temperature, the faster molecules move.","In the lungs, oxygen diffuses from the air (high) into the blood (low), and carbon dioxide diffuses from the blood (high) into the lungs (low) to be breathed out."],"act":{"type":"choice","prompt":"What happens to the rate of diffusion as temperature rises?","options":[{"label":"It speeds up","correct":true,"feedback":"Right. Heat makes molecules move faster."},{"label":"It slows down","correct":false,"feedback":"The textbook says higher temperature means faster movement."},{"label":"It doesn’t change","correct":false,"feedback":"Temperature does affect diffusion."}]}},{"id":"ap2-15","chapter":"Osmosis and tonicity","title":"Osmosis and tonicity","teach":["The plasma membrane is selectively permeable: it lets only some materials through. Materials cross it in three ways: diffusion, osmosis and active transport.","Osmosis is a special kind of diffusion: the movement of water only, across a selectively permeable membrane, from where water is more concentrated (fewer solutes) to where it’s less concentrated (more solutes).","Red blood cells show it clearly. In an isotonic solution (normal saline), salt inside and outside is equal, so the cell keeps its shape. In a hypotonic solution (pure water), water rushes in and the cell swells and bursts. In a hypertonic solution (5% salt), water leaves and the cell shrivels (crenates).","Proteins in blood can’t leave the capillaries, so they create osmotic pressure that pulls most escaped fluid back in."],"visual":{"kind":"flow","title":"A red blood cell in three solutions","items":[{"label":"Isotonic","detail":"Equal concentration. No change in shape."},{"label":"Hypotonic","detail":"Less solute outside. Water moves in; the cell swells and can burst."},{"label":"Hypertonic","detail":"More solute outside. Water moves out; the cell shrivels."}]},"mnemonic":{"cue":"HypO: the cell swells like an O","explanation":"In a hypotonic solution the cell takes on water and swells. In a hypertonic one it shrinks."},"act":{"type":"sort","prompt":"What happens to a red blood cell in each solution?","categories":["Isotonic","Hypotonic","Hypertonic"],"items":[{"label":"Normal saline","category":0,"feedback":"Same salt concentration as the cell."},{"label":"Distilled water","category":1,"feedback":"Water moves in and the cell can burst."},{"label":"5% salt solution","category":2,"feedback":"Water moves out and the cell shrivels."},{"label":"The cell shrivels","category":2,"feedback":"That’s a hypertonic solution."},{"label":"The cell swells","category":1,"feedback":"That’s a hypotonic solution."}]}},{"id":"ap2-16","chapter":"Active transport","title":"Active transport","teach":["Diffusion and osmosis can’t bring in everything a cell needs. Sugars, amino acids, larger proteins and fats often have to be moved against a concentration gradient, from low concentration to high.","This is active transport, and it needs energy in the form of ATP. It’s the main way most cells get the materials they need."],"act":{"type":"sort","prompt":"Does the process need energy (ATP)?","categories":["Needs ATP","No ATP needed"],"items":[{"label":"Active transport","category":0,"feedback":"It moves materials against the gradient."},{"label":"Diffusion","category":1,"feedback":"Molecules move down the gradient on their own."},{"label":"Osmosis","category":1,"feedback":"Water moves down its gradient on its own."}]}},{"id":"ap2-17","chapter":"pH, acids, bases and buffers","title":"pH, acids, bases and buffers","teach":["pH measures hydrogen ion (H⁺) concentration. Pure water splits into equal H⁺ and OH⁻, so its pH is 7: neutral.","An acid releases extra H⁺ in water and has a pH below 7. A base (alkali) combines with H⁺ and has a pH above 7. The scale is logarithmic, so each step is a tenfold change: lemon juice (pH 2) is 100 times more acidic than tomato juice (pH 4).","In the body: stomach acid is near pH 1, urine about 6, saliva just under 7, and blood 7.4 (slightly basic).","Enzymes are very sensitive to pH, so the body uses buffers: substances that release H⁺ when levels fall and take it up when levels rise. The key blood buffer is carbonic acid and bicarbonate."],"visual":{"kind":"flow","title":"Body fluids on the pH scale","items":[{"label":"Stomach, pH ~1","detail":"Very acidic."},{"label":"Urine, pH ~6","detail":"Slightly acidic."},{"label":"Pure water, pH 7","detail":"Neutral."},{"label":"Blood, pH 7.4","detail":"Slightly basic."}]},"act":{"type":"number","prompt":"Lemon juice is pH 2 and tomato juice is pH 4. How many times more acidic is lemon juice?","answer":100,"tolerance":0,"unit":"times","explanation":"Each pH step is a tenfold change. Two steps is 10 × 10 = 100 times."}}],"flashcards":[{"front":"Atom","back":"Smallest particle of an element that keeps its properties and reacts through its electrons."},{"front":"Proton / neutron / electron","back":"Positive, in nucleus / no charge, in nucleus / negative, orbits nucleus."},{"front":"Element","back":"A substance whose atoms all have the same number of protons and electrons."},{"front":"Isotope","back":"Same element (same protons), different number of neutrons."},{"front":"Atomic number","back":"The number of protons (or electrons) in an atom."},{"front":"Compound","back":"Atoms of two or more different elements bonded together."},{"front":"Ionic bond","back":"One atom gains electrons and another loses them; opposite ions attract. Dissociates in water."},{"front":"Covalent bond","back":"Atoms share electrons. Doesn’t dissociate in water."},{"front":"Hydrogen bond","back":"Weak bond that holds water molecules together and shapes proteins."},{"front":"Ion","back":"A charged atom. Gaining electrons makes it negative; losing them makes it positive."},{"front":"Water in cells","back":"60–80% of a cell; polar; the universal solvent."},{"front":"Ammonia","back":"Toxic waste from protein breakdown; the liver turns it into urea."},{"front":"Carbohydrate ratio","back":"C:H:O in a 1:2:1 ratio."},{"front":"Triacylglycerol","back":"Glycerol + fatty acids; 95% of body fat."},{"front":"Saturated vs unsaturated fat","back":"Single bonds only, solid / one or more double bonds, liquid."},{"front":"Peptide bond","back":"Covalent bond joining amino acids into a protein."},{"front":"Enzyme","back":"A protein catalyst that speeds up a reaction without being changed."},{"front":"Purines","back":"Adenine and guanine (double ring)."},{"front":"Pyrimidines","back":"Thymine, cytosine and uracil (single ring)."},{"front":"RNA vs DNA bases","back":"RNA uses uracil instead of thymine."},{"front":"ATP","back":"Ribose + adenine + 3 phosphates; the cell’s fuel."},{"front":"Diffusion","back":"Molecules move from high to low concentration."},{"front":"Osmosis","back":"Water moves across a selectively permeable membrane toward the side with more solute."},{"front":"Isotonic / hypotonic / hypertonic","back":"No change / cell swells / cell shrivels."},{"front":"Active transport","back":"Moving materials against a concentration gradient, using ATP."},{"front":"pH 7","back":"Neutral. Below 7 is acidic; above 7 is basic."},{"front":"Buffer","back":"Releases or takes up H⁺ to keep pH steady. Blood: carbonic acid/bicarbonate."}],"quiz":[{"q":"What is formed when two or more different elements combine by sharing electrons?","o":["proton","chemical","ion","compound"],"a":3,"e":"Checked answer, not from an official key. Chapter 2 says that when atoms of two or more different elements combine by transferring or sharing electrons, a compound is created. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"What kind of bond is formed when one atom gains an electron and another atom loses an electron?","o":["ionic","covalent","hydrogen","molecular"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says an ionic bond forms when one atom gains electrons while the other loses electrons. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Which nucleotide is found in RNA but not in DNA?","o":["guanine","adenine","thymine","uracil"],"a":3,"e":"Checked answer, not from an official key. Chapter 2 says RNA substitutes uracil for thymine. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"The covalent bonds that are formed between different amino acids to form a protein are known as _______________________________.","o":["peptide bonds","ionic bonds","hydrogen bonds","electrolyte bonds"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says the covalent bonds that form between amino acids to make proteins are called peptide bonds. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"The type of transport that requires energy input is called ________________________.","o":["passive transport","diffusion","osmosis","active transport"],"a":3,"e":"Checked answer, not from an official key. Chapter 2 says active transport needs energy in the form of ATP to move materials against a concentration gradient. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"A solution with a pH of 3 is called a(n) _______________________.","o":["acid","base","ion","solute"],"a":0,"e":"Checked answer, not from an official key. Acids have pH values below 7, so a solution with a pH of 3 is an acid. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"The basic building blocks of proteins are ______________________.","o":["triglycerides","monosaccharides","amino acids","nucleotides"],"a":2,"e":"Checked answer, not from an official key. Chapter 2 says the basic building blocks of proteins are 20 amino acids. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"What are the smallest particles of an element?","o":["atoms","molecules","compounds","cells"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says atoms are the smallest particles of an element that keep all its characteristics. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"The compact central nucleus of an atom contains _______________ and ________________.","o":["electrons; protons","electrons; neutrons","protons; neutrons","electrons; isotopes"],"a":2,"e":"Checked answer, not from an official key. Chapter 2 says each atom has a compact central nucleus made of protons and neutrons. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"What element is found in all living matter?","o":["nitrogen","carbon","lithium","oxygen"],"a":1,"e":"Checked answer, not from an official key. Chapter 2 says carbon is the element found in all living matter. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"In an atom, __________________ orbit the nucleus?","o":["protons","electrons","neutrons","isotopes"],"a":1,"e":"Checked answer, not from an official key. Chapter 2 says the lighter electrons orbit the nucleus. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"When the solute concentration outside a red blood cell equals the solute concentration inside the cell, the solution is called _____________________.","o":["hypotonic","osmotic","hypertonic","isotonic"],"a":3,"e":"Checked answer, not from an official key. Chapter 2 says that in an isotonic solution (normal saline) the salt concentration outside the red blood cell equals the concentration inside. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Distilled water has a pH of 7 and is therefore _______________________.","o":["acidic","basic","neutral","ionic"],"a":2,"e":"Checked answer, not from an official key. Chapter 2 says distilled water has a pH of 7, which indicates neutrality. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Which type of chemical bond holds water molecules together by forming a bridge between the negative oxygen atom of one water molecule and the positive hydrogen atoms of another water molecule?","o":["isotopic","hydrogen","ionic","covalent"],"a":1,"e":"Checked answer, not from an official key. Chapter 2 describes hydrogen bonds as a bridge between the negative oxygen of one water molecule and the positive hydrogens of another. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"DNA and RNA are examples of _____________________.","o":["proteins","lipids","nucleic acids","carbohydrates"],"a":2,"e":"Checked answer, not from an official key. Chapter 2 names DNA and RNA as the two important nucleic acids in cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Isotopes are atoms of the same element that have different numbers of neutrons but the same number or protons.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says isotopes are atoms of the same element with different numbers of neutrons. Same element means the same number of protons. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Atoms that gain electrons become negatively charged.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says atoms that gain electrons become negatively charged. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"An element is a substance whose atoms all contain the same number of neutrons.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Chapter 2 defines an element by the same number of protons and electrons, not neutrons. Atoms with different numbers of neutrons are isotopes of the same element. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Temperature has no effect on diffusion rate.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Chapter 2 says the higher the temperature, the faster the movement of diffusing molecules. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"The two purine nitrogen bases are adenine and guanine.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says the two purine nitrogen bases are adenine and guanine. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."}],"caseStudy":{"title":"A cell placed in a new solution","scenario":"A teaching model shows identical cells placed into three unlabeled solutions. One swells, one retains its volume and one shrinks.","prompts":["Classify each surrounding solution as hypotonic, isotonic or hypertonic.","Explain the direction of net water movement without saying that solute itself must cross.","Identify one reason a real cell may respond differently from a simplified model."],"takeaway":"Predicting transport requires the gradient, membrane permeability and the identity of the moving substance—not a memorized arrow alone."},"perStepChapter":true},{"n":3,"title":"Cell Structure","kicker":"Lesson 3 of your course, built from Chapter 3 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"75–95 minutes","steps":[{"id":"ap3-1","chapter":"The cell and its parts","title":"The cell and its parts","teach":["The cell is the basic unit of biologic organization; your body is made of trillions of them. Every cell is protoplasm (a watery mix of carbohydrates, proteins, lipids, nucleic acids and salts) surrounded by a cell membrane. Structures inside it are organelles.","Protoplasm inside the nucleus is nucleoplasm; protoplasm outside it is cytoplasm.","Human cells are eukaryotic (\"true\" nucleus): they have membrane-bound organelles. Prokaryotic cells, like bacteria, don’t.","Most cells are 10 to 100 micrometers across (a micrometer is a thousandth of a millimeter). Light microscopes magnify 10× to 1000×; seeing fine detail takes an electron microscope."],"act":{"type":"choice","prompt":"What makes a cell eukaryotic?","options":[{"label":"It has membrane-bound organelles, including a true nucleus","correct":true,"feedback":"Right. Human cells are eukaryotic; bacteria are prokaryotic."},{"label":"It has a cell wall","correct":false,"feedback":"Plant cells have walls, but that isn’t what makes a cell eukaryotic."},{"label":"It has no nucleus","correct":false,"feedback":"That describes a prokaryotic cell."}]}},{"id":"ap3-2","chapter":"Discovering cells and the cell theory","title":"Discovering cells and the cell theory","teach":["Robert Hooke first described cells in 1665, looking at dead cork. The empty walls looked like little rooms, so he called them cellulae. Antonie van Leeuwenhoek soon saw living \"animalcules\" in pond water.","In 1838 Matthias Schleiden (a botanist) said all plants are made of cells, and in 1839 Theodor Schwann (a zoologist) said the same of animals. That laid the foundation of the cell theory.","The modern cell theory: cells are the basic units of organization of all organisms; all organisms are made of one or more cells; cells arise only from preexisting cells by cell division; and all cells today descend from the first cells on earth."],"act":{"type":"sort","prompt":"Match each person to what they did.","categories":["Hooke","Leeuwenhoek","Schleiden","Schwann"],"items":[{"label":"Named cells after looking at cork (1665)","category":0,"feedback":"Robert Hooke."},{"label":"Saw living \"animalcules\" in pond water","category":1,"feedback":"Antonie van Leeuwenhoek."},{"label":"All plants are made of cells (1838)","category":2,"feedback":"Matthias Schleiden, a botanist."},{"label":"All animals are made of cells (1839)","category":3,"feedback":"Theodor Schwann, a zoologist."}]}},{"id":"ap3-3","chapter":"The cell membrane","title":"The cell membrane","teach":["The cell (plasma) membrane is a double layer of phospholipids with proteins embedded in it. Each phospholipid has a water-attracting (hydrophilic) head and water-repelling (hydrophobic) tails. Water passes through easily by osmosis.","The proteins do many jobs: channels for small ions, pumps for active transport (using ATP), receptor sites for hormones, identity markers, \"cement\" that holds cells together, and anchors for the cytoskeleton. The sodium-potassium pump in muscle and nerve cells is made of protein.","This arrangement is called the fluid mosaic model: the pieces are like mosaic tiles set in a fluid rather than solid cement. Every membrane-bound organelle has the same basic structure."],"visual":{"kind":"hub","title":"Jobs of membrane proteins","items":[{"label":"Channels","detail":"Let small dissolved ions through."},{"label":"Pumps","detail":"Active transport against a gradient, using ATP."},{"label":"Receptors","detail":"Binding sites for hormones."},{"label":"Identity markers","detail":"Tell the body which cells are \"self\"."},{"label":"Adhesion and support","detail":"Hold cells together and anchor the cytoskeleton."}]},"act":{"type":"choice","prompt":"The cell membrane’s structure is described as:","options":[{"label":"A fluid mosaic: a double phospholipid layer with proteins embedded in it","correct":true,"feedback":"Right."},{"label":"A rigid wall of cellulose","correct":false,"feedback":"That’s a plant cell wall."},{"label":"A single layer of protein","correct":false,"feedback":"It’s a double layer of phospholipids with proteins in it."}]}},{"id":"ap3-4","chapter":"Cytoplasm: solutions and colloids","title":"Cytoplasm: solutions and colloids","teach":["Cytoplasm is mostly water, with RNA, enzymes, hormones and other chemicals in it. Some are in solution and some are in colloidal suspension.","In a solution, individual atoms or ions are spread through the water. In a colloid, clumps of atoms are spread through it.","Which one a substance forms depends on polarity. Water is polar. Polar compounds, like ionically bonded salts, dissolve readily. Nonpolar compounds (covalent molecules that share electrons evenly) don’t dissolve readily. So mineral salts (sodium, potassium, calcium, chlorine, phosphorus) are in solution, while proteins, carbohydrates, fats and nucleic acids are in colloidal suspension.","Cytoplasm also holds storage granules, fat droplets and vacuoles (membrane-bound spaces holding water, food or waste)."],"act":{"type":"sort","prompt":"In the cytoplasm, is each substance in solution or in a colloid?","categories":["Solution (individual ions)","Colloid (clumps of atoms)"],"items":[{"label":"Sodium","category":0,"feedback":"Mineral salts dissolve."},{"label":"Potassium","category":0,"feedback":"Mineral salts dissolve."},{"label":"Proteins","category":1,"feedback":"Large nonpolar organic molecules are colloidal."},{"label":"Fats","category":1,"feedback":"Nonpolar, so colloidal."},{"label":"Nucleic acids","category":1,"feedback":"Colloidal."},{"label":"Calcium","category":0,"feedback":"Mineral salt, in solution."}]}},{"id":"ap3-5","chapter":"The nucleus","title":"The nucleus","teach":["The nucleus is the control center of the cell. Remove it and the cell loses its functions; transplant a nucleus and the cell takes on the donor’s characteristics.","The nuclear membrane (envelope) is a double membrane. The outer membrane connects to the endoplasmic reticulum. It has pores that let materials such as messenger RNA leave for the cytoplasm.","Stained, the nucleus shows dark threads of chromatin, the genetic material. During cell division the DNA duplicates, shortens and thickens into visible chromosomes. Chromosomes are made of DNA and proteins.","Human body cells have 46 chromosomes (22 pairs of autosomes plus one pair of sex chromosomes). Egg and sperm cells have 23.","The nucleolus is a round body with no membrane, made mostly of DNA, RNA and protein. It makes ribosomes."],"keyPoints":["46 chromosomes in body cells; 23 in egg and sperm","Chromatin when not dividing; chromosomes when dividing","Nucleolus makes ribosomes"],"act":{"type":"choice","prompt":"What does the nucleolus do?","options":[{"label":"Makes ribosomes","correct":true,"feedback":"Right. That’s how it supports protein synthesis."},{"label":"Makes ATP","correct":false,"feedback":"That’s the mitochondria."},{"label":"Packages secretions","correct":false,"feedback":"That’s the Golgi apparatus."}]}},{"id":"ap3-6","chapter":"Mitochondria","title":"Mitochondria","teach":["Mitochondria are small oblong organelles with two membranes. The inner membrane folds into cristae, which give lots of surface for energy reactions.","Cellular respiration (its aerobic phase) happens on the cristae, turning the chemical energy in food into ATP: glucose + oxygen → ATP + carbon dioxide + water. That’s why mitochondria are called the powerhouses of the cell.","High-energy cells like muscle have mitochondria with many cristae; low-energy cells like cheek lining have fewer. Mitochondria have their own DNA and are inherited from the mother through the egg."],"act":{"type":"choice","prompt":"Why do muscle cells have mitochondria with many cristae?","options":[{"label":"More folds mean more surface for making ATP, and muscle needs a lot of energy","correct":true,"feedback":"Right."},{"label":"Cristae store calcium for contraction","correct":false,"feedback":"Cristae are where ATP is made."},{"label":"Muscle cells have no nucleus","correct":false,"feedback":"That isn’t the reason."}]}},{"id":"ap3-7","chapter":"Lysosomes","title":"Lysosomes","teach":["Lysosomes are small, usually round bodies filled with powerful digestive enzymes. They have three jobs.","They fuse with food vacuoles to break stored food into usable pieces (starch to sugars, protein to amino acids, fat to fatty acids and glycerol). They break down worn-out parts so the material can be recycled. And they act as \"suicide agents\" in old or weak cells, releasing their enzymes to destroy the cell. This is autolysis."],"act":{"type":"choice","prompt":"Autolysis is when:","options":[{"label":"A lysosome releases its enzymes and destroys an old or weak cell","correct":true,"feedback":"Right."},{"label":"A cell divides into two","correct":false,"feedback":"That’s cell division."},{"label":"A ribosome builds a protein","correct":false,"feedback":"That’s protein synthesis."}]}},{"id":"ap3-8","chapter":"Endoplasmic reticulum and Golgi apparatus","title":"Endoplasmic reticulum and Golgi apparatus","teach":["The endoplasmic reticulum (ER) is a network of membrane-bound channels called cisternae, used to store and transport what the cell makes. It connects to the outer nuclear membrane and to the cell membrane.","Rough (granular) ER has ribosomes attached, so it’s a site of protein synthesis, especially proteins the cell will secrete. All cells have it.","Smooth (agranular) ER has no ribosomes and is found only in some cells: in the gonads, where it makes sex hormones, and in the intestinal lacteals, where it helps transport fats.","The Golgi apparatus is a stack of flat sacs, like pancakes. It’s where compounds the cell will secrete are collected and concentrated, a bit like a warehouse. It makes carbohydrates to combine with proteins, and lysosomes can form there. It also makes the cellulose of plant cell walls."],"act":{"type":"sort","prompt":"Rough ER, smooth ER or Golgi?","categories":["Rough ER","Smooth ER","Golgi apparatus"],"items":[{"label":"Has ribosomes attached","category":0,"feedback":"That’s what makes it rough."},{"label":"Makes sex hormones in the gonads","category":1,"feedback":"Smooth ER."},{"label":"Collects and concentrates secretions","category":2,"feedback":"The Golgi is the cell’s warehouse."},{"label":"Helps transport fats in intestinal lacteals","category":1,"feedback":"Smooth ER."},{"label":"Looks like a stack of pancakes","category":2,"feedback":"Flat sac-like cisternae."},{"label":"Found in all cells","category":0,"feedback":"All cells have rough ER; only some have smooth ER."}]}},{"id":"ap3-9","chapter":"Ribosomes and protein synthesis","title":"Ribosomes and protein synthesis","teach":["Ribosomes are tiny granules made of ribosomal RNA and protein, with no membrane. They float in the cytoplasm or sit on rough ER, and they’re where proteins are made.","The code for a protein is a gene on DNA in the nucleus. In transcription, messenger RNA (mRNA) copies the code with the help of the enzyme RNA polymerase, then leaves through a nuclear pore to a ribosome.","In translation, transfer RNA (tRNA) brings amino acids from the cytoplasm. Each tRNA has three bases called an anticodon, which matches three bases on the mRNA called a codon. The ribosome links the amino acids into a polypeptide chain."],"visual":{"kind":"flow","title":"From gene to protein","items":[{"label":"Gene on DNA","detail":"The code, in the nucleus."},{"label":"Transcription","detail":"mRNA copies the code (RNA polymerase helps)."},{"label":"mRNA leaves","detail":"Through a nuclear pore to a ribosome."},{"label":"Translation","detail":"tRNA anticodons match mRNA codons, bringing amino acids."},{"label":"Protein","detail":"The ribosome links amino acids into a chain."}]},"mnemonic":{"cue":"Transcription = copy (in the nucleus); Translation = build (in the cytoplasm)","explanation":"You transcribe notes word for word; you translate them into a new language: amino acids."},"act":{"type":"order","prompt":"Put the steps of protein synthesis in order.","items":[{"label":"mRNA copies a gene in the nucleus","detail":"Transcription"},{"label":"mRNA leaves through a nuclear pore","detail":"Goes to a ribosome"},{"label":"tRNA brings amino acids","detail":"Anticodon matches codon"},{"label":"The ribosome links the amino acids","detail":"Forms a polypeptide chain"}]}},{"id":"ap3-10","chapter":"Centrioles, cilia and flagella","title":"Centrioles, cilia and flagella","teach":["Centrioles are a pair of cylinders at right angles near the nucleus (together, the centrosome). Each is nine sets of triplet fibers. During cell division they move to opposite poles and form spindle fibers (microtubules of tubulin) that guide the duplicated chromosomes into the new cells.","Cilia and flagella are hair-like projections that beat. Cilia are short and come in rows; in the airway they sweep mucus and trapped dust up to the throat. A flagellum is long and there are only one to a few; the sperm cell uses one to swim.","Inside, both have nine double fibrils in a ring around two central ones (the \"9 + 2\" pattern), growing from a basal body built like a centriole."],"act":{"type":"sort","prompt":"Centrioles, cilia or flagellum?","categories":["Centrioles","Cilia","Flagellum"],"items":[{"label":"Form spindle fibers in cell division","category":0,"feedback":"Centrioles."},{"label":"Sweep mucus up the airway","category":1,"feedback":"Rows of short cilia."},{"label":"Propels the sperm cell","category":2,"feedback":"A single long flagellum."},{"label":"Nine sets of triplet fibers","category":0,"feedback":"Centriole structure."}]}},{"id":"ap3-11","chapter":"Plant cells: plastids and the cell wall","title":"Plant cells: plastids and the cell wall","teach":["Your course also compares plant and animal cells. Plant cells have a cell wall and plastids; animal cells don’t.","Chloroplasts are large plastids containing green chlorophyll. They are the site of photosynthesis, which turns light energy into chemical energy (glucose). Inside are stacks of membranes; each stack is a granum, made of thylakoids, and the grana are linked by lamellae.","Chromoplasts hold other pigments: xanthophyll (yellow) and carotene (red-orange). Leucoplasts have no pigment and store food, like sugar in onions and starch in potatoes.","The cell wall is made of cellulose, made by the Golgi. We can’t digest it; in our diet it’s fiber."],"act":{"type":"sort","prompt":"Which plastid?","categories":["Chloroplast","Chromoplast","Leucoplast"],"items":[{"label":"Site of photosynthesis","category":0,"feedback":"Chloroplasts contain chlorophyll."},{"label":"Yellow xanthophyll in a banana peel","category":1,"feedback":"Chromoplasts hold carotenoid pigments."},{"label":"Stores starch in a potato","category":2,"feedback":"Leucoplasts are storage plastids."},{"label":"Contains stacks called grana","category":0,"feedback":"Grana are inside chloroplasts."},{"label":"Red-orange carotene in carrots","category":1,"feedback":"Chromoplast."}]}},{"id":"ap3-12","chapter":"Apoptosis and aging","title":"Apoptosis and aging","teach":["Apoptosis is a natural, gene-controlled process by which cells die. It removes damaged cells, cells past their lifespan, infected cells and some cancer cells.","With age, repairing cells and replacing them by division gets harder. Some biologists think \"death genes\" switch on later in life."],"act":{"type":"choice","prompt":"Apoptosis is:","options":[{"label":"A natural, gene-controlled process of cell death","correct":true,"feedback":"Right."},{"label":"A type of cell division","correct":false,"feedback":"It’s cell death, not division."},{"label":"Always caused by infection","correct":false,"feedback":"It’s a normal process that also removes old and damaged cells."}]}}],"flashcards":[{"front":"Protoplasm","back":"Watery colloidal solution inside the cell membrane."},{"front":"Nucleoplasm / cytoplasm","back":"Protoplasm inside / outside the nucleus."},{"front":"Eukaryotic vs prokaryotic","back":"Has membrane-bound organelles / doesn’t (e.g., bacteria)."},{"front":"Modern cell theory","back":"Cells are the basic units of life; all organisms are cells; cells come only from preexisting cells; all cells descend from the first cells."},{"front":"Schleiden and Schwann","back":"Founded the cell theory (plants 1838, animals 1839)."},{"front":"Fluid mosaic model","back":"Double phospholipid layer with embedded proteins."},{"front":"Solution vs colloid","back":"Individual atoms or ions spread out / clumps of atoms spread out."},{"front":"Polar vs nonpolar","back":"Dissolves readily in water / doesn’t dissolve readily."},{"front":"Nucleus","back":"Control center; double membrane with pores."},{"front":"Chromatin vs chromosomes","back":"Long thin DNA threads / shortened, thickened DNA during division."},{"front":"Human chromosome number","back":"46 in body cells; 23 in egg and sperm."},{"front":"Nucleolus","back":"Membrane-free body in the nucleus that makes ribosomes."},{"front":"Mitochondria","back":"Powerhouses; aerobic respiration on the cristae makes ATP."},{"front":"Lysosomes","back":"Digestive enzymes: digest food, recycle parts, destroy old cells (autolysis)."},{"front":"Rough ER","back":"Has ribosomes; makes proteins for secretion."},{"front":"Smooth ER","back":"No ribosomes; sex hormones and fat transport."},{"front":"Golgi apparatus","back":"Stacked sacs that collect and concentrate secretions."},{"front":"Ribosomes","back":"rRNA + protein granules; sites of protein synthesis."},{"front":"Transcription","back":"mRNA copies a gene’s code in the nucleus."},{"front":"Translation","back":"tRNA brings amino acids to the mRNA at the ribosome."},{"front":"Codon / anticodon","back":"Three bases on mRNA / matching three bases on tRNA."},{"front":"Gene","back":"A region of DNA with the code for a particular protein."},{"front":"Centrioles","back":"Form spindle fibers that move chromosomes during division."},{"front":"Cilia vs flagella","back":"Short, many, move material / long, few, move the cell."},{"front":"Chloroplast","back":"Plastid with chlorophyll; site of photosynthesis; contains grana."},{"front":"Leucoplast","back":"Colorless plastid that stores food."},{"front":"Apoptosis","back":"Natural, gene-controlled cell death."}],"quiz":[{"q":"Clumps of atoms that are distributed throughout a water medium are referred to as a _________________.","o":["solution","compound","colloid","solute"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says in a colloid, clumps of atoms rather than individual atoms are distributed throughout the water. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Chromosomes are made of ________ molecules and proteins.","o":["DNA","RNA","lipids","ATP"],"a":0,"e":"Checked answer, not from an official key. Chapter 3 says chromosomes are made of DNA molecules and proteins. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Large organelles found mainly in plant cells that are the site of photosynthesis are known as __________________________.","o":["nuclei","mitochondria","chloroplasts","thylakoids"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says chloroplasts are large organelles found mainly in plant cells and are the site of photosynthesis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Which structures form the spindle fibres during cell division and guide the duplicated chromosomes to their daughter cells?","o":["nucleoli","mitochondria","centrioles","lysosomes"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says the centrioles form the spindle fibers during cell division and guide the duplicated chromosomes to their daughter cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"What are the basic units of organization of all organisms?","o":["Organelles","Organs","Molecules","Cells"],"a":3,"e":"Checked answer, not from an official key. The modern cell theory in Chapter 3 says cells are the basic units of organization of all organisms. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Chemical energy from food is converted to another form of chemical energy called ______________ in the mitochondria.","o":["ATP","glycogen","glucose","RNA"],"a":0,"e":"Checked answer, not from an official key. Chapter 3 says cellular respiration on the cristae converts food (chemical energy) into ATP. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Sodium, potassium, calcium, chlorine, and phosphorus are all examples of ___________________.","o":["proteins","carbohydrates","lipids","mineral salts","None of the above"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 lists sodium, potassium, calcium, chlorine and phosphorus as the mineral salts that are in solution in the cytoplasm. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The process of translation occurs in the _________________.","o":["nucleus","nucleolus","cytoplasm","smooth ER","None of the above"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says tRNA collects amino acids in the cytoplasm and brings them to the mRNA at the ribosomes, which are in the cytoplasm. That process is translation. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Which type of compound does not dissolve readily in water?","o":["Polar","Sonic","Electrolytic","Nonpolar"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 says nonpolar compounds do not dissolve readily in water. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Which type of RNA has three nitrogen bases at one end that are known collectively as an anticodon?","o":["Ribosomal","Messenger","Lysosomal","Transfer"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 says each tRNA is coded for an amino acid by three nitrogen bases at one end, known as the anticodon. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Which type of plastids store food?","o":["Chloroplasts","Chromoplasts","Leucoplasts","Granum"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says leucoplasts have no pigment and are storage plastids. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The aerobic phase of cellular respiration occurs in which organelle?","o":["Ribosome","Lysosome","Nucleus","Mitochondrion"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 says the aerobic phase of cellular respiration occurs in the mitochondrion. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Which term refers to the conversion of light energy into chemical energy?","o":["Dehydration Synthesis","Cellular Respiration","Hydrolysis","Photosynthesis"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 defines photosynthesis as the conversion of light energy into chemical energy. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The cells of the human body contain _____ chromosomes.","o":["40","46","36","42","22"],"a":1,"e":"Checked answer, not from an official key. Chapter 3 says the cells of the human body contain 46 chromosomes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"What type of RNA is used during the process of transcription?","o":["Ribosomal","Messenger","Transverse","Transfer"],"a":1,"e":"Checked answer, not from an official key. Chapter 3 says messenger RNA copies the code from DNA in a process called transcription. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The assembly of flat saclike cisternae where compounds to be secreted by the cell are collected and concentrated is called the _________________________________.","o":["mitochondrion","smooth ER","Golgi apparatus","lysosome"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 describes the Golgi apparatus as flat sac-like cisternae where compounds to be secreted are collected and concentrated. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The cell wall of plant cells is composed of ______________________.","o":["cellulose","lipid","protein","nucleic acid","chloroplasts"],"a":0,"e":"Checked answer, not from an official key. Chapter 3 says the plant cell wall is made of a complex carbohydrate called cellulose. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The many stacks of membranes found inside chloroplasts are known as _________________________.","o":["granum","cristae","chlorophyll","xanthophyll","None of the above"],"a":0,"e":"Checked answer, not from an official key. Chapter 3 says a chloroplast contains many stacks of membranes, each called a granum. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"A region of DNA that contains instructions for the amino acid sequence of a particular protein is called a(n) __________________.","o":["codon","sugar","gene","anticodon"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says the code to make a particular protein is a gene on a DNA molecule. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Transcription occurs in what organelle?","o":["Ribosome","Lysosome","Mitochondrion","Nucleus"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 says mRNA copies the code from the DNA molecule in the nucleus, which is transcription. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"DNA molecules that shorten and thicken during cell division are known as .","o":["chromatids","chromatin units","chromosomes","ribosomes"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says that when DNA duplicates during cell division it shortens and thickens and becomes visible as chromosomes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"In a colloid, individual atoms or ions are distributed throughout the medium.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. That describes a solution. In a colloid, clumps of atoms, not individual atoms or ions, are distributed through the medium. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Cells arise only from pre-existing cells through the process of cell division.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. This is one of the principles of the modern cell theory in Chapter 3. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Apoptosis is a natural process by which cells in the body die.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 3 says apoptosis is a natural process by which cells in the body die, controlled by specific genes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Eukaryotic cells do not have membrane-bound organelles.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Eukaryotic cells do have membrane-bound organelles. Cells without them (like bacteria) are prokaryotic. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."}],"caseStudy":{"title":"Follow a secreted enzyme","scenario":"A glandular cell has been stimulated to release a protein enzyme. The gene is active, the cell has abundant rough ER and Golgi cisternae, and secretory vesicles are moving toward its plasma membrane.","prompts":["Trace the enzyme from DNA information to a finished product outside the cell.","Explain why this cell contains abundant rough ER, Golgi apparatus, and mitochondria.","Predict what would happen to delivery if vesicles could no longer move along cytoskeletal tracks.","Identify the membrane event that releases vesicle contents while preserving the cell boundary."],"takeaway":"A cellular product is the result of coordinated information flow, organelle processing, energy transfer, cytoskeletal transport, and membrane trafficking—not the action of one isolated structure."},"perStepChapter":true},{"n":4,"title":"Cellular Metabolism and Reproduction","kicker":"Lesson 4 of your course, built from Chapter 4 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"95–120 minutes","steps":[{"id":"ap4-1","chapter":"Metabolism: building up and breaking down","title":"Metabolism: building up and breaking down","teach":["Metabolism is all the chemical changes inside a cell. Anabolism uses energy to build large molecules from small ones. Catabolism breaks large molecules into small ones and releases energy.","Cells break down (catabolize) carbohydrates, fats and proteins step by step, and use the released energy (measured in calories) to make ATP from ADP and phosphate. ATP is the energy every cell process runs on.","All of this food energy starts with photosynthesis in plants, which turns light energy into glucose."],"mnemonic":{"cue":"Anabolism Adds, Catabolism Cuts","explanation":"Anabolic reactions build up and cost energy; catabolic reactions break down and release it."},"act":{"type":"sort","prompt":"Anabolism or catabolism?","categories":["Anabolism (builds, uses energy)","Catabolism (breaks down, releases energy)"],"items":[{"label":"Joining amino acids into a protein","category":0,"feedback":"Building a larger molecule."},{"label":"Breaking glucose down to make ATP","category":1,"feedback":"Breaking down releases energy."},{"label":"Storing glucose as glycogen","category":0,"feedback":"Linking glucose units builds a larger molecule."},{"label":"Digesting fat into fatty acids and glycerol","category":1,"feedback":"Breaking down."}]}},{"id":"ap4-2","chapter":"Cellular respiration: the big picture","title":"Cellular respiration: the big picture","teach":["Cellular (biochemical) respiration is the oxygen-requiring, or aerobic, way cells make ATP. It isn’t the same as breathing. Overall: glucose + 6 O₂ → 6 CO₂ + 6 H₂O + ATP.","Glucose is the most common substance broken down aerobically to make ATP. The process is continuous, but it’s taught in three steps: glycolysis in the cytoplasm, then the Krebs citric acid cycle and the electron transport system in the mitochondria."],"visual":{"kind":"flow","title":"Three steps of cellular respiration","items":[{"label":"Glycolysis","detail":"Cytoplasm. Doesn’t need oxygen. Glucose → 2 pyruvic acid."},{"label":"Krebs citric acid cycle","detail":"Mitochondria. Needs oxygen. Releases CO₂, loads NAD and FAD."},{"label":"Electron transport system","detail":"Mitochondrial cristae. Needs oxygen. Makes most of the ATP."}]},"act":{"type":"sort","prompt":"Where does each step happen?","categories":["Cytoplasm","Mitochondria"],"items":[{"label":"Glycolysis","category":0,"feedback":"Glycolysis is in the cytoplasm."},{"label":"Krebs citric acid cycle","category":1,"feedback":"In the mitochondria."},{"label":"Electron transport","category":1,"feedback":"On the cristae of the mitochondria."}]}},{"id":"ap4-3","chapter":"Glycolysis","title":"Glycolysis","teach":["Glycolysis is the first step for both aerobic and anaerobic breakdown of glucose. Because it doesn’t need oxygen, it’s sometimes called anaerobic respiration.","It costs 2 ATP to start (adding phosphates to glucose, called phosphorylation). The six-carbon sugar splits into two three-carbon PGAL molecules, which become PGA and then two pyruvic acid molecules, making 4 ATP. Net gain: 2 ATP.","Two NADH₂ are also made. If oxygen is present, they send their electrons through electron transport for 6 more ATP, so aerobic glycolysis gives 8 ATP in total. Anaerobic glycolysis gives only 2."],"act":{"type":"number","prompt":"Glycolysis uses 2 ATP to start and produces 4 ATP. What is the net gain?","answer":2,"tolerance":0,"unit":"ATP","explanation":"4 made minus the 2 paid back = 2 ATP. With oxygen, the 2 NADH₂ add 6 more, for 8."}},{"id":"ap4-4","chapter":"The Krebs citric acid cycle","title":"The Krebs citric acid cycle","teach":["With oxygen present, each pyruvic acid enters the mitochondria. In a transition step it loses a carbon as CO₂ and becomes acetyl-CoA. Hans Krebs described the cycle in 1937.","Acetyl-CoA joins oxaloacetic acid to make citric acid (the cycle’s name). Citric acid is broken down step by step (alpha-ketoglutaric acid, succinic acid, malic acid) back to oxaloacetic acid, releasing CO₂ and passing hydrogens to the carriers NAD and FAD.","Per pyruvic acid: 3 CO₂, 4 NADH₂, 1 FADH₂ and 1 ATP (as GTP). Each glucose makes two pyruvic acids, so double everything."],"act":{"type":"choice","prompt":"Where does the Krebs citric acid cycle take place?","options":[{"label":"In the mitochondria","correct":true,"feedback":"Right, on the cristae and in the matrix."},{"label":"In the cytoplasm","correct":false,"feedback":"That’s glycolysis."},{"label":"In the nucleus","correct":false,"feedback":"The nucleus holds DNA. Respiration happens in the mitochondria."}]}},{"id":"ap4-5","chapter":"Electron transport and the ATP total","title":"Electron transport and the ATP total","teach":["Most ATP is made in the electron transport system on the mitochondrial cristae. NAD and FAD hand on the electrons they collected. As electrons pass from carrier to carrier (NAD, FAD, quinone, cytochromes), they give up energy that’s used to make ATP.","Oxygen is the final electron acceptor. It takes the electrons and hydrogens and forms water. That’s why breaking down glucose needs oxygen.","Each NADH₂ yields 3 ATP and each FADH₂ yields 2. The textbook totals 38 ATP per glucose (or 36 ATP plus 2 GTP), capturing about 60% of glucose’s energy."],"goodToKnow":"Newer textbooks often give a lower total, about 30 to 32 ATP. For your course test, use the textbook’s 38.","act":{"type":"choice","prompt":"What is the final electron acceptor in electron transport?","options":[{"label":"Oxygen","correct":true,"feedback":"Right. Oxygen takes the electrons and forms water."},{"label":"NAD","correct":false,"feedback":"NAD is a carrier that passes electrons on."},{"label":"Carbon dioxide","correct":false,"feedback":"CO₂ is a waste product of the Krebs cycle."}]}},{"id":"ap4-6","chapter":"Without oxygen: fermentation and lactic acid","title":"Without oxygen: fermentation and lactic acid","teach":["Glucose can be broken down without oxygen in two situations. Both start with glycolysis and make only 2 ATP per glucose.","Fermentation happens in yeast. Pyruvic acid becomes CO₂ and acetaldehyde, which becomes ethyl alcohol. The CO₂ makes bread rise; the alcohol is used in beer and wine.","In human muscle, when exercise outpaces the oxygen supply, NADH₂ passes its hydrogens to pyruvic acid, forming lactic acid. Lactic acid builds up and causes short-term muscle fatigue. When oxygen returns, it’s converted back to pyruvic acid. The textbook calls this anaerobic respiration."],"act":{"type":"sort","prompt":"Fermentation (yeast) or anaerobic respiration in muscle?","categories":["Fermentation","Muscle (anaerobic)"],"items":[{"label":"Produces ethyl alcohol","category":0,"feedback":"Yeast fermentation makes alcohol."},{"label":"Produces lactic acid","category":1,"feedback":"Muscle makes lactic acid."},{"label":"Makes bread rise","category":0,"feedback":"The CO₂ from yeast does this."},{"label":"Causes temporary muscle fatigue","category":1,"feedback":"Lactic acid build-up."}]}},{"id":"ap4-7","chapter":"Other foods in the \"cellular furnace\"","title":"Other foods in the \"cellular furnace\"","teach":["We don’t only eat glucose. Other foods join respiration at the step that matches their structure.","Glucose is a simple carbohydrate. Starch, glycogen and other sugars enter where glucose does. Digestion breaks fat into fatty acids and glycerol: glycerol enters glycolysis at the PGA stage, and fatty acids enter the Krebs cycle. Proteins become amino acids, which enter at pyruvic acid or at different points in the Krebs cycle."],"act":{"type":"sort","prompt":"Where does each food piece enter?","categories":["Glycolysis","Krebs citric acid cycle"],"items":[{"label":"Glucose","category":0,"feedback":"Glucose starts glycolysis."},{"label":"Glycerol","category":0,"feedback":"Enters at the PGA stage."},{"label":"Fatty acids","category":1,"feedback":"Enter the Krebs cycle."},{"label":"Glutamic acid (amino acid)","category":1,"feedback":"Resembles alpha-ketoglutaric acid in the cycle."}]}},{"id":"ap4-8","chapter":"Discovering DNA","title":"Discovering DNA","teach":["Friedrich Miescher found DNA in 1869 and called it nuclein. In the 1920s P. A. Levine showed it contained phosphate, a five-carbon sugar and nitrogen bases.","In 1953 Rosalind Franklin’s X-ray photograph showed DNA was a helix. James Watson and Francis Crick used it to work out the full 3D structure and won the Nobel Prize in 1962 (with Maurice Wilkins). Franklin had died of cancer before then. Today all three are credited."],"act":{"type":"choice","prompt":"Whose X-ray work showed that DNA is a helix?","options":[{"label":"Rosalind Franklin","correct":true,"feedback":"Right."},{"label":"Friedrich Miescher","correct":false,"feedback":"Miescher first found DNA in 1869."},{"label":"Hans Krebs","correct":false,"feedback":"Krebs described the citric acid cycle."}]}},{"id":"ap4-9","chapter":"DNA structure and replication","title":"DNA structure and replication","teach":["DNA is the hereditary material of the cell. It controls which proteins are made, and so controls the cell’s chemistry.","It’s a double helix of nucleotides, like a spiral staircase: the handrails are sugar and phosphate, and the steps are base pairs. Adenine pairs with thymine (two hydrogen bonds); guanine pairs with cytosine (three). A purine always pairs with a pyrimidine.","A gene is a sequence of base pairs that codes for a protein. The Human Genome Project found about 3 billion base pairs coding over 30,000 genes (the textbook’s figures).","Before a cell divides, DNA replicates: helicase enzymes unzip the hydrogen bonds, and DNA polymerase adds new nucleotides to each strand."],"act":{"type":"sort","prompt":"Which base pairs with each one in DNA?","categories":["Pairs with thymine","Pairs with cytosine"],"items":[{"label":"Adenine","category":0,"feedback":"A–T, two hydrogen bonds."},{"label":"Guanine","category":1,"feedback":"G–C, three hydrogen bonds."}]}},{"id":"ap4-10","chapter":"The cell cycle and interphase","title":"The cell cycle and interphase","teach":["Cellular reproduction is how a single cell duplicates itself. The cell cycle has three main stages: interphase, mitosis and cytokinesis.","Interphase is the longest stage. It isn’t division, but the cell is very busy. The DNA is unwound and visible only as threads of chromatin. G1 is the main growth phase. In the S (synthesis) phase, DNA duplicates, so each chromosome becomes two sister chromatids joined at the centromere. In G2 the cell gets ready: centrioles start to separate, mitochondria replicate and tubulin is made.","Speed varies: embryo cells cycle in under 20 minutes, a typical mammal cell in about 24 hours. Liver cells divide only if damaged; nerve and muscle cells rarely divide."],"act":{"type":"order","prompt":"Put the phases of interphase in order.","items":[{"label":"G1","detail":"Main growth phase"},{"label":"S","detail":"DNA duplicates into sister chromatids"},{"label":"G2","detail":"Final preparation for division"}]}},{"id":"ap4-11","chapter":"Mitosis","title":"Mitosis","teach":["Mitosis divides the nucleus into two identical nuclei. The daughter cells are exact copies (clones) of the parent cell.","Prophase: chromosomes shorten and thicken and become visible as two sister chromatids joined at the centromere. Centrioles move to opposite poles and spindle fibers form. The nuclear membrane breaks down.","Metaphase: chromosomes line up on the equatorial (metaphase) plate. Anaphase, the shortest stage: centromeres divide and sister chromatids are pulled to opposite poles in a V shape. Telophase: chromosomes uncoil, the spindle breaks down and a nuclear membrane forms around each set."],"mnemonic":{"cue":"PMAT: Prophase, Metaphase, Anaphase, Telophase","explanation":"Metaphase = Middle, Anaphase = Apart, Telophase = Two nuclei."},"act":{"type":"order","prompt":"Put the stages of mitosis in order.","items":[{"label":"Prophase","detail":"Chromosomes appear; spindle forms; nuclear membrane breaks down"},{"label":"Metaphase","detail":"Chromosomes line up at the middle"},{"label":"Anaphase","detail":"Sister chromatids pulled apart"},{"label":"Telophase","detail":"Two new nuclei form"}]}},{"id":"ap4-12","chapter":"Cytokinesis","title":"Cytokinesis","teach":["Cytokinesis divides the cytoplasm to finish making two cells. It can start in anaphase.","In animal cells, a ring of actin filaments pinches the membrane inward, forming a cleavage furrow until the cell splits. Plant cells build a cell plate across the middle instead, which becomes a new cell wall."],"act":{"type":"choice","prompt":"In animal cells, the pinching-in of the membrane during cytokinesis is called a:","options":[{"label":"Cleavage furrow","correct":true,"feedback":"Right."},{"label":"Cell plate","correct":false,"feedback":"That’s how plant cells divide."},{"label":"Metaphase plate","correct":false,"feedback":"That’s where chromosomes line up in metaphase."}]}},{"id":"ap4-13","chapter":"Meiosis","title":"Meiosis","teach":["Sexual reproduction joins two gametes (sperm and egg) into a fertilized egg, or zygote, giving offspring more genetic variety. Gametes are made by meiosis, which happens only in the gonads (ovaries and testes).","Meiosis is a reduction division: body cells are diploid (2n, 46 chromosomes), and gametes are haploid (n, 23). Fertilization restores 46.","DNA duplicates once, but there are two divisions. In prophase I, matching (homologous) chromosomes pair up in synapsis, forming tetrads, and may swap segments: crossing-over, seen as an X-shaped chiasma. Meiosis I separates the pairs (46 to 23); meiosis II separates the sister chromatids. The result is four haploid cells."],"act":{"type":"sort","prompt":"Mitosis or meiosis?","categories":["Mitosis","Meiosis"],"items":[{"label":"Two identical daughter cells","category":0,"feedback":"Mitosis makes clones."},{"label":"Four cells, each with half the chromosomes","category":1,"feedback":"Meiosis is a reduction division."},{"label":"Crossing-over can happen","category":1,"feedback":"Only in prophase I of meiosis."},{"label":"Repairs a cut finger","category":0,"feedback":"Tissue repair is by mitosis."},{"label":"Happens only in the gonads","category":1,"feedback":"Meiosis makes gametes."},{"label":"One division","category":0,"feedback":"Meiosis has two."}]}},{"id":"ap4-14","chapter":"Making sperm and eggs","title":"Making sperm and eggs","teach":["The four cells from meiosis still have to mature. This is gametogenesis.","Spermatogenesis happens in the seminiferous tubules of the testes. All four cells become sperm: the nucleus becomes the head, mitochondria gather in the middle piece to power the tail, and the cytoplasm becomes the flagellum. It begins at puberty and continues into old age.","Oogenesis, the formation of the egg, happens in the ovary. The cytoplasm divides unequally, so only one functional egg forms. The smaller cells are polar bodies, which die. Meiosis begins in the female embryo, and egg production stops after menopause."],"act":{"type":"choice","prompt":"The first meiotic division of oogenesis makes one large cell and one small cell. The small cell is a:","options":[{"label":"Polar body","correct":true,"feedback":"Right. Polar bodies give their cytoplasm to the egg and then die."},{"label":"Sperm","correct":false,"feedback":"Sperm come from spermatogenesis in the testes."},{"label":"Zygote","correct":false,"feedback":"A zygote is a fertilized egg."}]}},{"id":"ap4-15","chapter":"When cell division goes wrong","title":"When cell division goes wrong","teach":["A mutation is a mistake in copying DNA, which can be caused by chemicals (smoke, asbestos), radiation, X-rays or some viruses. If it affects the genes that control division, cells keep dividing and form a tumor. Cells that spread and form tumors elsewhere are metastases.","Carcinomas come from epithelial tissue; sarcomas from connective tissue such as bone. Cancer-causing agents are carcinogens.","Chromosome and gene disorders in the chapter: Down syndrome is usually caused by an extra chromosome 21. Klinefelter’s syndrome affects males with extra X chromosomes, most often XXY. Tay-Sachs disease is an inherited recessive disorder of lipid metabolism. Progeria causes premature aging."],"act":{"type":"sort","prompt":"Match each term to its meaning.","categories":["Carcinogen","Carcinoma","Sarcoma","Metastasis"],"items":[{"label":"A cancer-causing agent","category":0,"feedback":"Like tobacco smoke or asbestos."},{"label":"A tumor from epithelial tissue","category":1,"feedback":"Carcinoma."},{"label":"A tumor from connective tissue, like bone","category":2,"feedback":"Sarcoma."},{"label":"A tumor that has spread to a new site","category":3,"feedback":"Metastasis."}]}},{"id":"ap4-16","chapter":"Aging and metabolism","title":"Aging and metabolism","teach":["With age, metabolism slows because less energy is needed for growth and maintenance, so calorie needs drop. Eating less and exercising daily help prevent the weight gain common from the early 40s.","Women stop producing eggs after menopause, but men keep producing sperm into their 80s."],"act":{"type":"choice","prompt":"Why do calorie needs fall with age, according to the textbook?","options":[{"label":"Metabolism slows because less energy is needed for growth and maintenance","correct":true,"feedback":"Right."},{"label":"Cells stop making ATP","correct":false,"feedback":"Cells always need ATP; they just need less overall."},{"label":"Mitochondria disappear","correct":false,"feedback":"That isn’t what the textbook says."}]}}],"flashcards":[{"front":"Metabolism","back":"All the chemical changes inside a cell."},{"front":"Anabolism / catabolism","back":"Builds large molecules, uses energy / breaks them down, releases energy."},{"front":"Cellular respiration equation","back":"Glucose + 6 O₂ → 6 CO₂ + 6 H₂O + ATP."},{"front":"Glycolysis","back":"In the cytoplasm; glucose → 2 pyruvic acid; net 2 ATP (8 with oxygen)."},{"front":"Krebs citric acid cycle","back":"In the mitochondria; breaks down acetyl-CoA, releasing CO₂ and loading NAD and FAD."},{"front":"Electron transport system","back":"On the cristae; makes most of the ATP; oxygen is the final electron acceptor."},{"front":"ATP per glucose (textbook)","back":"38 ATP (or 36 ATP + 2 GTP)."},{"front":"Fermentation","back":"Anaerobic breakdown of glucose by yeast; makes CO₂ and ethyl alcohol; 2 ATP."},{"front":"Lactic acid","back":"Made in muscle when oxygen runs short; causes temporary fatigue."},{"front":"Fat digestion products","back":"Fatty acids and glycerol."},{"front":"Watson, Crick and Franklin","back":"Credited with discovering DNA’s double helix (1953)."},{"front":"DNA base pairing","back":"A–T and G–C."},{"front":"Gene","back":"A sequence of base pairs that codes for a protein."},{"front":"Cell cycle stages","back":"Interphase, mitosis, cytokinesis."},{"front":"Interphase phases","back":"G1 (growth), S (DNA synthesis), G2 (preparation)."},{"front":"Centromere","back":"Where sister chromatids are joined."},{"front":"Mitosis stages","back":"Prophase, metaphase, anaphase, telophase."},{"front":"Cleavage furrow","back":"The pinching-in of the membrane in animal cytokinesis."},{"front":"Meiosis","back":"Reduction division in the gonads; four haploid cells."},{"front":"Haploid / diploid","back":"23 chromosomes (n) / 46 chromosomes (2n)."},{"front":"Crossing-over","back":"Exchange of DNA between homologous chromosomes in prophase I."},{"front":"Zygote","back":"A fertilized egg."},{"front":"Oogenesis / spermatogenesis","back":"Egg formation in the ovary / sperm formation in the testes."},{"front":"Polar body","back":"Small cell from unequal division in oogenesis; dies."},{"front":"Carcinogen","back":"A cancer-causing agent."},{"front":"Down syndrome","back":"Usually an extra chromosome 21."},{"front":"Klinefelter’s syndrome","back":"Males with extra X chromosomes, most often XXY."}],"quiz":[{"q":"The most common substance decomposed aerobically in cells to produce ATP is _________________________.","o":["glucose","protein","oxygen","water"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 says the most common substance decomposed aerobically in cells to produce ATP is glucose. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"What is the net gain of ATP molecules produced by glycolysis, the citric acid cycle, and the electron transport system for each glucose molecule?","o":["38","30","34","28"],"a":0,"e":"Checked answer, not from an official key. The textbook totals 38 ATP per glucose (or 36 ATP and 2 GTP) from glycolysis, the citric acid cycle and electron transport. Newer sources often say about 30 to 32, but this test follows the textbook. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The first step in the anaerobic breakdown of glucose into carbon dioxide gas and water is known as __________________________.","o":["hydrolysis","respiration","glycolysis","anabolism"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says the first step in breaking glucose down to carbon dioxide and water is glycolysis, which doesn’t need oxygen. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Which term refers to the breakdown of glucose in human muscle cells when oxygen is insufficient due to muscle fatigue?","o":["anaerobic respiration","aerobic respiration","fermentation","metabolism"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 calls the breakdown of glucose in muscle cells without enough oxygen anaerobic respiration. Fermentation is the yeast version. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Glucose is a simple ___________________________ .","o":["protein","nucleic acid","carbohydrate","lipid"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says glucose is a simple carbohydrate. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Males who have an extra X chromosome (47,XXY) have __________________________________ .","o":["Tay-Sachs disease","Down syndrome","carcinoma","Klinefelter’s syndrome"],"a":3,"e":"Checked answer, not from an official key. Chapter 4 says Klinefelter’s syndrome is caused by extra X chromosomes in males, most commonly XXY. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Biochemical respiration is the oxygen-requiring or process of ATP production.","o":["metabolism","anaerobic","aerobic","glycolysis"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says biochemical respiration is strictly the oxygen-requiring, or aerobic, process of ATP production. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Sister chromatids are attached to one another at the __________________________.","o":["spindle fiber","microtubule","aster","centromere"],"a":3,"e":"Checked answer, not from an official key. Chapter 4 says sister chromatids are attached to each other at the centromere. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"When we cut a finger, cells are repaired and replaced by __________________________.","o":["mitosis","meiosis","spermatogenesis","oogenesis"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 says that when we cut a finger, the cells are repaired and replaced by mitosis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Cancer-causing agents are called __________________________ .","o":["carcinomas","sarcomas","carcinogens","metastases"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says cancer-causing agents are called carcinogens. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The first meiotic division of oogenesis yields one large cell and one smaller cell called a(n) __________________________ .","o":["sperm","oocyte","polar body","daughter cell"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says unequal division in oogenesis makes smaller cells called polar bodies. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The Krebs citric acid cycle takes place in the __________________________ .","o":["nucleus","mitochondrion","ribosome","Golgi apparatus"],"a":1,"e":"Checked answer, not from an official key. Chapter 4 says the Krebs citric acid cycle takes place in the mitochondria. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Most of the ATP produced during biochemical respiration is produced in the ______________________ system.","o":["glycolysis","carrier transport","electron transport","respiratory"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says most of the ATP made during biochemical respiration is produced in the electron transport system. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"What is the ultimate electron acceptor for the electrons captured by the cofactors during glucose decomposition?","o":["Nitrogen","Hydrogen","Oxygen","Carbon"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says oxygen is the ultimate electron acceptor for the electrons captured by the cofactors. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Digestion decomposes fat molecules into fatty acids and __________________________ .","o":["nucleic acid","glutamic acid","glucose","glycerol"],"a":3,"e":"Checked answer, not from an official key. Chapter 4 says digestion decomposes fat into fatty acids and glycerol. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Development of eggs in females is called __________________________.","o":["mitosis","oogenesis","spermatogenesis","cytogenesis"],"a":1,"e":"Checked answer, not from an official key. Chapter 4 says the formation of the female egg is called oogenesis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Unwound strands of chromosomes visible as threads in the nucleoplasm are called _______________________.","o":["nucleotides","chromatin","chromatids","centromere"],"a":1,"e":"Checked answer, not from an official key. Chapter 4 says the unwound strands of chromosomes are visible only as dark threads called chromatin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The indentation of the cell membrane during cytokinesis is called a __________________________.","o":["cleavage furrow","prophase","cell plate","metaphase plate"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 says animal cells separate by a pinching-in of the membrane called a cleavage furrow. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The process by which a single cell duplicates itself is known as __________________________ .","o":["cellular respiration","cellular reproduction","anaerobic respiration","aerobic respiration"],"a":1,"e":"Checked answer, not from an official key. Chapter 4 says cellular reproduction is the process by which a single cell duplicates itself. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"What is the hereditary material of the cell?","o":["RNA","protein","DNA","lipid"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says DNA is the hereditary material of the cell. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Which term refers to a fertilized egg?","o":["Gamete","Zygote","Sperm","Ovum"],"a":1,"e":"Checked answer, not from an official key. Chapter 4 says the sperm and egg unite to form a fertilized egg, or zygote. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The special kind of cellular reproduction that occurs only in gametes is known as mitosis.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. The special division that makes gametes is meiosis, not mitosis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The formation of the female egg is called oogenesis.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 says the formation of the female egg is called oogenesis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Down syndrome is a congenital defect commonly caused by an extra copy of chromosome 21.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 says Down syndrome is a congenital defect commonly caused by an extra chromosome 21. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Fermentation in yeast cells is a type of aerobic respiration.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Fermentation in yeast is anaerobic: it happens without oxygen. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."}],"caseStudy":{"title":"From breakfast glucose to tissue renewal","scenario":"A tissue cell receives glucose and oxygen, uses ATP for active transport, duplicates its DNA, and later divides to replace a worn cell. During a brief period of high demand, glycolysis outpaces mitochondrial oxidation and lactate formation increases.","prompts":["Trace the major carbon and electron path from glucose through aerobic respiration.","Explain why lactate formation can support continued glycolysis but cannot match aerobic ATP output.","Place DNA replication, mitosis, and cytokinesis in the correct cell-cycle order.","Explain why this somatic-cell division is mitosis rather than meiosis."],"takeaway":"Cellular energy pathways and cell reproduction are linked by ATP demand, molecular regulation, and accurate information transfer; neither process is a single isolated reaction."},"perStepChapter":true},{"n":5,"title":"Tissues","kicker":"Lesson 5 of your course, built from Chapter 5 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"85–105 minutes","steps":[{"id":"ap5-1","chapter":"What a tissue is","title":"What a tissue is","teach":["A tissue is a group of cells with a similar structure and function. Tissues are classified by how their cells are arranged and by how much material lies between the cells.","The study of tissues is histology. (Cytology is the study of cells.) The four basic types are epithelial, connective, muscle and nervous. Tissues combine to form organs."],"mnemonic":{"cue":"Histo = tissue, cyto = cell","explanation":"Histology studies tissues; cytology studies cells."},"act":{"type":"choice","prompt":"The study of tissues is called:","options":[{"label":"Histology","correct":true,"feedback":"Right."},{"label":"Cytology","correct":false,"feedback":"Cytology is the study of cells."},{"label":"Pathology","correct":false,"feedback":"Pathology is the study of disease."}]}},{"id":"ap5-2","chapter":"Epithelial tissue: what it does","title":"Epithelial tissue: what it does","teach":["Epithelial tissue has four main jobs. It protects (skin, the lining of the gut). It absorbs (nutrients through the small intestine lining). It secretes (all glands are epithelial tissue). And it excretes (sweat glands get rid of wastes like urea).","Its cells are packed tightly with little or no material between them, which makes it hard to penetrate. Cells are anchored to each other and to the tissue below by the basement membrane, like adhesive under floor tiles.","The free surface may be plain or have cilia, a flagellum, microvilli or secretory vesicles."],"act":{"type":"choice","prompt":"What anchors epithelial cells to each other and to the tissue underneath?","options":[{"label":"The basement membrane","correct":true,"feedback":"Right."},{"label":"The matrix","correct":false,"feedback":"Matrix is the material between cells in connective tissue."},{"label":"Intercalated disks","correct":false,"feedback":"Those connect cardiac muscle cells."}]}},{"id":"ap5-3","chapter":"Epithelial cell shapes","title":"Epithelial cell shapes","teach":["Squamous cells are flat. They line the mouth, blood and lymph vessels, parts of the kidney tubules, throat, esophagus and anus, and form the skin. They mainly protect.","Cuboidal cells look like small cubes. They’re found in glands and gland ducts (sweat and salivary), covering the ovaries, and in the retina. They secrete and protect, and absorb in parts of the kidney tubules.","Columnar cells are tall rectangles. They line the stomach, the intestinal villi, the uterine tubes, the upper airway, the bile duct and mammary ducts. Many have cilia."],"act":{"type":"sort","prompt":"Which cell shape is it?","categories":["Squamous","Cuboidal","Columnar"],"items":[{"label":"Flat cells lining blood vessels","category":0,"feedback":"Squamous."},{"label":"Cube-shaped cells in salivary gland ducts","category":1,"feedback":"Cuboidal."},{"label":"Tall cells lining the small intestine villi","category":2,"feedback":"Columnar."},{"label":"Outer surface of the skin","category":0,"feedback":"Stratified squamous."},{"label":"Lining of the uterine tubes","category":2,"feedback":"Columnar, often ciliated."}]}},{"id":"ap5-4","chapter":"Epithelial arrangements","title":"Epithelial arrangements","teach":["Epithelium is named by shape plus arrangement. Simple is one layer thick (capillaries, lung alveoli). Stratified is several layers thick (stratified squamous lines the mouth and throat and forms the skin surface).","Pseudostratified looks layered because the nuclei sit at different heights, but every cell touches the basement membrane. Pseudostratified ciliated columnar epithelium lines the throat, trachea and bronchi.","Transitional epithelium is several layers of stretchy cells. It looks flat when stretched (full bladder) and saw-toothed when relaxed (empty bladder). It lines the renal pelvis, ureters, bladder and upper urethra."],"act":{"type":"sort","prompt":"Match the arrangement to where it’s found.","categories":["Simple","Stratified","Pseudostratified","Transitional"],"items":[{"label":"Capillary walls and lung alveoli","category":0,"feedback":"One thin layer for easy exchange."},{"label":"Lining of the mouth","category":1,"feedback":"Several layers for protection."},{"label":"Trachea, with cilia","category":2,"feedback":"Pseudostratified ciliated columnar."},{"label":"Urinary bladder","category":3,"feedback":"Stretches as the bladder fills."}]}},{"id":"ap5-5","chapter":"Epithelium named by function","title":"Epithelium named by function","teach":["Mucous membrane lines every body cavity that opens to the outside: the digestive, respiratory, urinary and reproductive tracts. It protects, absorbs and secretes mucus, enzymes and bile salts.","Endothelium is the special name for the single layer of squamous cells lining the circulatory system (blood and lymph vessels). In the heart it’s called endocardium. Capillaries are just one layer of endothelium.","Mesothelium, or serous tissue, lines the large body cavities that don’t open to the outside. The pleura lines the thoracic cavity, the pericardium covers the heart, and the peritoneum lines the abdominal cavity. It reduces friction and secretes fluid."],"act":{"type":"sort","prompt":"Which membrane or lining is it?","categories":["Mucous membrane","Endothelium","Serous (mesothelium)"],"items":[{"label":"Lines the digestive tract","category":0,"feedback":"It opens to the outside."},{"label":"Lines blood vessels","category":1,"feedback":"Endothelium lines the circulatory system."},{"label":"Pleura lining the thoracic cavity","category":2,"feedback":"Serous membrane."},{"label":"Peritoneum lining the abdomen","category":2,"feedback":"Serous membrane."},{"label":"Lines the airway","category":0,"feedback":"Mucous membrane."}]}},{"id":"ap5-6","chapter":"Glands","title":"Glands","teach":["All glands are made of epithelial tissue.","Exocrine glands have ducts that carry their secretions to a surface. Simple exocrine glands have one unbranched duct (sweat glands, sebaceous glands, most digestive glands). Compound exocrine glands have branching ducts (mammary glands, large salivary glands).","Endocrine glands are ductless and secrete hormones straight into the blood (thyroid, pituitary). Goblet cells are single-celled glands that secrete mucus."],"mnemonic":{"cue":"EXOcrine EXits through a duct; ENDOcrine goes in(to the blood)","explanation":"Endocrine glands have no ducts."},"act":{"type":"sort","prompt":"Exocrine or endocrine?","categories":["Exocrine (ducts)","Endocrine (ductless)"],"items":[{"label":"Sweat gland","category":0,"feedback":"Simple exocrine."},{"label":"Thyroid gland","category":1,"feedback":"Secretes hormones into the blood."},{"label":"Mammary gland","category":0,"feedback":"Compound exocrine."},{"label":"Pituitary gland","category":1,"feedback":"Endocrine."},{"label":"Salivary gland","category":0,"feedback":"Compound exocrine."}]}},{"id":"ap5-7","chapter":"Connective tissue: the basics","title":"Connective tissue: the basics","teach":["Connective tissue supports other tissues and allows movement. Unlike epithelium, it has lots of intercellular material called matrix, with collagen and elastin fibers in it. The type and amount of matrix is a main difference between connective tissues.","There are three subgroups: loose, dense and specialized connective tissue."],"visual":{"kind":"hub","title":"Jobs of connective tissue","items":[{"label":"Support","detail":"Bones and cartilage."},{"label":"Nourish and transport","detail":"Blood carries nutrients, gases and hormones."},{"label":"Connect","detail":"Tendons (muscle to bone), ligaments (bone to bone)."},{"label":"Protect","detail":"Bones guard organs; white blood cells fight microbes."},{"label":"Insulate and store","detail":"Fat insulates and stores energy; bone stores calcium."}]},"act":{"type":"choice","prompt":"Which tissue has an abundance of intercellular material called matrix?","options":[{"label":"Connective","correct":true,"feedback":"Right."},{"label":"Epithelial","correct":false,"feedback":"Epithelial cells are tightly packed with almost no matrix."},{"label":"Nervous","correct":false,"feedback":"Matrix is the mark of connective tissue."}]}},{"id":"ap5-8","chapter":"Loose connective tissue","title":"Loose connective tissue","teach":["Loose connective tissue has loosely woven fibers and fills spaces between and within organs. There are three types: areolar, adipose and reticular.","Areolar is the most widespread. It surrounds organs, muscles, vessels and nerves and attaches skin to the tissue below. Its cells: fibroblasts make fibers and repair injuries; histiocytes are fixed macrophages that eat debris and microbes; mast cells make heparin (an anticoagulant) and histamine (an inflammatory substance released in allergies).","Adipose tissue is packed with fat cells that look like soap bubbles. It cushions organs (like the kidneys) and insulates the body.","Reticular tissue is a fine network of fibers that forms the framework of the liver, bone marrow, spleen and lymph nodes."],"act":{"type":"sort","prompt":"Which loose connective tissue?","categories":["Areolar","Adipose","Reticular"],"items":[{"label":"Attaches skin to the tissue below","category":0,"feedback":"Areolar."},{"label":"Loaded with fat cells","category":1,"feedback":"Adipose."},{"label":"Framework of the spleen and lymph nodes","category":2,"feedback":"Reticular."},{"label":"Contains mast cells that make histamine","category":0,"feedback":"Areolar."},{"label":"Cushions the kidneys","category":1,"feedback":"Adipose."}]}},{"id":"ap5-9","chapter":"Dense connective tissue","title":"Dense connective tissue","teach":["Dense connective tissue is tightly packed protein fibers.","Dense regular tissue has fibers in a regular arrangement: tendons attach muscle to bone, ligaments attach bone to bone, and aponeuroses are wide, flat tendons. Tendons are mostly collagen; ligaments mix collagen and elastin.","Dense irregular tissue has fibers going in many directions: the dermis of the skin, muscle sheaths, joint capsules, the outer coat of arteries, and fascia (which covers a whole muscle)."],"mnemonic":{"cue":"Tendons Tie muscle to bone; Ligaments Link bone to bone","explanation":"Both are dense regular connective tissue."},"act":{"type":"sort","prompt":"Regular or irregular dense connective tissue?","categories":["Dense regular","Dense irregular"],"items":[{"label":"Tendon","category":0,"feedback":"Attaches muscle to bone."},{"label":"Ligament","category":0,"feedback":"Attaches bone to bone."},{"label":"Dermis of the skin","category":1,"feedback":"Fibers run in many directions."},{"label":"Fascia around a muscle","category":1,"feedback":"Dense irregular."},{"label":"Aponeurosis","category":0,"feedback":"A wide flat tendon."}]}},{"id":"ap5-10","chapter":"Cartilage","title":"Cartilage","teach":["Cartilage cells are chondrocytes, sitting in cavities called lacunae within a firm matrix of protein and polysaccharides.","Hyaline cartilage has no visible fibers (\"hyaline\" means clear). The fetal skeleton starts as hyaline cartilage and is mostly replaced by bone (ossification). It remains on joint surfaces, in the costal cartilages joining ribs to the sternum, in the rings of the trachea and bronchi, and in the nasal septum.","Fibrocartilage is mostly tough collagen, so it’s dense and very resistant to stretching. It forms the intervertebral disks and the pubic symphysis.","Elastic cartilage is mostly elastin, so it stretches and springs back. It forms the external ear, the auditory tubes and the epiglottis."],"act":{"type":"sort","prompt":"Which type of cartilage?","categories":["Hyaline","Fibrocartilage","Elastic"],"items":[{"label":"Rings of the trachea","category":0,"feedback":"Hyaline."},{"label":"Intervertebral disks","category":1,"feedback":"Strong shock absorbers."},{"label":"External ear","category":2,"feedback":"Flexible and springs back."},{"label":"Dense and very resistant to stretching","category":1,"feedback":"Lots of collagen."},{"label":"Epiglottis","category":2,"feedback":"Elastic."},{"label":"Covers bone ends at joints","category":0,"feedback":"Hyaline."}]}},{"id":"ap5-11","chapter":"Bone, dentin and blood","title":"Bone, dentin and blood","teach":["Bone is very firm connective tissue. Its two types are compact bone (the dense outer layer) and cancellous bone (the spongy inner layer). Bone cells (osteocytes) sit in lacunae, and the matrix is hardened with calcium and phosphorus salts. Chapter 7 covers bone in detail.","Dentin forms the teeth. It’s like bone but harder and denser, and it’s covered by white enamel on the crown.","Blood is a unique connective tissue: a fluid portion (plasma) plus formed elements (red and white blood cells). It transports gases, nutrients, hormones and wastes, protects the body and helps regulate temperature. Blood cells are made in hematopoietic tissue (red bone marrow and lymphoid organs)."],"act":{"type":"choice","prompt":"Which connective tissue is made of plasma plus formed elements?","options":[{"label":"Blood","correct":true,"feedback":"Right."},{"label":"Bone","correct":false,"feedback":"Bone has a hard mineral matrix."},{"label":"Cartilage","correct":false,"feedback":"Cartilage has a firm matrix with chondrocytes."}]}},{"id":"ap5-12","chapter":"Lymphoid tissue, the RE system and synovial membranes","title":"Lymphoid tissue, the RE system and synovial membranes","teach":["Lymphoid tissue is in the lymph nodes, thymus, spleen, tonsils and adenoids. Its main role is making antibodies to protect against disease.","The reticuloendothelial (RE) system is the connective tissue cells that do phagocytosis: Kupffer’s cells lining the liver (and cells lining the spleen and marrow), macrophages, and microglia in the central nervous system.","Synovial membranes line the cavities of freely moving joints and the bursae (small fluid-filled sacs that prevent friction). They are classed as specialized connective tissue."],"act":{"type":"choice","prompt":"Which membrane lines the cavities of freely moving joints?","options":[{"label":"Synovial","correct":true,"feedback":"Right. It also lines bursae."},{"label":"Serous","correct":false,"feedback":"Serous membranes line closed body cavities like the thorax."},{"label":"Mucous","correct":false,"feedback":"Mucous membranes line cavities that open to the outside."}]}},{"id":"ap5-13","chapter":"Muscle tissue","title":"Muscle tissue","teach":["Muscle tissue contracts (shortens and thickens) because of two proteins, actin and myosin. Muscle cells are long, so they’re called muscle fibers. There are three types.","Smooth muscle: spindle-shaped cells with one nucleus, no striations, involuntary (autonomic control). It’s in the walls of hollow organs like the gut, arteries and veins. Its outer longitudinal and inner circular layers push contents along: in the gut this is peristalsis.","Skeletal (striated) muscle: long cells with many nuclei and light and dark bands (actin and myosin). Voluntary, controlled by the central nervous system. It moves bones and makes up about 40% of body weight.","Cardiac muscle: only in the heart. Striated like skeletal, one nucleus and involuntary like smooth. Its branching cells connect at intercalated disks, which coordinate the heartbeat."],"act":{"type":"sort","prompt":"Smooth, skeletal or cardiac?","categories":["Smooth","Skeletal","Cardiac"],"items":[{"label":"Spindle-shaped with one nucleus, no stripes","category":0,"feedback":"Smooth."},{"label":"Many nuclei and voluntary","category":1,"feedback":"Skeletal."},{"label":"Intercalated disks","category":2,"feedback":"Cardiac."},{"label":"Lines the digestive tract (peristalsis)","category":0,"feedback":"Smooth."},{"label":"Pulls on bones","category":1,"feedback":"Skeletal."},{"label":"Striated but involuntary","category":2,"feedback":"Cardiac."}]}},{"id":"ap5-14","chapter":"Nervous tissue","title":"Nervous tissue","teach":["The neuron (nerve cell) is the conducting cell of nervous tissue; neuroglia are supporting cells. Neurons are very long, so they’re also called nerve fibers.","A neuron has a cell body with the nucleus, dendrites that receive stimuli and carry them to the cell body, and an axon that carries the impulse away to the axon endings.","Nervous tissue makes up the brain, spinal cord and nerves. It’s the most highly organized tissue: it controls and coordinates the body, handles the senses, emotions and reasoning, and makes memory possible."],"visual":{"kind":"flow","title":"Direction of a nerve impulse","items":[{"label":"Dendrites","detail":"Receive the stimulus."},{"label":"Cell body","detail":"Contains the nucleus."},{"label":"Axon","detail":"Carries the impulse away."},{"label":"Axon endings","detail":"Pass the signal on."}]},"act":{"type":"choice","prompt":"Which part of a neuron receives stimuli and carries them to the cell body?","options":[{"label":"Dendrites","correct":true,"feedback":"Right."},{"label":"Axon","correct":false,"feedback":"The axon carries impulses away from the cell body."},{"label":"Neuroglia","correct":false,"feedback":"Neuroglia are supporting cells."}]}},{"id":"ap5-15","chapter":"Tissues and aging","title":"Tissues and aging","teach":["Cells divide more slowly in older adults, so injuries, especially to bone, heal more slowly and sometimes incompletely. Muscle cells and working neurons decrease with age.","Collagen fibers become irregular, making tendons and ligaments more fragile and less flexible, and elastic fibers lose their stretch. This is why skin wrinkles over time."],"act":{"type":"choice","prompt":"Why does skin wrinkle with age, according to the textbook?","options":[{"label":"Collagen becomes irregular and elastic fibers lose their stretch","correct":true,"feedback":"Right."},{"label":"Epithelial cells stop dividing completely","correct":false,"feedback":"They slow down, but the textbook links wrinkles to fiber changes."},{"label":"Adipose tissue increases","correct":false,"feedback":"The textbook points to connective tissue fibers."}]}}],"flashcards":[{"front":"Histology","back":"The study of tissues."},{"front":"Four basic tissues","back":"Epithelial, connective, muscle, nervous."},{"front":"Epithelial functions","back":"Protect, absorb, secrete, excrete."},{"front":"Basement membrane","back":"Anchors epithelial cells to each other and to the tissue below."},{"front":"Squamous / cuboidal / columnar","back":"Flat / cube-shaped / tall rectangles."},{"front":"Simple vs stratified","back":"One layer / several layers."},{"front":"Pseudostratified","back":"Looks layered, but every cell touches the basement membrane (trachea)."},{"front":"Transitional epithelium","back":"Stretchy layers lining the bladder, ureters and renal pelvis."},{"front":"Endothelium","back":"Epithelium lining the circulatory system."},{"front":"Pleura / pericardium / peritoneum","back":"Serous membranes of the thoracic cavity / heart / abdominal cavity."},{"front":"Exocrine vs endocrine","back":"Glands with ducts / ductless glands secreting hormones into the blood."},{"front":"Goblet cell","back":"Single-celled gland that secretes mucus."},{"front":"Matrix","back":"Abundant intercellular material of connective tissue."},{"front":"Loose connective tissue types","back":"Areolar, adipose, reticular."},{"front":"Mast cells","back":"Make heparin and histamine."},{"front":"Tendon / ligament","back":"Muscle to bone / bone to bone."},{"front":"Chondrocytes","back":"Cartilage cells, in lacunae."},{"front":"Hyaline cartilage","back":"No visible fibers; joint surfaces, trachea, nasal septum, costal cartilage."},{"front":"Fibrocartilage","back":"Dense, resists stretching; intervertebral disks, pubic symphysis."},{"front":"Elastic cartilage","back":"Flexible; external ear, auditory tube, epiglottis."},{"front":"Compact vs cancellous bone","back":"Dense outer layer / spongy inner layer."},{"front":"Blood","back":"Connective tissue of plasma plus formed elements."},{"front":"Synovial membrane","back":"Lines freely moving joint cavities and bursae."},{"front":"Smooth muscle","back":"Spindle-shaped, one nucleus, involuntary, hollow organ walls."},{"front":"Skeletal muscle","back":"Striated, many nuclei, voluntary."},{"front":"Cardiac muscle","back":"Striated, one nucleus, involuntary, intercalated disks."},{"front":"Dendrite / axon","back":"Carries impulses toward / away from the cell body."}],"quiz":[{"q":"The two types of ________________ tissue are compact (dense) and cancellous (spongy).","o":["adipose","blood","areolar","bone"],"a":3,"e":"Checked answer, not from an official key. Chapter 5 says bone is made of two types of tissue: compact bone and cancellous (spongy) bone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which glands are ductless and secrete hormones directly into the bloodstream?","o":["Goblet","Endocrine","Exocrine","Holocrine"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says endocrine glands are ductless and secrete hormones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"What is the dense regular connective tissue that attaches muscle to bone?","o":["Ligament","Areolar","Fascia","Tendon"],"a":3,"e":"Checked answer, not from an official key. Chapter 5 says tendons are dense regular connective tissue that attach muscle to bone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Epithelial cells are anchored to each other and to underlying tissues by the __________________ membrane.","o":["basement","apical","corner","endocrine"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says epithelial cells are anchored to each other and to underlying tissues by the basement membrane. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Mast cells produce which inflammatory substance in response to allergies?","o":["Fibroblasts","Histamine","Collagen","Cartilage"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says mast cells produce histamine, an inflammatory substance produced in response to allergies. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Chondrocytes are found in cavities called _____________________.","o":["lacunae","lamellae","canaliculi","canals"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says chondrocytes are found in cavities called lacunae. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which type of cartilage is dense and very resistant to stretching?","o":["Hyaline cartilage","Costal cartilage","Elastic cartilage","Fibrocartilage"],"a":3,"e":"Checked answer, not from an official key. Chapter 5 says fibrocartilage’s collagen fibers make it dense and very resistant to stretching. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"All glands are made of __________________________ tissue.","o":["connective","nervous","epithelial","muscle"],"a":2,"e":"Checked answer, not from an official key. Chapter 5 says all glands are made of epithelial tissue. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which unique connective tissue is composed of a fluid portion (plasma) and formed elements?","o":["Blood","Bone","Connective tissue proper","Cartilage"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says blood is a unique connective tissue made of a fluid portion (plasma) and formed elements. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"The type of muscle that lines the digestive tract is called _________________________ muscle.","o":["smooth","cardiac","skeletal","striated"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says smooth muscle is found in the walls of the digestive tract, where it pushes food along. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"A epithelium has several layers of epithelial cells thick.","o":["simple","stratified","pseudostratified","columnar"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says the stratified arrangement is several layers of cells thick. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which type of tissue makes up the brain and spinal cord?.","o":["Smooth","Nervous","Skeletal","Muscle"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says nervous tissue makes up the brain, spinal cord and nerves. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"What type of tissue is loaded with fat cells?.","o":["Areolar","Epithelial","Adipose","Dense regular connective"],"a":2,"e":"Checked answer, not from an official key. Chapter 5 says adipose tissue is loaded with fat cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"The three types of _______________________ tissue are smooth, skeletal, and cardiac.","o":["connective","nervous","muscle","epithelial"],"a":2,"e":"Checked answer, not from an official key. Chapter 5 names the three types of muscle tissue as smooth, striated (skeletal) and cardiac. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Areolar, adipose, and reticular tissues are all types of _______________________________ tissue.","o":["loose connective","dense connective","epithelial","nervous"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says the three types of loose connective tissue are areolar, adipose and reticular. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"The ________________________ is the serous tissue that lines the thoracic cavity.","o":["pericardium","peritoneum","pleura","endothelium"],"a":2,"e":"Checked answer, not from an official key. Chapter 5 says the pleura is the serous membrane that lines the thoracic cavity. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which type of membrane lines the cavities of freely moving joints?","o":["Peritoneum","Pericardial","Synovial","Endothelial"],"a":2,"e":"Checked answer, not from an official key. Chapter 5 says synovial membranes line the cavities of freely moving joints. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which type of tissue has a regular arrangement of embedded fibres and makes up tendons and ligaments?","o":["Loose connective tissue","Dense connective tissue","Areolar connective tissue","Cartilage"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says tendons and ligaments are dense connective tissue with a regular arrangement of fibers. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"What is the special name given to the epithelium that lines the circulatory system?","o":["Endomysium","Pericardium","Peritoneum","Endothelium"],"a":3,"e":"Checked answer, not from an official key. Chapter 5 says endothelium is the special name for the epithelium that lines the circulatory system. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which tissue is characterized by an abundance of intercellular material called the matrix?","o":["Epithelial","Nervous","Muscle","Connective"],"a":3,"e":"Checked answer, not from an official key. Chapter 5 says connective tissue has an abundance of intercellular material called matrix. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Cells of which type of muscle are spindle-shaped with a single nucleus?","o":["Cardiac","Smooth","Nervous","Skeletal"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says smooth muscle cells are spindle-shaped with a single nucleus. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"The study of tissue is called cytology.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. The study of tissue is histology. Cytology is the study of cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Simple epithelium is several layers thick","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Simple epithelium is one cell layer thick. Several layers is stratified. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"The three types of loose connective tissue are areolar, adipose and reticular.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says the three types of loose connective tissue are areolar, adipose and reticular. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Endocrine glands have ducts.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Endocrine glands are ductless. Exocrine glands have ducts. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."}],"caseStudy":{"title":"Map the wall of the small intestine","scenario":"A cross-section of small intestine shows a tall absorptive lining with goblet cells, loose connective tissue containing capillaries, bands of smooth muscle, and nerve fibers coordinating movement and secretion.","prompts":["Classify the epithelial lining and explain why its structure suits absorption.","Identify the tissue beneath the epithelium and explain how it supports nutrient transfer.","Explain the distinct roles of goblet cells, smooth muscle, and nervous tissue.","Trace an absorbed water-soluble nutrient from the epithelial surface toward a blood vessel without treating tissues as isolated layers."],"takeaway":"An organ works because multiple tissue classes form an integrated route: boundary and absorption, support and transport, movement, and regulation."},"perStepChapter":true},{"n":6,"title":"The Integumentary System","kicker":"Lesson 6 of your course, built from Chapter 6 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"90–110 minutes","steps":[{"id":"ap6-1","chapter":"The integumentary system","title":"The integumentary system","teach":["The integumentary system is the skin and its appendages: hair, nails, and sebaceous, ceruminous and sweat glands. \"Integument\" means covering.","An adult’s skin covers over 3,000 square inches and weighs about 6 pounds, nearly twice the weight of the brain or liver. It receives about one-third of all the blood circulating through the body.","It’s flexible but tough, repairs itself, is almost waterproof, blocks UV rays and most harmful chemicals, and helps control body temperature through sweating."],"act":{"type":"choice","prompt":"About how much of the body’s circulating blood does the skin receive?","options":[{"label":"One-third","correct":true,"feedback":"Right, according to the textbook."},{"label":"One-half","correct":false,"feedback":"The textbook says about one-third."},{"label":"One-fifth","correct":false,"feedback":"It’s more: about one-third."}]}},{"id":"ap6-2","chapter":"Layers of the skin","title":"Layers of the skin","teach":["The skin has two main layers. The epidermis on top is epithelial tissue. The dermis beneath it is dense connective tissue. Under the dermis is the subcutaneous layer, also called the hypodermis.","The epidermis is stratified squamous keratinized epithelium, held together by interlocking links called desmosomes. It has no blood vessels and sits on a basement membrane. It’s thickest on the palms and soles.","Cells at the bottom divide by mitosis and push older cells up. As they rise they lose water, fill with the protein keratin and die. This is keratinization. The dead surface cells are constantly shed."],"visual":{"kind":"flow","title":"From the surface down","items":[{"label":"Epidermis","detail":"Epithelial tissue; no blood vessels."},{"label":"Dermis","detail":"Dense connective tissue: the \"true skin\"."},{"label":"Hypodermis (subcutaneous)","detail":"Areolar and adipose tissue; fat."}]},"act":{"type":"order","prompt":"Put the layers in order from the surface down.","items":[{"label":"Epidermis","detail":"Outer layer"},{"label":"Dermis","detail":"Second layer"},{"label":"Hypodermis","detail":"Subcutaneous layer with fat"}]}},{"id":"ap6-3","chapter":"The five layers of the epidermis","title":"The five layers of the epidermis","teach":["From the surface down: stratum corneum, stratum lucidum, stratum granulosum, stratum spinosum and stratum germinativum.","Stratum corneum (horny layer): up to 25 layers of dead, keratinized, scale-like cells surrounded by lipids. They’re about 20% water (versus 70% in the deepest layer) and constantly shed (dandruff on the scalp). It’s a barrier to light and heat waves, microorganisms and most chemicals. Friction thickens it into a callus.","Stratum lucidum (clear layer): one or two layers of flat, transparent cells, hard to see in thin skin.","Stratum granulosum (granular layer): two or three layers of flattened cells, very active in keratinization. Cells lose their nuclei here.","Stratum spinosum (spiny or prickly layer): several layers of polyhedral cells whose outlines look spiny. Desmosomes are still common.","Stratum germinativum (regenerative layer, with the stratum basale at its base): the deepest and most important layer, the only epidermal cells that divide by mitosis. The epidermis regenerates only while this layer is intact."],"mnemonic":{"cue":"Come, Let’s Get Sun Burned","explanation":"Corneum, Lucidum, Granulosum, Spinosum, Basale (germinativum), from the top down."},"act":{"type":"order","prompt":"Put the layers of the epidermis in order, outermost first.","items":[{"label":"Stratum corneum","detail":"Horny layer"},{"label":"Stratum lucidum","detail":"Clear layer"},{"label":"Stratum granulosum","detail":"Granular layer"},{"label":"Stratum spinosum","detail":"Spiny layer"},{"label":"Stratum germinativum","detail":"Regenerative layer"}]}},{"id":"ap6-4","chapter":"Match the layer to its feature","title":"Match the layer to its feature","teach":["Each layer has something that marks it out. Use these to answer \"which layer...\" questions."],"act":{"type":"sort","prompt":"Which layer of the epidermis?","categories":["Corneum","Lucidum","Granulosum","Spinosum","Germinativum"],"items":[{"label":"Outermost layer; barrier to light and heat","category":0,"feedback":"Stratum corneum."},{"label":"The clear layer","category":1,"feedback":"Stratum lucidum."},{"label":"Cells lose their nuclei; very active in keratinization","category":2,"feedback":"Stratum granulosum."},{"label":"Spiny-looking polyhedral cells","category":3,"feedback":"Stratum spinosum."},{"label":"Only layer that divides by mitosis; has melanocytes","category":4,"feedback":"Stratum germinativum."},{"label":"Thickens into a callus with friction","category":0,"feedback":"Stratum corneum."}]}},{"id":"ap6-5","chapter":"Skin color","title":"Skin color","teach":["Melanocytes in the stratum germinativum make the pigment melanin, which produces skin color. Everyone has about the same number of melanocytes; genes control how much melanin they make. Sunlight stimulates them, which is a suntan.","Melanin protects against UV rays. Concentrations of melanin form freckles, moles and the areola. Albinism is a recessive condition in which no melanin is made.","Other color changes: the pink tint of light skin comes from blood vessels in the dermis, and blushing is those vessels dilating. Cyanosis is a bluish color caused by lack of oxygen in the blood; in darker skin it looks greyish or ashy."],"act":{"type":"choice","prompt":"Which cells produce skin color?","options":[{"label":"Melanocytes, which make melanin","correct":true,"feedback":"Right."},{"label":"Keratinocytes, which make keratin","correct":false,"feedback":"Keratin is a tough protein, not the pigment."},{"label":"Fibroblasts","correct":false,"feedback":"Fibroblasts make connective tissue fibers."}]}},{"id":"ap6-6","chapter":"The dermis and hypodermis","title":"The dermis and hypodermis","teach":["The dermis (corium, or \"true skin\") is dense connective tissue with collagen and elastin fibers. It holds blood vessels, nerves, lymph vessels, smooth muscle, sweat glands, hair follicles and sebaceous glands.","It has two parts: the papillary portion next to the epidermis and the deeper reticular portion.","Below it, the subcutaneous tissue (superficial fascia or hypodermis) is areolar tissue with lots of fat. It attaches the skin to muscle or bone, and it’s where hypodermic injections go."],"act":{"type":"choice","prompt":"The subcutaneous layer full of fat is the:","options":[{"label":"Hypodermis","correct":true,"feedback":"Right."},{"label":"Dermis","correct":false,"feedback":"The dermis is dense connective tissue above it."},{"label":"Epidermis","correct":false,"feedback":"The epidermis is the outer epithelial layer."}]}},{"id":"ap6-7","chapter":"Hair","title":"Hair","teach":["Each hair has three layers: the cuticle (overlapping scale-like cells on the outside), the cortex (the main part, with pigment in dark hair) and the medulla (the center, often with air spaces).","The shaft is the visible part. The root sits in the hair follicle, a tube of epidermis. Growth starts in the hair bulb, nourished by blood vessels. Scalp hair grows for about 3 years, then rests for 1 or 2.","The arrector pili is a bundle of smooth muscle attached to the follicle. When it contracts (fear or cold), the hair stands up and you get goose flesh.","Grey hair lacks pigment in the cortex; white hair also has air bubbles in the shaft. Hair texture depends on the shape of its keratin."],"act":{"type":"sort","prompt":"Match each hair part to its description.","categories":["Shaft","Root","Cuticle","Medulla","Arrector pili"],"items":[{"label":"The visible part of the hair","category":0,"feedback":"Shaft."},{"label":"Sits inside the follicle","category":1,"feedback":"Root."},{"label":"Outer layer of overlapping scales","category":2,"feedback":"Cuticle."},{"label":"Central part, often with air spaces","category":3,"feedback":"Medulla."},{"label":"Smooth muscle that causes goose flesh","category":4,"feedback":"Arrector pili."}]}},{"id":"ap6-8","chapter":"Nails","title":"Nails","teach":["Nails are modified horny epidermal cells made of very hard keratin.","The nail body is the visible part. The nail root is the part attached to the nail bed, and nails grow from the root area about 1 mm a week. The lunula is the white crescent at the base. The cuticle (eponychium) is stratum corneum extending over the base of the nail.","Fingernails grow faster than toenails: a lost fingernail regrows in about 3½ to 5½ months, a toenail in 6 to 8 months."],"act":{"type":"sort","prompt":"Which part of the nail?","categories":["Nail body","Nail root","Lunula","Cuticle (eponychium)"],"items":[{"label":"The visible part","category":0,"feedback":"Nail body."},{"label":"Where the nail grows from","category":1,"feedback":"Nail root."},{"label":"White crescent at the base","category":2,"feedback":"Lunula."},{"label":"Skin extending over the base","category":3,"feedback":"Cuticle."}]}},{"id":"ap6-9","chapter":"Sebaceous glands","title":"Sebaceous glands","teach":["Sebaceous glands grow along the walls of hair follicles and make sebum, an oily substance that lubricates the skin and hair and gives them a gloss. Sebum also fights bacteria and fungi.","Sebum production is controlled by hormones: it rises at puberty (acne), late in pregnancy, and falls in later life (dry skin).","Ceruminous glands in the ear canal are modified sebaceous glands that make earwax (cerumen).","In acne, a clogged gland’s sebum oxidizes into a blackhead; trapped sebum can feed bacteria and form a pimple, or a boil if deeper."],"act":{"type":"choice","prompt":"What is the oily substance that lubricates the skin?","options":[{"label":"Sebum","correct":true,"feedback":"Right, from sebaceous glands."},{"label":"Sweat","correct":false,"feedback":"Sweat is watery and cools the body."},{"label":"Cerumen","correct":false,"feedback":"Cerumen is earwax."}]}},{"id":"ap6-10","chapter":"Sweat glands","title":"Sweat glands","teach":["Sweat glands are simple coiled tubes with a duct opening on the skin. They’re most numerous on the palms and soles (about 3,000 per square inch on the palms).","Eccrine glands are the most common and numerous type and are the ones that cool the body. Apocrine glands are found only in the armpits, scrotum, labia majora and around the anus. They open into hair follicles, become active at puberty and don’t regulate temperature.","Sweat contains the same inorganic materials as blood but much more dilute. Its chief salt is sodium chloride. It also carries urea, uric acid, ammonia and lactic acid. Fresh sweat is nearly odorless; bacteria feeding on it cause the smell."],"act":{"type":"sort","prompt":"Eccrine or apocrine?","categories":["Eccrine","Apocrine"],"items":[{"label":"Most common and numerous","category":0,"feedback":"Eccrine."},{"label":"Cools the body","category":0,"feedback":"Eccrine."},{"label":"Found in the armpits and groin, opening into hair follicles","category":1,"feedback":"Apocrine."},{"label":"Becomes active at puberty and adds to body odor","category":1,"feedback":"Apocrine."}]}},{"id":"ap6-11","chapter":"Functions of the skin","title":"Functions of the skin","teach":["Sensation: receptors for temperature and pressure send signals to the brain and spinal cord.","Protection: the skin blocks most chemicals (though fat-soluble chemicals like DDT and poison ivy’s chemicals get through), melanin blocks UV, and the skin’s \"acid mantle\" kills most bacteria.","Thermoregulation: normal temperature is about 98.6°F (37°C). In heat, dermal vessels dilate and sweat evaporates to remove heat. In cold, vessels constrict to keep heat in the core; holding that too long can cause frostbite.","Secretion: sebum and sweat. Vitamin D: UV light helps the skin make a precursor that the liver and kidneys turn into vitamin D, which helps absorb calcium and phosphorus."],"visual":{"kind":"hub","title":"What the skin does","items":[{"label":"Sensation","detail":"Temperature and pressure receptors."},{"label":"Protection","detail":"Barrier, melanin, acid mantle."},{"label":"Thermoregulation","detail":"Blood vessels and sweat."},{"label":"Secretion","detail":"Sebum and sweat."},{"label":"Vitamin D","detail":"Made with help from sunlight."}]},"act":{"type":"choice","prompt":"On a hot day, how does the skin help cool you?","options":[{"label":"Dermal blood vessels dilate and sweat evaporates, carrying heat away","correct":true,"feedback":"Right."},{"label":"Dermal blood vessels constrict","correct":false,"feedback":"That keeps heat in. It happens in the cold."},{"label":"The arrector pili contracts","correct":false,"feedback":"That causes goose flesh."}]}},{"id":"ap6-12","chapter":"Burns","title":"Burns","teach":["First-degree burns involve only the epidermis: redness, pain, maybe slight swelling. Sunburn is an example. They heal in about a week with no scarring.","Second-degree burns involve the epidermis and dermis: redness, pain, swelling and blisters. First- and second-degree burns are partial-thickness burns because the deepest layer survives.","Third-degree (full-thickness) burns completely destroy the epidermis and dermis. They’re often painless because the nerve receptors are destroyed, heal only from the edges, and usually need skin grafts."],"act":{"type":"sort","prompt":"Which degree of burn?","categories":["First-degree","Second-degree","Third-degree"],"items":[{"label":"Epidermis only; redness and pain","category":0,"feedback":"First-degree."},{"label":"Blisters; epidermis and dermis involved","category":1,"feedback":"Second-degree."},{"label":"Epidermis and dermis completely destroyed","category":2,"feedback":"Third-degree."},{"label":"Often painless; needs grafts","category":2,"feedback":"Nerve endings are destroyed."},{"label":"Mild sunburn","category":0,"feedback":"First-degree."}]}},{"id":"ap6-13","chapter":"Skin disorders","title":"Skin disorders","teach":["Skin cancer: basal cell carcinoma is most common and rarely spreads; squamous cell carcinoma can spread; malignant melanoma, from a mole, is the most dangerous.","Infections: warts are caused by human papillomavirus; cold sores by herpes simplex type I; impetigo by Staphylococcus aureus bacteria (honey-colored crust); shingles by the chickenpox virus reactivating; ringworm (tinea) by fungi.","Other conditions: psoriasis is a chronic disorder with red patches covered by thick, dry, silvery scales. Vitiligo causes irregular patches with no pigment. Alopecia is hair loss."],"act":{"type":"sort","prompt":"What causes or describes each condition?","categories":["Virus","Bacterium","Fungus","Not an infection"],"items":[{"label":"Warts","category":0,"feedback":"Human papillomavirus."},{"label":"Impetigo","category":1,"feedback":"Staphylococcus aureus."},{"label":"Ringworm (athlete’s foot)","category":2,"feedback":"Fungi."},{"label":"Shingles","category":0,"feedback":"The chickenpox virus."},{"label":"Vitiligo","category":3,"feedback":"Loss of pigment; cause unknown."},{"label":"Psoriasis","category":3,"feedback":"Chronic disorder, possibly genetic."}]}},{"id":"ap6-14","chapter":"Skin lesions","title":"Skin lesions","teach":["A macule is a flat, small discoloration even with the skin surface (a small rash). A papule is a solid elevation under 1 cm. A wheal is a pale or red swelling, like a mosquito bite.","A vesicle or bulla is a thin blister with clear fluid; a pustule is a similar small elevation filled with pus. A crust is a scab. A furuncle (boil) is a staph infection of a follicle or gland. A cyst is an epithelium-lined sac.","A callus is a thickened area from friction; on bony parts of the foot, these form corns."],"act":{"type":"sort","prompt":"Name the lesion.","categories":["Macule","Papule","Wheal","Pustule"],"items":[{"label":"Flat discoloration even with the skin","category":0,"feedback":"Macule."},{"label":"Solid raised bump under 1 cm","category":1,"feedback":"Papule."},{"label":"Swelling like a mosquito bite","category":2,"feedback":"Wheal."},{"label":"Small raised bump filled with pus","category":3,"feedback":"Pustule."}]}},{"id":"ap6-15","chapter":"Skin and aging","title":"Skin and aging","teach":["With age, sebum drops (drier skin), collagen and elastin are lost (sagging and wrinkles), blood flow decreases and the skin thins. Fewer melanocytes in some areas leaves age spots, and less melanin means grey or white hair.","Hair thins, nails become brittle or thick and prone to fungus, and older adults feel the cold more because of reduced circulation and less fat under the skin."],"act":{"type":"choice","prompt":"Why does skin get drier with age?","options":[{"label":"Sebaceous glands secrete less sebum","correct":true,"feedback":"Right."},{"label":"Sweat glands make more sweat","correct":false,"feedback":"Dry skin comes from less sebum."},{"label":"The stratum corneum disappears","correct":false,"feedback":"It doesn’t disappear."}]}}],"flashcards":[{"front":"Integumentary system","back":"Skin plus hair, nails, and sebaceous, ceruminous and sweat glands."},{"front":"Skin blood supply","back":"About one-third of circulating blood."},{"front":"Epidermis / dermis / hypodermis","back":"Epithelial outer layer / dense connective tissue / fatty subcutaneous layer."},{"front":"Keratinization","back":"Cells move up, lose water, fill with keratin and die."},{"front":"Epidermal layers (out to in)","back":"Corneum, lucidum, granulosum, spinosum, germinativum (basale)."},{"front":"Stratum corneum","back":"Outermost; dead keratinized cells; barrier to light, heat, microbes and chemicals."},{"front":"Stratum lucidum","back":"The clear layer."},{"front":"Stratum spinosum","back":"Spiny-looking polyhedral cells."},{"front":"Stratum germinativum","back":"Deepest; only dividing layer; contains melanocytes."},{"front":"Melanocytes","back":"Make melanin, the pigment of skin color."},{"front":"Cyanosis","back":"Bluish skin from lack of oxygen in the blood."},{"front":"Callus","back":"Thickened skin from friction."},{"front":"Hair layers","back":"Cuticle, cortex, medulla."},{"front":"Hair shaft / root","back":"Visible part / part in the follicle."},{"front":"Arrector pili","back":"Smooth muscle on the follicle; causes goose flesh."},{"front":"Lunula","back":"White crescent at the base of the nail."},{"front":"Sebum","back":"Oil from sebaceous glands that lubricates skin and hair."},{"front":"Cerumen","back":"Earwax from ceruminous glands."},{"front":"Eccrine vs apocrine","back":"Most numerous, cooling / armpit and groin, odor, no cooling."},{"front":"Main salt in sweat","back":"Sodium chloride."},{"front":"Burn degrees","back":"1st: epidermis; 2nd: epidermis + dermis with blisters; 3rd: both destroyed."},{"front":"Warts","back":"Caused by human papillomavirus."},{"front":"Psoriasis","back":"Red patches with thick, dry, silvery scales."},{"front":"Vitiligo","back":"Irregular patches lacking pigment."},{"front":"Macule","back":"Flat, small discoloration even with the skin."},{"front":"Vitamin D and skin","back":"Sunlight helps skin make the precursor; liver and kidneys finish it."}],"quiz":[{"q":"The skin receives approximately ____________________ of all the blood circulating through the body.","o":["one-fifth","one-third","one-fourth","one-half"],"a":1,"e":"Checked answer, not from an official key. Chapter 6 says the skin receives approximately one-third of all the blood circulating through the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Cells that are responsible for producing skin colour are called ______________.","o":["keratinocytes","melanocytes","fibroblasts","Meissner’s corpuscles"],"a":1,"e":"Checked answer, not from an official key. Chapter 6 says melanocytes are responsible for producing skin color. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The visible portion of the hair is called the _____________________________.","o":["cuticle","medulla","shaft","root"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 says the shaft is the visible portion of the hair. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The second layer of the skin is the____________________________ .","o":["epidermis","hypodermis","keratin layer","dermis"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says the epidermis sits on top of the second layer of the skin, the dermis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The subcutaneous tissue that contains a lot of fat is the _________________________ .","o":["peridermis","dermis","hypodermis","epidermis"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 says the subcutaneous tissue, usually containing fat, is sometimes called the hypodermis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The most common and most numerous type of sweat glands is the _________________________ gland.","o":["holocrine","sebaceous","eccrine","apocrine"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 says the most common and most numerous sweat glands are eccrine sweat glands. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Which structure is a bundle of smooth muscle fibers that are attached to the hair follicle?","o":["cuticle","root","medulla","arrector pili"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says the arrector pili is a bundle of smooth muscle fibers attached to the hair follicle. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Which condition is caused by human papillomavirus?","o":["cold sores","shingles","impetigo","warts"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says warts are caused by human papillomavirus. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The primary salt in sweat is _______________________________.","o":["potassium chloride","sodium chloride","sodium bromide","calcium chloride"],"a":1,"e":"Checked answer, not from an official key. Chapter 6 says the chief salt in sweat is sodium chloride. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Which disease results in irregular patches of skin that lack pigmentation?","o":["vitiligo","shingles","alopecia","impetigo"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 says vitiligo results in irregular patches of skin completely lacking pigment. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The stratum ___________________ is commonly called the clear layer.","o":["lucidum","corneum","spinosum","granulosum"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 says the stratum lucidum is commonly called the clear layer. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Each individual _______________________ is composed of the cuticle, the cortex, and the medulla.","o":["hair","arrector pili","skin","nail"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 says each individual hair is composed of the cuticle, the cortex and the medulla. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The skin layer that functions as a physical barrier to light and heat waves is the stratum ____________________.","o":["germinativum","spinosum","corneum","lucidum"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 says the stratum corneum is a physical barrier to light and heat waves, microorganisms and most chemicals. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The nail grows from the nail ______________.","o":["root","bed","body","lunula"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 describes the nail root as the part of the nail attached to the nail bed, from which the nail grows. The sentence could be read as pointing to the bed, but standard anatomy sources place nail growth in the matrix under the root, so \"root\" is the best answer. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"A burn that involves complete destruction of both the epidermis and the dermis is a ___________- degree burn.","o":["fourth","first","second","third"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says in third-degree (full-thickness) burns the epidermis and dermis are completely destroyed. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"A flat, small discoloration of the skin that is even with the skin surface is known as a _________________.","o":["papule","wheal","macule","pustule"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 defines a macule as a flat, small discoloration of the skin that is even with the skin surface. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The oily substance responsible for lubricating the surface of the skin is called __________________.","o":["sebum","sweat","milk","cerumen"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 says sebum is the oily substance responsible for lubricating the surface of the skin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The condition caused by lack of oxygen in the blood that gives the skin a bluish coloration is called __________________.","o":["alopecia","shingles","cyanosis","blushing"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 says cyanosis is the bluish discoloration of skin caused by lack of oxygen in the blood. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The stratum __________________________ is the outermost layer of the skin.","o":["germinativum","corneum","spinosum","granulosum"],"a":1,"e":"Checked answer, not from an official key. Chapter 6 says the stratum corneum forms the outermost layer of the epidermis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Which skin layer consists of spiny-shaped cells that are polyhedron in structure?","o":["stratum germinativum","stratum granulosum","stratum lucidum","stratum spinosum"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says the stratum spinosum has several layers of spiny-shaped cells that are polyhedral in structure. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"A thickened area of the skin that results from excess friction is known as a __________________________.","o":["papilla","nail body","Langerhans cell","callus"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says excessive abrasion or friction produces a thickened area called a callus. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"First-degree burns only damage the epidermis.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 says first-degree burns involve just the epidermis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Psoriasis is a common chronic skin disorder that is characterized by red patches covered by thick, dry, and silvery scales.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 describes psoriasis as a common chronic skin disorder with red patches covered with thick, dry, silvery scales. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Melanocytes produce the pigment keratin.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Melanocytes produce the pigment melanin. Keratin is a protein made as cells keratinize. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Sweat glands produce sebum.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Sebum is made by sebaceous glands. Sweat glands make sweat. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."}],"caseStudy":{"title":"A hot, humid shift","scenario":"During several hours of work in warm humid conditions, a person’s skin becomes flushed and wet. Sweat drips from the surface, but cooling feels limited. A small friction callus is also visible on the palm.","prompts":["Trace the negative-feedback responses involving dermal vessels and eccrine glands.","Explain why high humidity limits cooling even when sweat production is high.","Identify the epidermal process responsible for the callus and explain its protective tradeoff.","List contextual factors needed before offering individualized fluid or electrolyte guidance."],"takeaway":"Skin observations become meaningful when layer anatomy, gland routes, environmental physics, and whole-body context are combined—without turning a visible sign into a diagnosis."},"perStepChapter":true},{"n":7,"title":"The Skeletal System","kicker":"Lesson 7 of your course, built from Chapter 7 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"70–90 minutes","steps":[{"id":"ap7-1","chapter":"What the skeleton does","title":"What the skeleton does","teach":["The skeletal system includes all the bones of the body plus their cartilage, tendons and ligaments. Bones are living tissue; their hardness comes from mineral salts like calcium phosphate in the matrix. The adult skeleton typically has 206 named bones.","It has five functions: support, protection of vital organs, movement (bones act as levers for muscles), making blood cells (hematopoiesis, mainly in red marrow), and storage of minerals (calcium and phosphorus) and fat.","Ligaments attach bone to bone. Tendons attach muscle to bone. Cartilage gives a smooth surface at joints and is the environment in which fetal bone develops."],"visual":{"kind":"hub","title":"Five functions of the skeleton","items":[{"label":"Support","detail":"Holds up muscles, vessels, nerves, fat and skin."},{"label":"Protection","detail":"Brain, spinal cord, heart and lungs."},{"label":"Movement","detail":"Bones are levers pulled by muscles."},{"label":"Blood cell formation","detail":"Hematopoiesis in red bone marrow."},{"label":"Storage","detail":"Calcium, phosphorus and fat."}]},"act":{"type":"choice","prompt":"Making blood cells in red bone marrow is called:","options":[{"label":"Hematopoiesis","correct":true,"feedback":"Right."},{"label":"Ossification","correct":false,"feedback":"Ossification is the formation of bone."},{"label":"Osteomalacia","correct":false,"feedback":"That’s softening of the bones in adults."}]}},{"id":"ap7-2","chapter":"Bone cells and growth","title":"Bone cells and growth","teach":["Osteoblasts are bone-forming cells that develop from osteoprogenitor cells under the periosteum (the fibrovascular membrane covering bone) and in the endosteum (lining the medullary cavity). When an osteoblast is surrounded by matrix it becomes an osteocyte, a mature bone cell.","Osteoclasts, which come from immune cells, reabsorb (remove) bone during remodeling, such as after a break or when braces straighten a bow-legged child’s legs.","Strain builds bone: the more stress on a bone, the more bone is deposited. That’s why the heel bone is so large, why bones in a cast weaken, and why exercise strengthens them.","Bones grow in length at the epiphyseal plate until about 15 in girls and 16 in boys; maturation continues to about 21."],"act":{"type":"sort","prompt":"Which bone cell?","categories":["Osteoblast","Osteocyte","Osteoclast"],"items":[{"label":"Forms new bone","category":0,"feedback":"Osteoblasts build bone."},{"label":"Mature bone cell in a lacuna","category":1,"feedback":"Osteocyte."},{"label":"Reabsorbs bone during remodeling","category":2,"feedback":"Osteoclast."},{"label":"Comes from immune system cells","category":2,"feedback":"Osteoclasts do."}]}},{"id":"ap7-3","chapter":"Ossification","title":"Ossification","teach":["Ossification is the formation of bone by osteoblasts. The fetal skeleton is mostly cartilage at three months; bone forms over the remaining months. Cartilage doesn’t turn into bone; it’s the environment where bone develops.","Intramembranous ossification replaces connective tissue membranes with bone. Only the cranial bones form this way. The unfinished membranes are the fontanelles, or soft spots, on a baby’s skull.","Endochondral ossification forms all the other bones, using cartilage as the environment (endo = inside, chondro = cartilage).","Calcium balance is controlled by hormones: calcitonin (thyroid) stores calcium in bone; parathormone (parathyroids) releases it into the blood."],"act":{"type":"sort","prompt":"Which type of ossification?","categories":["Intramembranous","Endochondral"],"items":[{"label":"Cranial bones","category":0,"feedback":"Only the skull forms this way."},{"label":"Femur","category":1,"feedback":"Long bones form in cartilage."},{"label":"Leaves fontanelles in a newborn","category":0,"feedback":"The soft spots."},{"label":"Cartilage is the environment for bone","category":1,"feedback":"Endo-chondral."}]}},{"id":"ap7-4","chapter":"Compact bone and the osteon","title":"Compact bone and the osteon","teach":["Compact bone is dense and strong. Its unit is the haversian system, or osteon, named after Clopton Havers.","At its center is the haversian (central) canal carrying blood vessels. Around it are concentric rings of bone, each called a lamella. Between the lamellae are tiny cavities, lacunae, each holding an osteocyte. Tiny canals called canaliculi connect the lacunae to each other and to the central canal. Volkmann’s (perforating) canals run crosswise and also carry vessels.","Tissue fluid flows through all these canals, bringing oxygen and nutrients to the osteocytes and carrying away waste."],"visual":{"kind":"hub","title":"Parts of an osteon","items":[{"label":"Central (haversian) canal","detail":"Runs lengthwise; blood vessels."},{"label":"Lamella","detail":"One concentric ring of bone."},{"label":"Lacuna","detail":"Small cavity holding an osteocyte."},{"label":"Canaliculi","detail":"Tiny canals linking lacunae."},{"label":"Perforating (Volkmann’s) canal","detail":"Runs crosswise; blood vessels."}]},"act":{"type":"sort","prompt":"Match each osteon part to its description.","categories":["Lamella","Lacuna","Canaliculi","Central canal"],"items":[{"label":"A concentric ring of bone","category":0,"feedback":"Lamella."},{"label":"Cavity holding an osteocyte","category":1,"feedback":"Lacuna."},{"label":"Tiny canals connecting the cavities","category":2,"feedback":"Canaliculi."},{"label":"Center of the osteon, with blood vessels","category":3,"feedback":"Haversian (central) canal."}]}},{"id":"ap7-5","chapter":"Spongy bone and marrow","title":"Spongy bone and marrow","teach":["Cancellous (spongy) bone is at the ends of long bones and the center of other bones. It’s a meshwork of bony plates called trabeculae, strong but light, with marrow in the spaces.","Red bone marrow makes red and white blood cells and platelets. In adults it’s in the ribs, vertebrae, sternum and pelvis.","Yellow bone marrow is mostly fat and fills the medullary cavity in the shafts of long bones."],"act":{"type":"choice","prompt":"What fills the medullary cavity of a long bone in an adult?","options":[{"label":"Yellow bone marrow (mostly fat)","correct":true,"feedback":"Right."},{"label":"Red bone marrow","correct":false,"feedback":"In adults, red marrow is mainly in the ribs, vertebrae, sternum and pelvis."},{"label":"Cartilage","correct":false,"feedback":"Cartilage covers joint surfaces."}]}},{"id":"ap7-6","chapter":"Bone shapes and the long bone","title":"Bone shapes and the long bone","teach":["Long bones are longer than they are wide (femur, humerus, and also metacarpals and phalanges). Short bones lack a long axis (carpals, tarsals). Flat bones are thin, usually curved, and found where muscles need wide attachment or soft organs need protection (sternum, ribs, scapula, skull bones). Irregular bones have odd shapes (vertebrae, ear ossicles). Sesamoid bones are small, round and inside tendons; the patella is the largest.","A long bone has a diaphysis (shaft, mostly compact bone), a metaphysis at each flared end, and an epiphysis at each end, separated by the epiphyseal (growth) line. The interior of the shaft is the medullary cavity. The periosteum covers the outside."],"act":{"type":"sort","prompt":"Classify each bone by shape.","categories":["Long","Short","Flat","Irregular","Sesamoid"],"items":[{"label":"Femur","category":0,"feedback":"Long."},{"label":"Carpals","category":1,"feedback":"Short."},{"label":"Sternum","category":2,"feedback":"Flat."},{"label":"Vertebra","category":3,"feedback":"Irregular."},{"label":"Patella","category":4,"feedback":"The largest sesamoid bone."},{"label":"Scapula","category":2,"feedback":"Flat."}]}},{"id":"ap7-7","chapter":"Bone markings","title":"Bone markings","teach":["Processes stick out: a spine is sharp and slender; a condyle is a rounded knuckle at a joint; a tubercle is a small round bump; a trochanter is a very large projection (femur); a crest is a narrow ridge (iliac crest); a head is an enlarged end, joined to the rest by a neck.","Fossae are depressions or openings: a suture is a narrow junction between skull bones; a foramen is a hole for vessels and nerves; a meatus is a tube-like canal; a sinus is a cavity in a bone; a sulcus is a groove."],"act":{"type":"sort","prompt":"Process (projection) or fossa (depression/opening)?","categories":["Process","Fossa"],"items":[{"label":"Condyle","category":0,"feedback":"A rounded projection."},{"label":"Foramen","category":1,"feedback":"An opening."},{"label":"Trochanter","category":0,"feedback":"A very large projection."},{"label":"Sinus","category":1,"feedback":"A cavity."},{"label":"Crest","category":0,"feedback":"A ridge."},{"label":"Meatus","category":1,"feedback":"A canal."}]}},{"id":"ap7-8","chapter":"Fractures and bone disorders","title":"Fractures and bone disorders","teach":["A fracture is a break in a bone or its cartilage. Open (compound) fractures break through the skin; closed (simple) ones don’t. A greenstick fracture is incomplete; a comminuted fracture shatters into pieces.","Rickets (children) and osteomalacia (adults) are caused by a lack of calcium, phosphorus or vitamin D/sunlight; bones stay soft.","Osteoporosis is loss of bone mass with more fractures, linked to falling estrogen. Paget’s disease is a common nonmetabolic bone disease with irregular thickening and softening of bones. Acromegaly is caused by an overactive anterior pituitary making too much growth hormone, widening the bones of the hands, face, jaws and feet. Spina bifida is a defect in the vertebral arch."],"act":{"type":"sort","prompt":"Match the disorder to its cause or sign.","categories":["Rickets","Osteoporosis","Paget’s disease","Acromegaly"],"items":[{"label":"Children lacking vitamin D and calcium","category":0,"feedback":"Rickets."},{"label":"Loss of bone mass after menopause","category":1,"feedback":"Osteoporosis."},{"label":"Irregular thickening and softening of bone","category":2,"feedback":"Paget’s disease."},{"label":"Too much growth hormone in adults","category":3,"feedback":"Acromegaly."}]}},{"id":"ap7-9","chapter":"The skeleton: axial and appendicular","title":"The skeleton: axial and appendicular","teach":["The axial skeleton is the skull (28 bones, cranial and facial), the hyoid, the vertebrae (26), the ribs (24) and the sternum.","The appendicular skeleton is the upper extremities (64 bones, including the shoulder girdles) and the lower extremities (62 bones, including the pelvic girdle)."],"act":{"type":"sort","prompt":"Axial or appendicular?","categories":["Axial","Appendicular"],"items":[{"label":"Skull","category":0,"feedback":"Axial."},{"label":"Ribs","category":0,"feedback":"Axial."},{"label":"Femur","category":1,"feedback":"Appendicular."},{"label":"Scapula","category":1,"feedback":"Part of the shoulder girdle."},{"label":"Vertebrae","category":0,"feedback":"Axial."},{"label":"Hip bones","category":1,"feedback":"Pelvic girdle."}]}},{"id":"ap7-10","chapter":"Cranial bones","title":"Cranial bones","teach":["The cranium protects the brain and sense organs. Its bones are joined by immovable sutures.","Frontal: the forehead and roof of the orbits; joins the parietals at the coronal suture. Parietals (2): the upper sides and roof; joined at the sagittal suture. Occipital: the back and base; joins the parietals at the lambdoid suture and has the foramen magnum, the large opening where the spinal cord connects to the brain. Its occipital condyles rest on the atlas.","Temporals (2): the lower sides; each encloses an ear and has the mastoid process and the styloid process. Sphenoid: looks like a butterfly and anchors all the cranial bones together. Ethmoid: supports the nasal cavities; the lightest cranial bone.","The ear ossicles are the malleus, incus and stapes. Wormian bones sit in sutures and aren’t counted."],"act":{"type":"sort","prompt":"Which cranial bone?","categories":["Frontal","Occipital","Temporal","Sphenoid","Ethmoid"],"items":[{"label":"Forms the forehead","category":0,"feedback":"Frontal."},{"label":"Has the foramen magnum","category":1,"feedback":"Occipital."},{"label":"Encloses the ear; has the mastoid process","category":2,"feedback":"Temporal."},{"label":"Butterfly-shaped anchor for the cranial bones","category":3,"feedback":"Sphenoid."},{"label":"Lightest cranial bone; supports the nasal cavities","category":4,"feedback":"Ethmoid."}]}},{"id":"ap7-11","chapter":"Facial bones and the hyoid","title":"Facial bones and the hyoid","teach":["Facial bones are joined by sutures, except the mandible, which moves.","Nasal bones (2) form the bridge of the nose. Palatine bones (2) form the back of the hard palate. Maxillae (2) form the upper jaw and hold the upper teeth; if they don’t fuse, the result is a cleft palate. Zygomatic (malar) bones (2) form the cheeks. Lacrimal bones (2) hold the tear sac. Nasal conchae (turbinates) warm and filter air. The vomer forms the lower nasal septum.","The mandible is the strongest and longest bone of the face and forms the lower jaw.","The hyoid bone supports the tongue and doesn’t articulate with any other bone; it hangs from the styloid processes by ligaments."],"act":{"type":"choice","prompt":"Which is the strongest and longest bone of the face?","options":[{"label":"Mandible","correct":true,"feedback":"Right. It forms the lower jaw."},{"label":"Maxilla","correct":false,"feedback":"The maxillae form the upper jaw."},{"label":"Zygomatic","correct":false,"feedback":"The zygomatic bones are the cheekbones."}]}},{"id":"ap7-12","chapter":"The vertebral column","title":"The vertebral column","teach":["The spine has 26 vertebrae separated by intervertebral disks of fibrocartilage: 7 cervical, 12 thoracic, 5 lumbar, plus the sacrum (5 fused) and the coccyx (4 fused).","A typical vertebra has a body, a neural arch around the vertebral foramen (for the spinal cord), a spinous process and two transverse processes, and articular processes.","The atlas (C1) holds up the head; the axis (C2) is the pivot it rotates on. Thoracic vertebrae have long downward spines and facets for ribs. Lumbar vertebrae are the largest and strongest.","Abnormal curves: kyphosis (hunchback, upper thoracic), lordosis (swayback, lumbar) and scoliosis (sideways curve, usually thoracic)."],"mnemonic":{"cue":"Breakfast at 7, lunch at 12, dinner at 5","explanation":"7 cervical, 12 thoracic, 5 lumbar vertebrae."},"act":{"type":"sort","prompt":"Match the spinal curvature to the region.","categories":["Kyphosis","Lordosis","Scoliosis"],"items":[{"label":"Exaggerated upper thoracic curve (hunchback)","category":0,"feedback":"Kyphosis."},{"label":"Exaggerated lumbar curve (swayback)","category":1,"feedback":"Lordosis."},{"label":"Sideways curve","category":2,"feedback":"Scoliosis."}]}},{"id":"ap7-13","chapter":"The thoracic cage","title":"The thoracic cage","teach":["The rib cage (sternum, costal cartilages, ribs and thoracic vertebrae) protects the heart and lungs.","The sternum, or breastbone, is shaped like a sword: the manubrium (handle), the gladiolus or body (blade) and the xiphoid process (tip).","There are 12 pairs of ribs. The upper seven pairs attach directly to the sternum: true ribs. The lower five pairs are false ribs. Pairs 8 to 10 attach indirectly through the 7th rib’s cartilage, and pairs 11 and 12 don’t attach in front at all: floating ribs."],"act":{"type":"sort","prompt":"What kind of rib?","categories":["True ribs","False ribs (attach indirectly)","Floating ribs"],"items":[{"label":"Pairs 1–7","category":0,"feedback":"Attach directly to the sternum."},{"label":"Pairs 8–10","category":1,"feedback":"Attach through the 7th rib’s cartilage."},{"label":"Pairs 11–12","category":2,"feedback":"No front attachment."}]}},{"id":"ap7-14","chapter":"Upper extremity","title":"Upper extremity","teach":["The shoulder (pectoral) girdle is the clavicle (collarbone) and scapula (shoulder blade). The scapula’s glenoid fossa receives the head of the humerus.","The humerus is the largest and longest bone of the upper arm. The ulna is the longer, medial forearm bone; its olecranon process is the elbow (\"funny bone\"). The radius is the shorter, lateral forearm bone.","The wrist has 8 carpals in two rows (pisiform, triquetral, lunate, scaphoid; hamate, capitate, trapezoid, trapezium). The palm has 5 metacarpals. Each finger has 3 phalanges; the thumb has 2."],"act":{"type":"sort","prompt":"Where is each bone?","categories":["Arm","Forearm","Wrist","Hand"],"items":[{"label":"Humerus","category":0,"feedback":"Upper arm."},{"label":"Ulna","category":1,"feedback":"Medial forearm."},{"label":"Radius","category":1,"feedback":"Lateral forearm."},{"label":"Carpals","category":2,"feedback":"Wrist bones."},{"label":"Metacarpals","category":3,"feedback":"Palm."}]}},{"id":"ap7-15","chapter":"Pelvic girdle and lower extremity","title":"Pelvic girdle and lower extremity","teach":["The pelvic girdle is the two hip (coxal) bones, which meet at the front at the pubic symphysis and at the back with the sacrum. Each hip bone is three fused parts: the ilium (largest, with the iliac crest), the ischium (strongest; you sit on its tuberosity) and the pubis. The obturator foramen is the largest foramen in the body. The acetabulum is the socket for the femur.","The femur is the largest and heaviest bone. The patella (kneecap) is the largest sesamoid bone. The tibia (shinbone) is the larger lower-leg bone; the fibula is the slender lateral one.","The ankle has 7 tarsals; the calcaneus (heel) is the largest. The foot has 5 metatarsals and 14 phalanges.","The foot has two longitudinal arches and one transverse arch. The medial longitudinal arch is the highest. Flat foot is pes planus."],"act":{"type":"sort","prompt":"Match the bone to its description.","categories":["Femur","Patella","Tibia","Calcaneus"],"items":[{"label":"Largest and heaviest bone","category":0,"feedback":"Femur."},{"label":"Largest sesamoid bone","category":1,"feedback":"Patella."},{"label":"Shinbone","category":2,"feedback":"Tibia."},{"label":"Heel bone; largest tarsal","category":3,"feedback":"Calcaneus."}]}},{"id":"ap7-16","chapter":"Bones and aging","title":"Bones and aging","teach":["With age, less protein matrix forms and calcium is lost, so bones break more easily. Less collagen in tendons and ligaments makes the skeleton stiffer.","People \"shrink\" because the intervertebral disks thin: from about age 40, roughly half an inch every 20 years. Calcium-rich food and regular exercise like walking help."],"act":{"type":"choice","prompt":"Why do people lose height with age, according to the textbook?","options":[{"label":"The intervertebral disks thin","correct":true,"feedback":"Right."},{"label":"The femur gets shorter","correct":false,"feedback":"It’s the disks in the spine."},{"label":"The skull shrinks","correct":false,"feedback":"It’s the disks."}]}}],"flashcards":[{"front":"Skeletal system","back":"All bones plus their cartilage, tendons and ligaments."},{"front":"Number of bones","back":"206 named bones."},{"front":"Hematopoiesis","back":"Making blood cells, chiefly in red bone marrow."},{"front":"Ligament / tendon","back":"Bone to bone / muscle to bone."},{"front":"Periosteum","back":"Fibrovascular membrane covering bone."},{"front":"Osteoblast / osteocyte / osteoclast","back":"Builds bone / mature bone cell / reabsorbs bone."},{"front":"Ossification","back":"The formation of bone."},{"front":"Intramembranous vs endochondral","back":"Cranial bones only / all other bones, in cartilage."},{"front":"Calcitonin / parathormone","back":"Stores calcium in bone / releases it to the blood."},{"front":"Osteon parts","back":"Central canal, lamellae, lacunae (osteocytes), canaliculi, perforating canals."},{"front":"Lamella","back":"A concentric ring of bone around the central canal."},{"front":"Medullary cavity","back":"Interior of a long bone’s shaft, with yellow marrow."},{"front":"Diaphysis / epiphysis","back":"Shaft / end of a long bone."},{"front":"Flat bones","back":"Thin; for muscle attachment or protection (sternum, ribs, scapula, skull)."},{"front":"Fracture","back":"A break in a bone or its cartilage."},{"front":"Rickets","back":"Soft bones in children from lack of calcium, phosphorus or vitamin D."},{"front":"Paget’s disease","back":"Nonmetabolic disease with irregular thickening and softening of bone."},{"front":"Acromegaly","back":"Too much growth hormone from the anterior pituitary in adults."},{"front":"Foramen magnum","back":"Large opening in the occipital bone for the spinal cord."},{"front":"Sphenoid","back":"Butterfly-shaped bone anchoring the cranial bones."},{"front":"Mandible","back":"Strongest and longest facial bone; lower jaw."},{"front":"Vertebrae","back":"7 cervical, 12 thoracic, 5 lumbar, sacrum, coccyx (26 total)."},{"front":"Lordosis / kyphosis / scoliosis","back":"Lumbar swayback / thoracic hunchback / sideways curve."},{"front":"True / false / floating ribs","back":"Pairs 1–7 / 8–12 / 11–12."},{"front":"Sternum parts","back":"Manubrium, gladiolus (body), xiphoid process."},{"front":"Humerus","back":"Largest and longest bone of the upper arm."},{"front":"Carpals / tarsals","back":"Wrist bones / ankle bones."},{"front":"Pelvic girdle","back":"The two hip bones (ilium, ischium, pubis fused)."},{"front":"Patella","back":"Kneecap; largest sesamoid bone."},{"front":"Highest arch of the foot","back":"Medial longitudinal arch."}],"quiz":[{"q":"The breaking of a bone or the associated cartilage is called a(n) __________________________.","o":["ricket","osteomalacia","epiphysis","fracture"],"a":3,"e":"Checked answer, not from an official key. Chapter 7 says the breaking of bone or associated cartilage is known as a fracture. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The _____________________ system includes all the bones of the body and their associated cartilage, tendons, and ligaments.","o":["integumentary","urinary","skeletal","muscular"],"a":2,"e":"Checked answer, not from an official key. Chapter 7 says the skeletal system includes all the bones of the body and their associated cartilage, tendons and ligaments. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The _______________ bone is the strongest and longest bone of the face and forms the lower jaw.","o":["maxillary","sphenoid","mandible","zygomatic"],"a":2,"e":"Checked answer, not from an official key. Chapter 7 says the mandible is the strongest and longest bone of the face. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Overactivity of the anterior pituitary gland results in excessive secretions of growth hormone and which chronic condition?","o":["Acromegaly","Spina bifida","Cleft palate","Osteomalacia"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says acromegaly is a chronic condition caused by overactivity of the anterior pituitary, resulting in excessive growth hormone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Abnormal curvature of the lumbar portion of the spine is called _________________.","o":["lordosis","scoliosis","kyphosis","rickets"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says lordosis, or swayback, is an abnormal accentuated lumbar curvature. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Which disease occurs in children and is caused by deficiencies in calcium and vitamin D?","o":["Fracture","Rickets","Osteoporosis","Diaphysis"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says rickets occurs in children and is caused by deficiencies in calcium, phosphorus or vitamin D. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The term for the formation of bone is called _________________________.","o":["calcification","ossification","fontanellation","chondrofication"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 defines ossification as the formation of bone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The ____________________ bone looks like a butterfly and acts as an anchor binding all of the cranial bones together.","o":["frontal","sphenoid","occipital","temporal"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says the sphenoid looks like a butterfly from below and acts as an anchor binding all the cranial bones together. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The _____________________ is the largest and longest bone of the upper arm.","o":["ulna","humerus","tibia","radius"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says the humerus is the largest and longest bone of the upper arm. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The highest arch of the foot is the _____________________ arch.","o":["longitudinal","transverse","medial longitudinal","medial"],"a":2,"e":"Checked answer, not from an official key. Chapter 7 says the medial longitudinal arch is the highest arch of the foot. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The central canal of an osteon is surrounded by concentric rings of bone, each layer of which is called a(n) ______________________________.","o":["canaliculus","lamella","lacuna","perforating canal"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says the central canals are surrounded by concentric rings of bone, each called a lamella. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Which bones are thin and typically found where there is a need for extensive muscle attachment or protection for soft or vital parts of the body?","o":["Long","Flat","Short","Irregular"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says flat bones are thin bones found where there is a need for extensive muscle attachment or protection for soft or vital parts. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The _____________________ girdle is made up of the two hip bones.","o":["pectoral","pubic","iliac","pelvic"],"a":3,"e":"Checked answer, not from an official key. Chapter 7 says the pelvic girdle is made up of the two hip (coxal) bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The fibrovascular membrane that covers bone is called the _________________________.","o":["periosteum","perichondrium","endosteum","osseus"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 calls the fibrovascular membrane that covers a bone the periosteum. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The occipital bone has a large opening called the _____________________ through which the spinal cord connects to the brain.","o":["mental foramen","occipital condyle","foramen magnum","temporal condyle"],"a":2,"e":"Checked answer, not from an official key. Chapter 7 says the occipital bone has a large opening called the foramen magnum, through which the spinal cord connects with the brain. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The upper seven pairs of ribs articulate directly with the sternum and are called _____________ ribs.","o":["true","free","floating","false"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says the upper seven pairs of ribs articulate directly with the sternum and are called true ribs. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Which common non-metabolic disease presents with irregular thickening and softening of the bones?","o":["Gigantism","Paget’s disease","Osteoporosis","Rickets"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says Paget’s disease is a common nonmetabolic bone disease with irregular thickening and softening of the bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The type of bone cell responsible for the reabsorption of bone is called an ____________________.","o":["osteocyte","osteoblast","osteogenic cell","osteoclast"],"a":3,"e":"Checked answer, not from an official key. Chapter 7 says osteoclasts are responsible for the reabsorption of bone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The breastbone is called the _____________________.","o":["scapula","clavicle","rib","sternum"],"a":3,"e":"Checked answer, not from an official key. Chapter 7 says the sternum is also known as the breastbone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The ______________ (kneecap) is the largest sesamoid bone in the human body.","o":["patella","scapula","fibula","tibia"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says the patella, or kneecap, is the largest of the sesamoid bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The interior of the shaft of long bone contains the ______________________________.","o":["medullary cavity","cortical cavity","medullary sinus","cortical sinus"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says the interior of the shaft of a long bone is the medullary cavity. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The tiny cavities in the osteon called lacunae contain _____________________.","o":["osteocytes","osteoblasts","osteoclasts","chondroblasts"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says each lacuna contains an osteocyte, or bone cell. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Tendons are tough connective tissue structures that attach bones to bones.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Tendons attach muscle to bone. Ligaments attach bone to bone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The bones of the wrist are called tarsals.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. The wrist bones are carpals. Tarsals are the ankle bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"There are 14 thoracic vertebrae.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. There are 12 thoracic vertebrae. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."}],"caseStudy":{"title":"From a fall to a systems explanation","scenario":"An older adult reports a recent fall and asks whether drinking more milk alone will “rebuild” every weak bone.","prompts":["Name the skeletal functions relevant to the fall.","Explain remodeling using osteoblasts and osteoclasts.","Identify the limits of a one-food explanation.","State which concerns require clinical assessment rather than nutrition education alone."],"takeaway":"Use anatomy to explain the system, support adequate nutrition without promises, and keep fracture and bone-density assessment within clinical care."},"perStepChapter":true},{"n":8,"title":"The Articular System","kicker":"Classify joints by structure and degree of movement.","duration":"60–80 minutes","steps":[{"id":"l8-m1","chapter":"A map of every joint","chapterSummary":"Start with the two classification questions: what connects the bones, and how much can they move?","title":"Structural and functional classifications","highYield":"Structure and movement are two different naming systems.","teach":["A joint, or articulation, is where two or more skeletal elements meet. Structural classification asks what material joins the bones: fibrous tissue, cartilage, or a fluid-filled synovial cavity.","Functional classification asks how much movement is possible. A synarthrosis is essentially immovable, an amphiarthrosis allows limited movement, and a diarthrosis moves freely. Most limb joints are diarthroses and structurally synovial."],"keyPoints":["Fibrous, cartilaginous and synovial are structural groups.","Synarthroses do not move.","Amphiarthroses move slightly.","Diarthroses move freely."],"visual":{"title":"Two lenses","kind":"concept-map","items":[{"label":"Structure","detail":"What physically joins the bones?"},{"label":"Function","detail":"How much movement occurs?"},{"label":"Key pairing","detail":"Synovial joints are usually diarthroses"}]},"mnemonic":{"title":"SAD movement scale","cue":"Synarthrosis · Amphiarthrosis · Diarthrosis","explanation":"Think still, a little, dynamic."},"goodToKnow":"The two systems overlap, but their terms are not interchangeable.","act":{"type":"choice","prompt":"Which functional class describes a freely movable shoulder joint?","options":[{"label":"Diarthrosis","correct":true,"feedback":"Correct. A freely movable joint is a diarthrosis."},{"label":"Amphiarthrosis","correct":false,"feedback":"That class permits only slight movement."},{"label":"Synarthrosis","correct":false,"feedback":"That class is essentially immovable."}]}},{"id":"l8-m2","chapter":null,"chapterSummary":null,"title":"Fibrous and cartilaginous joints","highYield":"Less motion generally brings more stability.","teach":["Fibrous joints are united by dense connective tissue. Skull sutures are nearly immovable; a syndesmosis uses a ligament or membrane between bones; a gomphosis anchors a tooth in its socket.","Cartilaginous joints join bones with cartilage. A synchondrosis uses hyaline cartilage, as in an epiphyseal plate before it closes. A symphysis uses fibrocartilage and allows limited movement, as at the pubic symphysis or between vertebral bodies."],"keyPoints":["Suture and gomphosis are fibrous.","Syndesmosis uses fibrous tissue.","Synchondrosis uses hyaline cartilage.","Symphysis uses fibrocartilage."],"visual":{"title":"Low-motion joints","kind":"concept-map","items":[{"label":"Suture","detail":"Interlocking skull bones"},{"label":"Gomphosis","detail":"Tooth in socket"},{"label":"Synchondrosis","detail":"Hyaline cartilage bridge"},{"label":"Symphysis","detail":"Fibrocartilage pad"}]},"mnemonic":{"title":"CH = cartilage","cue":"SynCHondrosis uses hyaline Cartilage","explanation":"The shared sound helps separate it from a symphysis."},"goodToKnow":"The former growth plate between a diaphysis and epiphysis is a classic synchondrosis.","act":{"type":"choice","prompt":"Which joint is united by fibrocartilage and allows slight movement?","options":[{"label":"Symphysis","correct":true,"feedback":"Correct. Symphyses are cartilaginous amphiarthroses."},{"label":"Suture","correct":false,"feedback":"A suture is fibrous and generally immovable."},{"label":"Ball-and-socket","correct":false,"feedback":"That is a freely movable synovial form."}]}},{"id":"joint-language-match","title":"Match it: Two lenses","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["What physically joins the bones?","How much movement occurs?","Synovial joints are usually diarthroses"],"items":[{"label":"Structure","category":0,"feedback":"Structure: What physically joins the bones?"},{"label":"Function","category":1,"feedback":"Function: How much movement occurs?"},{"label":"Key pairing","category":2,"feedback":"Key pairing: Synovial joints are usually diarthroses"}]}},{"id":"l8-m3","chapter":"The synovial-joint toolkit","chapterSummary":"A cavity, cartilage, capsule and lubricant create controlled, low-friction motion.","title":"Inside a synovial joint","highYield":"Articular cartilage reduces friction; fluid lubricates; ligaments guide and restrain.","teach":["At a synovial joint, the bone ends are capped by smooth articular cartilage and separated by a cavity. A capsule encloses the joint; its fibrous outer layer stabilizes while its inner synovial membrane produces synovial fluid.","Ligaments connect bone to bone. Bursae are small fluid-filled sacs positioned where skin, tendon, ligament, or bone might rub. Menisci or discs in some joints improve fit and distribute load."],"keyPoints":["Articular cartilage covers opposing bone ends.","Synovial fluid lubricates and nourishes cartilage.","Ligaments connect bone to bone.","Bursae reduce friction at pressure points."],"visual":{"title":"Synovial layers","kind":"concept-map","items":[{"label":"Cartilage","detail":"Smooth bearing surface"},{"label":"Cavity + fluid","detail":"Low-friction space"},{"label":"Capsule","detail":"Enclosure and stability"},{"label":"Ligament","detail":"Bone-to-bone restraint"},{"label":"Bursa","detail":"Friction-reducing sac"}]},"mnemonic":{"title":"C-C-F-L-B","cue":"Cartilage · Capsule · Fluid · Ligament · Bursa","explanation":"Rebuild the joint from the surfaces outward."},"goodToKnow":"Subcutaneous bursae lie between skin and a bony prominence, such as around the knee or elbow.","act":{"type":"choice","prompt":"What directly provides lubrication inside a synovial cavity?","options":[{"label":"Synovial fluid","correct":true,"feedback":"Correct. It reduces friction between moving surfaces."},{"label":"Sebum","correct":false,"feedback":"Sebum lubricates skin and hair, not joints."},{"label":"A suture","correct":false,"feedback":"A suture is a fibrous joint."}]}},{"id":"l8-m4","chapter":null,"chapterSummary":null,"title":"Six joint shapes","highYield":"Shape predicts available axes of motion.","teach":["Plane joints glide; hinge joints mainly flex and extend; pivot joints rotate around one axis. Condyloid joints move in two planes, saddle joints allow broad biaxial movement, and ball-and-socket joints move around multiple axes.","Use anchor examples: intercarpal plane, elbow hinge, proximal radioulnar pivot, knuckle condyloid, thumb saddle, and shoulder or hip ball-and-socket. Ball-and-socket mobility is broad, but stability still depends on socket depth, capsule, ligaments and muscles."],"keyPoints":["Hinge and pivot are uniaxial.","Condyloid and saddle are biaxial.","Ball-and-socket is multiaxial.","The thumb carpometacarpal joint is saddle shaped."],"visual":{"title":"Shape-to-motion ladder","kind":"concept-map","items":[{"label":"Plane","detail":"Glide"},{"label":"Hinge","detail":"Door-like arc"},{"label":"Pivot","detail":"Axial rotation"},{"label":"Condyloid","detail":"Two-plane oval"},{"label":"Saddle","detail":"Two-plane reciprocal curves"},{"label":"Ball-and-socket","detail":"Multiaxial sphere"}]},"mnemonic":{"title":"Please Help People Cook Soup Bowls","cue":"Plane · Hinge · Pivot · Condyloid · Saddle · Ball-and-socket","explanation":"Use the first letters to recall the six shapes."},"goodToKnow":"The hip and shoulder share a joint type but differ in stability because their surrounding anatomy differs.","act":{"type":"choice","prompt":"Which joint type is found at the base of the thumb?","options":[{"label":"Saddle","correct":true,"feedback":"Correct. The thumb carpometacarpal joint is the classic saddle joint."},{"label":"Hinge","correct":false,"feedback":"A hinge mainly flexes and extends."},{"label":"Pivot","correct":false,"feedback":"A pivot rotates around one axis."}]}},{"id":"synovial-design-match","title":"Match it: Synovial layers","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Smooth bearing surface","Low-friction space","Enclosure and stability","Bone-to-bone restraint","Friction-reducing sac"],"items":[{"label":"Cavity + fluid","category":1,"feedback":"Cavity + fluid: Low-friction space"},{"label":"Bursa","category":4,"feedback":"Bursa: Friction-reducing sac"},{"label":"Capsule","category":2,"feedback":"Capsule: Enclosure and stability"},{"label":"Cartilage","category":0,"feedback":"Cartilage: Smooth bearing surface"},{"label":"Ligament","category":3,"feedback":"Ligament: Bone-to-bone restraint"}]}},{"id":"l8-m5","chapter":"Decode movement words","chapterSummary":"Movement terms describe a direction, not a disease or level of ability.","title":"Angle and midline movements","highYield":"Flex/extend change an angle; abduct/adduct change distance from the midline.","teach":["Flexion decreases the angle between bones, while extension increases it. Hyperextension continues beyond the anatomical position. Abduction moves a part away from the midline; adduction returns it toward the midline.","Circumduction combines flexion, extension, abduction and adduction so the distal end traces a circle. Rotation turns a bone around its long axis."],"keyPoints":["Flexion decreases an angle.","Extension increases an angle.","Abduction moves away from the midline.","Adduction moves toward the midline."],"visual":{"title":"Direction compass","kind":"concept-map","items":[{"label":"Flexion","detail":"Close the angle"},{"label":"Extension","detail":"Open the angle"},{"label":"Abduction","detail":"Away from midline"},{"label":"Adduction","detail":"Add toward midline"},{"label":"Rotation","detail":"Turn around an axis"}]},"mnemonic":{"title":"ABduct = away","cue":"ABduction begins with the same sound as away","explanation":"Then adduction means add it back."},"goodToKnow":"Pronation is not movement of the jaw; in the forearm it turns the palm posteriorly/downward from anatomical position.","act":{"type":"choice","prompt":"A leg moves laterally away from the body midline. What movement occurred?","options":[{"label":"Abduction","correct":true,"feedback":"Correct. Abduction moves away from the midline."},{"label":"Adduction","correct":false,"feedback":"Adduction returns toward the midline."},{"label":"Flexion","correct":false,"feedback":"Flexion changes the joint angle."}]}},{"id":"l8-m6","chapter":null,"chapterSummary":null,"title":"Special movements","highYield":"Feet, forearms, jaw and shoulder girdles use specialized vocabulary.","teach":["Dorsiflexion brings the top of the foot toward the shin; plantar flexion points the foot. Inversion turns the sole inward and eversion turns it outward. Pronation and supination describe forearm rotation.","Elevation raises a body part and depression lowers it. Protraction moves a structure anteriorly, while retraction moves it posteriorly. Opposition brings the thumb across the palm to meet a fingertip."],"keyPoints":["Dorsiflexion lifts the foot.","Inversion and eversion apply to the foot.","Elevation and depression are opposites.","Opposition is central to thumb function."],"visual":{"title":"Special-movement pairs","kind":"concept-map","items":[{"label":"Dorsi / plantar","detail":"Foot up / point"},{"label":"Inversion / eversion","detail":"Sole in / out"},{"label":"Pronation / supination","detail":"Palm down / up"},{"label":"Elevation / depression","detail":"Raise / lower"},{"label":"Protraction / retraction","detail":"Forward / back"}]},"mnemonic":{"title":"SOUPination","cue":"Supination holds a bowl of soup","explanation":"Palm-up imagery separates it from pronation."},"goodToKnow":"Movement descriptions assume the anatomical position unless the context says otherwise.","act":{"type":"choice","prompt":"Which movement raises the foot at the ankle?","options":[{"label":"Dorsiflexion","correct":true,"feedback":"Correct. Dorsiflexion brings the dorsum toward the shin."},{"label":"Plantar flexion","correct":false,"feedback":"That points the foot downward."},{"label":"Eversion","correct":false,"feedback":"That turns the sole outward."}]}},{"id":"movement-match","title":"Match it: Direction compass","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Close the angle","Open the angle","Away from midline","Add toward midline","Turn around an axis"],"items":[{"label":"Extension","category":1,"feedback":"Extension: Open the angle"},{"label":"Rotation","category":4,"feedback":"Rotation: Turn around an axis"},{"label":"Abduction","category":2,"feedback":"Abduction: Away from midline"},{"label":"Flexion","category":0,"feedback":"Flexion: Close the angle"},{"label":"Adduction","category":3,"feedback":"Adduction: Add toward midline"}]}},{"id":"l8-m7","chapter":"Stress, injury and joint conditions","chapterSummary":"Separate the injured structure from the movement affected and from the condition’s cause.","title":"Sprain, strain and dislocation","highYield":"The words identify different structures and events.","teach":["A sprain injures a ligament; a strain injures muscle or tendon. A dislocation occurs when articulating bone surfaces are displaced, while subluxation is partial displacement. These require appropriate clinical assessment rather than self-classification.","Repetitive loading can irritate tendons or bursae and may contribute to compression syndromes such as carpal tunnel syndrome. A laminectomy is a surgical removal of part of a vertebral lamina to create space; it is not simply another word for dislocation."],"keyPoints":["Sprain involves a ligament.","Strain involves muscle or tendon.","Dislocation changes joint congruence.","Bursitis is inflammation of a bursa."],"visual":{"title":"Structure-first sorting","kind":"concept-map","items":[{"label":"Ligament","detail":"Sprain"},{"label":"Muscle/tendon","detail":"Strain"},{"label":"Joint alignment","detail":"Dislocation"},{"label":"Bursa","detail":"Bursitis"},{"label":"Joint overall","detail":"Arthritis"}]},"mnemonic":{"title":"SPRained Ligament","cue":"SPrain pairs with supporting ligament","explanation":"Contrast it with STRain of muscle/tendon."},"goodToKnow":"A temporarily displaced joint is still a safety concern even if it seems to move back into place.","act":{"type":"choice","prompt":"Which term best matches injury to a ligament?","options":[{"label":"Sprain","correct":true,"feedback":"Correct. Ligaments are the affected structure in a sprain."},{"label":"Strain","correct":false,"feedback":"A strain affects muscle or tendon."},{"label":"Arthritis","correct":false,"feedback":"Arthritis refers to joint inflammation/disease, not this injury category."}]}},{"id":"l8-m8","chapter":null,"chapterSummary":null,"title":"Arthritis patterns without shortcuts","highYield":"Arthritis is a broad category; several mechanisms can affect a joint.","teach":["Osteoarthritis involves degeneration of joint structures over time and load. Rheumatoid arthritis is a systemic autoimmune connective-tissue disorder that often inflames small joints. Gout follows deposition of urate crystals, commonly affecting the joint at the base of the large toe.","Shared symptoms such as pain, stiffness or swelling do not make the conditions equivalent. History, examination and testing guide diagnosis; anatomy study should help you understand the involved structures, not diagnose from a symptom list."],"keyPoints":["Arthritis means joint inflammation/disease as a broad label.","Osteoarthritis is degenerative.","Rheumatoid arthritis is autoimmune/systemic.","Gout involves urate crystals."],"visual":{"title":"Three mechanisms","kind":"concept-map","items":[{"label":"Wear/degeneration","detail":"Osteoarthritis"},{"label":"Autoimmune inflammation","detail":"Rheumatoid arthritis"},{"label":"Crystal deposition","detail":"Gout"}]},"mnemonic":{"title":"ORG","cue":"Osteoarthritis · Rheumatoid · Gout","explanation":"Name the mechanism after the label."},"goodToKnow":"Gout can involve other joints even though the first metatarsophalangeal joint is a classic site.","act":{"type":"choice","prompt":"Which condition is associated with urate-crystal deposition?","options":[{"label":"Gout","correct":true,"feedback":"Correct. Urate crystals can inflame affected joints."},{"label":"Rheumatoid arthritis","correct":false,"feedback":"That is an autoimmune disorder."},{"label":"Bursitis","correct":false,"feedback":"That affects a bursa rather than describing crystal deposition."}]}},{"id":"applied-joints-match","title":"Match it: Structure-first sorting","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Sprain","Strain","Dislocation","Bursitis","Arthritis"],"items":[{"label":"Muscle/tendon","category":1,"feedback":"Muscle/tendon: Strain"},{"label":"Joint overall","category":4,"feedback":"Joint overall: Arthritis"},{"label":"Joint alignment","category":2,"feedback":"Joint alignment: Dislocation"},{"label":"Ligament","category":0,"feedback":"Ligament: Sprain"},{"label":"Bursa","category":3,"feedback":"Bursa: Bursitis"}]}}],"flashcards":[{"front":"Synarthrosis","back":"Functionally immovable joint."},{"front":"Amphiarthrosis","back":"Slightly movable joint."},{"front":"Diarthrosis","back":"Freely movable joint; most are synovial."},{"front":"Synchondrosis","back":"Cartilaginous joint united by hyaline cartilage."},{"front":"Symphysis","back":"Cartilaginous joint united by fibrocartilage."},{"front":"Bursa","back":"Small fluid-filled sac that reduces friction."},{"front":"Flexion","back":"Movement that decreases a joint angle."},{"front":"Abduction","back":"Movement away from the midline."},{"front":"Dorsiflexion","back":"Movement bringing the top of the foot toward the shin."},{"front":"Saddle joint","back":"Biaxial synovial joint; classic example is the thumb base."},{"front":"Sprain","back":"Ligament injury."},{"front":"Gout","back":"Inflammatory arthritis associated with urate crystals."}],"quiz":[],"caseStudy":{"title":"Name the motion, then the structure","scenario":"A client with a clinician-confirmed wrist condition says repetitive chopping is difficult and asks what “kind of joint problem” it is.","prompts":["Describe the task using movement terms.","List the synovial structures that reduce friction or add stability.","Explain why symptoms alone cannot distinguish tendon, ligament, bursa or nerve involvement.","Suggest an appropriate scope-safe next step for meal-planning support."],"takeaway":"Use joint language to understand function and adapt the task; leave diagnosis and rehabilitation to the appropriate clinician."}},{"n":9,"title":"The Muscular System","kicker":"Compare skeletal, cardiac and smooth muscle.","duration":"75–95 minutes","steps":[{"id":"l9-m1","chapter":"From whole muscle to filament","chapterSummary":"Muscle organization is nested: organ, fascicle, fiber, myofibril, sarcomere, filament.","title":"Three muscle tissues","highYield":"Control, striation, cell shape and location separate the three types.","teach":["Skeletal muscle is striated, usually voluntary, and moves the skeleton. Cardiac muscle is striated but involuntary and forms the heart wall. Smooth muscle lacks visible striations, is involuntary, and moves material through hollow organs and blood vessels.","All three convert chemical energy into force, yet their cell organization and control differ. Cardiac activity is influenced by the autonomic nervous system; this does not make cardiac tissue smooth muscle."],"keyPoints":["Skeletal: striated and voluntary.","Cardiac: striated and involuntary.","Smooth: nonstriated and involuntary.","Cardiac and smooth activity are autonomically influenced."],"visual":{"title":"Three-way comparison","kind":"concept-map","items":[{"label":"Skeletal","detail":"Bones; voluntary"},{"label":"Cardiac","detail":"Heart; involuntary"},{"label":"Smooth","detail":"Hollow organs; involuntary"}]},"mnemonic":{"title":"SCS","cue":"Skeletal · Cardiac · Smooth","explanation":"Move from body wall to heart to hollow organs."},"goodToKnow":"A tissue can be striated without being voluntarily controlled.","act":{"type":"choice","prompt":"Which striated muscle is involuntary?","options":[{"label":"Cardiac","correct":true,"feedback":"Correct. Cardiac muscle is striated and involuntary."},{"label":"Skeletal","correct":false,"feedback":"Skeletal muscle is usually voluntary."},{"label":"Smooth","correct":false,"feedback":"Smooth muscle is involuntary but not striated."}]}},{"id":"l9-m2","chapter":null,"chapterSummary":null,"title":"The nested organization","highYield":"Connective-tissue layers package force-producing cells.","teach":["Epimysium surrounds the whole muscle. Perimysium surrounds a fascicle, and endomysium surrounds each muscle fiber. A fiber contains many myofibrils, which are repeating chains of sarcomeres.","Within each sarcomere, thin actin and thick myosin filaments form the banding pattern. The light I band contains thin filaments; the dark A band spans thick filaments. Tendons transmit the combined pull to bone."],"keyPoints":["Epimysium: whole muscle.","Perimysium: fascicle.","Endomysium: fiber.","Myofibrils contain repeating sarcomeres.","Actin is thin; myosin is thick."],"visual":{"title":"Zoom sequence","kind":"concept-map","items":[{"label":"Muscle","detail":"Epimysium"},{"label":"Fascicle","detail":"Perimysium"},{"label":"Fiber","detail":"Endomysium"},{"label":"Myofibril","detail":"Sarcomere chain"},{"label":"Sarcomere","detail":"Actin + myosin"}]},"mnemonic":{"title":"EPE: entire, packet, each","cue":"Epimysium · Perimysium · Endomysium","explanation":"Move from the entire muscle to packets to each fiber."},"goodToKnow":"A fascicle is a bundle of muscle fibers, not one fiber or one myofibril.","act":{"type":"choice","prompt":"What surrounds a fascicle?","options":[{"label":"Perimysium","correct":true,"feedback":"Correct. Perimysium wraps each fascicle."},{"label":"Epimysium","correct":false,"feedback":"That surrounds the whole muscle."},{"label":"Endomysium","correct":false,"feedback":"That surrounds an individual fiber."}]}},{"id":"muscle-map-match","title":"Match it: Three-way comparison","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Bones; voluntary","Heart; involuntary","Hollow organs; involuntary"],"items":[{"label":"Skeletal","category":0,"feedback":"Skeletal: Bones; voluntary"},{"label":"Cardiac","category":1,"feedback":"Cardiac: Heart; involuntary"},{"label":"Smooth","category":2,"feedback":"Smooth: Hollow organs; involuntary"}]}},{"id":"l9-m3","chapter":"Turn a nerve signal into force","chapterSummary":"Electrical events release calcium; calcium permits actin–myosin cycling; ATP powers and resets it.","title":"Neuromuscular activation","highYield":"Acetylcholine starts a muscle-fiber action potential.","teach":["When a motor-neuron impulse reaches the neuromuscular junction, acetylcholine is released. It binds receptors on the sarcolemma, changing ion permeability; sodium entry helps depolarize the membrane and launch an action potential.","The signal travels along the sarcolemma and down T tubules. This triggers the sarcoplasmic reticulum to release calcium around the myofibrils. The electrical message has now become a chemical permission signal for contraction."],"keyPoints":["Acetylcholine is the neuromuscular transmitter.","Sodium is concentrated outside the resting fiber.","The action potential enters T tubules.","The sarcoplasmic reticulum releases calcium."],"visual":{"title":"Signal relay","kind":"concept-map","items":[{"label":"Motor neuron","detail":"Impulse arrives"},{"label":"ACh","detail":"Crosses junction"},{"label":"Sarcolemma/T tubule","detail":"Conducts signal"},{"label":"SR","detail":"Releases Ca²⁺"}]},"mnemonic":{"title":"A-T-C","cue":"Acetylcholine · T tubule · Calcium","explanation":"Recall the activation sequence."},"goodToKnow":"Calcium release here is intracellular signaling, not a claim that an acute calcium supplement directly causes a stronger contraction.","act":{"type":"choice","prompt":"What ion is released by the sarcoplasmic reticulum after T-tubule activation?","options":[{"label":"Calcium","correct":true,"feedback":"Correct. Calcium exposes actin sites through regulatory proteins."},{"label":"Sodium","correct":false,"feedback":"Sodium helps depolarize the membrane but is not the SR signal here."},{"label":"Chloride","correct":false,"feedback":"It is not the key coupling ion in this sequence."}]}},{"id":"l9-m4","chapter":null,"chapterSummary":null,"title":"Sliding filaments and ATP","highYield":"Filaments slide past one another; they do not become shorter.","teach":["Calcium binds the regulatory system associated with troponin and tropomyosin, exposing binding sites on actin. Energized myosin heads attach, pivot, and pull thin filaments toward the sarcomere center.","ATP binding releases myosin from actin; ATP breakdown re-cocks the head for another cycle. As cycling repeats, Z lines approach, the I band and H zone narrow, and the A band stays the same length."],"keyPoints":["Calcium exposes binding sites.","Myosin forms cross-bridges with actin.","ATP is needed for detachment and re-energizing.","The A band remains constant."],"visual":{"title":"Cross-bridge cycle","kind":"concept-map","items":[{"label":"Expose","detail":"Calcium shifts regulators"},{"label":"Attach","detail":"Myosin binds actin"},{"label":"Pull","detail":"Power stroke"},{"label":"Release","detail":"ATP binds"},{"label":"Reset","detail":"ATP is hydrolyzed"}]},"mnemonic":{"title":"CAPRR","cue":"Calcium · Attach · Pull · Release · Reset","explanation":"Use the cycle rather than memorizing isolated steps."},"goodToKnow":"Rigor after death reflects loss of ATP-dependent cross-bridge release, illustrating ATP’s role in relaxation.","act":{"type":"choice","prompt":"During contraction, which band remains the same length?","options":[{"label":"A band","correct":true,"feedback":"Correct. It reflects the length of thick filaments."},{"label":"I band","correct":false,"feedback":"The I band narrows as overlap increases."},{"label":"H zone","correct":false,"feedback":"The H zone narrows and may disappear."}]}},{"id":"contraction-match","title":"Match it: Signal relay","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Impulse arrives","Crosses junction","Conducts signal","Releases Ca²⁺"],"items":[{"label":"SR","category":3,"feedback":"SR: Releases Ca²⁺"},{"label":"Sarcolemma/T tubule","category":2,"feedback":"Sarcolemma/T tubule: Conducts signal"},{"label":"ACh","category":1,"feedback":"ACh: Crosses junction"},{"label":"Motor neuron","category":0,"feedback":"Motor neuron: Impulse arrives"}]}},{"id":"l9-m5","chapter":"Fuel, tension and adaptation","chapterSummary":"Muscles regenerate ATP through overlapping systems and express force in different ways.","title":"Three routes to ATP","highYield":"Stored ATP is small; phosphocreatine, glycolysis and aerobic metabolism replenish it.","teach":["Muscle stores only a brief supply of ATP. Phosphocreatine rapidly transfers a phosphate to ADP and is especially useful during short, intense work. Anaerobic glycolysis produces ATP quickly from glucose but yields lactate when pyruvate cannot be processed aerobically at the same rate.","Aerobic metabolism in mitochondria uses oxygen and fuel molecules to generate much more ATP, supporting longer-duration activity. All systems overlap; their relative contribution shifts with intensity, duration, training and recovery."],"keyPoints":["Phosphocreatine rapidly buffers ATP.","Glycolysis can proceed without oxygen.","Aerobic metabolism yields more ATP over time.","Lactate is associated with anaerobic processing in this text’s framework."],"visual":{"title":"Energy continuum","kind":"concept-map","items":[{"label":"Stored ATP","detail":"Seconds"},{"label":"Phosphocreatine","detail":"Rapid high power"},{"label":"Anaerobic glycolysis","detail":"Fast, limited yield"},{"label":"Aerobic metabolism","detail":"Slower, sustained yield"}]},"mnemonic":{"title":"PGA","cue":"Phosphocreatine · Glycolysis · Aerobic","explanation":"Order the major replenishment routes from rapid to sustained."},"goodToKnow":"Phosphocreatine is the phosphorylated molecule named in the source quiz, whereas creatine alone is not the immediate phosphate donor.","act":{"type":"choice","prompt":"What molecule rapidly donates phosphate to regenerate ATP in muscle?","options":[{"label":"Phosphocreatine","correct":true,"feedback":"Correct. It serves as a rapid high-energy phosphate reserve."},{"label":"Actin","correct":false,"feedback":"Actin is a contractile protein."},{"label":"Lactate","correct":false,"feedback":"Lactate is not the immediate phosphate donor."}]}},{"id":"l9-m6","chapter":null,"chapterSummary":null,"title":"Tone and contraction types","highYield":"Length change and tension are separate features.","teach":["Muscle tone is a low level of ongoing activation that helps posture and readiness. In an isotonic contraction, tension moves a load and muscle length changes: concentric action shortens; eccentric action lengthens under tension.","In an isometric contraction, tension rises but overall muscle length and the joint angle remain relatively constant. Repeated overload can promote hypertrophy; disuse can lead to atrophy."],"keyPoints":["Tone supports posture.","Concentric shortens under load.","Eccentric lengthens under load.","Isometric creates tension without visible shortening.","Disuse promotes atrophy."],"visual":{"title":"Tension map","kind":"concept-map","items":[{"label":"Concentric","detail":"Shorten"},{"label":"Eccentric","detail":"Lengthen under load"},{"label":"Isometric","detail":"Hold length"},{"label":"Tone","detail":"Baseline activation"}]},"mnemonic":{"title":"Metric means length","cue":"IsoMETRIC keeps the measurement similar","explanation":"Isotonic involves movement in the simplified textbook contrast."},"goodToKnow":"Holding a weight still is isometric; lifting it is typically concentric, not isometric.","act":{"type":"choice","prompt":"A person holds a grocery bag motionless with the elbow fixed. Which contraction dominates?","options":[{"label":"Isometric","correct":true,"feedback":"Correct. Tension is present without an obvious length change."},{"label":"Concentric","correct":false,"feedback":"That would shorten the active muscle to move the load."},{"label":"Atrophy","correct":false,"feedback":"Atrophy is loss of muscle bulk, not a contraction type."}]}},{"id":"energy-control-match","title":"Match it: Energy continuum","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Seconds","Rapid high power","Fast, limited yield","Slower, sustained yield"],"items":[{"label":"Aerobic metabolism","category":3,"feedback":"Aerobic metabolism: Slower, sustained yield"},{"label":"Anaerobic glycolysis","category":2,"feedback":"Anaerobic glycolysis: Fast, limited yield"},{"label":"Phosphocreatine","category":1,"feedback":"Phosphocreatine: Rapid high power"},{"label":"Stored ATP","category":0,"feedback":"Stored ATP: Seconds"}]}},{"id":"l9-m7","chapter":"Read muscle names and actions","chapterSummary":"Names often reveal location, shape, fiber direction, attachment or action.","title":"Origin, insertion and teamwork","highYield":"Movement emerges from groups, not one muscle acting alone.","teach":["The origin is usually the less movable attachment; the insertion is usually the more movable attachment where the effect is seen. During an action, the prime mover or agonist supplies the main force, an antagonist opposes or controls it, and synergists assist or stabilize.","Muscle names can encode clues: rectus means straight, oblique signals diagonal fibers, maximus indicates large size, and terms such as flexor, adductor or levator describe action."],"keyPoints":["Insertion is typically the movable attachment.","Agonist is the prime mover.","Antagonist opposes or controls.","Synergists assist.","Names often predict action or anatomy."],"visual":{"title":"Team roles","kind":"concept-map","items":[{"label":"Agonist","detail":"Main action"},{"label":"Antagonist","detail":"Opposes/controls"},{"label":"Synergist","detail":"Assists"},{"label":"Origin","detail":"Less movable"},{"label":"Insertion","detail":"More movable"}]},"mnemonic":{"title":"AIS","cue":"Agonist acts · antagonist inhibits/controls · synergist supports","explanation":"Use roles rather than memorizing pairs."},"goodToKnow":"The same muscle may be an agonist in one movement and an antagonist in another.","act":{"type":"choice","prompt":"What is the movable attachment called?","options":[{"label":"Insertion","correct":true,"feedback":"Correct. The effect of contraction is usually seen at the insertion."},{"label":"Origin","correct":false,"feedback":"The origin is usually less movable."},{"label":"Fascicle","correct":false,"feedback":"A fascicle is a bundle of fibers."}]}},{"id":"l9-m8","chapter":null,"chapterSummary":null,"title":"Anchor muscles by function","highYield":"Connect a familiar action to each name.","teach":["Frontalis raises the eyebrows; rectus abdominis flexes the trunk; the superior rectus elevates the eye. Flexor digitorum longus flexes the toes, while tibialis anterior contributes to dorsiflexion.","Action words generalize: abductors move away from the midline, adductors return toward it, levators raise, depressors lower, flexors decrease an angle and extensors increase it. Learn the rule first, then the regional example."],"keyPoints":["Frontalis raises eyebrows.","Rectus abdominis flexes trunk.","Flexor digitorum longus flexes toes.","Superior rectus raises the eye.","Tibialis anterior dorsiflexes."],"visual":{"title":"Name-to-action anchors","kind":"concept-map","items":[{"label":"Frontalis","detail":"Forehead/eyebrows"},{"label":"Rectus abdominis","detail":"Trunk flexion"},{"label":"Flexor digitorum longus","detail":"Toe flexion"},{"label":"Superior rectus","detail":"Eye elevation"},{"label":"Tibialis anterior","detail":"Dorsiflexion"}]},"mnemonic":{"title":"Name is a clue","cue":"Region + direction + action","explanation":"Decode the components before rote recall."},"goodToKnow":"Dorsiflexion appears in both the joint and muscle lessons because movement vocabulary bridges systems.","act":{"type":"choice","prompt":"Which muscle is emphasized in a traditional sit-up?","options":[{"label":"Rectus abdominis","correct":true,"feedback":"Correct. It is a major trunk flexor."},{"label":"Frontalis","correct":false,"feedback":"That raises the eyebrows."},{"label":"Superior rectus","correct":false,"feedback":"That moves the eye."}]}},{"id":"muscle-actions-match","title":"Match it: Team roles","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Main action","Opposes/controls","Assists","Less movable","More movable"],"items":[{"label":"Antagonist","category":1,"feedback":"Antagonist: Opposes/controls"},{"label":"Insertion","category":4,"feedback":"Insertion: More movable"},{"label":"Synergist","category":2,"feedback":"Synergist: Assists"},{"label":"Agonist","category":0,"feedback":"Agonist: Main action"},{"label":"Origin","category":3,"feedback":"Origin: Less movable"}]}}],"flashcards":[{"front":"Fascicle","back":"Bundle of muscle fibers."},{"front":"Epimysium","back":"Connective tissue around a whole muscle."},{"front":"Perimysium","back":"Connective tissue around a fascicle."},{"front":"Sarcomere","back":"Repeating contractile unit of a myofibril."},{"front":"Actin","back":"Thin contractile filament."},{"front":"Myosin","back":"Thick motor filament."},{"front":"Acetylcholine","back":"Neurotransmitter released at the neuromuscular junction."},{"front":"Phosphocreatine","back":"Rapid high-energy phosphate reserve for ATP regeneration."},{"front":"Isometric","back":"Tension without appreciable muscle shortening."},{"front":"Atrophy","back":"Decrease in muscle bulk, often associated with disuse."},{"front":"Agonist","back":"Prime mover for an action."},{"front":"Insertion","back":"Usually the more movable muscle attachment."}],"quiz":[],"caseStudy":{"title":"Fuel is only one part of force","scenario":"A recreational athlete says fatigue during repeated lifts must mean one specific nutrient is missing.","prompts":["Trace the signal from motor neuron to calcium release.","Name the ATP systems that overlap during repeated work.","Distinguish concentric, eccentric and isometric phases.","Explain why fatigue cannot be diagnosed from the workout description alone."],"takeaway":"Connect neural activation, cross-bridge cycling, energy systems and task demands before considering nutrition within scope."}},{"n":10,"title":"The Nervous System: Introduction, Spinal Cord, and Spinal Nerves","kicker":"Organize the nervous system into central, peripheral, sensory and motor divisions.","duration":"75–95 minutes","steps":[{"id":"l10-m1","chapter":"Build the communication map","chapterSummary":"The nervous system receives information, integrates it and sends a response.","title":"CNS, PNS, sensory and motor","highYield":"Location and direction create the master map.","teach":["The central nervous system (CNS) is the brain and spinal cord. The peripheral nervous system (PNS) includes nerves and ganglia outside the CNS. Together they form a rapid control and communication network.","Sensory, or afferent, neurons carry information toward the CNS. Motor, or efferent, neurons carry commands from the CNS to muscles and glands. Interneurons inside the CNS connect and process these pathways."],"keyPoints":["CNS = brain + spinal cord.","PNS = nerves + ganglia.","Afferent arrives at the CNS.","Efferent exits the CNS.","Interneurons integrate."],"visual":{"title":"Information loop","kind":"concept-map","items":[{"label":"Receptor","detail":"Detects change"},{"label":"Afferent neuron","detail":"Toward CNS"},{"label":"Interneuron","detail":"Integrates"},{"label":"Efferent neuron","detail":"Away from CNS"},{"label":"Effector","detail":"Responds"}]},"mnemonic":{"title":"SAME direction","cue":"Sensory Afferent; Motor Efferent","explanation":"SAME pairs pathway role with directional term."},"goodToKnow":"A motor neuron is also called efferent; the first neuron from a receptor is sensory/afferent, not motor.","act":{"type":"choice","prompt":"Which neuron carries a command from spinal cord to skeletal muscle?","options":[{"label":"Motor/efferent","correct":true,"feedback":"Correct. Efferent pathways exit the CNS."},{"label":"Sensory/afferent","correct":false,"feedback":"Afferent pathways carry input toward the CNS."},{"label":"Bipolar receptor only","correct":false,"feedback":"Shape does not replace directional function."}]}},{"id":"l10-m2","chapter":null,"chapterSummary":null,"title":"Neuron shapes and parts","highYield":"Dendrites receive, the soma maintains, and the axon conducts away.","teach":["A neuron has a cell body, dendrites and usually one axon. Multipolar neurons have many dendrites and one axon and are common among motor neurons and interneurons. Most general sensory neurons are unipolar; bipolar neurons occur in special sensory pathways.","Neuron shape and pathway role are related but not identical labels. A neuron may be called sensory because of information direction and unipolar because of structure."],"keyPoints":["Dendrites receive input.","The axon carries signals away from the soma.","Multipolar neurons have many dendrites.","Most general sensory neurons are unipolar.","Bipolar neurons serve special senses."],"visual":{"title":"Neuron forms","kind":"concept-map","items":[{"label":"Multipolar","detail":"Many dendrites, one axon"},{"label":"Unipolar","detail":"Single process; common sensory form"},{"label":"Bipolar","detail":"Two processes; special senses"}]},"mnemonic":{"title":"MUB","cue":"Multipolar · Unipolar · Bipolar","explanation":"Picture many, one, and two processes."},"goodToKnow":"The soma is metabolically essential; a long axon depends on transport from its cell body.","act":{"type":"choice","prompt":"Which structural type describes most general sensory neurons?","options":[{"label":"Unipolar","correct":true,"feedback":"Correct. Most are unipolar in this textbook classification."},{"label":"Multipolar","correct":false,"feedback":"Most motor neurons and interneurons are multipolar."},{"label":"Acellular","correct":false,"feedback":"Neurons are cells."}]}},{"id":"organization-match","title":"Match it: Information loop","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Detects change","Toward CNS","Integrates","Away from CNS","Responds"],"items":[{"label":"Afferent neuron","category":1,"feedback":"Afferent neuron: Toward CNS"},{"label":"Effector","category":4,"feedback":"Effector: Responds"},{"label":"Interneuron","category":2,"feedback":"Interneuron: Integrates"},{"label":"Receptor","category":0,"feedback":"Receptor: Detects change"},{"label":"Efferent neuron","category":3,"feedback":"Efferent neuron: Away from CNS"}]}},{"id":"l10-m3","chapter":"Support and signal","chapterSummary":"Glia maintain the neural environment; neurons generate and transmit electrochemical signals.","title":"Neuroglia are active partners","highYield":"Different glia support, defend, insulate and circulate fluid.","teach":["Astrocytes form a supporting network and help regulate the CNS environment. Oligodendrocytes form myelin in the CNS; Schwann cells form myelin in the PNS. Microglia are phagocytic defenders, and ependymal cells line fluid-filled CNS spaces.","Satellite cells support neuron cell bodies in peripheral ganglia. Glia are more numerous than neurons in many regions; the claim that more than 60% of all brain cells are neurons is therefore not a safe generalization."],"keyPoints":["Astrocytes support and regulate.","Oligodendrocytes myelinate CNS axons.","Schwann cells myelinate PNS axons.","Microglia defend.","Ependymal cells line ventricles/central canal."],"visual":{"title":"Glial jobs","kind":"concept-map","items":[{"label":"Astrocyte","detail":"Support and environment"},{"label":"Oligodendrocyte","detail":"CNS myelin"},{"label":"Schwann cell","detail":"PNS myelin"},{"label":"Microglia","detail":"Defense"},{"label":"Ependymal","detail":"Fluid-space lining"}]},"mnemonic":{"title":"CNS O, PNS S","cue":"Oligodendrocyte in the CNS; Schwann in the PNS","explanation":"Anchor the myelin cells by location."},"goodToKnow":"A single oligodendrocyte can myelinate parts of several CNS axons; one Schwann cell wraps one PNS segment.","act":{"type":"choice","prompt":"Which cell forms myelin around a peripheral nerve fiber?","options":[{"label":"Schwann cell","correct":true,"feedback":"Correct. Schwann cells myelinate PNS axons."},{"label":"Astrocyte","correct":false,"feedback":"Astrocytes support the CNS environment."},{"label":"Microglia","correct":false,"feedback":"Microglia are immune-like CNS cells."}]}},{"id":"l10-m4","chapter":null,"chapterSummary":null,"title":"Action potentials and synapses","highYield":"Electrical conduction along an axon becomes chemical signaling at many synapses.","teach":["At rest, ion gradients create a membrane potential. A sufficient stimulus opens voltage-gated channels: sodium entry depolarizes the membrane, then potassium movement helps repolarize it. The refractory period supports one-way propagation from the trigger zone along the axon.","Myelin speeds conduction because current effectively jumps between nodes. At a chemical synapse, the action potential triggers neurotransmitter release; transmitter crosses the cleft, binds receptors and changes the next cell. Acetylcholine is a common transmitter, but the body uses many others."],"keyPoints":["Sodium entry drives depolarization.","Potassium movement supports repolarization.","Myelin increases conduction speed.","Neurotransmitters cross chemical synapses.","Refractory behavior supports one-way travel."],"visual":{"title":"Signal sequence","kind":"concept-map","items":[{"label":"Rest","detail":"Ion gradients"},{"label":"Depolarize","detail":"Na⁺ entry"},{"label":"Repolarize","detail":"K⁺ shift"},{"label":"Conduct","detail":"Along axon"},{"label":"Transmit","detail":"Neurotransmitter across cleft"}]},"mnemonic":{"title":"Na in, K reset","cue":"Sodium depolarizes; potassium helps restore","explanation":"Then transmitter carries the message across the gap."},"goodToKnow":"Unmyelinated fibers conduct along the full membrane and are generally slower than comparable myelinated fibers.","act":{"type":"choice","prompt":"What crosses the gap at a chemical synapse?","options":[{"label":"A neurotransmitter","correct":true,"feedback":"Correct. It binds receptors on the next cell."},{"label":"A sarcolemma","correct":false,"feedback":"That is a muscle-cell membrane."},{"label":"A tract","correct":false,"feedback":"A tract is a CNS bundle of axons."}]}},{"id":"cells-signals-match","title":"Match it: Glial jobs","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Support and environment","CNS myelin","PNS myelin","Defense","Fluid-space lining"],"items":[{"label":"Oligodendrocyte","category":1,"feedback":"Oligodendrocyte: CNS myelin"},{"label":"Ependymal","category":4,"feedback":"Ependymal: Fluid-space lining"},{"label":"Schwann cell","category":2,"feedback":"Schwann cell: PNS myelin"},{"label":"Astrocyte","category":0,"feedback":"Astrocyte: Support and environment"},{"label":"Microglia","category":3,"feedback":"Microglia: Defense"}]}},{"id":"l10-m5","chapter":"Read the spinal cord and nerves","chapterSummary":"Learn the location vocabulary before tracing a pathway.","title":"Gray, white, tract, nerve, nucleus, ganglion","highYield":"The same cellular material receives different names by location.","teach":["Gray matter contains many neuron cell bodies, dendrites and synapses; white matter contains many myelinated axons. In the spinal cord, gray matter forms an inner butterfly-like region surrounded by white columns.","A bundle of axons inside the CNS is a tract; outside it is a nerve. A cluster of neuron cell bodies inside the CNS is a nucleus; outside it is a ganglion. These paired terms are frequent test targets."],"keyPoints":["Gray matter emphasizes somas and dendrites.","White matter emphasizes myelinated axons.","CNS axon bundle = tract.","PNS axon bundle = nerve.","PNS cell-body cluster = ganglion."],"visual":{"title":"Location vocabulary","kind":"concept-map","items":[{"label":"CNS bundle","detail":"Tract"},{"label":"PNS bundle","detail":"Nerve"},{"label":"CNS somas","detail":"Nucleus"},{"label":"PNS somas","detail":"Ganglion"}]},"mnemonic":{"title":"TNNG map","cue":"Tract/Nucleus in CNS; Nerve/Ganglion in PNS","explanation":"Sort by axons versus somas, then by location."},"goodToKnow":"Ganglion and ganglia refer to the same PNS cell-body structure in singular and plural.","act":{"type":"choice","prompt":"What is a bundle of axons within the CNS called?","options":[{"label":"Tract","correct":true,"feedback":"Correct. A peripheral bundle would be a nerve."},{"label":"Ganglion","correct":false,"feedback":"A ganglion is a PNS cluster of cell bodies."},{"label":"Nucleus","correct":false,"feedback":"A nucleus is a CNS cluster of cell bodies."}]}},{"id":"l10-m6","chapter":null,"chapterSummary":null,"title":"Cord, roots and mixed spinal nerves","highYield":"Sensory and motor fibers separate at roots but combine in each spinal nerve.","teach":["The spinal cord continues from the medulla oblongata through the vertebral canal. Dorsal roots bring sensory information into the cord, and their dorsal-root ganglia contain sensory neuron cell bodies. Ventral roots carry motor output away.","A dorsal and ventral root unite to form a mixed spinal nerve, so every spinal nerve carries both sensory and motor fibers. The epidural space lies between the vertebral canal and the dura mater and contains cushioning tissue and vessels."],"keyPoints":["Cord continues from medulla oblongata.","Dorsal root is sensory.","Ventral root is motor.","All spinal nerves are mixed.","Epidural space lies outside the dura."],"visual":{"title":"Root-to-nerve","kind":"concept-map","items":[{"label":"Dorsal root","detail":"Sensory input"},{"label":"Dorsal-root ganglion","detail":"Sensory somas"},{"label":"Ventral root","detail":"Motor output"},{"label":"Spinal nerve","detail":"Mixed fibers"},{"label":"Epidural space","detail":"Outside dura"}]},"mnemonic":{"title":"DAVE","cue":"Dorsal Afferent; Ventral Efferent","explanation":"Then the roots unite into a mixed nerve."},"goodToKnow":"The adult spinal cord ends above the lowest vertebrae; lower roots descend before exiting.","act":{"type":"choice","prompt":"Why is a spinal nerve called mixed?","options":[{"label":"It contains both sensory and motor fibers.","correct":true,"feedback":"Correct. The two root streams combine."},{"label":"It belongs only to the autonomic system.","correct":false,"feedback":"Spinal nerves carry multiple functional fiber types."},{"label":"It contains gray and white matter.","correct":false,"feedback":"Those terms describe CNS tissue organization."}]}},{"id":"spinal-map-match","title":"Match it: Location vocabulary","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Tract","Nerve","Nucleus","Ganglion"],"items":[{"label":"PNS somas","category":3,"feedback":"PNS somas: Ganglion"},{"label":"CNS somas","category":2,"feedback":"CNS somas: Nucleus"},{"label":"PNS bundle","category":1,"feedback":"PNS bundle: Nerve"},{"label":"CNS bundle","category":0,"feedback":"CNS bundle: Tract"}]}},{"id":"l10-m7","chapter":"Fast responses and autonomic balance","chapterSummary":"Reflex arcs protect and regulate; autonomic divisions shift organ activity with context.","title":"The reflex arc","highYield":"A reflex can produce a rapid response before conscious interpretation.","teach":["A basic somatic reflex arc includes receptor, sensory neuron, integration center, motor neuron and skeletal-muscle effector. Some reflexes are monosynaptic; many use interneurons and multiple synapses.","The brain can become aware of the event and modify later behavior, but the spinal circuitry does not need to wait for a conscious decision. Reflex testing therefore samples both sensory and motor pathway integrity."],"keyPoints":["Receptor detects the stimulus.","Afferent neuron enters the CNS.","Integration occurs in CNS gray matter.","Efferent neuron activates an effector."],"visual":{"title":"Reflex loop","kind":"concept-map","items":[{"label":"1 Receptor","detail":"Detect"},{"label":"2 Afferent","detail":"Carry in"},{"label":"3 Integration","detail":"Process"},{"label":"4 Efferent","detail":"Carry out"},{"label":"5 Effector","detail":"Respond"}]},"mnemonic":{"title":"RAIME","cue":"Receptor · Afferent · Integration · Motor · Effector","explanation":"Trace the five stations in order."},"goodToKnow":"A withdrawal reflex and the conscious perception of pain are related but not identical events.","act":{"type":"choice","prompt":"Which neuron directly brings a command to the responding muscle?","options":[{"label":"Motor/efferent neuron","correct":true,"feedback":"Correct. It is the output limb of the arc."},{"label":"Sensory/afferent neuron","correct":false,"feedback":"That carries information from the receptor."},{"label":"Dorsal-root ganglion","correct":false,"feedback":"That is a cluster of sensory cell bodies."}]}},{"id":"l10-m8","chapter":null,"chapterSummary":null,"title":"ANS bridge for this quiz bank","highYield":"Sympathetic mobilizes; parasympathetic supports routine restorative functions.","teach":["The autonomic nervous system is the involuntary motor branch serving smooth muscle, cardiac muscle and glands. Its sympathetic division generally mobilizes the body during challenge, increasing selected activities needed for action; its parasympathetic division predominates during many routine conditions and supports digestion, urination and defecation.","In the textbook framing, acetylcholine is released at parasympathetic nerve endings at target organs, while sympathetic end organs commonly receive norepinephrine. Both divisions use acetylcholine at their first ganglionic synapse. Lesson 11 expands this preview; it appears here because the supplied Lesson 10 quiz tests it directly."],"keyPoints":["ANS is involuntary motor output.","Sympathetic prepares for challenge.","Parasympathetic supports rest-and-digest functions.","ACh is used at parasympathetic target endings.","Both divisions use ACh before the ganglion."],"visual":{"title":"Autonomic balance","kind":"concept-map","items":[{"label":"Sympathetic","detail":"Mobilize"},{"label":"Parasympathetic","detail":"Restore and maintain"},{"label":"Shared first synapse","detail":"ACh"},{"label":"Parasympathetic target","detail":"ACh"},{"label":"Common sympathetic target","detail":"Norepinephrine"}]},"mnemonic":{"title":"S = stress; P = peace","cue":"Sympathetic mobilizes, parasympathetic maintains","explanation":"Use the pattern, not the idea that one division is always on alone."},"goodToKnow":"The two divisions often have opposing effects, yet both continuously contribute to organ regulation.","act":{"type":"choice","prompt":"Which transmitter does the parasympathetic division release at its target endings in this course?","options":[{"label":"Acetylcholine","correct":true,"feedback":"Correct. This is the quiz-bank wording and textbook pattern."},{"label":"Dopamine","correct":false,"feedback":"Dopamine has other CNS roles."},{"label":"Epinephrine only","correct":false,"feedback":"That is not the standard parasympathetic target transmitter."}]}},{"id":"responses-match","title":"Match it: Reflex loop","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Detect","Carry in","Process","Carry out","Respond"],"items":[{"label":"2 Afferent","category":1,"feedback":"2 Afferent: Carry in"},{"label":"5 Effector","category":4,"feedback":"5 Effector: Respond"},{"label":"3 Integration","category":2,"feedback":"3 Integration: Process"},{"label":"1 Receptor","category":0,"feedback":"1 Receptor: Detect"},{"label":"4 Efferent","category":3,"feedback":"4 Efferent: Carry out"}]}}],"flashcards":[{"front":"Afferent neuron","back":"Carries sensory information toward the CNS."},{"front":"Efferent neuron","back":"Carries motor output away from the CNS."},{"front":"Unipolar neuron","back":"Common structural type for general sensory neurons."},{"front":"Astrocyte","back":"Star-shaped CNS glial cell that supports and regulates the neural environment."},{"front":"Schwann cell","back":"Cell that forms PNS myelin."},{"front":"Neurotransmitter","back":"Chemical messenger released across a synapse."},{"front":"Tract","back":"Bundle of axons within the CNS."},{"front":"Ganglion","back":"Cluster of neuron cell bodies in the PNS."},{"front":"Gray matter","back":"Region rich in neuron somas, dendrites and synapses."},{"front":"Dorsal root","back":"Sensory/afferent root of a spinal nerve."},{"front":"Sympathetic","back":"Autonomic division that mobilizes body functions during challenge."},{"front":"Parasympathetic","back":"Autonomic division supporting routine restorative and digestive functions."},{"front":"Depressant","back":"Drug category that reduces aspects of CNS activity; Valium is the quiz example."},{"front":"Anabolic steroid","back":"Substance class with androgen-like effects; not a stimulant/depressant/hallucinogen category."}],"quiz":[],"caseStudy":{"title":"A hot surface and a fast response","scenario":"A person touches a hot tray, withdraws the hand, then notices pain and a racing heart.","prompts":["Trace the withdrawal reflex from receptor to effector.","Separate the spinal reflex from conscious perception.","Name the autonomic division that supports the challenge response.","Explain why this sequence does not identify the cause of persistent symptoms."],"takeaway":"Map sensory, integrative, motor and autonomic events as connected layers, while leaving diagnosis to clinical assessment."}},{"n":11,"title":"The Brain, Cranial Nerves, Autonomic Nervous System, and Special Senses","kicker":"Locate major brain regions and connect each with its broad function.","duration":"90–110 minutes","steps":[{"id":"l11-m1","chapter":"Brain regions as a working team","chapterSummary":"Avoid “one region, one behavior” oversimplification while learning each region’s anchor job.","title":"Cerebrum and lobes","highYield":"The cerebral cortex supports conscious sensation, movement and higher processing.","teach":["The longitudinal fissure separates right and left cerebral hemispheres, while the corpus callosum connects them. Gyri are raised folds and sulci are shallower grooves; folding expands cortical surface area.","The frontal lobe supports planning and voluntary motor control; parietal regions process somatic sensation; temporal regions contribute to hearing and memory; the occipital lobe receives and interprets visual input. These functions operate through networks rather than isolated boxes."],"keyPoints":["Longitudinal fissure separates hemispheres.","Corpus callosum connects hemispheres.","Gyri are folds.","Occipital lobe is the visual anchor.","Cortical functions are networked."],"visual":{"title":"Cortical anchors","kind":"concept-map","items":[{"label":"Frontal","detail":"Plan and move"},{"label":"Parietal","detail":"Body sensation"},{"label":"Temporal","detail":"Hear and remember"},{"label":"Occipital","detail":"See"}]},"mnemonic":{"title":"FPTO","cue":"Front · Parietal · Temporal · Occipital","explanation":"Move front-to-back around the cortex."},"goodToKnow":"The cerebral hemispheres are highly interconnected; “left brain/right brain personality” claims are oversimplified.","act":{"type":"choice","prompt":"Which lobe is the primary visual-processing anchor?","options":[{"label":"Occipital","correct":true,"feedback":"Correct. Visual input is received and interpreted there."},{"label":"Temporal","correct":false,"feedback":"Temporal regions are associated more strongly with hearing and memory."},{"label":"Frontal","correct":false,"feedback":"Frontal regions anchor planning and motor functions."}]}},{"id":"l11-m2","chapter":null,"chapterSummary":null,"title":"Diencephalon, brainstem and cerebellum","highYield":"Relay, homeostasis, vital pathways and movement coordination occupy different regions.","teach":["The thalamus relays much sensory information toward the cortex. The hypothalamus links neural and endocrine regulation and helps govern temperature, appetite, thirst and autonomic activity; the infundibulum connects it to the pituitary. The pineal gland secretes melatonin.","Midbrain, pons and medulla form the brainstem; ascending and descending tracts pass through it, and the medulla continues as the spinal cord. The reticular formation supports arousal. The cerebellum coordinates timing, balance and complex skeletal movement rather than intellectual processes or emotions."],"keyPoints":["Thalamus is a major relay.","Hypothalamus regulates homeostasis and pituitary control.","Infundibulum connects hypothalamus and pituitary.","Reticular formation supports arousal.","Cerebellum coordinates movement."],"visual":{"title":"Deep-brain map","kind":"concept-map","items":[{"label":"Thalamus","detail":"Relay"},{"label":"Hypothalamus","detail":"Homeostasis"},{"label":"Brainstem","detail":"Pathways/vital centers"},{"label":"Reticular formation","detail":"Arousal"},{"label":"Cerebellum","detail":"Coordination"}]},"mnemonic":{"title":"THReC","cue":"Thalamus · Hypothalamus · Reticular · Cerebellum","explanation":"Attach relay, homeostasis, arousal and coordination."},"goodToKnow":"The medulla contains pathways linking spinal cord and higher brain regions as well as important autonomic centers.","act":{"type":"choice","prompt":"Which region coordinates complex skeletal movements as a reflex center?","options":[{"label":"Cerebellum","correct":true,"feedback":"Correct. It refines timing, balance and coordination."},{"label":"Corpus callosum","correct":false,"feedback":"That connects the hemispheres."},{"label":"Occipital lobe","correct":false,"feedback":"That processes vision."}]}},{"id":"brain-regions-match","title":"Match it: Cortical anchors","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Plan and move","Body sensation","Hear and remember","See"],"items":[{"label":"Occipital","category":3,"feedback":"Occipital: See"},{"label":"Temporal","category":2,"feedback":"Temporal: Hear and remember"},{"label":"Parietal","category":1,"feedback":"Parietal: Body sensation"},{"label":"Frontal","category":0,"feedback":"Frontal: Plan and move"}]}},{"id":"l11-m3","chapter":"Protect and connect the brain","chapterSummary":"Membranes, fluid, vessels and cranial nerves interface the brain with the body.","title":"Meninges, CSF and circulation","highYield":"Three membranes and circulating fluid cushion vulnerable neural tissue.","teach":["From outside inward, the meninges are dura mater, arachnoid mater and pia mater. Cerebrospinal fluid (CSF) circulates through ventricles and the subarachnoid space, providing buoyancy, cushioning and chemical stability.","The brain requires continuous blood flow. An interrupted vessel can produce a cerebrovascular accident, or stroke; an aneurysm is a dilation of a vessel wall that may rupture. These are urgent medical concerns, not conditions to assess through nutrition symptoms alone."],"keyPoints":["Dura is outermost.","Arachnoid is middle.","Pia closely follows brain surface.","CSF cushions CNS.","Stroke and aneurysm are vascular terms."],"visual":{"title":"Protective layers","kind":"concept-map","items":[{"label":"Dura","detail":"Tough outer"},{"label":"Arachnoid","detail":"Web-like middle"},{"label":"Subarachnoid space","detail":"CSF"},{"label":"Pia","detail":"Delicate inner"}]},"mnemonic":{"title":"DAP","cue":"Dura · Arachnoid · Pia","explanation":"Recall meninges from outer to inner."},"goodToKnow":"Meningitis affects meninges; encephalitis affects brain tissue itself.","act":{"type":"choice","prompt":"What is the middle meningeal layer?","options":[{"label":"Arachnoid mater","correct":true,"feedback":"Correct. It lies between dura and pia."},{"label":"Pia mater","correct":false,"feedback":"Pia is the innermost layer."},{"label":"Dura mater","correct":false,"feedback":"Dura is the outermost layer."}]}},{"id":"l11-m4","chapter":null,"chapterSummary":null,"title":"Cranial-nerve anchors","highYield":"Learn tested functions before attempting all details at once.","teach":["Twelve pairs of cranial nerves arise from the brain. The trigeminal nerve is the largest and carries facial sensation plus chewing motor fibers. The hypoglossal nerve controls tongue movements; the vestibulocochlear nerve carries hearing and balance information.","The abducens nerve is motor and moves the eyeball laterally. The optic nerve carries visual information and exits the eye at the optic disc. Cranial nerves may be sensory, motor or mixed."],"keyPoints":["Trigeminal is the largest cranial nerve.","Hypoglossal moves tongue.","Vestibulocochlear serves hearing/balance.","Abducens moves the eye.","Optic carries vision."],"visual":{"title":"Five tested nerves","kind":"concept-map","items":[{"label":"V Trigeminal","detail":"Face and chewing"},{"label":"VI Abducens","detail":"Eye movement"},{"label":"VIII Vestibulocochlear","detail":"Hearing/balance"},{"label":"II Optic","detail":"Vision"},{"label":"XII Hypoglossal","detail":"Tongue"}]},"mnemonic":{"title":"TAVOH","cue":"Trigeminal · Abducens · Vestibulocochlear · Optic · Hypoglossal","explanation":"Use the tested anchors, then add the remaining nerves later."},"goodToKnow":"The lacrimal gland makes tears; it is a gland, not a cranial nerve.","act":{"type":"choice","prompt":"Which cranial nerve controls tongue movement?","options":[{"label":"Hypoglossal","correct":true,"feedback":"Correct. Cranial nerve XII is motor to the tongue."},{"label":"Trigeminal","correct":false,"feedback":"It is mainly facial sensation and chewing."},{"label":"Vestibulocochlear","correct":false,"feedback":"It serves hearing and balance."}]}},{"id":"protection-nerves-match","title":"Match it: Protective layers","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Tough outer","Web-like middle","CSF","Delicate inner"],"items":[{"label":"Pia","category":3,"feedback":"Pia: Delicate inner"},{"label":"Subarachnoid space","category":2,"feedback":"Subarachnoid space: CSF"},{"label":"Arachnoid","category":1,"feedback":"Arachnoid: Web-like middle"},{"label":"Dura","category":0,"feedback":"Dura: Tough outer"}]}},{"id":"l11-m5","chapter":"Automatic control without a simple on/off switch","chapterSummary":"Somatic and autonomic systems serve different effectors; sympathetic and parasympathetic outputs rebalance organs.","title":"Somatic versus autonomic motor output","highYield":"The effector identifies the motor branch.","teach":["Somatic motor pathways control skeletal muscle. Autonomic pathways regulate smooth muscle, cardiac muscle and glands through a two-neuron chain with a peripheral ganglion.","Sympathetic output generally prepares the body for challenge; parasympathetic output supports routine, nonstressful functions such as digestion. Both divisions usually maintain some activity, so “fight or flight” and “rest and digest” are useful anchors rather than complete descriptions."],"keyPoints":["Somatic targets skeletal muscle.","Autonomic targets smooth/cardiac muscle and glands.","ANS uses a two-neuron chain.","Sympathetic mobilizes.","Parasympathetic maintains/restores."],"visual":{"title":"Motor branches","kind":"concept-map","items":[{"label":"Somatic","detail":"Skeletal muscle"},{"label":"Sympathetic","detail":"Mobilizing ANS"},{"label":"Parasympathetic","detail":"Restorative ANS"}]},"mnemonic":{"title":"Skeletal = somatic","cue":"Somatic starts with S, as does skeletal","explanation":"Autonomic covers organs and glands."},"goodToKnow":"The somatic system does not regulate internal organs; that function belongs mainly to autonomic motor pathways.","act":{"type":"choice","prompt":"Which division predominates during many normal nonstressful digestive activities?","options":[{"label":"Parasympathetic","correct":true,"feedback":"Correct. It supports many routine vegetative functions."},{"label":"Sympathetic","correct":false,"feedback":"It more often mobilizes resources during challenge."},{"label":"Somatic","correct":false,"feedback":"Somatic pathways target skeletal muscle."}]}},{"id":"l11-m6","chapter":null,"chapterSummary":null,"title":"Transmitters and organ effects","highYield":"Ganglionic and target synapses use different transmitter patterns.","teach":["Both autonomic divisions release acetylcholine from preganglionic neurons. Parasympathetic postganglionic neurons also typically release acetylcholine; most sympathetic postganglionic neurons release norepinephrine.","Effects depend on receptor type and target organ. Sympathetic activity can increase cardiac output and redirect resources, while parasympathetic activity can promote digestive motility and secretion. The divisions are coordinated, not moral opposites."],"keyPoints":["All preganglionic ANS neurons use ACh.","Parasympathetic target endings use ACh.","Most sympathetic target endings use norepinephrine.","Effect depends on receptor and organ."],"visual":{"title":"Two-neuron chain","kind":"concept-map","items":[{"label":"Preganglionic","detail":"ACh in both divisions"},{"label":"Autonomic ganglion","detail":"Second neuron begins"},{"label":"Parasympathetic target","detail":"Usually ACh"},{"label":"Sympathetic target","detail":"Usually norepinephrine"}]},"mnemonic":{"title":"A-A/N","cue":"ACh first; ACh parasympathetic, NE sympathetic at targets","explanation":"Track each synapse separately."},"goodToKnow":"Exceptions exist, so transmitter patterns should be learned as common organization rather than absolute rules.","act":{"type":"choice","prompt":"What transmitter do both ANS divisions use before the ganglion?","options":[{"label":"Acetylcholine","correct":true,"feedback":"Correct. Both preganglionic neuron types release ACh."},{"label":"Norepinephrine","correct":false,"feedback":"That is common at sympathetic target endings."},{"label":"Melatonin","correct":false,"feedback":"Melatonin is a pineal hormone."}]}},{"id":"autonomic-match","title":"Match it: Motor branches","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Skeletal muscle","Mobilizing ANS","Restorative ANS"],"items":[{"label":"Somatic","category":0,"feedback":"Somatic: Skeletal muscle"},{"label":"Sympathetic","category":1,"feedback":"Sympathetic: Mobilizing ANS"},{"label":"Parasympathetic","category":2,"feedback":"Parasympathetic: Restorative ANS"}]}},{"id":"l11-m7","chapter":"Vision: route light to neural signal","chapterSummary":"Follow light through transparent structures to photoreceptors, then out through the optic nerve.","title":"Layers and the light path","highYield":"The cornea and lens focus; the retina transduces.","teach":["The sclera is the tough outer coat; its transparent anterior portion is the cornea. The vascular middle layer includes choroid, ciliary body and iris. The iris controls pupil diameter and therefore light entry. The retina is the inner photosensitive layer.","Light passes through cornea, aqueous humor, pupil, lens and vitreous humor before reaching the retina. The lens changes shape for near or far focus. Neural signals leave at the optic disc, a region without photoreceptors."],"keyPoints":["Cornea is transparent outer layer.","Iris regulates pupil diameter.","Lens focuses light.","Retina contains photoreceptors.","Optic disc is the nerve exit."],"visual":{"title":"Light route","kind":"concept-map","items":[{"label":"Cornea","detail":"Initial refraction"},{"label":"Pupil/iris","detail":"Light amount"},{"label":"Lens","detail":"Focus"},{"label":"Vitreous","detail":"Transmits"},{"label":"Retina","detail":"Transduces"},{"label":"Optic nerve","detail":"Carries signal"}]},"mnemonic":{"title":"CPLRO","cue":"Cornea · Pupil · Lens · Retina · Optic nerve","explanation":"A simplified route to reconstruct under test pressure."},"goodToKnow":"The fovea centralis is specialized for high-acuity vision, whereas the optic disc creates a blind spot.","act":{"type":"choice","prompt":"Which layer contains the photosensitive cells?","options":[{"label":"Retina","correct":true,"feedback":"Correct. Rods and cones are retinal photoreceptors."},{"label":"Sclera","correct":false,"feedback":"The sclera is the tough outer coat."},{"label":"Iris","correct":false,"feedback":"The iris regulates pupil diameter."}]}},{"id":"l11-m8","chapter":null,"chapterSummary":null,"title":"Rods and cones","highYield":"Sensitivity and color discrimination trade off.","teach":["Rods are highly sensitive and support dim-light, noncolor vision. Cones require more light and support color vision and fine detail; they are densely concentrated in the fovea.","Photoreceptors pass signals through retinal circuits to ganglion-cell axons, which form the optic nerve. The brain then interprets the patterned activity; the eye does not produce a finished picture on its own."],"keyPoints":["Rods work well in dim light.","Rods do not provide color vision.","Cones support color and detail.","Cones need brighter light.","Optic nerve is formed by ganglion-cell axons."],"visual":{"title":"Photoreceptor contrast","kind":"concept-map","items":[{"label":"Rods","detail":"Dim, sensitive, no color"},{"label":"Cones","detail":"Bright, color, fine detail"},{"label":"Fovea","detail":"High cone density"}]},"mnemonic":{"title":"Rods roam at night","cue":"Rods = low light; cones = color","explanation":"Pair the functional contrasts."},"goodToKnow":"Vitamin A is involved in visual pigment physiology, but new night-vision problems should not be assumed to be dietary deficiency.","act":{"type":"choice","prompt":"Which photoreceptors produce color vision?","options":[{"label":"Cones","correct":true,"feedback":"Correct. Cones require more light and distinguish color."},{"label":"Rods","correct":false,"feedback":"Rods are sensitive in dim light but do not produce color vision."},{"label":"Ganglia","correct":false,"feedback":"Ganglion cells relay output rather than detect photons."}]}},{"id":"vision-match","title":"Match it: Photoreceptor contrast","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Dim, sensitive, no color","Bright, color, fine detail","High cone density"],"items":[{"label":"Rods","category":0,"feedback":"Rods: Dim, sensitive, no color"},{"label":"Cones","category":1,"feedback":"Cones: Bright, color, fine detail"},{"label":"Fovea","category":2,"feedback":"Fovea: High cone density"}]}},{"id":"l11-m9","chapter":"Hearing, balance and neurologic vocabulary","chapterSummary":"Mechanical vibration becomes neural activity; condition names point to different tissues and mechanisms.","title":"From sound wave to cochlea","highYield":"Outer ear collects, middle ear transfers, inner ear transduces.","teach":["Sound waves enter the auditory canal and vibrate the tympanic membrane. The malleus, incus and stapes transmit the vibration to the oval window, creating fluid waves in the cochlea that bend sensory hair cells.","Signals travel through the cochlear branch of the vestibulocochlear nerve. The semicircular ducts detect rotational movements, while vestibular structures respond to linear acceleration and head position."],"keyPoints":["Tympanic membrane vibrates first.","Ossicles transmit vibration.","Stapes contacts oval window.","Cochlear hair cells transduce sound.","Vestibular apparatus supports balance."],"visual":{"title":"Sound pathway","kind":"concept-map","items":[{"label":"Canal","detail":"Directs sound"},{"label":"Tympanic membrane","detail":"Vibrates"},{"label":"Ossicles","detail":"Amplify/transfer"},{"label":"Oval window","detail":"Starts inner-ear wave"},{"label":"Cochlea","detail":"Transduces"},{"label":"CN VIII","detail":"Carries signal"}]},"mnemonic":{"title":"TM-O-C","cue":"Tympanic membrane · Ossicles · Cochlea","explanation":"Use the three main stages, then add details."},"goodToKnow":"The auditory tube helps equalize middle-ear pressure; it is not the main sound receptor.","act":{"type":"choice","prompt":"What structure first vibrates when sound reaches the end of the ear canal?","options":[{"label":"Tympanic membrane","correct":true,"feedback":"Correct. It transfers sound energy to the ossicles."},{"label":"Oval window","correct":false,"feedback":"The stapes reaches it after the ossicles move."},{"label":"Retina","correct":false,"feedback":"That is part of the eye."}]}},{"id":"l11-m10","chapter":null,"chapterSummary":null,"title":"Keep neurologic terms distinct","highYield":"Tissue, mechanism and clinical course determine the label.","teach":["Meningitis is inflammation of the meninges; encephalitis is inflammation of brain tissue. Multiple sclerosis involves progressive demyelination in the CNS. Alzheimer disease produces progressive cognitive deterioration, while Parkinson disease is associated with movement-control circuitry.","A stroke results from interrupted or bleeding cerebral circulation; an aneurysm is an abnormal vessel-wall dilation. Epilepsy involves recurrent seizure tendency. These summaries support vocabulary only—diagnosis requires clinical evaluation."],"keyPoints":["Meningitis affects meninges.","Encephalitis affects brain tissue.","Multiple sclerosis involves CNS demyelination.","Stroke is a vascular brain event.","Aneurysm is vessel-wall dilation."],"visual":{"title":"Term sorter","kind":"concept-map","items":[{"label":"Membranes","detail":"Meningitis"},{"label":"Brain tissue inflammation","detail":"Encephalitis"},{"label":"Myelin","detail":"Multiple sclerosis"},{"label":"Blood flow","detail":"Stroke"},{"label":"Vessel wall","detail":"Aneurysm"}]},"mnemonic":{"title":"ME-MSA","cue":"Meningitis · Encephalitis · MS · Stroke · Aneurysm","explanation":"Attach each term to its primary tissue/mechanism."},"goodToKnow":"Similar symptoms can arise from very different processes, which is why pattern-matching is unsafe.","act":{"type":"choice","prompt":"Which term means inflammation of brain tissue?","options":[{"label":"Encephalitis","correct":true,"feedback":"Correct. Encephalo- refers to brain."},{"label":"Meningitis","correct":false,"feedback":"That affects the meninges."},{"label":"Aneurysm","correct":false,"feedback":"That is vessel-wall dilation."}]}},{"id":"hearing-balance-match","title":"Match it: Term sorter","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Meningitis","Encephalitis","Multiple sclerosis","Stroke","Aneurysm"],"items":[{"label":"Brain tissue inflammation","category":1,"feedback":"Brain tissue inflammation: Encephalitis"},{"label":"Vessel wall","category":4,"feedback":"Vessel wall: Aneurysm"},{"label":"Myelin","category":2,"feedback":"Myelin: Multiple sclerosis"},{"label":"Membranes","category":0,"feedback":"Membranes: Meningitis"},{"label":"Blood flow","category":3,"feedback":"Blood flow: Stroke"}]}}],"flashcards":[{"front":"Longitudinal fissure","back":"Deep groove separating the cerebral hemispheres."},{"front":"Gyri","back":"Raised folds of the cerebral cortex."},{"front":"Cerebellum","back":"Region coordinating balance and complex skeletal movement."},{"front":"Reticular formation","back":"Brainstem network involved in arousal and consciousness."},{"front":"Arachnoid mater","back":"Middle meningeal layer."},{"front":"Cerebrospinal fluid","back":"Fluid that cushions and supports the CNS."},{"front":"Trigeminal nerve","back":"Largest cranial nerve; facial sensation and chewing functions."},{"front":"Hypoglossal nerve","back":"Motor nerve controlling tongue movement."},{"front":"Retina","back":"Innermost eye layer containing photoreceptors."},{"front":"Cones","back":"Photoreceptors for color and fine detail in brighter light."},{"front":"Tympanic membrane","back":"Membrane vibrated by incoming sound waves."},{"front":"Encephalitis","back":"Inflammation of brain tissue."},{"front":"Stroke","back":"Brain injury from interrupted or bleeding cerebral circulation."},{"front":"Aneurysm","back":"Abnormal dilation of a blood-vessel wall."}],"quiz":[],"caseStudy":{"title":"One breakfast, many neural tasks","scenario":"An older adult after a clinician-diagnosed stroke has visual-field difficulty, reduced hand control and trouble following a fast conversation.","prompts":["Name the broad brain and sensory systems involved without localizing the lesion.","Identify accommodations that could make counselling accessible.","Explain the roles of cranial nerves and somatic motor pathways in eating.","List issues that require team-based assessment, such as swallowing safety."],"takeaway":"Anatomy helps anticipate functional demands and design access; it does not replace neurologic or swallowing assessment."}},{"n":12,"title":"The Endocrine System","kicker":"Distinguish endocrine from exocrine signaling and compare major hormone classes.","duration":"90–110 minutes","steps":[{"id":"l12-m1","chapter":"How hormones communicate","chapterSummary":"Hormones travel widely but act only where the right receptor and cellular machinery are present.","title":"Endocrine versus exocrine","highYield":"Ductless endocrine glands release to blood; exocrine glands use ducts.","teach":["Endocrine glands secrete hormones into interstitial fluid and then the bloodstream. Hormones circulate throughout the body, but only target cells with suitable receptors respond. Exocrine glands send products through ducts to a surface or lumen.","Neural and endocrine control interact: neural signals are typically rapid and targeted, whereas hormonal signals may begin more slowly and persist longer. The hypothalamus is a central bridge between the systems."],"keyPoints":["Endocrine glands are ductless.","Hormones enter circulation.","Receptors create target specificity.","Exocrine glands use ducts.","Hypothalamus links nervous and endocrine control."],"visual":{"title":"Signal comparison","kind":"concept-map","items":[{"label":"Endocrine","detail":"Blood-borne hormone"},{"label":"Target cell","detail":"Matching receptor"},{"label":"Exocrine","detail":"Duct to surface/lumen"},{"label":"Neural","detail":"Rapid directed signal"}]},"mnemonic":{"title":"ENDO enters blood","cue":"Endocrine goes inward to circulation; exocrine exits by duct","explanation":"Use route, not product name alone."},"goodToKnow":"The pancreas has both endocrine islets and exocrine digestive tissue.","act":{"type":"choice","prompt":"Which statement describes an endocrine gland?","options":[{"label":"It releases hormone into circulation without a duct.","correct":true,"feedback":"Correct. Endocrine glands are ductless."},{"label":"It always releases through a duct.","correct":false,"feedback":"That describes exocrine secretion."},{"label":"It acts on every cell equally.","correct":false,"feedback":"Only receptor-bearing target cells respond."}]}},{"id":"l12-m2","chapter":null,"chapterSummary":null,"title":"Hormone chemistry and receptors","highYield":"Protein, steroid and modified amino-acid hormones signal differently.","teach":["Protein and peptide hormones, including insulin and growth hormone, are water soluble and generally bind membrane receptors, activating internal second-messenger pathways. Steroid hormones, including cortisol and testosterone, are lipid soluble and bind intracellular receptors that influence gene expression.","Modified amino-acid hormones include epinephrine and thyroid hormones. Their behavior depends on structure: catecholamines use membrane receptors, while thyroid hormone acts more like a lipid-soluble signal."],"keyPoints":["Insulin and GH are protein hormones.","Cortisol and testosterone are steroids.","Epinephrine is a modified amino acid.","Water-soluble hormones use membrane receptors.","Steroids use intracellular receptors."],"visual":{"title":"Hormone classes","kind":"concept-map","items":[{"label":"Protein/peptide","detail":"Insulin, GH"},{"label":"Steroid","detail":"Cortisol, testosterone"},{"label":"Modified amino acid","detail":"Epinephrine, thyroid hormone"}]},"mnemonic":{"title":"PSA","cue":"Protein · Steroid · Amino-acid derivative","explanation":"Class first, then attach examples."},"goodToKnow":"A hormone’s chemistry helps predict receptor location, not whether it is “stronger.”","act":{"type":"choice","prompt":"Which pair contains steroid hormones?","options":[{"label":"Cortisol and testosterone","correct":true,"feedback":"Correct. Both derive from cholesterol."},{"label":"Insulin and growth hormone","correct":false,"feedback":"Those are protein hormones."},{"label":"Epinephrine and insulin","correct":false,"feedback":"They belong to different classes."}]}},{"id":"hormone-logic-match","title":"Match it: Signal comparison","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Blood-borne hormone","Matching receptor","Duct to surface/lumen","Rapid directed signal"],"items":[{"label":"Neural","category":3,"feedback":"Neural: Rapid directed signal"},{"label":"Exocrine","category":2,"feedback":"Exocrine: Duct to surface/lumen"},{"label":"Target cell","category":1,"feedback":"Target cell: Matching receptor"},{"label":"Endocrine","category":0,"feedback":"Endocrine: Blood-borne hormone"}]}},{"id":"l12-m3","chapter":"Feedback and the pituitary hub","chapterSummary":"Hormone axes are regulated loops, not one-way chains.","title":"Negative feedback","highYield":"The response reduces the original drive and stabilizes a variable.","teach":["In negative feedback, rising hormone or target-variable levels inhibit further secretion from upstream sources. For example, hypothalamic TRH stimulates pituitary TSH, which stimulates thyroid hormone; adequate thyroid hormone then reduces TRH and TSH drive.","Positive feedback amplifies a process for a limited event. Oxytocin-driven uterine contractions during childbirth are a classic example: contraction promotes additional oxytocin signaling until birth ends the loop."],"keyPoints":["Negative feedback opposes change.","Rising end hormone can inhibit upstream signals.","TRH → TSH → thyroid hormone.","Oxytocin can participate in positive feedback."],"visual":{"title":"Feedback loop","kind":"concept-map","items":[{"label":"Hypothalamus","detail":"Releasing hormone"},{"label":"Anterior pituitary","detail":"Tropic hormone"},{"label":"Target gland","detail":"End hormone"},{"label":"Feedback","detail":"End hormone reduces upstream drive"}]},"mnemonic":{"title":"TRH tells TSH","cue":"TRH from hypothalamus triggers pituitary TSH","explanation":"Then thyroid hormone feeds back."},"goodToKnow":"Feedback is dynamic; a single hormone measurement is interpreted with timing and related signals.","act":{"type":"choice","prompt":"What happens in endocrine negative feedback?","options":[{"label":"A rising output inhibits continued secretion upstream.","correct":true,"feedback":"Correct. The loop resists further change."},{"label":"Every hormone rises without limit.","correct":false,"feedback":"That would not stabilize the system."},{"label":"A duct carries hormone to the target.","correct":false,"feedback":"Endocrine hormones circulate without ducts."}]}},{"id":"l12-m4","chapter":null,"chapterSummary":null,"title":"Anterior and posterior pituitary","highYield":"One lobe synthesizes several hormones; the other stores and releases hypothalamic hormones.","teach":["The pituitary, or hypophysis, has two major lobes. The anterior pituitary produces growth hormone, TSH, ACTH, FSH, LH, prolactin and MSH. GH supports growth and metabolism; MSH can increase pigmentation; LH helps trigger ovulation; prolactin supports milk production after birth.","The posterior pituitary stores and releases oxytocin and antidiuretic hormone made in the hypothalamus. Oxytocin supports uterine contractions and milk ejection; ADH promotes water conservation by the kidneys."],"keyPoints":["Pituitary is also called hypophysis.","Anterior lobe makes GH, TSH, ACTH, FSH, LH, prolactin, MSH.","LH triggers ovulation.","Prolactin supports milk production.","Posterior lobe releases ADH and oxytocin."],"visual":{"title":"Pituitary split","kind":"concept-map","items":[{"label":"Anterior","detail":"Makes multiple tropic/direct hormones"},{"label":"Posterior","detail":"Stores/releases hypothalamic ADH + oxytocin"},{"label":"LH","detail":"Ovulation"},{"label":"Prolactin","detail":"Milk production"},{"label":"MSH","detail":"Pigmentation"}]},"mnemonic":{"title":"FLAT PiG + M","cue":"FSH · LH · ACTH · TSH · Prolactin · GH · MSH","explanation":"A common checklist for anterior-pituitary hormones."},"goodToKnow":"Milk production (prolactin) and milk ejection (oxytocin) are different processes.","act":{"type":"choice","prompt":"Which anterior-pituitary hormone triggers ovulation?","options":[{"label":"Luteinizing hormone","correct":true,"feedback":"Correct. The LH surge triggers ovulation."},{"label":"Oxytocin","correct":false,"feedback":"Oxytocin is released from the posterior pituitary."},{"label":"Aldosterone","correct":false,"feedback":"Aldosterone is an adrenal-cortex hormone."}]}},{"id":"feedback-pituitary-match","title":"Match it: Feedback loop","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Releasing hormone","Tropic hormone","End hormone","End hormone reduces upstream drive"],"items":[{"label":"Feedback","category":3,"feedback":"Feedback: End hormone reduces upstream drive"},{"label":"Target gland","category":2,"feedback":"Target gland: End hormone"},{"label":"Anterior pituitary","category":1,"feedback":"Anterior pituitary: Tropic hormone"},{"label":"Hypothalamus","category":0,"feedback":"Hypothalamus: Releasing hormone"}]}},{"id":"l12-m5","chapter":"Metabolic rate and calcium balance","chapterSummary":"The thyroid and parathyroids regulate different variables despite their close location.","title":"Thyroid hormones and iodine","highYield":"Thyroid hormone supports metabolic activity; calcitonin participates in calcium regulation.","teach":["TSH stimulates the thyroid to produce T3 and T4, hormones that increase metabolic activity in many tissues. Iodine is required to build these hormones. Inadequate iodine can contribute to thyroid enlargement, called goiter, though goiter has more than one possible cause.","Excess thyroid-hormone production is associated with hyperthyroid states such as Graves disease. Severe adult hypothyroid patterns were historically described with myxedema, including fluid accumulation in subcutaneous tissues; diagnosis depends on clinical and laboratory evaluation."],"keyPoints":["TSH stimulates thyroid.","T3/T4 require iodine.","Goiter means enlarged thyroid.","Graves disease is associated with excess thyroid activity.","Myxedema is a severe hypothyroid pattern."],"visual":{"title":"Thyroid chain","kind":"concept-map","items":[{"label":"TRH","detail":"Hypothalamus"},{"label":"TSH","detail":"Anterior pituitary"},{"label":"T3/T4","detail":"Thyroid"},{"label":"Iodine","detail":"Hormone substrate"},{"label":"Feedback","detail":"T3/T4 reduce upstream drive"}]},"mnemonic":{"title":"T3/T4 need I","cue":"Thyroid hormone requires iodine","explanation":"Adequacy matters; more is not automatically better."},"goodToKnow":"Excess iodine can also disrupt thyroid function; avoid treating an assumed deficiency without assessment.","act":{"type":"choice","prompt":"What dietary element is required to synthesize T3 and T4?","options":[{"label":"Iodine","correct":true,"feedback":"Correct. Iodine is built into thyroid hormones."},{"label":"Iron only","correct":false,"feedback":"Iron has many roles but is not the defining thyroid-hormone element."},{"label":"Calcium","correct":false,"feedback":"Calcium is regulated by other endocrine pathways."}]}},{"id":"l12-m6","chapter":null,"chapterSummary":null,"title":"Parathyroid hormone and calcitonin","highYield":"Low blood calcium activates PTH; calcitonin generally opposes that direction.","teach":["When blood calcium falls, parathyroid hormone (PTH) raises it by acting on bone and kidneys and by supporting vitamin-D activation, which increases intestinal calcium absorption. The net effect is to defend extracellular calcium needed for nerve and muscle function.","Calcitonin from thyroid C cells tends to lower blood calcium by discouraging bone resorption, although its role in adult moment-to-moment regulation is smaller than PTH’s. Excess PTH can demineralize and deform bone over time."],"keyPoints":["Parathyroids release PTH.","PTH responds to low blood calcium.","PTH supports renal retention and vitamin-D activation.","Calcitonin tends to lower blood calcium.","Chronic excess PTH can weaken bone."],"visual":{"title":"Calcium directions","kind":"concept-map","items":[{"label":"Low Ca²⁺","detail":"PTH rises"},{"label":"Kidney","detail":"Retain Ca²⁺/activate vitamin D"},{"label":"Intestine","detail":"Absorb more with active vitamin D"},{"label":"Bone","detail":"PTH can increase release"},{"label":"Calcitonin","detail":"Opposing direction"}]},"mnemonic":{"title":"PTH Pulls calcium To Higher blood levels","cue":"PTH raises extracellular calcium","explanation":"Attach the direction before the mechanisms."},"goodToKnow":"Blood calcium is tightly controlled, so a normal blood value does not by itself prove optimal skeletal calcium stores.","act":{"type":"choice","prompt":"Which gland responds when blood calcium is too low?","options":[{"label":"Parathyroid","correct":true,"feedback":"Correct. It releases PTH."},{"label":"Pineal","correct":false,"feedback":"The pineal releases melatonin."},{"label":"Pituitary only","correct":false,"feedback":"It is not the direct calcium-sensing gland in this pathway."}]}},{"id":"thyroid-calcium-match","title":"Match it: Thyroid chain","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Hypothalamus","Anterior pituitary","Thyroid","Hormone substrate","T3/T4 reduce upstream drive"],"items":[{"label":"TSH","category":1,"feedback":"TSH: Anterior pituitary"},{"label":"Feedback","category":4,"feedback":"Feedback: T3/T4 reduce upstream drive"},{"label":"T3/T4","category":2,"feedback":"T3/T4: Thyroid"},{"label":"TRH","category":0,"feedback":"TRH: Hypothalamus"},{"label":"Iodine","category":3,"feedback":"Iodine: Hormone substrate"}]}},{"id":"l12-m7","chapter":"Adrenal layers and stress responses","chapterSummary":"Cortex and medulla have different origins, hormones and time courses.","title":"Adrenal cortex zones","highYield":"Mineral balance, glucose/stress and androgens map from outer to inner cortex.","teach":["The adrenal cortex produces steroid hormones. Its outer zona glomerulosa makes mineralocorticoids such as aldosterone, which promote sodium retention and potassium excretion. The middle zona fasciculata makes glucocorticoids such as cortisol, which influence metabolism and stress adaptation.","The inner zona reticularis produces adrenal androgens. Too little adrenal-cortex output is associated with Addison disease; chronic excess, especially cortisol, with Cushing syndrome. These are clinical diagnoses, not conclusions from body shape or fatigue alone."],"keyPoints":["Cortex makes steroids.","Outer cortex makes mineralocorticoids.","Cortisol is a glucocorticoid.","Inner cortex makes androgens.","Cushing = excess cortex hormones; Addison = deficiency."],"visual":{"title":"Cortex layers","kind":"concept-map","items":[{"label":"Glomerulosa","detail":"Salt/mineralocorticoids"},{"label":"Fasciculata","detail":"Sugar/glucocorticoids"},{"label":"Reticularis","detail":"Sex/androgens"}]},"mnemonic":{"title":"GFR: Salt, Sugar, Sex","cue":"Glomerulosa · Fasciculata · Reticularis","explanation":"Move outer to inner with the three S words."},"goodToKnow":"Cortisol has normal essential functions; “cortisol is bad” is biologically inaccurate.","act":{"type":"choice","prompt":"What does the outer adrenal cortex chiefly secrete?","options":[{"label":"Mineralocorticoids","correct":true,"feedback":"Correct. Aldosterone is the key example."},{"label":"Melatonin","correct":false,"feedback":"That comes from the pineal."},{"label":"Insulin","correct":false,"feedback":"That comes from pancreatic beta cells."}]}},{"id":"l12-m8","chapter":null,"chapterSummary":null,"title":"Adrenal medulla","highYield":"Epinephrine and norepinephrine rapidly support fight-or-flight physiology.","teach":["The adrenal medulla is functionally linked to the sympathetic nervous system. Its chromaffin cells release epinephrine and norepinephrine into blood, extending a rapid challenge response throughout the body.","These catecholamines can increase cardiac activity, redirect blood flow and help mobilize fuel. They are modified amino-acid hormones, unlike the steroid hormones produced by the cortex."],"keyPoints":["Medulla releases epinephrine and norepinephrine.","These are fight-or-flight hormones.","They are modified amino-acid derivatives.","Medulla is linked to sympathetic output.","Cortex hormones are steroids."],"visual":{"title":"One gland, two systems","kind":"concept-map","items":[{"label":"Cortex","detail":"Slower steroid signals"},{"label":"Medulla","detail":"Rapid catecholamines"},{"label":"Epinephrine/NE","detail":"Fight-or-flight"}]},"mnemonic":{"title":"Medulla = emergency middle","cue":"The inner medulla releases rapid challenge signals","explanation":"Contrast it with the steroid cortex."},"goodToKnow":"A short stress response is adaptive; chronic symptoms have many possible contributors.","act":{"type":"choice","prompt":"Which pair is released by the adrenal medulla?","options":[{"label":"Epinephrine and norepinephrine","correct":true,"feedback":"Correct. They are catecholamine fight-or-flight hormones."},{"label":"Insulin and glucagon","correct":false,"feedback":"Those are pancreatic hormones."},{"label":"T3 and T4","correct":false,"feedback":"Those are thyroid hormones."}]}},{"id":"adrenal-stress-match","title":"Match it: Cortex layers","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Salt/mineralocorticoids","Sugar/glucocorticoids","Sex/androgens"],"items":[{"label":"Glomerulosa","category":0,"feedback":"Glomerulosa: Salt/mineralocorticoids"},{"label":"Fasciculata","category":1,"feedback":"Fasciculata: Sugar/glucocorticoids"},{"label":"Reticularis","category":2,"feedback":"Reticularis: Sex/androgens"}]}},{"id":"l12-m9","chapter":"Fuel, reproduction and biological time","chapterSummary":"Pancreas, gonads and pineal gland regulate distinct but interacting variables.","title":"Insulin and glucagon","highYield":"Pancreatic islets defend blood glucose in opposite directions.","teach":["Beta cells release insulin when blood glucose rises. Insulin supports glucose uptake in responsive tissues and storage, so blood glucose falls. Alpha cells release glucagon when glucose is low; glucagon stimulates the liver to break down glycogen and produce/release glucose.","Diabetes mellitus involves inadequate insulin production, impaired insulin action, or both. Polydipsia means excessive thirst; polyuria is excessive urination; polyphagia is excessive hunger. These signs require assessment rather than self-diagnosis."],"keyPoints":["Beta cells make insulin.","Alpha cells make glucagon.","Insulin lowers circulating glucose.","Glucagon raises it through liver action.","Polydipsia means excessive thirst."],"visual":{"title":"Glucose seesaw","kind":"concept-map","items":[{"label":"High glucose","detail":"Insulin from beta cells"},{"label":"Storage/uptake","detail":"Glucose falls"},{"label":"Low glucose","detail":"Glucagon from alpha cells"},{"label":"Liver output","detail":"Glucose rises"}]},"mnemonic":{"title":"I lowers; G gives","cue":"Insulin lowers blood glucose; glucagon gives glucose back","explanation":"Use the directional contrast."},"goodToKnow":"Insulin and glucagon often act together across meals and fasting rather than as isolated switches.","act":{"type":"choice","prompt":"Which pancreatic cells secrete insulin?","options":[{"label":"Beta cells","correct":true,"feedback":"Correct. Beta cells are the insulin source."},{"label":"Alpha cells","correct":false,"feedback":"Alpha cells secrete glucagon."},{"label":"Oxyphil cells","correct":false,"feedback":"Those are found in parathyroid tissue."}]}},{"id":"l12-m10","chapter":null,"chapterSummary":null,"title":"Gonads, prolactin and melatonin","highYield":"Reproductive signals and circadian timing complete the endocrine map.","teach":["The ovaries produce estrogens and progesterone; testes produce testosterone. FSH and LH from the anterior pituitary regulate gonadal function, with LH triggering ovulation. Testosterone and related anabolic steroids have androgenic and anabolic effects; nonmedical use carries risks.","Prolactin supports milk production after childbirth. The pineal gland secretes melatonin, which helps regulate circadian rhythms. Seasonal changes in light can influence melatonin timing, but seasonal affective disorder is more complex than simply “too much melatonin.”"],"keyPoints":["FSH/LH regulate gonads.","LH triggers ovulation.","Prolactin supports milk production.","Pineal gland makes melatonin.","Melatonin helps set circadian rhythms."],"visual":{"title":"Reproduction and rhythm","kind":"concept-map","items":[{"label":"Gonads","detail":"Sex steroids"},{"label":"FSH/LH","detail":"Pituitary control"},{"label":"Prolactin","detail":"Milk production"},{"label":"Pineal","detail":"Melatonin"},{"label":"Melatonin","detail":"Circadian timing"}]},"mnemonic":{"title":"PLM","cue":"Prolactin · LH · Melatonin","explanation":"Milk production, ovulation, biological night."},"goodToKnow":"Anabolic steroids are variants related to testosterone; they are not the same category as stimulants or depressants.","act":{"type":"choice","prompt":"Which hormone helps regulate circadian rhythms?","options":[{"label":"Melatonin","correct":true,"feedback":"Correct. It is secreted by the pineal gland."},{"label":"Aldosterone","correct":false,"feedback":"That regulates sodium and potassium handling."},{"label":"Prolactin","correct":false,"feedback":"That supports milk production."}]}},{"id":"fuel-reproduction-rhythm-match","title":"Match it: Glucose seesaw","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Insulin from beta cells","Glucose falls","Glucagon from alpha cells","Glucose rises"],"items":[{"label":"Liver output","category":3,"feedback":"Liver output: Glucose rises"},{"label":"Low glucose","category":2,"feedback":"Low glucose: Glucagon from alpha cells"},{"label":"Storage/uptake","category":1,"feedback":"Storage/uptake: Glucose falls"},{"label":"High glucose","category":0,"feedback":"High glucose: Insulin from beta cells"}]}}],"flashcards":[{"front":"Endocrine gland","back":"Ductless gland that releases hormone into circulation."},{"front":"Protein hormone","back":"Water-soluble hormone such as insulin or growth hormone."},{"front":"Steroid hormone","back":"Cholesterol-derived hormone such as cortisol or testosterone."},{"front":"Negative feedback","back":"Rising output reduces continued upstream secretion."},{"front":"Hypophysis","back":"Another name for the pituitary gland."},{"front":"Luteinizing hormone","back":"Anterior-pituitary hormone whose surge triggers ovulation."},{"front":"Prolactin","back":"Hormone supporting milk production."},{"front":"Goiter","back":"Enlargement of the thyroid gland."},{"front":"Parathyroid hormone","back":"Hormone that raises blood calcium when it falls."},{"front":"Mineralocorticoid","back":"Adrenal-cortex hormone class regulating electrolytes; aldosterone is the example."},{"front":"Beta cell","back":"Pancreatic islet cell that releases insulin."},{"front":"Glucagon","back":"Pancreatic hormone that raises blood glucose through liver action."},{"front":"Polydipsia","back":"Excessive thirst."},{"front":"Melatonin","back":"Pineal hormone involved in circadian timing."}],"quiz":[],"caseStudy":{"title":"After a meal: a coordinated endocrine story","scenario":"A learner says one high-carbohydrate meal permanently “breaks hormones” and that every tired feeling must be high cortisol.","prompts":["Trace insulin and glucagon around a meal and between meals.","Explain negative feedback using one pituitary axis.","Contrast adrenal cortex and medulla signals.","Identify why symptoms alone cannot establish an endocrine diagnosis.","Offer scope-safe nutrition education without fear-based claims."],"takeaway":"Endocrine regulation is dynamic, receptor-specific and feedback controlled; nutrition matters within a larger physiologic and clinical context."}},{"n":13,"title":"The Blood","kicker":"Explain how plasma and formed elements support transport, regulation, and protection.","duration":"70–90 minutes","steps":[{"id":"l13-m1","chapter":"Build the blood map","chapterSummary":"Start with the liquid matrix, formed elements, and where blood cells come from.","title":"Blood is a moving connective tissue","highYield":"Blood transports materials, stabilizes the internal environment, and limits harm; it is more than a carrier for oxygen.","teach":["Blood is classified as connective tissue because living cells are suspended in an extracellular matrix called plasma. Its transport work includes respiratory gases, nutrients, hormones, heat, and wastes. Its regulatory work supports temperature, fluid balance, and acid–base conditions, while its protective work includes immune defence and hemostasis.","A useful first distinction is concentration versus total amount. A laboratory value reports what is present in a sample under specific conditions; hydration, timing, illness, altitude, and many other factors may influence interpretation. One result is evidence to place in context, not a stand-alone diagnosis."],"keyPoints":["Plasma is the liquid matrix.","Formed elements are erythrocytes, leukocytes, and platelets.","Transport, regulation, and protection overlap.","Concentration and total body amount are not identical."],"visual":{"title":"Three jobs of blood","kind":"map","items":[{"label":"Transport","detail":"Gases, nutrients, hormones, heat, and wastes"},{"label":"Regulate","detail":"Temperature, fluid distribution, and pH"},{"label":"Protect","detail":"Immune activity and control of blood loss"}]},"mnemonic":{"title":"TRP","cue":"Transport · Regulate · Protect","explanation":"Use TRP to recall the three broad functions before naming individual cells."},"goodToKnow":"Plasma volume can change more quickly than red-cell mass, so a concentration can shift even when the total number of cells has not changed by the same proportion.","act":{"type":"choice","prompt":"Which statement best describes blood as a tissue?","options":[{"label":"Cells suspended in a liquid extracellular matrix that supports transport, regulation, and protection","correct":true,"feedback":"Correct. Plasma is the matrix and the formed elements perform specialized work."},{"label":"A fluid made only of water and dissolved nutrients","correct":false,"feedback":"Plasma contains water and dissolved substances, but blood also contains cells and platelets."},{"label":"An organ whose only function is oxygen transport","correct":false,"feedback":"Oxygen transport matters, but blood also regulates and protects."}]}},{"id":"l13-m2","chapter":null,"chapterSummary":null,"title":"Plasma and formed elements tell different parts of the story","highYield":"Plasma carries dissolved materials; formed elements perform cell-based transport, defence, and hemostasis.","teach":["Plasma is mostly water, but its proteins and dissolved solutes make it physiologically active. Albumin contributes to fluid distribution, globulins include transport and immune proteins, and fibrinogen is a precursor used in clot formation. Electrolytes, nutrients, gases, hormones, and wastes travel within this medium.","The formed elements include erythrocytes, several leukocyte families, and platelets. A complete blood count separates these populations because a total blood volume cannot show which component has changed. Reading the compartments first prevents the common error of treating every abnormal blood result as the same problem."],"keyPoints":["Albumin influences oncotic pressure and transport.","Fibrinogen participates in clot formation.","Erythrocytes are the most numerous formed element.","Platelets are cell fragments, not complete cells."],"visual":{"title":"What is in blood?","kind":"layers","items":[{"label":"Plasma","detail":"Water, proteins, electrolytes, nutrients, hormones, gases, and wastes"},{"label":"Buffy coat","detail":"Leukocytes and platelets; a small fraction by volume"},{"label":"Erythrocytes","detail":"The dominant cellular fraction"}]},"mnemonic":{"title":"P-F-E","cue":"Plasma · Formed elements · Examine separately","explanation":"Separate the fluid and cellular compartments before interpreting change."},"goodToKnow":"Serum is the fluid remaining after clotting factors used in coagulation have been removed from plasma.","act":{"type":"choice","prompt":"Which plasma protein is directly converted into a fibrin mesh during coagulation?","options":[{"label":"Fibrinogen","correct":true,"feedback":"Correct. Coagulation converts soluble fibrinogen into insoluble fibrin strands."},{"label":"Hemoglobin","correct":false,"feedback":"Hemoglobin is inside erythrocytes and transports respiratory gases."},{"label":"Keratin","correct":false,"feedback":"Keratin is a structural protein of skin, hair, and nails."}]}},{"id":"composition-match","title":"Match it: Three jobs of blood","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Gases, nutrients, hormones, heat, and wastes","Temperature, fluid distribution, and pH","Immune activity and control of blood loss"],"items":[{"label":"Transport","category":0,"feedback":"Transport: Gases, nutrients, hormones, heat, and wastes"},{"label":"Regulate","category":1,"feedback":"Regulate: Temperature, fluid distribution, and pH"},{"label":"Protect","category":2,"feedback":"Protect: Immune activity and control of blood loss"}]}},{"id":"l13-m3","chapter":"Follow blood-cell life cycles","chapterSummary":"Connect hematopoiesis, erythrocyte design, and leukocyte specialization.","title":"Hematopoiesis is a regulated production system","highYield":"Blood cells arise from stem-cell lineages in red bone marrow and are produced in response to changing needs.","teach":["Hematopoiesis begins with multipotent stem cells in red bone marrow. Through branching lineages, these precursors become erythrocytes, leukocytes, or platelet-producing megakaryocytes. Growth factors and hormones regulate the rate and direction of production rather than all cell types being made equally at all times.","Reduced oxygen delivery stimulates the kidneys to increase erythropoietin signalling, which supports erythrocyte production in marrow. Production also requires raw materials such as amino acids, iron, folate, and vitamin B12. A nutrient is necessary for the pathway, but its necessity does not prove that every low blood count is caused by diet."],"keyPoints":["Red bone marrow is the main production site.","Stem cells branch into specialized lineages.","Kidney oxygen sensing influences erythropoietin.","Adequate substrates do not replace investigation of blood loss, inflammation, or marrow disease."],"visual":{"title":"Production pathway","kind":"flow","items":[{"label":"Stem cell","detail":"Self-renewing marrow precursor"},{"label":"Lineage signals","detail":"Direct development toward red cells, white cells, or platelets"},{"label":"Maturation","detail":"Cells acquire their specialized structure and function"},{"label":"Release","detail":"Mature elements enter circulation"}]},"mnemonic":{"title":"M-S-M-R","cue":"Marrow · Signal · Mature · Release","explanation":"Trace a blood cell from origin to circulation."},"goodToKnow":"Erythropoietin is a signal, not an iron source; marrow still needs appropriate substrates and functional tissue.","act":{"type":"choice","prompt":"Which sequence best represents regulated erythrocyte production?","options":[{"label":"Low oxygen signal → kidney erythropoietin → marrow response → mature erythrocytes","correct":true,"feedback":"Correct. The kidney signal and marrow response are distinct steps."},{"label":"Dietary iron → immediate conversion into circulating red cells","correct":false,"feedback":"Iron is a substrate, but erythrocyte production requires regulated marrow maturation over time."},{"label":"Platelets → leukocytes → erythrocytes","correct":false,"feedback":"These are separate differentiated products of precursor lineages."}]}},{"id":"l13-m4","chapter":null,"chapterSummary":null,"title":"Erythrocyte shape supports gas transport","highYield":"A biconcave, flexible, nucleus-free erythrocyte devotes space to hemoglobin and moves through tiny capillaries.","teach":["Mature erythrocytes are flexible biconcave discs. The shape increases surface area relative to volume and shortens diffusion distance. Loss of the nucleus and most organelles creates room for hemoglobin, but it also limits repair and protein synthesis, so erythrocytes have a finite life span.","Hemoglobin binds oxygen reversibly and participates in carbon-dioxide and acid–base transport. Old or damaged erythrocytes are removed mainly by macrophages in the spleen and liver; useful components such as iron can be recycled, while heme is processed into pigments excreted through bile."],"keyPoints":["Biconcave shape improves exchange area.","Flexibility supports capillary passage.","Hemoglobin carries oxygen reversibly.","Iron can be recycled after erythrocyte breakdown."],"visual":{"title":"Structure serves function","kind":"comparison","items":[{"label":"Biconcave disc","detail":"Large surface area and short diffusion path"},{"label":"Flexible membrane","detail":"Deforms through narrow capillaries"},{"label":"No nucleus","detail":"More space for hemoglobin but little repair capacity"},{"label":"Hemoglobin","detail":"Binds and releases oxygen according to local conditions"}]},"mnemonic":{"title":"SHAPE","cue":"Surface · Hemoglobin · Adaptable · Passage · Exchange","explanation":"SHAPE links erythrocyte anatomy to oxygen delivery."},"goodToKnow":"Hemoglobin concentration, erythrocyte number, and hematocrit are related measurements but are not interchangeable.","act":{"type":"choice","prompt":"Why does the mature erythrocyte lack a nucleus?","options":[{"label":"It allows more internal space for hemoglobin, while limiting the cell's ability to repair itself","correct":true,"feedback":"Correct. The adaptation improves carrying capacity but shortens functional life."},{"label":"It enables the cell to divide rapidly in the bloodstream","correct":false,"feedback":"Mature erythrocytes do not divide."},{"label":"It lets oxygen dissolve only in plasma","correct":false,"feedback":"Most oxygen is carried bound to hemoglobin inside erythrocytes."}]}},{"id":"cells-order","title":"Put it in order: Production pathway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Stem cell","detail":"Self-renewing marrow precursor"},{"label":"Lineage signals","detail":"Direct development toward red cells, white cells, or platelets"},{"label":"Maturation","detail":"Cells acquire their specialized structure and function"},{"label":"Release","detail":"Mature elements enter circulation"}]}},{"id":"cells-match","title":"Match it: Structure serves function","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Large surface area and short diffusion path","Deforms through narrow capillaries","More space for hemoglobin but little repair capacity","Binds and releases oxygen according to local conditions"],"items":[{"label":"Hemoglobin","category":3,"feedback":"Hemoglobin: Binds and releases oxygen according to local conditions"},{"label":"No nucleus","category":2,"feedback":"No nucleus: More space for hemoglobin but little repair capacity"},{"label":"Flexible membrane","category":1,"feedback":"Flexible membrane: Deforms through narrow capillaries"},{"label":"Biconcave disc","category":0,"feedback":"Biconcave disc: Large surface area and short diffusion path"}]}},{"id":"l13-m5","chapter":"Differentiate defence cells","chapterSummary":"Use cell roles—not colour or a single count—to distinguish leukocytes and platelets.","title":"Leukocytes divide defence work","highYield":"Leukocyte families specialize in rapid ingestion, inflammatory signalling, targeted immunity, and cleanup.","teach":["Neutrophils are rapid phagocytic responders, especially in many bacterial infections. Eosinophils participate in responses to parasites and allergic inflammation, while basophils release mediators such as histamine. Monocytes enter tissues and can mature into macrophages that ingest debris and coordinate responses.","Lymphocytes include B cells, T cells, and natural killer cells. Their roles differ, but together they support targeted recognition, antibody production, cellular regulation, and destruction of abnormal or infected cells. Counts vary with age and context, so a differential is interpreted as a pattern rather than a ranking of which cell is most important."],"keyPoints":["Neutrophils are rapid phagocytes.","Eosinophils and basophils contribute to distinct inflammatory patterns.","Monocytes can become tissue macrophages.","Lymphocytes support adaptive and cytotoxic responses."],"visual":{"title":"Leukocyte role map","kind":"map","items":[{"label":"Neutrophil","detail":"Rapid phagocytic response"},{"label":"Eosinophil","detail":"Parasite defence and allergic inflammation"},{"label":"Basophil","detail":"Inflammatory mediator release"},{"label":"Monocyte","detail":"Macrophage precursor and cleanup"},{"label":"Lymphocyte","detail":"Targeted recognition and immune memory"}]},"mnemonic":{"title":"Never Let Monkeys Eat Bananas","cue":"Neutrophils · Lymphocytes · Monocytes · Eosinophils · Basophils","explanation":"A familiar order aid; always pair the name with its actual function."},"goodToKnow":"A high or low leukocyte count describes a laboratory pattern; it does not by itself identify the cause.","act":{"type":"choice","prompt":"Which leukocyte can enter tissue and develop into a macrophage?","options":[{"label":"Monocyte","correct":true,"feedback":"Correct. Circulating monocytes can differentiate into tissue macrophages."},{"label":"Erythrocyte","correct":false,"feedback":"An erythrocyte transports gases and is not a leukocyte."},{"label":"Platelet","correct":false,"feedback":"A platelet is a cell fragment involved in hemostasis."}]}},{"id":"l13-m6","chapter":null,"chapterSummary":null,"title":"Platelets start repair but do not work alone","highYield":"Platelets adhere and aggregate at injury; coagulation then stabilizes the temporary plug with fibrin.","teach":["Platelets are fragments released from large marrow cells called megakaryocytes. When a vessel is injured, local signals expose surfaces that promote platelet adhesion. Activated platelets change shape, release chemical signals, and recruit additional platelets to form a temporary plug.","Platelet activity is only one part of hemostasis. Vascular constriction reduces flow, and the coagulation cascade generates fibrin that reinforces the plug. Later, repair and fibrinolysis remodel and remove the clot. The system must respond strongly at injury while remaining restrained in intact vessels."],"keyPoints":["Platelets derive from megakaryocytes.","Adhesion and aggregation form a temporary plug.","Fibrin stabilizes the plug.","Clot formation and clot removal are both regulated."],"visual":{"title":"From injury to repair","kind":"sequence","items":[{"label":"1 · Constrict","detail":"The damaged vessel narrows"},{"label":"2 · Plug","detail":"Platelets adhere, activate, and aggregate"},{"label":"3 · Reinforce","detail":"Coagulation creates fibrin"},{"label":"4 · Remodel","detail":"Repair proceeds and fibrinolysis limits the clot"}]},"mnemonic":{"title":"CPFR","cue":"Constrict · Plug · Fibrin · Remodel","explanation":"Use the sequence to avoid collapsing all hemostasis into 'clotting.'"},"goodToKnow":"Clotting factors circulate largely as inactive precursors so that coagulation can be amplified locally without continuously clotting the circulation.","act":{"type":"choice","prompt":"What most directly stabilizes the initial platelet plug?","options":[{"label":"A fibrin mesh produced through coagulation","correct":true,"feedback":"Correct. Fibrin reinforces the temporary platelet plug."},{"label":"Conversion of platelets into red blood cells","correct":false,"feedback":"Platelets and erythrocytes are distinct formed elements."},{"label":"Removal of all plasma proteins","correct":false,"feedback":"Plasma clotting proteins are required for coagulation."}]}},{"id":"defence-order","title":"Put it in order: From injury to repair","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"1 · Constrict","detail":"The damaged vessel narrows"},{"label":"2 · Plug","detail":"Platelets adhere, activate, and aggregate"},{"label":"3 · Reinforce","detail":"Coagulation creates fibrin"},{"label":"4 · Remodel","detail":"Repair proceeds and fibrinolysis limits the clot"}]}},{"id":"defence-match","title":"Match it: Leukocyte role map","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Rapid phagocytic response","Parasite defence and allergic inflammation","Inflammatory mediator release","Macrophage precursor and cleanup","Targeted recognition and immune memory"],"items":[{"label":"Eosinophil","category":1,"feedback":"Eosinophil: Parasite defence and allergic inflammation"},{"label":"Lymphocyte","category":4,"feedback":"Lymphocyte: Targeted recognition and immune memory"},{"label":"Basophil","category":2,"feedback":"Basophil: Inflammatory mediator release"},{"label":"Neutrophil","category":0,"feedback":"Neutrophil: Rapid phagocytic response"},{"label":"Monocyte","category":3,"feedback":"Monocyte: Macrophage precursor and cleanup"}]}},{"id":"l13-m7","chapter":"Reason through blood compatibility","chapterSummary":"Separate antigens, antibodies, compatibility testing, and the limits of simplified rules.","title":"ABO type is an antigen–antibody relationship","highYield":"ABO compatibility depends on antigens on erythrocytes and antibodies in plasma; mismatching can cause agglutination and hemolysis.","teach":["In the ABO system, erythrocytes may display A antigen, B antigen, both, or neither. Plasma contains predictable antibodies against the ABO antigen a person lacks. If donor erythrocytes carry an antigen targeted by the recipient's antibodies, cells can agglutinate and be destroyed.","The familiar universal-donor and universal-recipient shortcuts refer to specific components and circumstances, not every transfusion product. Modern transfusion practice uses typing, antibody screening, and crossmatching because ABO is not the only clinically relevant antigen system."],"keyPoints":["Type A cells carry A antigen.","Type B cells carry B antigen.","Type AB cells carry both; type O cells carry neither A nor B.","Compatibility depends on the component and recipient antibodies."],"visual":{"title":"ABO logic","kind":"comparison","items":[{"label":"A","detail":"A antigen; anti-B antibodies"},{"label":"B","detail":"B antigen; anti-A antibodies"},{"label":"AB","detail":"A and B antigens; neither anti-A nor anti-B"},{"label":"O","detail":"Neither A nor B antigen; both anti-A and anti-B"}]},"mnemonic":{"title":"Antigen on, antibody against","cue":"Name what is on the cell; then name what plasma targets","explanation":"This two-step logic is safer than memorizing arrows without understanding them."},"goodToKnow":"Plasma compatibility runs in the opposite conceptual direction from red-cell compatibility because the transfused component contains different antibodies and antigens.","act":{"type":"choice","prompt":"Why can incompatible red-cell transfusion be dangerous?","options":[{"label":"Recipient antibodies can bind donor-cell antigens, causing agglutination and hemolysis","correct":true,"feedback":"Correct. The antigen–antibody reaction can rapidly damage donor erythrocytes."},{"label":"Donor erythrocytes become platelets","correct":false,"feedback":"Cell types do not convert this way."},{"label":"The recipient immediately stops producing plasma","correct":false,"feedback":"The danger is the immune reaction against incompatible cells."}]}},{"id":"l13-m8","chapter":null,"chapterSummary":null,"title":"Rh status adds another compatibility layer","highYield":"Rh-positive means the D antigen is present; Rh-negative means it is absent, but antibody formation usually follows exposure.","teach":["The Rh system includes several antigens, with D being the main antigen used in routine Rh typing. A person who is Rh-negative does not normally have anti-D from birth. Exposure to Rh-positive erythrocytes through transfusion or pregnancy can stimulate antibody formation in some people.","In pregnancy, maternal antibodies formed after sensitization may cross the placenta in a later pregnancy and affect Rh-positive fetal erythrocytes. Prevention and monitoring are medical processes. For study, keep the sequence clear: antigen difference, exposure, sensitization, then possible antibody-mediated effects."],"keyPoints":["Rh status usually refers to D antigen.","Anti-D is generally acquired after exposure.","Sensitization and disease are not the same event.","ABO and Rh are separate classification systems."],"visual":{"title":"Rh sensitization sequence","kind":"flow","items":[{"label":"Antigen difference","detail":"Rh-negative person encounters Rh-positive cells"},{"label":"Exposure","detail":"Transfusion or fetomaternal blood contact"},{"label":"Sensitization","detail":"Immune system forms anti-D"},{"label":"Later exposure","detail":"Antibodies may respond more rapidly"}]},"mnemonic":{"title":"D-E-S-R","cue":"D antigen · Exposure · Sensitize · Respond","explanation":"Use the order to distinguish status from acquired antibody formation."},"goodToKnow":"An antibody screen provides information beyond the ABO/Rh label because other erythrocyte antigens can also matter.","act":{"type":"choice","prompt":"Which statement about an Rh-negative person is most accurate?","options":[{"label":"They lack the D antigen and may form anti-D after exposure to Rh-positive erythrocytes","correct":true,"feedback":"Correct. Rh status describes the antigen; sensitization describes an acquired immune response."},{"label":"They are born with large amounts of anti-D in every case","correct":false,"feedback":"Anti-D usually develops after exposure rather than being naturally present."},{"label":"They cannot have any other red-cell antigens","correct":false,"feedback":"Rh D is only one antigen among many blood-group systems."}]}},{"id":"compatibility-order","title":"Put it in order: Rh sensitization sequence","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Antigen difference","detail":"Rh-negative person encounters Rh-positive cells"},{"label":"Exposure","detail":"Transfusion or fetomaternal blood contact"},{"label":"Sensitization","detail":"Immune system forms anti-D"},{"label":"Later exposure","detail":"Antibodies may respond more rapidly"}]}},{"id":"compatibility-match","title":"Match it: ABO logic","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["A antigen; anti-B antibodies","B antigen; anti-A antibodies","A and B antigens; neither anti-A nor anti-B","Neither A nor B antigen; both anti-A and anti-B"],"items":[{"label":"O","category":3,"feedback":"O: Neither A nor B antigen; both anti-A and anti-B"},{"label":"AB","category":2,"feedback":"AB: A and B antigens; neither anti-A nor anti-B"},{"label":"B","category":1,"feedback":"B: B antigen; anti-A antibodies"},{"label":"A","category":0,"feedback":"A: A antigen; anti-B antibodies"}]}}],"flashcards":[{"front":"Plasma","back":"The liquid extracellular matrix of blood containing water, proteins, electrolytes, nutrients, hormones, gases, and wastes."},{"front":"Formed elements","back":"Erythrocytes, leukocytes, and platelets suspended in plasma."},{"front":"Hematopoiesis","back":"The regulated formation and maturation of blood cells, mainly in red bone marrow."},{"front":"Erythropoietin","back":"A kidney-derived signal that increases marrow erythrocyte production when oxygen delivery is reduced."},{"front":"Hemoglobin","back":"The erythrocyte protein that reversibly binds oxygen and contributes to gas and acid–base transport."},{"front":"Neutrophil","back":"A rapid phagocytic leukocyte important in many acute bacterial responses."},{"front":"Monocyte","back":"A circulating leukocyte that can enter tissue and differentiate into a macrophage."},{"front":"Platelet","back":"A megakaryocyte-derived cell fragment that adheres and aggregates at vessel injury."},{"front":"Fibrin","back":"An insoluble protein mesh that stabilizes a platelet plug during coagulation."},{"front":"ABO antigen","back":"An A or B surface marker on erythrocytes used in ABO blood typing."},{"front":"Agglutination","back":"Clumping that can occur when antibodies bind incompatible erythrocyte antigens."},{"front":"Rh sensitization","back":"Formation of anti-D after an Rh-negative person is exposed to Rh-positive erythrocytes."}],"quiz":[],"caseStudy":{"title":"Fatigue, a low hemoglobin result, and a tempting shortcut","scenario":"A client reports persistent fatigue and shows you a recent low hemoglobin result. They assume the answer is to buy the highest-dose iron supplement immediately. They also report heavy menstrual bleeding and have not discussed the result with their clinician.","prompts":["Which blood measurements and contextual questions would help separate anemia from its possible causes?","Why does iron's role in hemoglobin not prove iron deficiency from this information alone?","What food-intake information is useful within nutrition scope?","What follow-up is appropriate before high-dose supplementation?"],"takeaway":"Connect physiology to safe reasoning: low hemoglobin warrants cause-focused assessment. Nutrition history can support the picture, but blood loss, inflammation, absorption, inherited conditions, and other causes require appropriate clinical evaluation."}},{"n":14,"title":"The Cardiovascular Circulatory System","kicker":"Trace blood through the chambers, valves, lungs, and systemic circulation.","duration":"80–100 minutes","steps":[{"id":"l14-m1","chapter":"Build the heart as a pump","chapterSummary":"Learn the coverings, wall layers, chambers, valves, and great vessels as one connected design.","title":"The heart wall and its coverings have distinct jobs","highYield":"Pericardium contains and protects; myocardium contracts; endocardium lines the chambers and valves.","teach":["The heart sits within a pericardial sac that limits friction and helps contain the organ. The wall itself includes an outer epicardial surface, a thick myocardium, and a smooth endocardial lining. The myocardium is thickest where the pressure demand is greatest, especially in the left ventricle.","Layer names are easiest to learn by asking what touches what. The endocardium touches blood, myocardium produces force, and the outer surface meets the pericardial space. Inflammation or damage in one layer is not automatically equivalent to disease in another."],"keyPoints":["The pericardium surrounds the heart.","Myocardium is cardiac muscle.","Endocardium lines chambers and valves.","Left ventricular myocardium is especially thick."],"visual":{"title":"Heart from outside to inside","kind":"layers","items":[{"label":"Fibrous/serous pericardium","detail":"Protective sac and low-friction surfaces"},{"label":"Epicardium","detail":"Outer heart-wall layer"},{"label":"Myocardium","detail":"Contractile cardiac muscle"},{"label":"Endocardium","detail":"Smooth inner lining"}]},"mnemonic":{"title":"E-M-E","cue":"Epicardium · Myocardium · Endocardium","explanation":"Move from exterior to interior; myocardium in the middle makes the movement."},"goodToKnow":"The wall of the left ventricle is thicker because it must generate pressure for systemic circulation, not because it contains more blood.","act":{"type":"choice","prompt":"Which layer generates the force that ejects blood?","options":[{"label":"Myocardium","correct":true,"feedback":"Correct. Cardiac muscle in the myocardium contracts."},{"label":"Endocardium","correct":false,"feedback":"The endocardium is the inner lining."},{"label":"Parietal pericardium","correct":false,"feedback":"The pericardium surrounds the heart but does not pump blood."}]}},{"id":"l14-m2","chapter":null,"chapterSummary":null,"title":"Four chambers create two coordinated pumps","highYield":"The right side sends blood to the lungs; the left side sends blood to the body.","teach":["The atria receive blood and the ventricles eject it. The right atrium receives systemic venous blood, and the right ventricle sends it through the pulmonary trunk toward the lungs. Pulmonary veins return oxygenated blood to the left atrium, and the left ventricle ejects it into the aorta.","Septa separate the right and left sides, while valves support one-way movement. The tricuspid and mitral valves lie between atria and ventricles; the pulmonary and aortic semilunar valves guard ventricular outflow. Valves open and close because pressure gradients change, not because they actively pull themselves open."],"keyPoints":["Atria receive; ventricles eject.","Right heart supports pulmonary flow.","Left heart supports systemic flow.","Pressure differences operate the valves."],"visual":{"title":"Chambers and valves","kind":"flow","items":[{"label":"Right atrium","detail":"Receives vena-caval and coronary venous return"},{"label":"Tricuspid valve","detail":"Directs flow to right ventricle"},{"label":"Pulmonary valve","detail":"Directs flow to pulmonary trunk"},{"label":"Left atrium","detail":"Receives pulmonary venous return"},{"label":"Mitral and aortic valves","detail":"Direct flow through left ventricle into aorta"}]},"mnemonic":{"title":"A-V-E","cue":"Atrium receives · Ventricle pumps · Exit through semilunar valve","explanation":"Use AVE on both sides of the heart."},"goodToKnow":"Pulmonary arteries carry deoxygenated blood and pulmonary veins carry oxygenated blood; artery and vein are defined by direction relative to the heart.","act":{"type":"choice","prompt":"What directly causes a normal heart valve to open?","options":[{"label":"A pressure difference across the valve","correct":true,"feedback":"Correct. Flow follows the pressure gradient and moves the valve leaflets."},{"label":"A valve-specific nerve pulling it open","correct":false,"feedback":"Valves operate passively through pressure changes."},{"label":"The colour of the blood","correct":false,"feedback":"Diagram colours do not control physiology."}]}},{"id":"heart-structure-order","title":"Put it in order: Chambers and valves","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Right atrium","detail":"Receives vena-caval and coronary venous return"},{"label":"Tricuspid valve","detail":"Directs flow to right ventricle"},{"label":"Pulmonary valve","detail":"Directs flow to pulmonary trunk"},{"label":"Left atrium","detail":"Receives pulmonary venous return"},{"label":"Mitral and aortic valves","detail":"Direct flow through left ventricle into aorta"}]}},{"id":"heart-structure-match","title":"Match it: Heart from outside to inside","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Protective sac and low-friction surfaces","Outer heart-wall layer","Contractile cardiac muscle","Smooth inner lining"],"items":[{"label":"Endocardium","category":3,"feedback":"Endocardium: Smooth inner lining"},{"label":"Myocardium","category":2,"feedback":"Myocardium: Contractile cardiac muscle"},{"label":"Epicardium","category":1,"feedback":"Epicardium: Outer heart-wall layer"},{"label":"Fibrous/serous pericardium","category":0,"feedback":"Fibrous/serous pericardium: Protective sac and low-friction surfaces"}]}},{"id":"l14-m3","chapter":"Follow flow and electrical timing","chapterSummary":"Connect circulation order, conduction, and the mechanical cardiac cycle.","title":"Trace one complete circuit without skipping the lungs","highYield":"Systemic return → right heart → lungs → left heart → systemic arteries.","teach":["A complete trace begins with systemic veins entering the venae cavae, then passes through the right atrium, tricuspid valve, right ventricle, pulmonary valve, pulmonary trunk, and pulmonary arteries. Gas exchange occurs in lung capillaries before pulmonary veins return blood to the left atrium.","Blood then crosses the mitral valve into the left ventricle, passes the aortic valve, and enters the aorta. Coronary arteries branch near the aortic root to supply the heart itself. Remember that the two pumps work in series: sustained output from one side must be matched by the other."],"keyPoints":["Pulmonary circulation links right and left heart.","Systemic circulation begins at the aorta.","Coronary circulation supplies myocardium.","The two sides pump the same long-term volume."],"visual":{"title":"One red-cell journey","kind":"sequence","items":[{"label":"Systemic veins","detail":"Return blood to venae cavae"},{"label":"Right heart","detail":"Receives and sends blood to lungs"},{"label":"Lung capillaries","detail":"Exchange oxygen and carbon dioxide"},{"label":"Left heart","detail":"Receives and sends blood to aorta"},{"label":"Systemic capillaries","detail":"Exchange with tissues"}]},"mnemonic":{"title":"Body–Right–Lungs–Left–Body","cue":"BRLLB","explanation":"Say the five locations before adding chambers and valves."},"goodToKnow":"Oxygenation changes in capillary beds; it does not occur simply because blood enters an artery or vein.","act":{"type":"choice","prompt":"Which vessel returns oxygenated blood from the lungs?","options":[{"label":"Pulmonary veins","correct":true,"feedback":"Correct. They enter the left atrium."},{"label":"Pulmonary arteries","correct":false,"feedback":"Pulmonary arteries carry blood from the right ventricle toward the lungs."},{"label":"Superior vena cava","correct":false,"feedback":"It returns systemic venous blood to the right atrium."}]}},{"id":"l14-m4","chapter":null,"chapterSummary":null,"title":"Electrical conduction coordinates contraction","highYield":"SA node initiates, AV node delays, and the ventricular conduction network distributes the impulse.","teach":["Autorhythmic cells can generate electrical activity without a motor nerve initiating every beat. The sinoatrial node normally sets the rhythm across the atria. The atrioventricular node briefly delays conduction, allowing atrial emptying before the impulse travels into the atrioventricular bundle.","Bundle branches and Purkinje fibres distribute activation through ventricular myocardium so contraction proceeds efficiently. Electrical activity and mechanical contraction are linked but not identical; an electrocardiogram records surface electrical patterns, not the pumping force itself."],"keyPoints":["SA node is the usual pacemaker.","AV delay supports filling.","Bundle branches and Purkinje fibres activate ventricles.","ECG reflects electrical, not direct mechanical, activity."],"visual":{"title":"Conduction pathway","kind":"flow","items":[{"label":"SA node","detail":"Initiates atrial depolarization"},{"label":"AV node","detail":"Brief delay"},{"label":"AV bundle","detail":"Only normal electrical bridge through fibrous skeleton"},{"label":"Bundle branches","detail":"Travel through interventricular septum"},{"label":"Purkinje network","detail":"Distributes activation through ventricles"}]},"mnemonic":{"title":"Start–Await–Bundle–Branch–Purkinje","cue":"S-A-B-B-P","explanation":"The sequence mirrors the path from pacemaker to ventricular muscle."},"goodToKnow":"Autonomic nerves change heart rate and force, but the intrinsic conduction system organizes the beat.","act":{"type":"choice","prompt":"Why is the AV nodal delay useful?","options":[{"label":"It gives the atria time to complete emptying before ventricular contraction","correct":true,"feedback":"Correct. Timing supports efficient sequential pumping."},{"label":"It oxygenates blood inside the node","correct":false,"feedback":"Gas exchange occurs mainly in capillaries, not the AV node."},{"label":"It closes every blood vessel","correct":false,"feedback":"The AV node coordinates electrical timing, not vessel closure."}]}},{"id":"flow-rhythm-order","title":"Put it in order: One red-cell journey","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Systemic veins","detail":"Return blood to venae cavae"},{"label":"Right heart","detail":"Receives and sends blood to lungs"},{"label":"Lung capillaries","detail":"Exchange oxygen and carbon dioxide"},{"label":"Left heart","detail":"Receives and sends blood to aorta"},{"label":"Systemic capillaries","detail":"Exchange with tissues"}]}},{"id":"l14-m5","chapter":"Connect the cardiac cycle to vessels","chapterSummary":"Distinguish systole, diastole, vessel walls, and capillary exchange.","title":"Systole and diastole describe changing pressure phases","highYield":"Filling and ejection depend on pressure gradients created by relaxation and contraction.","teach":["During ventricular diastole, ventricular pressure falls and the atrioventricular valves open when atrial pressure is higher. Ventricular filling is mostly passive, with atrial contraction adding the final portion. During ventricular systole, pressure rises, atrioventricular valves close, and semilunar valves open once ventricular pressure exceeds arterial pressure.","Heart sounds are associated mainly with valve closure and surrounding vibration. Stroke volume is the amount ejected per beat, while cardiac output is heart rate multiplied by stroke volume. These values change with activity and physiological demand rather than remaining fixed at one ideal number."],"keyPoints":["Diastole supports filling.","Systole supports ejection.","Valves respond to pressure gradients.","Cardiac output = heart rate × stroke volume."],"visual":{"title":"Cycle logic","kind":"comparison","items":[{"label":"Diastole","detail":"Ventricular relaxation and filling"},{"label":"AV-valve closure","detail":"Beginning of ventricular systole"},{"label":"Ejection","detail":"Semilunar valves open when ventricular pressure is higher"},{"label":"Semilunar closure","detail":"Occurs as arterial pressure exceeds ventricular pressure"}]},"mnemonic":{"title":"D fills, S sends","cue":"Diastole fills · Systole sends","explanation":"A compact cue for the ventricular cycle."},"goodToKnow":"Blood pressure and cardiac output are related but not equivalent; pressure also depends strongly on vessel resistance and arterial properties.","act":{"type":"choice","prompt":"What is cardiac output?","options":[{"label":"Heart rate multiplied by stroke volume","correct":true,"feedback":"Correct. It estimates volume pumped per minute."},{"label":"Systolic pressure minus diastolic pressure","correct":false,"feedback":"That difference is pulse pressure."},{"label":"The amount of blood in the entire body","correct":false,"feedback":"Cardiac output is flow per unit time."}]}},{"id":"l14-m6","chapter":null,"chapterSummary":null,"title":"Vessel walls match pressure and exchange","highYield":"Arteries distribute under pressure, veins return with high capacitance, and capillaries optimize exchange.","teach":["Arteries have a prominent smooth-muscle and elastic middle layer that tolerates and adjusts to pulsatile pressure. Veins operate at lower pressure, have thinner walls and larger lumens, and often use valves plus skeletal-muscle and respiratory pumps to support return to the heart.","Capillary walls are primarily a single endothelial layer with a basement membrane, minimizing diffusion distance. Their enormous total cross-sectional area slows flow and supports exchange. Arterioles provide major resistance control; venules collect blood from capillary beds."],"keyPoints":["Arteries carry blood away from the heart.","Veins carry blood toward the heart.","Capillaries are exchange vessels.","Arterioles strongly influence local resistance."],"visual":{"title":"Vessel comparison","kind":"comparison","items":[{"label":"Artery","detail":"Thick, elastic, muscular wall; higher pressure"},{"label":"Vein","detail":"Larger lumen; lower pressure; valves in many regions"},{"label":"Capillary","detail":"One-cell-thick exchange surface"},{"label":"Arteriole","detail":"Adjustable resistance vessel"}]},"mnemonic":{"title":"Away–Return–Exchange","cue":"Artery away · Vein return · Capillary exchange","explanation":"Direction defines artery and vein; wall design supports the job."},"goodToKnow":"A vessel carrying oxygen-poor blood can still be an artery if it carries blood away from the heart.","act":{"type":"choice","prompt":"Which vessel is best designed for diffusion between blood and tissue?","options":[{"label":"Capillary","correct":true,"feedback":"Correct. Its thin wall and broad network support exchange."},{"label":"Aorta","correct":false,"feedback":"The aorta is designed for high-pressure distribution."},{"label":"Vena cava","correct":false,"feedback":"The vena cava is a large return vessel."}]}},{"id":"cycle-vessels-match","title":"Match it: Cycle logic","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Ventricular relaxation and filling","Beginning of ventricular systole","Semilunar valves open when ventricular pressure is higher","Occurs as arterial pressure exceeds ventricular pressure"],"items":[{"label":"Semilunar closure","category":3,"feedback":"Semilunar closure: Occurs as arterial pressure exceeds ventricular pressure"},{"label":"Ejection","category":2,"feedback":"Ejection: Semilunar valves open when ventricular pressure is higher"},{"label":"AV-valve closure","category":1,"feedback":"AV-valve closure: Beginning of ventricular systole"},{"label":"Diastole","category":0,"feedback":"Diastole: Ventricular relaxation and filling"}]}},{"id":"l14-m7","chapter":"Think in routes and regulation","chapterSummary":"Use circulation routes and homeostatic reasoning in applied scenarios.","title":"Not every circuit follows the same itinerary","highYield":"Pulmonary, coronary, systemic, and portal routes serve different exchange needs.","teach":["Pulmonary circulation moves blood between heart and lungs. Coronary circulation supplies the myocardium. Systemic circulation serves the rest of the body, while portal circulation sends blood through a second capillary bed before returning to the heart. The hepatic portal route carries nutrient-rich blood from digestive organs to the liver.","The liver can process, store, transform, or release absorbed substances before they enter the general circulation. This first-pass relationship is central to nutrient handling and many medicines. It does not mean all absorbed material is stored, nor that the liver 'detoxes' every exposure completely."],"keyPoints":["Coronary circulation feeds the heart muscle.","Pulmonary circulation supports gas exchange.","Hepatic portal blood reaches the liver before systemic return.","Routes reflect the exchange task."],"visual":{"title":"Four circulation routes","kind":"map","items":[{"label":"Pulmonary","detail":"Heart ↔ lungs"},{"label":"Coronary","detail":"Aorta → myocardium → coronary sinus/right atrium"},{"label":"Systemic","detail":"Left heart → body tissues → right heart"},{"label":"Hepatic portal","detail":"Digestive capillaries → portal vein → liver sinusoids"}]},"mnemonic":{"title":"PCSH","cue":"Pulmonary · Coronary · Systemic · Hepatic portal","explanation":"Name the destination and purpose for each route."},"goodToKnow":"Dietary lipids are initially routed largely through intestinal lymph rather than directly through the hepatic portal vein.","act":{"type":"choice","prompt":"Where does blood from most absorbed water-soluble nutrients travel first?","options":[{"label":"Through the hepatic portal vein to the liver","correct":true,"feedback":"Correct. The liver receives portal blood from digestive organs."},{"label":"Directly from the intestine into the left ventricle","correct":false,"feedback":"Venous return reaches the liver and then the right heart before systemic circulation."},{"label":"Only into the coronary arteries","correct":false,"feedback":"Coronary arteries supply the myocardium."}]}},{"id":"l14-m8","chapter":null,"chapterSummary":null,"title":"Perfusion depends on pump, pipes, and volume","highYield":"Tissue delivery reflects cardiac output, vessel resistance, circulating volume, and local control.","teach":["Cardiovascular homeostasis is a coordinated problem. The heart provides flow, arteries distribute pressure, arterioles adjust resistance, capillaries exchange, and veins return volume. Nervous, endocrine, renal, and local tissue signals continually alter this system to match changing demand.","Population-level dietary patterns can influence long-term cardiovascular risk, but a single nutrient cannot explain an individual's pressure, symptoms, or disease. Accurate practice separates risk-factor education from diagnosis and recognizes urgent symptoms that need immediate medical assessment."],"keyPoints":["Flow requires a pressure gradient.","Resistance changes strongly with vessel radius.","Kidneys influence long-term volume and pressure.","Risk education is not acute symptom assessment."],"visual":{"title":"Perfusion model","kind":"map","items":[{"label":"Pump","detail":"Heart rate and stroke volume"},{"label":"Pipes","detail":"Vessel radius and elasticity"},{"label":"Volume","detail":"Blood and extracellular-fluid regulation"},{"label":"Demand","detail":"Local metabolic control in tissues"}]},"mnemonic":{"title":"PPVD","cue":"Pump · Pipes · Volume · Demand","explanation":"Use all four before explaining tissue perfusion."},"goodToKnow":"Sodium affects extracellular-fluid regulation, but pressure response varies and cannot be inferred from one meal.","act":{"type":"choice","prompt":"Which change most directly raises resistance in a small artery?","options":[{"label":"A decrease in vessel radius","correct":true,"feedback":"Correct. Narrowing greatly increases resistance to flow."},{"label":"A larger capillary exchange area","correct":false,"feedback":"Exchange area affects velocity and diffusion, not arteriolar radius directly."},{"label":"Opening an atrioventricular valve","correct":false,"feedback":"That changes intracardiac flow, not small-artery resistance."}]}},{"id":"integration-match","title":"Match it: Four circulation routes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Heart ↔ lungs","Aorta → myocardium → coronary sinus/right atrium","Left heart → body tissues → right heart","Digestive capillaries → portal vein → liver sinusoids"],"items":[{"label":"Hepatic portal","category":3,"feedback":"Hepatic portal: Digestive capillaries → portal vein → liver sinusoids"},{"label":"Systemic","category":2,"feedback":"Systemic: Left heart → body tissues → right heart"},{"label":"Coronary","category":1,"feedback":"Coronary: Aorta → myocardium → coronary sinus/right atrium"},{"label":"Pulmonary","category":0,"feedback":"Pulmonary: Heart ↔ lungs"}]}}],"flashcards":[{"front":"Myocardium","back":"The contractile cardiac-muscle layer of the heart wall."},{"front":"Endocardium","back":"The smooth inner lining of heart chambers and valves."},{"front":"Tricuspid valve","back":"The right atrioventricular valve between right atrium and ventricle."},{"front":"Mitral valve","back":"The left atrioventricular valve between left atrium and ventricle."},{"front":"SA node","back":"The usual pacemaker that initiates atrial depolarization."},{"front":"AV node","back":"The conduction site that briefly delays the impulse before ventricular activation."},{"front":"Stroke volume","back":"The amount of blood ejected by one ventricle per beat."},{"front":"Cardiac output","back":"Heart rate multiplied by stroke volume; flow per minute."},{"front":"Arteriole","back":"A small resistance vessel that regulates flow into capillary beds."},{"front":"Capillary","back":"A microscopic thin-walled vessel specialized for exchange."},{"front":"Hepatic portal circulation","back":"Route carrying blood from digestive capillaries to liver sinusoids before systemic return."},{"front":"Coronary circulation","back":"Blood supply serving the myocardium itself."}],"quiz":[],"caseStudy":{"title":"A number, a symptom, and two different priorities","scenario":"A client wants nutrition advice after a home blood-pressure reading. During the conversation they also mention new chest pressure while climbing stairs. They ask whether simply avoiding salt for a week will settle both concerns.","prompts":["Which information belongs to long-term cardiovascular risk education?","Why can one home reading not define the mechanism?","Which symptom changes the priority of the conversation?","How can you state the nutrition role without delaying appropriate assessment?"],"takeaway":"Nutrition can support long-term cardiovascular health, but new exertional chest pressure requires prompt medical assessment. Do not let risk-factor counselling become a substitute for symptom triage."}},{"n":15,"title":"The Lymphatic Circulatory System","kicker":"Explain how lymphatic vessels return interstitial fluid and absorbed lipids to circulation.","duration":"75–95 minutes","steps":[{"id":"l15-m1","chapter":"Follow fluid back to blood","chapterSummary":"Understand one-way lymph flow, vessel design, and intestinal lipid transport.","title":"Lymph begins as interstitial fluid","highYield":"The lymphatic system returns excess tissue fluid and proteins that blood capillaries do not directly recover.","teach":["Fluid filters from blood capillaries into the interstitial space, where it supports exchange with cells. Most returns locally to blood, while a portion enters blind-ended lymphatic capillaries. Once inside the lymphatic network, the fluid is called lymph.","Lymphatic capillaries have overlapping endothelial flaps that open when tissue pressure rises. Larger vessels contain valves and ultimately return lymph to large veins near the base of the neck. If filtration, return, or drainage becomes unbalanced, fluid can accumulate in tissues, but the cause cannot be identified from swelling alone."],"keyPoints":["Interstitial fluid becomes lymph after entering lymphatic capillaries.","Lymph flow is one-way toward the venous circulation.","Valves limit backflow.","Edema reflects a fluid-balance problem, not one single diagnosis."],"visual":{"title":"Fluid recovery loop","kind":"flow","items":[{"label":"Blood capillary","detail":"Filters fluid into tissue"},{"label":"Interstitial space","detail":"Exchange environment around cells"},{"label":"Lymphatic capillary","detail":"Collects excess fluid and proteins"},{"label":"Lymphatic ducts","detail":"Return lymph to large veins"}]},"mnemonic":{"title":"Filter–Feed–Fetch–Flow back","cue":"FFFF","explanation":"Blood filters, tissue fluid feeds cells, lymphatics fetch excess, and lymph flows back to veins."},"goodToKnow":"The lymphatic circulation has no single central pump equivalent to the heart.","act":{"type":"choice","prompt":"When does interstitial fluid become lymph?","options":[{"label":"After it enters a lymphatic capillary","correct":true,"feedback":"Correct. Location within the lymphatic vessel defines lymph."},{"label":"As soon as plasma leaves the heart","correct":false,"feedback":"Fluid becomes interstitial after capillary filtration and lymph only after lymphatic entry."},{"label":"Only after passing through the spleen","correct":false,"feedback":"Lymph is present throughout lymphatic vessels before any organ encounter."}]}},{"id":"l15-m2","chapter":null,"chapterSummary":null,"title":"Movement depends on valves and body motion","highYield":"Skeletal-muscle contraction, breathing, smooth muscle, and valves move lymph through a low-pressure system.","teach":["Lymphatic vessels resemble thin-walled veins but begin as capillaries in tissues. Contraction of surrounding skeletal muscle compresses them, pressure changes during breathing draw lymph toward the thorax, and smooth muscle in larger vessel walls contributes rhythmic propulsion.","Valves segment the pathway so each compression tends to move fluid centrally. The right lymphatic duct drains part of the upper body, while the thoracic duct drains most remaining regions. Both empty into venous circulation near the junctions of internal jugular and subclavian veins."],"keyPoints":["Lymph flow is low pressure.","Muscle and respiratory pumps assist movement.","The thoracic duct drains most of the body.","Ducts return lymph to venous blood."],"visual":{"title":"What moves lymph?","kind":"map","items":[{"label":"Skeletal-muscle pump","detail":"External compression of vessels"},{"label":"Respiratory pump","detail":"Thoracic pressure changes during breathing"},{"label":"Vessel smooth muscle","detail":"Intrinsic contraction in larger vessels"},{"label":"Valves","detail":"Limit reverse flow"}]},"mnemonic":{"title":"Move–Breathe–Valve","cue":"MBV","explanation":"Movement and breathing provide pressure; valves preserve direction."},"goodToKnow":"Being still does not stop all lymph flow, but ordinary movement contributes to its efficiency.","act":{"type":"choice","prompt":"Which feature most directly prevents lymph from moving backward after a vessel is compressed?","options":[{"label":"Valves","correct":true,"feedback":"Correct. Valves create one-way segments."},{"label":"Erythrocytes","correct":false,"feedback":"Lymph normally contains few or no erythrocytes."},{"label":"Gastric acid","correct":false,"feedback":"Gastric acid has no role in lymphatic valve function."}]}},{"id":"circulation-order","title":"Put it in order: Fluid recovery loop","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Blood capillary","detail":"Filters fluid into tissue"},{"label":"Interstitial space","detail":"Exchange environment around cells"},{"label":"Lymphatic capillary","detail":"Collects excess fluid and proteins"},{"label":"Lymphatic ducts","detail":"Return lymph to large veins"}]}},{"id":"circulation-match","title":"Match it: What moves lymph?","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["External compression of vessels","Thoracic pressure changes during breathing","Intrinsic contraction in larger vessels","Limit reverse flow"],"items":[{"label":"Valves","category":3,"feedback":"Valves: Limit reverse flow"},{"label":"Vessel smooth muscle","category":2,"feedback":"Vessel smooth muscle: Intrinsic contraction in larger vessels"},{"label":"Respiratory pump","category":1,"feedback":"Respiratory pump: Thoracic pressure changes during breathing"},{"label":"Skeletal-muscle pump","category":0,"feedback":"Skeletal-muscle pump: External compression of vessels"}]}},{"id":"l15-m3","chapter":"Map lymphatic organs","chapterSummary":"Separate filtration of lymph, filtration of blood, immune-cell maturation, and mucosal surveillance.","title":"Nodes filter lymph and organize responses","highYield":"Lymph nodes sample lymph, house immune cells, and slow flow so antigens and cells can interact.","teach":["A lymph node receives lymph through multiple afferent vessels and releases it through fewer efferent vessels at the hilum. Its capsule and internal sinuses channel flow through regions rich in macrophages, B cells, T cells, and antigen-presenting cells.","Nodes enlarge for many reasons, including immune-cell activation, increased traffic, infection, and malignancy. Tenderness, location, duration, and associated symptoms matter. A palpable node is an observation—not enough information to label the cause."],"keyPoints":["Afferent vessels enter; efferent vessels exit.","Nodes filter lymph, not blood.","Cortex and deeper regions organize immune cells.","Node enlargement has multiple possible causes."],"visual":{"title":"Through a lymph node","kind":"flow","items":[{"label":"Afferent vessels","detail":"Bring lymph into the capsule"},{"label":"Sinuses","detail":"Slow and channel flow"},{"label":"Immune zones","detail":"Support B-cell, T-cell, and macrophage interactions"},{"label":"Efferent vessel","detail":"Carries filtered lymph away"}]},"mnemonic":{"title":"A arrives, E exits","cue":"Afferent arrives · Efferent exits","explanation":"Use the first letters to keep vessel direction straight."},"goodToKnow":"Cancer cells may travel through lymph and be found in nodes, but node enlargement is not synonymous with cancer.","act":{"type":"choice","prompt":"Which statement correctly distinguishes lymph nodes from the spleen?","options":[{"label":"Nodes filter lymph; the spleen filters blood","correct":true,"feedback":"Correct. Their fluid pathways differ."},{"label":"Nodes pump blood; the spleen produces bile","correct":false,"feedback":"Neither statement describes their primary roles."},{"label":"Nodes mature erythrocytes; the spleen filters air","correct":false,"feedback":"Erythrocytes mature in marrow and air is filtered in the respiratory tract."}]}},{"id":"l15-m4","chapter":null,"chapterSummary":null,"title":"Spleen, thymus, and tonsils occupy different checkpoints","highYield":"Spleen monitors blood, thymus supports T-cell maturation, and tonsils sample material at the pharyngeal entrance.","teach":["The spleen's white pulp supports immune surveillance of blood-borne antigens, while red pulp removes aged or damaged erythrocytes and stores some platelets. Unlike a lymph node, the spleen is connected directly to blood circulation rather than positioned in a chain of lymphatic vessels.","The thymus provides an environment for T-cell maturation and is most active earlier in life. Tonsils and other mucosa-associated lymphoid tissues sample material near respiratory and digestive entry points. Each structure contributes to defence from a different anatomical location."],"keyPoints":["Spleen filters blood and recycles erythrocyte components.","Thymus supports T-cell maturation.","Tonsils survey the pharyngeal region.","Lymphatic organs are not interchangeable."],"visual":{"title":"Organ checkpoints","kind":"comparison","items":[{"label":"Lymph node","detail":"Samples lymph from tissues"},{"label":"Spleen","detail":"Samples blood and removes old erythrocytes"},{"label":"Thymus","detail":"Supports T-cell maturation"},{"label":"Tonsils/MALT","detail":"Monitor mucosal entry sites"}]},"mnemonic":{"title":"Node–Blood–T–Throat","cue":"Node filters lymph · spleen filters blood · thymus trains T cells · tonsils watch throat","explanation":"The location hints at the job."},"goodToKnow":"The thymus becomes less prominent after puberty but does not simply vanish or make adult immunity impossible.","act":{"type":"choice","prompt":"Which organ removes many aged erythrocytes from blood?","options":[{"label":"Spleen","correct":true,"feedback":"Correct. Red pulp participates in erythrocyte removal and recycling."},{"label":"Thymus","correct":false,"feedback":"The thymus is primarily associated with T-cell maturation."},{"label":"Tonsil","correct":false,"feedback":"Tonsils are mucosal immune tissues near the pharynx."}]}},{"id":"organs-order","title":"Put it in order: Through a lymph node","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Afferent vessels","detail":"Bring lymph into the capsule"},{"label":"Sinuses","detail":"Slow and channel flow"},{"label":"Immune zones","detail":"Support B-cell, T-cell, and macrophage interactions"},{"label":"Efferent vessel","detail":"Carries filtered lymph away"}]}},{"id":"organs-match","title":"Match it: Organ checkpoints","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Samples lymph from tissues","Samples blood and removes old erythrocytes","Supports T-cell maturation","Monitor mucosal entry sites"],"items":[{"label":"Tonsils/MALT","category":3,"feedback":"Tonsils/MALT: Monitor mucosal entry sites"},{"label":"Thymus","category":2,"feedback":"Thymus: Supports T-cell maturation"},{"label":"Spleen","category":1,"feedback":"Spleen: Samples blood and removes old erythrocytes"},{"label":"Lymph node","category":0,"feedback":"Lymph node: Samples lymph from tissues"}]}},{"id":"l15-m5","chapter":"Layer innate and adaptive defence","chapterSummary":"Understand barriers, inflammation, antigen recognition, and lymphocyte specialization.","title":"Innate defence responds quickly to patterns","highYield":"Barriers, phagocytes, complement, inflammation, and fever act without needing prior exposure to one exact antigen.","teach":["Innate defence includes intact skin and mucosa, antimicrobial secretions, resident and recruited phagocytes, natural killer cells, complement proteins, and inflammatory signals. These components recognize broad features of damage or microbes and respond rapidly.","Inflammation increases local blood flow and vessel permeability while recruiting cells and proteins. This can support containment and repair, but excessive or misplaced inflammation can damage tissue. 'Inflammation' is therefore a process, not a universal diagnosis or a food morality label."],"keyPoints":["Barriers are first-line defences.","Innate recognition is pattern-based.","Inflammation recruits cells and proteins.","Fever and inflammation are regulated responses with possible costs."],"visual":{"title":"Innate defence layers","kind":"layers","items":[{"label":"Barrier","detail":"Skin, mucosa, secretions"},{"label":"Recognition","detail":"Cells detect common danger patterns"},{"label":"Response","detail":"Phagocytosis, complement, inflammation"},{"label":"Resolution","detail":"Signals limit response and support repair"}]},"mnemonic":{"title":"B-R-R-R","cue":"Barrier · Recognize · Respond · Resolve","explanation":"A healthy defence response must eventually resolve."},"goodToKnow":"A marker of inflammation can rise for many reasons and does not identify a specific food trigger by itself.","act":{"type":"choice","prompt":"Which is an innate defence?","options":[{"label":"A skin barrier and rapid phagocyte response","correct":true,"feedback":"Correct. These act broadly without requiring antigen-specific memory."},{"label":"A highly specific memory B-cell response after vaccination","correct":false,"feedback":"That is adaptive immunity."},{"label":"ABO compatibility testing","correct":false,"feedback":"That is a transfusion-safety process, not an innate defence."}]}},{"id":"l15-m6","chapter":null,"chapterSummary":null,"title":"Adaptive immunity adds specificity and memory","highYield":"B and T lymphocytes recognize specific antigens, expand selected clones, and can leave memory cells.","teach":["Adaptive responses begin when lymphocytes with matching receptors encounter antigen in the right signalling context. Clonal expansion creates many related cells. B cells can differentiate into plasma cells that secrete antibodies, while memory B cells support faster future responses.","T-cell populations perform different work: helper T cells coordinate responses, cytotoxic T cells kill selected infected or abnormal cells, and regulatory T cells help limit inappropriate activation. Antibodies act outside cells; cytotoxic T cells inspect cellular antigen presentation. Both arms cooperate with innate defence."],"keyPoints":["Adaptive recognition is antigen-specific.","B cells can produce antibody-secreting plasma cells.","T cells coordinate, kill, or regulate.","Memory changes a later response."],"visual":{"title":"Two adaptive arms","kind":"comparison","items":[{"label":"Humoral","detail":"B cells and antibodies act in extracellular spaces"},{"label":"Cell-mediated","detail":"T cells coordinate or act on selected cells"},{"label":"Memory","detail":"Long-lived cells support faster later response"},{"label":"Cooperation","detail":"Innate signals help activate and shape adaptive responses"}]},"mnemonic":{"title":"B = antibodies, T = tasks in tissues","cue":"B builds antibodies · T targets and tunes","explanation":"A study cue, not a complete catalogue of lymphocyte biology."},"goodToKnow":"Antibodies can neutralize, tag, or activate other defence mechanisms; they do not directly 'eat' microbes.","act":{"type":"choice","prompt":"Which cell directly secretes large amounts of antibody?","options":[{"label":"A plasma cell derived from a B lymphocyte","correct":true,"feedback":"Correct. Plasma cells are specialized antibody secretors."},{"label":"An erythrocyte","correct":false,"feedback":"Erythrocytes transport gases."},{"label":"A platelet","correct":false,"feedback":"Platelets function mainly in hemostasis and repair signalling."}]}},{"id":"immunity-match","title":"Match it: Innate defence layers","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Skin, mucosa, secretions","Cells detect common danger patterns","Phagocytosis, complement, inflammation","Signals limit response and support repair"],"items":[{"label":"Resolution","category":3,"feedback":"Resolution: Signals limit response and support repair"},{"label":"Response","category":2,"feedback":"Response: Phagocytosis, complement, inflammation"},{"label":"Recognition","category":1,"feedback":"Recognition: Cells detect common danger patterns"},{"label":"Barrier","category":0,"feedback":"Barrier: Skin, mucosa, secretions"}]}},{"id":"l15-m7","chapter":"Compare acquired protection","chapterSummary":"Distinguish active and passive immunity, antigen–antibody binding, and safe practice boundaries.","title":"Active and passive immunity differ in who makes the antibody","highYield":"Active immunity develops after your immune system responds; passive immunity transfers ready-made antibodies.","teach":["Active immunity follows infection or vaccination and requires the recipient's lymphocytes to respond. It takes time to develop but can create memory. Passive immunity provides antibodies made elsewhere, such as maternal antibodies transferred across the placenta or an administered antibody product.","Passive protection can act quickly but is temporary because the recipient did not create the memory response. Natural and artificial describe how exposure occurs, while active and passive describe who produced the protective antibodies. Keep these two classification axes separate."],"keyPoints":["Active immunity can form memory.","Passive immunity transfers antibody.","Passive protection is relatively immediate and temporary.","Natural/artificial and active/passive answer different questions."],"visual":{"title":"Four acquisition routes","kind":"comparison","items":[{"label":"Natural active","detail":"Immune response after infection"},{"label":"Artificial active","detail":"Immune response after vaccination"},{"label":"Natural passive","detail":"Maternal antibody transfer"},{"label":"Artificial passive","detail":"Administered antibody preparation"}]},"mnemonic":{"title":"Active acts; passive passes","cue":"Act to make · Pass ready-made","explanation":"Active means the recipient's immune system produces the response."},"goodToKnow":"Vaccination does not guarantee identical protection in every person, but it trains adaptive recognition without requiring the full disease experience.","act":{"type":"choice","prompt":"Which example is natural passive immunity?","options":[{"label":"Maternal IgG crossing the placenta","correct":true,"feedback":"Correct. Ready-made antibody is naturally transferred."},{"label":"Memory after recovering from infection","correct":false,"feedback":"That is natural active immunity."},{"label":"Antibody production after vaccination","correct":false,"feedback":"That is artificial active immunity."}]}},{"id":"l15-m8","chapter":null,"chapterSummary":null,"title":"Antigen–antibody binding is precise but not sufficient alone","highYield":"Antibodies bind particular molecular features and then recruit or block other processes.","teach":["An antigen contains molecular regions called epitopes. An antibody's binding site fits a particular epitope closely enough to bind. This specificity explains why one antibody does not recognize every pathogen and why cross-reactivity can occur when structures are similar.","Binding can neutralize a toxin or virus, mark a target for phagocytosis, clump particles, or activate complement. Outcome depends on the antibody class, location, target, and other immune components. A positive antibody result may reflect past exposure, vaccination, current response, or cross-reactivity; interpretation needs context."],"keyPoints":["Epitopes are recognized portions of antigens.","Antibody specificity is selective, not absolute.","Binding recruits additional mechanisms.","An antibody test is contextual evidence."],"visual":{"title":"What antibody binding can do","kind":"map","items":[{"label":"Neutralize","detail":"Block a target from attaching or acting"},{"label":"Opsonize","detail":"Tag a target for phagocytes"},{"label":"Agglutinate","detail":"Cross-link particles"},{"label":"Activate complement","detail":"Trigger a protein cascade"}]},"mnemonic":{"title":"NOAC","cue":"Neutralize · Opsonize · Agglutinate · Complement","explanation":"Four common consequences of antibody binding."},"goodToKnow":"Allergy is an immune response to a usually harmless substance; it is not evidence that the immune system is simply 'weak.'","act":{"type":"choice","prompt":"What is an epitope?","options":[{"label":"A specific region of an antigen recognized by an immune receptor or antibody","correct":true,"feedback":"Correct. Recognition occurs at particular molecular features."},{"label":"The fluid inside a lymphatic vessel","correct":false,"feedback":"That fluid is lymph."},{"label":"A valve in a vein","correct":false,"feedback":"A valve directs fluid flow and is unrelated to antigen recognition."}]}},{"id":"memory-match","title":"Match it: Four acquisition routes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Immune response after infection","Immune response after vaccination","Maternal antibody transfer","Administered antibody preparation"],"items":[{"label":"Artificial passive","category":3,"feedback":"Artificial passive: Administered antibody preparation"},{"label":"Natural passive","category":2,"feedback":"Natural passive: Maternal antibody transfer"},{"label":"Artificial active","category":1,"feedback":"Artificial active: Immune response after vaccination"},{"label":"Natural active","category":0,"feedback":"Natural active: Immune response after infection"}]}}],"flashcards":[{"front":"Lymph","back":"Interstitial fluid after it enters lymphatic vessels."},{"front":"Thoracic duct","back":"The major lymphatic duct draining most of the body into venous circulation."},{"front":"Lacteal","back":"A lymphatic capillary in an intestinal villus that absorbs dietary lipids packaged as chylomicrons."},{"front":"Afferent lymphatic","back":"A vessel carrying lymph into a node."},{"front":"Efferent lymphatic","back":"A vessel carrying lymph away from a node."},{"front":"Spleen","back":"A lymphatic organ that filters blood and removes many aged erythrocytes."},{"front":"Thymus","back":"An organ supporting T-cell maturation, especially early in life."},{"front":"Innate immunity","back":"Rapid pattern-based defence including barriers, phagocytes, inflammation, and complement."},{"front":"Humoral immunity","back":"Adaptive defence mediated primarily by B cells and antibodies."},{"front":"Cell-mediated immunity","back":"Adaptive defence involving T-cell coordination and action on selected cells."},{"front":"Active immunity","back":"Protection generated by the recipient's own immune response, often with memory."},{"front":"Passive immunity","back":"Temporary protection from transferred ready-made antibodies."}],"quiz":[],"caseStudy":{"title":"A persistent neck lump and an 'immune-boosting' plan","scenario":"A client has noticed an enlarging neck lump for several weeks and asks which supplement will 'drain the lymph' and strengthen immunity. They have not sought medical assessment.","prompts":["What can and cannot be inferred from a palpable node?","Which duration and change details make follow-up important?","How would you explain the role of a lymph node without diagnosing the cause?","What supportive nutrition conversation can occur without delaying assessment?"],"takeaway":"Lymph nodes enlarge for multiple reasons. Explain the mechanism, avoid supplement promises, and encourage appropriate clinical assessment of a persistent or enlarging lump."}},{"n":16,"title":"Nutrition and the Digestive System","kicker":"Trace food through the alimentary canal and identify accessory-organ contributions.","duration":"90–110 minutes","steps":[{"id":"l16-m1","chapter":"Orient to the digestive tube","chapterSummary":"Build the wall layers, movement pattern, and oral phase before following individual nutrients.","title":"One continuous tube, four repeating wall layers","highYield":"Mucosa handles contact and absorption; submucosa supports; muscularis moves; serosa/adventitia anchors or reduces friction.","teach":["The alimentary canal runs from mouth to anus. Although each region is specialized, much of the tube follows a four-layer plan: mucosa, submucosa, muscularis externa, and an outer serosa or adventitia. The mucosa includes epithelium, connective tissue, and a thin muscle layer; its surface changes according to function.","The submucosa carries vessels, glands, and nerve networks. Circular and longitudinal smooth muscle in the muscularis mix and propel contents. Enteric nerve plexuses coordinate local activity while autonomic and hormonal signals modify it. Digestion is therefore mechanical, chemical, and regulatory at the same time."],"keyPoints":["Mucosa faces the lumen.","Submucosa supports vessels, glands, and nerves.","Muscularis mixes and propels.","Serosa reduces friction; adventitia anchors some regions."],"visual":{"title":"GI wall from lumen outward","kind":"layers","items":[{"label":"Mucosa","detail":"Secretion, protection, absorption"},{"label":"Submucosa","detail":"Vessels, glands, connective support, nerve plexus"},{"label":"Muscularis externa","detail":"Circular and longitudinal movement"},{"label":"Serosa/adventitia","detail":"Outer covering or attachment"}]},"mnemonic":{"title":"M-S-M-S","cue":"Mucosa · Submucosa · Muscularis · Serosa","explanation":"Move from the lumen outward; substitute adventitia where the organ is anchored."},"goodToKnow":"The enteric nervous system can coordinate local reflexes, but it still communicates with the central nervous and endocrine systems.","act":{"type":"choice","prompt":"Which layer directly contacts material in the intestinal lumen?","options":[{"label":"Mucosa","correct":true,"feedback":"Correct. Its epithelium forms the luminal surface."},{"label":"Muscularis externa","correct":false,"feedback":"The muscularis lies deeper and produces movement."},{"label":"Serosa","correct":false,"feedback":"The serosa is an outer covering."}]}},{"id":"l16-m2","chapter":null,"chapterSummary":null,"title":"The mouth begins both processing and decision-making","highYield":"Chewing, saliva, tongue movement, and swallowing prepare a manageable bolus; digestion does not begin in the stomach.","teach":["Teeth mechanically reduce food size, increasing surface area. The tongue positions food, contributes to taste, and forms a bolus. Saliva moistens and lubricates, buffers the oral environment, and contains enzymes that begin starch and some lipid processing, although most digestion occurs later.","Swallowing begins voluntarily and then becomes a coordinated reflex moving the bolus through pharynx and esophagus. Peristaltic waves propel it toward the stomach while sphincters help direct flow. Chewing time or saliva alone cannot determine nutrient absorption, but oral function can strongly affect what a person can comfortably eat."],"keyPoints":["Mastication increases surface area.","Saliva lubricates and begins chemical digestion.","The tongue forms and positions the bolus.","Swallowing changes from voluntary to reflex control."],"visual":{"title":"Oral-to-esophageal sequence","kind":"sequence","items":[{"label":"Chew","detail":"Mechanical breakdown"},{"label":"Moisten","detail":"Saliva lubricates and buffers"},{"label":"Form bolus","detail":"Tongue organizes material"},{"label":"Swallow","detail":"Pharyngeal reflex protects airway and directs bolus"},{"label":"Peristalsis","detail":"Esophagus propels toward stomach"}]},"mnemonic":{"title":"CMFSP","cue":"Chew · Moisten · Form · Swallow · Propel","explanation":"A five-step oral and esophageal route."},"goodToKnow":"Salivary amylase starts starch digestion but is not responsible for completing carbohydrate digestion.","act":{"type":"choice","prompt":"What is the main immediate benefit of chewing for digestion?","options":[{"label":"It reduces particle size and increases surface area","correct":true,"feedback":"Correct. This improves contact with fluids and enzymes."},{"label":"It absorbs all nutrients through the teeth","correct":false,"feedback":"Teeth mechanically process food; they do not absorb nutrients."},{"label":"It converts protein directly into glucose","correct":false,"feedback":"Protein digestion requires enzymatic steps in the stomach and small intestine."}]}},{"id":"organization-order","title":"Put it in order: Oral-to-esophageal sequence","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Chew","detail":"Mechanical breakdown"},{"label":"Moisten","detail":"Saliva lubricates and buffers"},{"label":"Form bolus","detail":"Tongue organizes material"},{"label":"Swallow","detail":"Pharyngeal reflex protects airway and directs bolus"},{"label":"Peristalsis","detail":"Esophagus propels toward stomach"}]}},{"id":"organization-match","title":"Match it: GI wall from lumen outward","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Secretion, protection, absorption","Vessels, glands, connective support, nerve plexus","Circular and longitudinal movement","Outer covering or attachment"],"items":[{"label":"Serosa/adventitia","category":3,"feedback":"Serosa/adventitia: Outer covering or attachment"},{"label":"Muscularis externa","category":2,"feedback":"Muscularis externa: Circular and longitudinal movement"},{"label":"Submucosa","category":1,"feedback":"Submucosa: Vessels, glands, connective support, nerve plexus"},{"label":"Mucosa","category":0,"feedback":"Mucosa: Secretion, protection, absorption"}]}},{"id":"l16-m3","chapter":"Coordinate stomach and accessory organs","chapterSummary":"Separate storage, acid and enzymes, pancreatic secretion, bile, and liver processing.","title":"The stomach stores, mixes, acidifies, and meters","highYield":"The stomach begins substantial protein digestion and delivers chyme gradually; it is not the main nutrient-absorption site.","teach":["The stomach's folds allow expansion while muscular layers churn food into chyme. Parietal cells secrete hydrochloric acid and intrinsic factor, chief cells release pepsinogen, and mucous cells help protect the lining. Acid denatures proteins and activates pepsin, while intrinsic factor later supports vitamin B12 absorption in the ileum.","Pyloric control meters chyme into the duodenum. Emptying rate changes with meal composition, particle size, and regulatory signals. Fat and high energy density often slow emptying, but individual symptoms are not a direct readout of one nutrient or of stomach acid level."],"keyPoints":["Acid denatures protein and activates pepsin.","Intrinsic factor is required for normal B12 absorption.","Mucus and bicarbonate protect the stomach lining.","The pylorus regulates delivery to duodenum."],"visual":{"title":"Gastric cell roles","kind":"comparison","items":[{"label":"Parietal cell","detail":"Hydrochloric acid and intrinsic factor"},{"label":"Chief cell","detail":"Pepsinogen precursor"},{"label":"Mucous cell","detail":"Protective mucus and local buffering"},{"label":"Muscle layers","detail":"Mix chyme and support emptying"}]},"mnemonic":{"title":"A-I-P-M","cue":"Acid · Intrinsic factor · Pepsin · Mucus","explanation":"Four gastric products/functions to keep distinct."},"goodToKnow":"Very little macronutrient absorption occurs in the stomach; most absorption occurs in the small intestine.","act":{"type":"choice","prompt":"Which stomach product is essential for efficient vitamin B12 absorption later in the ileum?","options":[{"label":"Intrinsic factor","correct":true,"feedback":"Correct. B12 binds intrinsic factor before receptor-mediated absorption."},{"label":"Bile","correct":false,"feedback":"Bile is produced by the liver and aids lipid handling."},{"label":"Insulin","correct":false,"feedback":"Insulin is an endocrine pancreatic hormone, not a gastric product."}]}},{"id":"l16-m4","chapter":null,"chapterSummary":null,"title":"Pancreas, liver, and gallbladder deliver complementary support","highYield":"Pancreas supplies bicarbonate and enzymes; liver makes bile and processes portal blood; gallbladder stores and concentrates bile.","teach":["The exocrine pancreas delivers bicarbonate to neutralize acidic chyme and enzymes that digest carbohydrate, protein, fat, and nucleic acids. Its endocrine islets release hormones such as insulin and glucagon into blood. Exocrine and endocrine functions share an organ but use different ducts and destinations.","The liver produces bile, processes portal nutrients, stores selected fuels and vitamins, synthesizes many plasma proteins, and modifies wastes and chemicals. The gallbladder stores and concentrates bile, then releases it when signalled. Bile emulsifies fat into smaller droplets; it is not a digestive enzyme and does not chemically split triglycerides."],"keyPoints":["Pancreatic bicarbonate raises duodenal pH.","Pancreatic enzymes act on all major nutrient classes.","Liver produces bile; gallbladder stores it.","Bile emulsifies rather than hydrolyzes fat."],"visual":{"title":"Accessory-organ teamwork","kind":"map","items":[{"label":"Pancreas","detail":"Bicarbonate plus digestive enzymes"},{"label":"Liver","detail":"Bile production and portal processing"},{"label":"Gallbladder","detail":"Bile storage and concentration"},{"label":"Duodenum","detail":"Receives chyme, bile, and pancreatic secretion"}]},"mnemonic":{"title":"PBLG","cue":"Pancreas breaks · Bile bundles · Liver generates · Gallbladder holds","explanation":"A compact cue; remember enzymes break bonds while bile disperses fat."},"goodToKnow":"A person can live without a gallbladder because the liver still produces bile, though delivery becomes less concentrated and less meal-timed.","act":{"type":"choice","prompt":"Which statement about bile is accurate?","options":[{"label":"It emulsifies fat, increasing surface area for lipase","correct":true,"feedback":"Correct. Bile disperses fat droplets but does not hydrolyze triglycerides itself."},{"label":"It is a protease secreted by the stomach","correct":false,"feedback":"Bile is not an enzyme and is produced by the liver."},{"label":"It transports oxygen in red blood cells","correct":false,"feedback":"Hemoglobin performs that role."}]}},{"id":"upper-organs-match","title":"Match it: Gastric cell roles","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Hydrochloric acid and intrinsic factor","Pepsinogen precursor","Protective mucus and local buffering","Mix chyme and support emptying"],"items":[{"label":"Muscle layers","category":3,"feedback":"Muscle layers: Mix chyme and support emptying"},{"label":"Mucous cell","category":2,"feedback":"Mucous cell: Protective mucus and local buffering"},{"label":"Chief cell","category":1,"feedback":"Chief cell: Pepsinogen precursor"},{"label":"Parietal cell","category":0,"feedback":"Parietal cell: Hydrochloric acid and intrinsic factor"}]}},{"id":"l16-m5","chapter":"Digest and absorb","chapterSummary":"Use small-intestinal surface area and colon function to explain nutrient and fluid handling.","title":"The small intestine completes digestion and captures nutrients","highYield":"Folds, villi, and microvilli create a large absorptive surface supplied by blood capillaries and lacteals.","teach":["The duodenum receives chyme, bile, and pancreatic secretion; the jejunum is a major site of absorption; and the ileum completes absorption of selected substances, including the intrinsic-factor–B12 complex and recycled bile salts. Segmentation mixes contents while peristalsis advances them.","Circular folds, villi, and microvilli multiply surface area. Monosaccharides, amino acids, and many water-soluble products enter blood capillaries and travel through the hepatic portal vein. Long-chain lipids are rebuilt into triglycerides, packaged into chylomicrons, and enter lacteals before reaching blood."],"keyPoints":["Duodenum coordinates neutralization and digestion.","Villi and microvilli expand surface area.","Water-soluble nutrients generally enter portal blood.","Chylomicrons generally enter lymphatic lacteals."],"visual":{"title":"Two absorption routes","kind":"comparison","items":[{"label":"Blood capillary route","detail":"Monosaccharides, amino acids, many minerals and water-soluble vitamins → portal vein"},{"label":"Lacteal route","detail":"Chylomicrons containing long-chain dietary lipid → lymph → venous blood"},{"label":"Ileal specialities","detail":"B12–intrinsic factor complex and bile-salt recovery"}]},"mnemonic":{"title":"Sugar and amino acids sail portal; fat floats lymph","cue":"Portal for soluble · lymph for chylomicrons","explanation":"A useful general pattern with exceptions for some shorter fatty acids."},"goodToKnow":"Absorption is selective and transporter-dependent; eating a nutrient does not guarantee identical absorption in every context.","act":{"type":"choice","prompt":"Where do most long-chain dietary lipids go immediately after absorption?","options":[{"label":"Into chylomicrons that enter intestinal lacteals","correct":true,"feedback":"Correct. They travel through lymph before venous blood."},{"label":"Directly into the aorta as free triglycerides","correct":false,"feedback":"They are packaged in enterocytes and enter lymph first."},{"label":"Into the urinary bladder","correct":false,"feedback":"The urinary tract is not an absorption route for dietary lipid."}]}},{"id":"l16-m6","chapter":null,"chapterSummary":null,"title":"The large intestine recovers fluid and forms stool","highYield":"The colon reabsorbs water and electrolytes, houses microbes, compacts contents, and coordinates elimination.","teach":["Material entering the large intestine contains water, electrolytes, undigested components, microbes, shed cells, and secretions. The colon absorbs much of the remaining water and electrolytes, secretes mucus, and moves contents through haustral mixing and mass movements toward the rectum.","Colonic microbes ferment selected carbohydrates and produce metabolites, including short-chain fatty acids, while also contributing to some vitamin production. Microbiome composition varies widely; one stool pattern cannot define a 'healthy microbiome,' and broad claims about cleansing or toxins are not supported by colon anatomy."],"keyPoints":["Colon recovers water and electrolytes.","Mucus supports passage.","Microbes ferment selected substrates.","Rectal filling participates in the defecation reflex."],"visual":{"title":"Colon functions","kind":"map","items":[{"label":"Recover","detail":"Water and electrolytes"},{"label":"Ferment","detail":"Microbial use of selected carbohydrates"},{"label":"Compact","detail":"Formation of fecal material"},{"label":"Propel","detail":"Movement toward rectum and elimination"}]},"mnemonic":{"title":"RFCP","cue":"Recover · Ferment · Compact · Propel","explanation":"Four colon functions without calling it a waste-storage tube only."},"goodToKnow":"Stool frequency varies; a change from a person's usual pattern plus symptoms is often more informative than one universal number.","act":{"type":"choice","prompt":"Which is a major function of the large intestine?","options":[{"label":"Recovery of water and electrolytes","correct":true,"feedback":"Correct. The colon helps conserve fluid while forming stool."},{"label":"Production of pancreatic enzymes","correct":false,"feedback":"Those enzymes come from the pancreas."},{"label":"Most amino-acid absorption","correct":false,"feedback":"Most nutrient absorption occurs in the small intestine."}]}},{"id":"intestinal-match","title":"Match it: Two absorption routes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Monosaccharides, amino acids, many minerals and water-soluble vitamins → portal vein","Chylomicrons containing long-chain dietary lipid → lymph → venous blood","B12–intrinsic factor complex and bile-salt recovery"],"items":[{"label":"Blood capillary route","category":0,"feedback":"Blood capillary route: Monosaccharides, amino acids, many minerals and water-soluble vitamins → portal vein"},{"label":"Lacteal route","category":1,"feedback":"Lacteal route: Chylomicrons containing long-chain dietary lipid → lymph → venous blood"},{"label":"Ileal specialities","category":2,"feedback":"Ileal specialities: B12–intrinsic factor complex and bile-salt recovery"}]}},{"id":"l16-m7","chapter":"Connect foods to pathways","chapterSummary":"Follow macronutrient digestion and use a scoped, evidence-aware nutrition lens.","title":"Each macronutrient needs a different breakdown strategy","highYield":"Carbohydrate becomes absorbable monosaccharides, protein becomes amino acids and small peptides, and triglyceride becomes lipid products before repackaging.","teach":["Starch digestion begins with amylase and is completed by pancreatic and brush-border enzymes to monosaccharides. Protein is denatured in the stomach and hydrolyzed by gastric, pancreatic, and brush-border proteases into amino acids and small peptides. These products use specific transport systems to enter enterocytes and then portal blood.","Fat requires emulsification by bile and hydrolysis mainly by pancreatic lipase. Lipid products form micelles that approach the enterocyte membrane, then are absorbed, reassembled, and packaged into chylomicrons. The pathway explains why bile and pancreatic function matter without implying that dietary fat is inherently difficult or harmful."],"keyPoints":["Starch → monosaccharides.","Protein → amino acids and small peptides.","Triglycerides → fatty acids/monoglycerides → reassembly.","Transporters and packaging complete absorption."],"visual":{"title":"Macronutrient pathways","kind":"comparison","items":[{"label":"Carbohydrate","detail":"Amylases and brush-border enzymes → monosaccharides → portal blood"},{"label":"Protein","detail":"Pepsin and pancreatic/brush-border proteases → amino acids/peptides → portal blood"},{"label":"Fat","detail":"Bile + lipase → micelles → enterocyte → chylomicron → lymph"}]},"mnemonic":{"title":"C-P-F: Cut, Process, Ferry","cue":"Cut bonds · Process at brush border · Ferry through blood or lymph","explanation":"Use the same logic while keeping each nutrient's products and route distinct."},"goodToKnow":"Fibre is not digested into glucose by human enzymes; fermentable fibre can be metabolized by colonic microbes.","act":{"type":"choice","prompt":"Which pairing is correct?","options":[{"label":"Bile emulsifies lipid; pancreatic lipase hydrolyzes triglyceride","correct":true,"feedback":"Correct. Physical dispersion and chemical digestion are different jobs."},{"label":"Pepsin digests starch into glucose","correct":false,"feedback":"Pepsin is a protease."},{"label":"Amylase converts protein into amino acids","correct":false,"feedback":"Amylase acts on starch."}]}},{"id":"l16-m8","chapter":null,"chapterSummary":null,"title":"Assessment separates intake, digestion, absorption, and use","highYield":"A nutrient problem can arise before eating, during digestion, at absorption, in transport, or during cellular use.","teach":["Nutritional status is not determined by intake alone. Food access and appetite affect intake; oral and GI function affect digestion; mucosal surface and transporters affect absorption; liver and circulation affect distribution; and cells must use or store what arrives. Losses and altered needs add further branches.","This pathway keeps counselling focused. Ask what the person eats, what happens after eating, how long the pattern has persisted, what medical evaluation exists, and which practical barriers matter. Avoid diagnosing malabsorption or prescribing restrictive diets from symptoms alone."],"keyPoints":["Availability precedes intake.","Digestion and absorption are distinct.","Transport and cellular use follow absorption.","Losses and needs change status."],"visual":{"title":"Nutrition status pathway","kind":"flow","items":[{"label":"Available","detail":"Food access and feasibility"},{"label":"Consumed","detail":"Appetite, chewing, swallowing"},{"label":"Digested","detail":"Mechanical and enzymatic breakdown"},{"label":"Absorbed","detail":"Movement across gut epithelium"},{"label":"Used/stored","detail":"Transport, metabolism, and reserves"}]},"mnemonic":{"title":"A-C-D-A-U","cue":"Available · Consumed · Digested · Absorbed · Used","explanation":"Locate the possible bottleneck before choosing an intervention."},"goodToKnow":"A normal-looking diet does not rule out impaired absorption, and GI symptoms do not prove malabsorption.","act":{"type":"choice","prompt":"A client eats adequate B12 but has impaired intrinsic-factor production. Which stage is most directly affected?","options":[{"label":"Absorption","correct":true,"feedback":"Correct. Intake may be adequate while ileal B12 uptake is impaired."},{"label":"Food availability","correct":false,"feedback":"The nutrient is available and consumed in this example."},{"label":"Chewing","correct":false,"feedback":"The mechanism described is not oral processing."}]}},{"id":"nutrient-integration-order","title":"Put it in order: Nutrition status pathway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Available","detail":"Food access and feasibility"},{"label":"Consumed","detail":"Appetite, chewing, swallowing"},{"label":"Digested","detail":"Mechanical and enzymatic breakdown"},{"label":"Absorbed","detail":"Movement across gut epithelium"},{"label":"Used/stored","detail":"Transport, metabolism, and reserves"}]}},{"id":"nutrient-integration-match","title":"Match it: Macronutrient pathways","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Amylases and brush-border enzymes → monosaccharides → portal blood","Pepsin and pancreatic/brush-border proteases → amino acids/peptides → portal blood","Bile + lipase → micelles → enterocyte → chylomicron → lymph"],"items":[{"label":"Carbohydrate","category":0,"feedback":"Carbohydrate: Amylases and brush-border enzymes → monosaccharides → portal blood"},{"label":"Protein","category":1,"feedback":"Protein: Pepsin and pancreatic/brush-border proteases → amino acids/peptides → portal blood"},{"label":"Fat","category":2,"feedback":"Fat: Bile + lipase → micelles → enterocyte → chylomicron → lymph"}]}}],"flashcards":[{"front":"Mucosa","back":"The innermost GI layer responsible for protection, secretion, and absorption."},{"front":"Peristalsis","back":"Coordinated wave-like contraction that propels contents along the digestive tract."},{"front":"Intrinsic factor","back":"A gastric protein required for efficient vitamin B12 absorption in the ileum."},{"front":"Pepsin","back":"A gastric protease activated in acidic conditions that begins protein digestion."},{"front":"Bile","back":"A liver secretion that emulsifies lipid and supports micelle formation; it is not an enzyme."},{"front":"Pancreatic bicarbonate","back":"An alkaline secretion that helps neutralize acidic chyme in the duodenum."},{"front":"Villus","back":"A projection of small-intestinal mucosa containing blood capillaries and a lacteal."},{"front":"Chylomicron","back":"A lipoprotein particle carrying absorbed long-chain dietary lipid from enterocyte into lymph."},{"front":"Hepatic portal vein","back":"Vessel delivering blood from digestive organs to the liver before systemic return."},{"front":"Segmentation","back":"Local intestinal mixing contractions that expose contents to enzymes and absorptive surfaces."},{"front":"Colon","back":"Large-intestinal region that recovers water/electrolytes, houses microbes, and compacts stool."},{"front":"Bioavailability","back":"The fraction of an ingested substance that becomes available for absorption and use, shaped by food and host factors."}],"quiz":[],"caseStudy":{"title":"A restrictive diet built from symptoms alone","scenario":"A client reports bloating, intermittent diarrhea, fatigue, and an unplanned weight change. They have removed gluten, dairy, legumes, fruit, and several vegetables after online advice, but symptoms continue. No diagnostic evaluation has occurred.","prompts":["Which stages of the nutrition-status pathway could contribute?","Which red flags or duration details should be clarified?","How might broad restriction create additional nutrition risk?","What can be documented and supported while medical assessment proceeds?"],"takeaway":"GI symptoms rarely identify one mechanism by themselves. Protect intake, document the pattern, avoid escalating unsupported restrictions, and coordinate appropriate assessment."}},{"n":17,"title":"The Respiratory System","kicker":"Trace air through conducting and respiratory zones.","duration":"75–95 minutes","steps":[{"id":"l17-m1","chapter":"Follow the conducting zone","chapterSummary":"Learn how the upper and lower airways condition air while protecting a delicate exchange surface.","title":"The upper airway warms, humidifies, filters, and senses","highYield":"The nose and pharynx prepare inspired air before it reaches the gas-exchange surface.","teach":["Air entering the nasal cavity encounters hairs, mucus, a vascular mucosa, and turbinates that create turbulence. These features trap particles and increase contact for warming and humidification. Olfactory receptors occupy a specialized superior region rather than the entire nasal lining.","The pharynx is shared by respiratory and digestive pathways. The nasopharynx carries air, while lower regions also conduct swallowed material. This shared architecture explains why coordination of swallowing, laryngeal closure, and breathing is essential for airway protection."],"keyPoints":["Nasal turbinates increase contact area.","Mucus traps particles.","Rich blood supply warms air.","The pharynx is a shared passage."],"visual":{"title":"Upper-airway tasks","kind":"map","items":[{"label":"Filter","detail":"Hair, mucus, and cilia trap material"},{"label":"Warm","detail":"Vascular mucosa transfers heat"},{"label":"Humidify","detail":"Moist surfaces add water"},{"label":"Sense","detail":"Olfactory epithelium detects odorants"}]},"mnemonic":{"title":"FWHS","cue":"Filter · Warm · Humidify · Sense","explanation":"Four functions before air reaches the larynx."},"goodToKnow":"Breathing through the mouth can bypass some nasal conditioning, but mouth breathing alone does not identify why nasal airflow is limited.","act":{"type":"choice","prompt":"What is a main function of the nasal turbinates?","options":[{"label":"Create airflow turbulence and increase mucosal contact","correct":true,"feedback":"Correct. This supports warming, humidifying, and filtering."},{"label":"Exchange oxygen directly with systemic blood","correct":false,"feedback":"Gas exchange occurs mainly in alveoli."},{"label":"Produce surfactant","correct":false,"feedback":"Alveolar type II cells produce pulmonary surfactant."}]}},{"id":"l17-m2","chapter":null,"chapterSummary":null,"title":"Larynx, trachea, and bronchi keep a route open","highYield":"Cartilage maintains airway patency while branching, smooth muscle, mucus, and cilia shape airflow and clearance.","teach":["The larynx protects the lower airway and houses the vocal folds. During swallowing, coordinated elevation and closure help direct material away from the trachea. The trachea is reinforced by C-shaped cartilage rings; its open posterior portion allows the esophagus room to expand.","The trachea branches into main bronchi, then smaller bronchi and bronchioles. Cartilage becomes less prominent with branching, while smooth muscle becomes important in controlling bronchiolar diameter. Ciliated epithelium and mucus form a clearance system that moves trapped material toward the pharynx."],"keyPoints":["Larynx supports voice and airway protection.","Tracheal cartilage limits collapse.","Bronchi branch into bronchioles.","Cilia move mucus toward the pharynx."],"visual":{"title":"Branching airway","kind":"flow","items":[{"label":"Larynx","detail":"Protective gateway and voice"},{"label":"Trachea","detail":"Cartilage-supported conduit"},{"label":"Main bronchi","detail":"Enter right and left lungs"},{"label":"Bronchioles","detail":"Smooth-muscle control of small-airway radius"},{"label":"Terminal bronchioles","detail":"End of conducting zone"}]},"mnemonic":{"title":"L-T-B-B","cue":"Larynx · Trachea · Bronchi · Bronchioles","explanation":"Follow the branches before reaching respiratory bronchioles and alveoli."},"goodToKnow":"The right main bronchus is generally wider and more vertical, which helps explain why aspirated material often enters the right side.","act":{"type":"choice","prompt":"Why are tracheal cartilage rings C-shaped rather than complete circles?","options":[{"label":"They support the airway while allowing the esophagus behind it to expand","correct":true,"feedback":"Correct. The open posterior wall provides flexibility beside the esophagus."},{"label":"They allow blood to enter the airway","correct":false,"feedback":"Blood should remain within vessels."},{"label":"They create alveolar surfactant","correct":false,"feedback":"Surfactant is produced in alveoli, not tracheal cartilage."}]}},{"id":"airway-order","title":"Put it in order: Branching airway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Larynx","detail":"Protective gateway and voice"},{"label":"Trachea","detail":"Cartilage-supported conduit"},{"label":"Main bronchi","detail":"Enter right and left lungs"},{"label":"Bronchioles","detail":"Smooth-muscle control of small-airway radius"},{"label":"Terminal bronchioles","detail":"End of conducting zone"}]}},{"id":"airway-match","title":"Match it: Upper-airway tasks","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Hair, mucus, and cilia trap material","Vascular mucosa transfers heat","Moist surfaces add water","Olfactory epithelium detects odorants"],"items":[{"label":"Sense","category":3,"feedback":"Sense: Olfactory epithelium detects odorants"},{"label":"Humidify","category":2,"feedback":"Humidify: Moist surfaces add water"},{"label":"Warm","category":1,"feedback":"Warm: Vascular mucosa transfers heat"},{"label":"Filter","category":0,"feedback":"Filter: Hair, mucus, and cilia trap material"}]}},{"id":"l17-m3","chapter":"Reach the alveolar interface","chapterSummary":"Connect lung architecture, pleura, alveoli, and diffusion.","title":"Lungs pair branching trees with pleural mechanics","highYield":"The visceral and parietal pleura create a low-friction, pressure-coupled interface between lung and thoracic wall.","teach":["Each lung contains lobes supplied by branching bronchi, vessels, and nerves. The visceral pleura adheres to the lung surface, while parietal pleura lines the thoracic cavity. A thin fluid layer reduces friction and helps couple lung movement to changes in the chest wall.","The pleural space normally has pressure below atmospheric pressure, helping keep lungs expanded against the thoracic wall. Loss of this pressure relationship can allow lung recoil and impaired expansion. Pleural mechanics are different from airflow through bronchi and from diffusion at alveoli."],"keyPoints":["Visceral pleura covers lung.","Parietal pleura lines thorax.","Pleural fluid reduces friction.","Pressure coupling helps lungs follow chest expansion."],"visual":{"title":"Pleural relationship","kind":"layers","items":[{"label":"Thoracic wall","detail":"Moves during breathing"},{"label":"Parietal pleura","detail":"Lines the cavity"},{"label":"Pleural fluid space","detail":"Low-friction pressure coupling"},{"label":"Visceral pleura","detail":"Covers lung surface"},{"label":"Lung","detail":"Elastic tissue containing airways and alveoli"}]},"mnemonic":{"title":"Parietal = perimeter","cue":"P lines the perimeter; visceral visits the organ","explanation":"A spatial cue for the two pleural layers."},"goodToKnow":"Pleural fluid is a thin lubricating layer, not a large normal reservoir around the lungs.","act":{"type":"choice","prompt":"Which pleural layer is directly attached to the lung surface?","options":[{"label":"Visceral pleura","correct":true,"feedback":"Correct. The visceral layer follows the lung surface."},{"label":"Parietal pleura","correct":false,"feedback":"The parietal layer lines the thoracic cavity."},{"label":"Pericardium","correct":false,"feedback":"The pericardium surrounds the heart."}]}},{"id":"l17-m4","chapter":null,"chapterSummary":null,"title":"Alveoli trade distance for area","highYield":"A very thin alveolar–capillary membrane and enormous surface area support rapid diffusion.","teach":["Respiratory bronchioles lead to alveolar ducts and sacs. Alveoli are lined mainly by thin type I cells, while type II cells produce surfactant. Closely applied capillary endothelium and shared thin barriers minimize diffusion distance between air and blood.","Oxygen diffuses down its partial-pressure gradient into blood, and carbon dioxide diffuses in the opposite direction. Surfactant reduces surface tension and helps prevent small alveoli from collapsing. Efficient exchange also requires ventilation, perfusion, adequate surface area, and a thin intact membrane."],"keyPoints":["Type I cells form much of the exchange surface.","Type II cells produce surfactant.","Diffusion follows partial-pressure gradients.","Ventilation and perfusion must be reasonably matched."],"visual":{"title":"Alveolar exchange unit","kind":"layers","items":[{"label":"Alveolar air","detail":"Source of inspired oxygen"},{"label":"Type I epithelium","detail":"Thin gas-exchange surface"},{"label":"Fused basement region","detail":"Minimal diffusion distance"},{"label":"Capillary endothelium","detail":"Thin vessel wall"},{"label":"Erythrocyte","detail":"Hemoglobin binds oxygen"}]},"mnemonic":{"title":"A-T-M","cue":"Area · Thinness · Match","explanation":"Exchange needs large area, a thin membrane, and ventilation–perfusion matching."},"goodToKnow":"More ventilation does not help an alveolus that has no blood flow, and more blood flow does not help an alveolus that receives no fresh air.","act":{"type":"choice","prompt":"What is surfactant's main mechanical contribution?","options":[{"label":"It lowers alveolar surface tension","correct":true,"feedback":"Correct. This supports alveolar stability and reduces work of inflation."},{"label":"It carries oxygen through plasma","correct":false,"feedback":"Hemoglobin performs most oxygen transport."},{"label":"It contracts the diaphragm","correct":false,"feedback":"The phrenic nerves activate the diaphragm."}]}},{"id":"exchange-match","title":"Match it: Pleural relationship","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Moves during breathing","Lines the cavity","Low-friction pressure coupling","Covers lung surface","Elastic tissue containing airways and alveoli"],"items":[{"label":"Parietal pleura","category":1,"feedback":"Parietal pleura: Lines the cavity"},{"label":"Lung","category":4,"feedback":"Lung: Elastic tissue containing airways and alveoli"},{"label":"Pleural fluid space","category":2,"feedback":"Pleural fluid space: Low-friction pressure coupling"},{"label":"Thoracic wall","category":0,"feedback":"Thoracic wall: Moves during breathing"},{"label":"Visceral pleura","category":3,"feedback":"Visceral pleura: Covers lung surface"}]}},{"id":"l17-m5","chapter":"Move air and gases","chapterSummary":"Separate ventilation mechanics from exchange and transport.","title":"Inspiration follows expansion and falling pressure","highYield":"Diaphragm contraction expands thoracic volume, lowers alveolar pressure, and draws air inward.","teach":["During quiet inspiration, the diaphragm contracts and descends while external intercostal activity expands the rib cage. Greater thoracic volume lowers pressure within the lungs below atmospheric pressure, so air flows inward. Air moves because of a pressure gradient, not because lungs actively pull individual oxygen molecules.","Quiet expiration is largely passive as inspiratory muscles relax and elastic tissues recoil, raising alveolar pressure above atmospheric pressure. Forced breathing recruits additional muscles. Airway resistance, tissue elasticity, and surface tension all influence the work required."],"keyPoints":["Volume and pressure change inversely.","Diaphragm is the principal quiet-inspiration muscle.","Quiet expiration uses elastic recoil.","Air flows down a pressure gradient."],"visual":{"title":"One quiet breath","kind":"comparison","items":[{"label":"Inspiration","detail":"Thorax expands → alveolar pressure falls → air enters"},{"label":"Expiration","detail":"Elastic recoil reduces volume → alveolar pressure rises → air leaves"},{"label":"Resistance","detail":"Narrower airways require a larger pressure difference"}]},"mnemonic":{"title":"Expand–Drop–Enter","cue":"EDE","explanation":"Thorax expands, pressure drops, air enters."},"goodToKnow":"Deep breathing changes ventilation, but oxygen delivery also depends on alveolar exchange, blood flow, hemoglobin, and tissue demand.","act":{"type":"choice","prompt":"What immediately draws air into the lungs during quiet inspiration?","options":[{"label":"Alveolar pressure falls below atmospheric pressure","correct":true,"feedback":"Correct. Air moves down the resulting pressure gradient."},{"label":"Carbon dioxide stops being produced","correct":false,"feedback":"Metabolism continues; pressure change drives airflow."},{"label":"The pleural membranes open to outside air","correct":false,"feedback":"The pleural space normally remains closed."}]}},{"id":"l17-m6","chapter":null,"chapterSummary":null,"title":"Ventilation, respiration, and transport are separate steps","highYield":"Airflow, lung exchange, blood transport, and tissue exchange are linked but not interchangeable.","teach":["Ventilation is movement of air into and out of lungs. External respiration is gas exchange between alveoli and pulmonary capillary blood. Blood then transports gases, mostly with oxygen bound to hemoglobin and carbon dioxide carried mainly as bicarbonate.","Internal respiration is exchange between systemic capillary blood and tissues. Cells use oxygen in aerobic metabolism and produce carbon dioxide. A problem at any step can limit overall delivery, so a normal breathing rate alone does not prove normal tissue oxygenation."],"keyPoints":["Ventilation moves air.","External respiration exchanges gases at lungs.","Blood transports gases.","Internal respiration exchanges gases with tissues."],"visual":{"title":"Oxygen pathway","kind":"flow","items":[{"label":"Ventilate","detail":"Atmosphere ↔ alveoli"},{"label":"Exchange","detail":"Alveoli ↔ pulmonary blood"},{"label":"Transport","detail":"Pulmonary blood → systemic circulation"},{"label":"Deliver","detail":"Systemic blood ↔ tissues"},{"label":"Use","detail":"Mitochondrial metabolism"}]},"mnemonic":{"title":"VETDU","cue":"Ventilate · Exchange · Transport · Deliver · Use","explanation":"Locate the step before explaining low oxygen delivery."},"goodToKnow":"Most carbon dioxide is transported as bicarbonate after reactions within erythrocytes, not simply dissolved as gas.","act":{"type":"choice","prompt":"What is external respiration?","options":[{"label":"Gas exchange between alveoli and pulmonary capillary blood","correct":true,"feedback":"Correct. It occurs across the respiratory membrane."},{"label":"Air moving through the nose","correct":false,"feedback":"That is ventilation through the conducting zone."},{"label":"Cellular ATP production","correct":false,"feedback":"That is cellular metabolism using delivered oxygen."}]}},{"id":"ventilation-order","title":"Put it in order: Oxygen pathway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Ventilate","detail":"Atmosphere ↔ alveoli"},{"label":"Exchange","detail":"Alveoli ↔ pulmonary blood"},{"label":"Transport","detail":"Pulmonary blood → systemic circulation"},{"label":"Deliver","detail":"Systemic blood ↔ tissues"},{"label":"Use","detail":"Mitochondrial metabolism"}]}},{"id":"ventilation-match","title":"Match it: One quiet breath","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Thorax expands → alveolar pressure falls → air enters","Elastic recoil reduces volume → alveolar pressure rises → air leaves","Narrower airways require a larger pressure difference"],"items":[{"label":"Inspiration","category":0,"feedback":"Inspiration: Thorax expands → alveolar pressure falls → air enters"},{"label":"Expiration","category":1,"feedback":"Expiration: Elastic recoil reduces volume → alveolar pressure rises → air leaves"},{"label":"Resistance","category":2,"feedback":"Resistance: Narrower airways require a larger pressure difference"}]}},{"id":"l17-m7","chapter":"Measure and integrate","chapterSummary":"Use lung volumes as functional measurements and connect respiratory control to homeostasis.","title":"Volumes combine into capacities","highYield":"A volume is one measurable compartment; a capacity is the sum of two or more lung volumes.","teach":["Tidal volume is air moved during a quiet breath. Inspiratory and expiratory reserve volumes describe additional air that can be moved beyond a quiet breath. Residual volume remains after maximal expiration and cannot be measured by simple spirometry.","Vital capacity combines inspiratory reserve, tidal volume, and expiratory reserve. Total lung capacity also includes residual volume. Values vary with body size, age, sex-related anatomy, posture, effort, conditioning, and disease, so a measured result must be compared with appropriate reference values and test quality."],"keyPoints":["Tidal volume is a quiet breath.","Reserve volumes extend beyond tidal breathing.","Residual volume remains after maximal exhalation.","Capacities combine volumes."],"visual":{"title":"Stacked lung volumes","kind":"layers","items":[{"label":"Inspiratory reserve","detail":"Additional volume inhaled above tidal inspiration"},{"label":"Tidal volume","detail":"Quiet breath"},{"label":"Expiratory reserve","detail":"Additional volume exhaled below tidal expiration"},{"label":"Residual volume","detail":"Air remaining after maximal exhalation"}]},"mnemonic":{"title":"VC = IRV + TV + ERV","cue":"Vital uses the three movable volumes","explanation":"Residual volume is not part of vital capacity."},"goodToKnow":"Simple spirometry cannot directly measure residual volume, so it also cannot directly measure capacities that include it.","act":{"type":"choice","prompt":"Which volume remains after the strongest possible exhalation?","options":[{"label":"Residual volume","correct":true,"feedback":"Correct. It helps keep alveoli from emptying completely."},{"label":"Tidal volume","correct":false,"feedback":"Tidal volume is a quiet breath."},{"label":"Inspiratory reserve volume","correct":false,"feedback":"That is additional inhaled volume above a normal inspiration."}]}},{"id":"l17-m8","chapter":null,"chapterSummary":null,"title":"Respiratory control responds strongly to carbon dioxide","highYield":"Brainstem networks adjust ventilation using chemical and mechanical feedback; rising carbon dioxide is a major normal drive.","teach":["Respiratory rhythm is generated by interacting brainstem networks and modified by sensory input. Central chemoreceptors respond indirectly to carbon-dioxide–related changes in cerebrospinal-fluid pH, while peripheral chemoreceptors respond to arterial oxygen, carbon dioxide, and pH.","Exercise increases ventilation through feed-forward motor signals and feedback from working tissues. The respiratory, cardiovascular, renal, and nervous systems cooperate to regulate gases and acid–base conditions. Nutrition supports energy metabolism and respiratory muscle function, but does not replace evaluation of persistent cough or breathlessness."],"keyPoints":["Brainstem networks generate rhythm.","Carbon dioxide/pH strongly influence normal ventilation.","Peripheral chemoreceptors also sense low arterial oxygen.","Respiratory and renal systems coordinate acid–base balance."],"visual":{"title":"Control loop","kind":"flow","items":[{"label":"Change","detail":"CO₂, O₂, pH, movement, emotion"},{"label":"Sensors","detail":"Central/peripheral chemoreceptors and mechanoreceptors"},{"label":"Brainstem","detail":"Integrates and adjusts rhythm"},{"label":"Muscles","detail":"Diaphragm and chest wall change ventilation"},{"label":"Feedback","detail":"Blood gases and pH shift toward need"}]},"mnemonic":{"title":"Sense–Set–Send","cue":"Sensors report · brainstem sets · motor nerves send","explanation":"A short respiratory-control loop."},"goodToKnow":"In chronic respiratory disease, ventilatory control can be altered; simplified statements that oxygen 'turns off breathing' are unsafe.","act":{"type":"choice","prompt":"Which chemical change is a major normal stimulus for increased ventilation?","options":[{"label":"Rising carbon dioxide and associated fall in pH","correct":true,"feedback":"Correct. CO₂-related pH change strongly influences respiratory drive."},{"label":"A small rise in dietary fibre","correct":false,"feedback":"Fibre intake does not directly set the brainstem respiratory rhythm."},{"label":"Lower skin melanin","correct":false,"feedback":"Melanin does not regulate ventilation."}]}},{"id":"capacity-order","title":"Put it in order: Control loop","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Change","detail":"CO₂, O₂, pH, movement, emotion"},{"label":"Sensors","detail":"Central/peripheral chemoreceptors and mechanoreceptors"},{"label":"Brainstem","detail":"Integrates and adjusts rhythm"},{"label":"Muscles","detail":"Diaphragm and chest wall change ventilation"},{"label":"Feedback","detail":"Blood gases and pH shift toward need"}]}},{"id":"capacity-match","title":"Match it: Stacked lung volumes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Additional volume inhaled above tidal inspiration","Quiet breath","Additional volume exhaled below tidal expiration","Air remaining after maximal exhalation"],"items":[{"label":"Residual volume","category":3,"feedback":"Residual volume: Air remaining after maximal exhalation"},{"label":"Expiratory reserve","category":2,"feedback":"Expiratory reserve: Additional volume exhaled below tidal expiration"},{"label":"Tidal volume","category":1,"feedback":"Tidal volume: Quiet breath"},{"label":"Inspiratory reserve","category":0,"feedback":"Inspiratory reserve: Additional volume inhaled above tidal inspiration"}]}}],"flashcards":[{"front":"Conducting zone","back":"Airways that move, warm, humidify, and filter air without direct gas exchange."},{"front":"Mucociliary escalator","back":"Cilia moving mucus and trapped material toward the pharynx."},{"front":"Visceral pleura","back":"Serous membrane covering the lung surface."},{"front":"Type I alveolar cell","back":"Thin epithelial cell forming most of the gas-exchange surface."},{"front":"Type II alveolar cell","back":"Cell that produces pulmonary surfactant."},{"front":"Surfactant","back":"Material that lowers alveolar surface tension and improves stability."},{"front":"Ventilation","back":"Movement of air into and out of lungs."},{"front":"External respiration","back":"Gas exchange between alveoli and pulmonary capillary blood."},{"front":"Internal respiration","back":"Gas exchange between systemic capillary blood and tissues."},{"front":"Tidal volume","back":"Air moved during a quiet breath."},{"front":"Residual volume","back":"Air remaining after maximal exhalation."},{"front":"Vital capacity","back":"Inspiratory reserve + tidal volume + expiratory reserve."}],"quiz":[],"caseStudy":{"title":"Breathlessness after 'just being out of shape'","scenario":"A client reports increasing shortness of breath during ordinary activity, a persistent cough, and new difficulty finishing meals because breathing feels hard. They ask for an energy supplement and assume deconditioning is the only cause.","prompts":["Which steps in VETDU could limit oxygen delivery?","Which symptoms and progression details change the urgency?","What nutrition risks can develop when breathing interferes with meals?","How can nutrition support occur without diagnosing or delaying respiratory assessment?"],"takeaway":"Breathlessness can arise at multiple respiratory, cardiovascular, hematologic, and metabolic steps. Progressive symptoms need clinical assessment; nutrition support can address intake barriers alongside, not instead of, that care."}},{"n":18,"title":"The Urinary System","kicker":"Identify the organs of the urinary system and explain how the kidneys maintain internal balance.","duration":"90–110 minutes","steps":[{"id":"l18-m1","chapter":"Orient to the kidneys","chapterSummary":"Start with the system's homeostatic jobs, then locate the external and internal structures that support them.","title":"The kidneys edit blood, not merely remove waste","highYield":"Kidneys continually adjust what stays in blood and what leaves in urine, supporting volume, composition, pH, endocrine signalling, and waste removal.","teach":["The urinary system includes two kidneys, two ureters, the urinary bladder, and the urethra. The kidneys receive a large blood supply and produce urine; the ureters transport it, the bladder stores it, and the urethra carries it outside. This sequence is simple, but urine formation is selective rather than a passive draining process.","By filtering plasma and then reclaiming or adding selected substances, kidneys regulate water, sodium, potassium, acid–base balance, and many dissolved wastes. They also release renin and erythropoietin and participate in vitamin D activation. The lungs, skin, liver, and intestines also remove particular wastes, yet they cannot replace the full range of kidney functions."],"keyPoints":["Kidneys form urine from filtered blood plasma.","Ureters transport; bladder stores; urethra eliminates.","Kidneys regulate fluid, electrolytes, and acid–base balance.","Renin, erythropoietin, and vitamin D activation are additional renal roles."],"visual":{"title":"Four organs, four main jobs","kind":"flow","items":[{"label":"Kidneys","detail":"Filter and selectively adjust blood; form urine"},{"label":"Ureters","detail":"Move urine by smooth-muscle peristalsis"},{"label":"Bladder","detail":"Stores urine until voiding"},{"label":"Urethra","detail":"Carries urine to the exterior"}]},"mnemonic":{"title":"K-U-B-U","cue":"Kidneys edit · Ureters move · Bladder holds · Urethra exits","explanation":"Use the route to separate urine formation from transport and storage."},"goodToKnow":"Urine colour and volume change with hydration, diet, medicines, temperature, and other factors; neither alone diagnoses kidney function.","act":{"type":"choice","prompt":"Which urinary organ makes urine by selectively processing filtered blood?","options":[{"label":"Kidneys","correct":true,"feedback":"Correct. Nephrons within the kidneys form urine."},{"label":"Ureters","correct":false,"feedback":"Ureters transport urine but do not form it."},{"label":"Urinary bladder","correct":false,"feedback":"The bladder stores urine until voiding."}]}},{"id":"l18-m2","chapter":null,"chapterSummary":null,"title":"Kidney regions create a collecting funnel","highYield":"Cortex and medulla contain nephron structures; pyramids drain through papillae and calyces into the renal pelvis.","teach":["The kidneys lie behind the peritoneal lining on the posterior abdominal wall, with the right usually slightly lower because of the liver. At the medial hilum, the renal artery, renal vein, nerves, lymphatics, and ureter enter or leave. A fibrous renal capsule, cushioning adipose tissue, and renal fascia protect and anchor each kidney.","Internally, the cortex forms the outer region and extends between medullary pyramids as renal columns. Each pyramid ends at a papilla, where collecting ducts empty into a minor calyx. Minor calyces join into major calyces, which feed the renal pelvis and then the ureter. This is the urine route after nephron processing is complete."],"keyPoints":["Kidneys are retroperitoneal.","The hilum is the gateway for vessels, nerves, lymphatics, and ureter.","Cortex surrounds medullary pyramids and extends as columns.","Papilla → minor calyx → major calyx → renal pelvis → ureter."],"visual":{"title":"From kidney tissue to ureter","kind":"sequence","items":[{"label":"Cortex/medulla","detail":"Nephrons and collecting ducts process filtrate"},{"label":"Papilla","detail":"Tip of a medullary pyramid"},{"label":"Minor calyx","detail":"Receives urine from one papillary region"},{"label":"Major calyx","detail":"Collects from minor calyces"},{"label":"Renal pelvis","detail":"Funnel leading to the ureter"}]},"mnemonic":{"title":"Please Make More Renal Urine","cue":"Papilla · Minor calyx · Major calyx · Renal pelvis · Ureter","explanation":"A route cue for urine after it leaves collecting ducts."},"goodToKnow":"The adrenal glands sit near the kidneys but are endocrine organs with distinct functions; their position does not make them part of the urinary tract.","act":{"type":"choice","prompt":"What structure receives urine immediately after a renal papilla?","options":[{"label":"Minor calyx","correct":true,"feedback":"Correct. Papillary ducts drain into a minor calyx."},{"label":"Renal artery","correct":false,"feedback":"The renal artery supplies blood, not urine."},{"label":"Urinary bladder","correct":false,"feedback":"Urine reaches the bladder only after the renal pelvis and ureter."}]}},{"id":"homeostasis-anatomy-order","title":"Put it in order: Four organs, four main jobs","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Kidneys","detail":"Filter and selectively adjust blood; form urine"},{"label":"Ureters","detail":"Move urine by smooth-muscle peristalsis"},{"label":"Bladder","detail":"Stores urine until voiding"},{"label":"Urethra","detail":"Carries urine to the exterior"}]}},{"id":"l18-m3","chapter":"Build the nephron map","chapterSummary":"Connect the renal corpuscle, tubule, collecting system, and two capillary beds before studying transport.","title":"A nephron begins with a filter and continues as a tubule","highYield":"The renal corpuscle filters; the renal tubule modifies; the collecting duct makes final water and solute adjustments.","teach":["A nephron's renal corpuscle consists of a capillary tuft called the glomerulus surrounded by the glomerular capsule. Blood enters through an afferent arteriole and leaves through an efferent arteriole. The filtration barrier separates blood cells and most large proteins from water and smaller dissolved substances that enter capsular space.","Filtrate then passes through the proximal convoluted tubule, descending and ascending limbs of the nephron loop, and distal convoluted tubule. The distal tubule empties into a collecting duct shared by several nephrons. Segment-specific permeability and transport let the kidney recover useful substances, remove additional wastes, and vary the final urine concentration."],"keyPoints":["Renal corpuscle = glomerulus plus glomerular capsule.","Afferent enters; efferent exits.","Tubule route: proximal → loop → distal.","Collecting ducts receive fluid from multiple nephrons."],"visual":{"title":"Nephron route","kind":"flow","items":[{"label":"Glomerulus","detail":"Capillary pressure creates filtrate"},{"label":"Glomerular capsule","detail":"Receives filtered water and small solutes"},{"label":"Proximal tubule","detail":"Bulk reclamation and some secretion"},{"label":"Nephron loop","detail":"Builds medullary gradients"},{"label":"Distal tubule/collecting duct","detail":"Regulated fine-tuning"}]},"mnemonic":{"title":"Filter, Proximal, Loop, Distal, Collect","cue":"F-P-L-D-C","explanation":"Follow filtrate through the nephron without confusing it with blood flow."},"goodToKnow":"The filtrate is not yet urine. Its composition changes substantially as it passes through the tubule and collecting duct.","act":{"type":"choice","prompt":"Which vessel carries blood away from the glomerulus?","options":[{"label":"Efferent arteriole","correct":true,"feedback":"Correct. Think E for exit."},{"label":"Afferent arteriole","correct":false,"feedback":"Afferent blood arrives at the glomerulus."},{"label":"Ureter","correct":false,"feedback":"The ureter carries urine, not blood."}]}},{"id":"l18-m4","chapter":null,"chapterSummary":null,"title":"One arteriole links two capillary networks","highYield":"Glomerular capillaries support filtration; peritubular capillaries and vasa recta support exchange with the tubule.","teach":["Renal blood travels from the renal artery through progressively smaller branches to afferent arterioles and glomerular capillaries. Instead of draining directly into a vein, the glomerulus drains through the efferent arteriole. That vessel then forms peritubular capillaries around cortical tubules and, for deeper nephrons, long vasa recta alongside the nephron loop.","This two-capillary arrangement serves two different tasks. Relatively high pressure in the glomerulus favours filtration, while vessels around the tubule receive reabsorbed water and solutes and deliver substances for secretion. Their proximity also helps preserve the medullary gradient needed to conserve water."],"keyPoints":["Renal artery branches ultimately supply afferent arterioles.","Glomerulus lies between afferent and efferent arterioles.","Peritubular capillaries exchange with cortical tubules.","Vasa recta support deep loops and medullary gradients."],"visual":{"title":"Blood–filtrate partnership","kind":"parallel","items":[{"label":"Blood path","detail":"Afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries/vasa recta → veins"},{"label":"Filtrate path","detail":"Capsule → proximal tubule → loop → distal tubule → collecting duct"},{"label":"Cross-talk","detail":"Reabsorption moves toward blood; secretion moves toward tubule"}]},"mnemonic":{"title":"A-G-E-P","cue":"Afferent · Glomerulus · Efferent · Peritubular","explanation":"The core renal microcirculation sequence."},"goodToKnow":"Juxtamedullary nephrons have long loops extending deep into the medulla and are especially important for producing concentrated urine.","act":{"type":"choice","prompt":"Why is the efferent arteriole unusual in this circulation?","options":[{"label":"It leaves one capillary bed and then forms another","correct":true,"feedback":"Correct. It links glomerular filtration to peritubular exchange."},{"label":"It carries urine into the bladder","correct":false,"feedback":"Arterioles carry blood."},{"label":"It is the only vessel containing red blood cells","correct":false,"feedback":"Red blood cells normally remain throughout the blood vessels."}]}},{"id":"nephron-map-order","title":"Put it in order: Nephron route","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Glomerulus","detail":"Capillary pressure creates filtrate"},{"label":"Glomerular capsule","detail":"Receives filtered water and small solutes"},{"label":"Proximal tubule","detail":"Bulk reclamation and some secretion"},{"label":"Nephron loop","detail":"Builds medullary gradients"},{"label":"Distal tubule/collecting duct","detail":"Regulated fine-tuning"}]}},{"id":"nephron-map-match","title":"Match it: Blood–filtrate partnership","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries/vasa recta → veins","Capsule → proximal tubule → loop → distal tubule → collecting duct","Reabsorption moves toward blood; secretion moves toward tubule"],"items":[{"label":"Blood path","category":0,"feedback":"Blood path: Afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries/vasa recta → veins"},{"label":"Filtrate path","category":1,"feedback":"Filtrate path: Capsule → proximal tubule → loop → distal tubule → collecting duct"},{"label":"Cross-talk","category":2,"feedback":"Cross-talk: Reabsorption moves toward blood; secretion moves toward tubule"}]}},{"id":"l18-m5","chapter":"Transform filtrate into urine","chapterSummary":"Use three directional processes and regulated water handling to explain how kidneys preserve balance.","title":"Filtration, reabsorption, and secretion have different directions","highYield":"Filtration enters the nephron, reabsorption returns to blood, and secretion adds from blood to tubular fluid.","teach":["Glomerular filtration uses blood pressure to move water and small solutes across the filtration barrier into capsular space. Cells and most large plasma proteins normally remain in the circulation. The resulting filtrate contains many useful substances as well as wastes, so filtration alone cannot produce an appropriate final urine.","Tubular reabsorption moves selected substances from tubular fluid through the epithelium and back to blood; most filtered water and solutes are reclaimed. Tubular secretion moves substances from peritubular blood into tubular fluid. Together, the three processes can be summarized as excretion equals filtration minus reabsorption plus secretion."],"keyPoints":["Filtration: blood → capsular space.","Reabsorption: tubule → blood.","Secretion: blood → tubule.","Excretion = filtered − reabsorbed + secreted."],"visual":{"title":"Three renal directions","kind":"equation","items":[{"label":"Filter","detail":"Glomerular blood → capsule"},{"label":"Reabsorb","detail":"Tubular fluid → peritubular blood"},{"label":"Secrete","detail":"Peritubular blood → tubular fluid"},{"label":"Excrete","detail":"What remains and leaves as urine"}]},"mnemonic":{"title":"F in, R return, S supplement","cue":"Filter in · Reabsorb returns · Secrete supplements","explanation":"Anchor each process to the direction relative to the nephron."},"goodToKnow":"A substance can be filtered and then partly reabsorbed, filtered and secreted, or handled differently along multiple nephron segments.","act":{"type":"choice","prompt":"Glucose moves from tubular fluid back into peritubular blood. What process is this?","options":[{"label":"Tubular reabsorption","correct":true,"feedback":"Correct. The substance returns from the tubule to blood."},{"label":"Glomerular filtration","correct":false,"feedback":"Filtration is the initial movement from glomerular blood to capsular space."},{"label":"Tubular secretion","correct":false,"feedback":"Secretion moves from blood into tubular fluid."}]}},{"id":"l18-m6","chapter":null,"chapterSummary":null,"title":"Hormones help match water and sodium output to need","highYield":"ADH primarily changes collecting-duct water permeability; aldosterone promotes sodium reabsorption and potassium secretion in distal segments.","teach":["The proximal tubule performs bulk reabsorption, while the nephron loop establishes a concentration gradient in the medulla. The descending limb is relatively water-permeable; the ascending limb moves salts but is much less permeable to water. This countercurrent organization allows later segments to vary how much water is recovered.","Antidiuretic hormone increases water permeability in the late distal tubule and collecting duct, conserving water when appropriate. Aldosterone supports sodium reabsorption and potassium secretion in distal segments; water may follow retained sodium. Renin-angiotensin-aldosterone signalling, natriuretic peptides, sympathetic input, thirst, and circulation all contribute to fluid and pressure regulation."],"keyPoints":["The nephron loop helps create a medullary gradient.","ADH promotes regulated water reabsorption.","Aldosterone supports sodium retention and potassium secretion.","Renal, endocrine, cardiovascular, and nervous systems coordinate fluid balance."],"visual":{"title":"Segment and signal","kind":"map","items":[{"label":"Proximal tubule","detail":"Bulk recovery of water and many solutes"},{"label":"Nephron loop","detail":"Builds medullary osmotic gradient"},{"label":"ADH","detail":"Raises late-nephron water permeability"},{"label":"Aldosterone","detail":"Promotes distal sodium reabsorption and potassium secretion"}]},"mnemonic":{"title":"ADH adds water doors","cue":"More ADH → more aquaporin-mediated water recovery","explanation":"A functional cue; ADH does not add water to the body, it changes renal retention."},"goodToKnow":"Thirst and urine concentration respond to many signals. A universal water target ignores body size, climate, activity, food moisture, pregnancy, lactation, and medical conditions.","act":{"type":"choice","prompt":"Which hormone most directly increases collecting-duct water permeability?","options":[{"label":"Antidiuretic hormone","correct":true,"feedback":"Correct. ADH promotes insertion of water channels in responsive cells."},{"label":"Erythropoietin","correct":false,"feedback":"Erythropoietin stimulates red-cell production."},{"label":"Insulin","correct":false,"feedback":"Insulin regulates fuel metabolism, not collecting-duct water permeability."}]}},{"id":"urine-formation-match","title":"Match it: Three renal directions","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Glomerular blood → capsule","Tubular fluid → peritubular blood","Peritubular blood → tubular fluid","What remains and leaves as urine"],"items":[{"label":"Excrete","category":3,"feedback":"Excrete: What remains and leaves as urine"},{"label":"Secrete","category":2,"feedback":"Secrete: Peritubular blood → tubular fluid"},{"label":"Reabsorb","category":1,"feedback":"Reabsorb: Tubular fluid → peritubular blood"},{"label":"Filter","category":0,"feedback":"Filter: Glomerular blood → capsule"}]}},{"id":"l18-m7","chapter":"Integrate regulation and elimination","chapterSummary":"Connect acid–base and endocrine roles to urine composition, transport, storage, and safe nutrition practice.","title":"Kidneys share regulation with lungs, blood, bone, and marrow","highYield":"Renal handling of hydrogen and bicarbonate supports pH; renin, erythropoietin, and vitamin D activation link kidneys to other systems.","teach":["Kidneys contribute to acid–base balance by secreting hydrogen ions, reclaiming filtered bicarbonate, and generating new bicarbonate. Their response is slower than respiratory changes but provides sustained control. This partnership explains why ventilation and renal function must be considered together when thinking about blood pH.","Renin participates in a cascade that supports blood-pressure and sodium regulation. Erythropoietin signals red bone marrow to increase red-cell production when renal oxygen sensing indicates need. The kidneys also complete a major activation step for vitamin D, linking renal function to calcium and phosphate balance and therefore to bone physiology."],"keyPoints":["Hydrogen secretion and bicarbonate handling support pH.","Renin participates in pressure and sodium regulation.","Erythropoietin links kidney oxygen sensing to marrow.","Vitamin D activation links kidneys to mineral and bone balance."],"visual":{"title":"Renal system links","kind":"network","items":[{"label":"Lungs","detail":"Rapid carbon-dioxide contribution to acid–base balance"},{"label":"Circulation","detail":"Renin-related pressure and perfusion regulation"},{"label":"Bone marrow","detail":"Erythropoietin supports erythrocyte production"},{"label":"Intestine/bone","detail":"Activated vitamin D supports calcium and phosphate handling"}]},"mnemonic":{"title":"R-E-D-A","cue":"Renin · Erythropoietin · vitamin D Activation · Acid–base","explanation":"Four kidney jobs beyond making urine."},"goodToKnow":"Renal disease can affect hemoglobin, minerals, and acid–base status; these are systemic effects, not separate coincidences.","act":{"type":"choice","prompt":"Which renal product stimulates red bone marrow to make more erythrocytes?","options":[{"label":"Erythropoietin","correct":true,"feedback":"Correct. It is produced largely by specialized cells in the kidney."},{"label":"Bile","correct":false,"feedback":"Bile is produced by the liver and supports lipid digestion."},{"label":"Surfactant","correct":false,"feedback":"Pulmonary surfactant is produced in the lungs."}]}},{"id":"l18-m8","chapter":null,"chapterSummary":null,"title":"Urine is propelled, stored, and released by coordinated muscle","highYield":"Ureteral peristalsis moves urine; bladder stretch initiates a spinal reflex; voluntary control acts mainly through the external urethral sphincter.","teach":["Urine moves from each renal pelvis through a ureter, propelled mainly by smooth-muscle peristalsis rather than gravity alone. Transitional epithelium lets the ureters and bladder stretch. The bladder's detrusor muscle expands during filling, while its trigone is defined by the two ureter openings and the urethral outlet.","As bladder stretch rises, sensory signals reach the spinal cord and higher centres. The micturition reflex contracts the detrusor and relaxes the involuntary internal sphincter, while learned control of the skeletal external sphincter helps delay or permit voiding. The urethra is shorter in typical female anatomy and longer in typical male anatomy, where it also serves the reproductive tract at different times."],"keyPoints":["Ureteral peristalsis moves urine to the bladder.","Transitional epithelium accommodates stretching.","Detrusor contraction supports voiding.","Internal sphincter is involuntary; external sphincter has voluntary control."],"visual":{"title":"Urine exit route","kind":"sequence","items":[{"label":"Renal pelvis","detail":"Collects urine from calyces"},{"label":"Ureter","detail":"Peristaltic transport"},{"label":"Bladder","detail":"Storage and stretch sensing"},{"label":"Sphincters","detail":"Coordinate continence and voiding"},{"label":"Urethra","detail":"Final path to the exterior"}]},"mnemonic":{"title":"Pelvis–Pipe–Pouch–Passage","cue":"Renal pelvis · ureter · bladder · urethra","explanation":"A plain-language route from kidney to exterior."},"goodToKnow":"Frequent urination can reflect fluid timing, caffeine, medicines, pregnancy, sleep patterns, infection, metabolic changes, and more; frequency alone does not identify the cause.","act":{"type":"choice","prompt":"Which muscle forms the main contractile wall of the bladder?","options":[{"label":"Detrusor muscle","correct":true,"feedback":"Correct. Its smooth-muscle layers contract during voiding."},{"label":"Diaphragm","correct":false,"feedback":"The diaphragm is the main inspiratory muscle."},{"label":"Myocardium","correct":false,"feedback":"Myocardium is cardiac muscle."}]}},{"id":"integration-elimination-order","title":"Put it in order: Urine exit route","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Renal pelvis","detail":"Collects urine from calyces"},{"label":"Ureter","detail":"Peristaltic transport"},{"label":"Bladder","detail":"Storage and stretch sensing"},{"label":"Sphincters","detail":"Coordinate continence and voiding"},{"label":"Urethra","detail":"Final path to the exterior"}]}},{"id":"integration-elimination-match","title":"Match it: Renal system links","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Rapid carbon-dioxide contribution to acid–base balance","Renin-related pressure and perfusion regulation","Erythropoietin supports erythrocyte production","Activated vitamin D supports calcium and phosphate handling"],"items":[{"label":"Intestine/bone","category":3,"feedback":"Intestine/bone: Activated vitamin D supports calcium and phosphate handling"},{"label":"Bone marrow","category":2,"feedback":"Bone marrow: Erythropoietin supports erythrocyte production"},{"label":"Circulation","category":1,"feedback":"Circulation: Renin-related pressure and perfusion regulation"},{"label":"Lungs","category":0,"feedback":"Lungs: Rapid carbon-dioxide contribution to acid–base balance"}]}}],"flashcards":[{"front":"Urinary system organs","back":"Two kidneys, two ureters, urinary bladder, and urethra."},{"front":"Hilum","back":"Medial kidney gateway where vessels, nerves, lymphatics, and ureter enter or leave."},{"front":"Renal cortex","back":"Outer kidney region containing renal corpuscles and portions of tubules."},{"front":"Renal medulla","back":"Inner region organized into pyramids containing loops and collecting ducts."},{"front":"Renal corpuscle","back":"Glomerulus plus glomerular capsule; site where filtrate first forms."},{"front":"Afferent arteriole","back":"Vessel carrying blood into the glomerulus."},{"front":"Tubular reabsorption","back":"Movement of substances from tubular fluid back to blood."},{"front":"Tubular secretion","back":"Movement of substances from peritubular blood into tubular fluid."},{"front":"ADH","back":"Hormone that increases regulated water permeability in the late nephron."},{"front":"Erythropoietin","back":"Renal hormone that stimulates erythrocyte production in red bone marrow."},{"front":"Detrusor muscle","back":"Smooth muscle in the bladder wall that contracts during voiding."},{"front":"Micturition","back":"Coordinated process of emptying the urinary bladder."}],"quiz":[],"caseStudy":{"title":"A hydration shortcut that ignores the whole picture","scenario":"A client has started forcing several extra litres of water daily after seeing a fixed online target. They now wake repeatedly to urinate and feel light-headed at times. They also mention a recent change in medication and assume that completely clear urine always proves ideal hydration.","prompts":["Which kidney and bladder processes explain the change in urine volume and frequency?","What information about body size, activity, climate, diet, medicines, health conditions, thirst, and symptoms is missing?","Why is urine colour an imperfect standalone hydration measure?","Which symptoms or medication concerns should be referred rather than managed through a generic fluid prescription?"],"takeaway":"Fluid needs are contextual, and the kidneys continuously adjust water output. Support practical observation and clinical coordination instead of treating one intake number or urine colour as a universal target."}},{"n":19,"title":"The Reproductive System","kicker":"Map the major male and female reproductive organs and explain how structure supports each organ's role.","duration":"75–95 minutes","steps":[{"id":"l19-m1","chapter":"Male reproductive organization","chapterSummary":"Follow sperm production from the testis through maturation, transport, and seminal-fluid formation.","title":"The testes have paired exocrine and endocrine jobs","highYield":"Seminiferous tubules make sperm, while interstitial cells between the tubules make testosterone.","teach":["Each testis is wrapped by a fibrous capsule that sends partitions inward, forming lobules. Inside those lobules, tightly coiled seminiferous tubules provide the site of sperm formation. The scrotum holds the testes outside the pelvic cavity, where muscular adjustments help maintain a temperature suited to sperm production.","Two cell populations clarify the testis's dual role. Developing germ cells and their supporting Sertoli cells occupy the tubules, while interstitial Leydig cells lie in the tissue between tubules and secrete testosterone. The organ therefore sends sperm through ducts and hormones into blood."],"keyPoints":["Tunica albuginea and internal septa organize the testis into lobules.","Spermatogenesis occurs in seminiferous tubules.","Sertoli cells support developing sperm cells.","Leydig cells secrete testosterone into the circulation."],"visual":{"title":"Inside a testis","kind":"layers","items":[{"label":"Capsule","detail":"Tunica albuginea forms a durable outer coat."},{"label":"Lobules","detail":"Septa divide the organ into compartments."},{"label":"Tubules","detail":"Seminiferous tubules contain developing sperm and Sertoli cells."},{"label":"Between tubules","detail":"Leydig cells produce testosterone."}]},"mnemonic":{"title":"S inside, L between","cue":"Sertoli supports sperm in Seminiferous tubules; Leydig lies between Loops.","explanation":"The repeated initials anchor the location and role of the two important support cells."},"goodToKnow":"The testes are both exocrine and endocrine: sperm travel through ducts, whereas testosterone enters the bloodstream.","act":{"type":"choice","prompt":"Which pairing correctly identifies a testicular cell and its main role?","options":[{"label":"Leydig cell — testosterone secretion","correct":true,"feedback":"Correct. Leydig cells are interstitial endocrine cells."},{"label":"Sertoli cell — carrying urine to the bladder","correct":false,"feedback":"Sertoli cells support developing sperm within seminiferous tubules."},{"label":"Spermatogonium — producing seminal-vesicle fluid","correct":false,"feedback":"A spermatogonium is an early germ cell, not an accessory gland."}]}},{"id":"l19-m2","chapter":null,"chapterSummary":null,"title":"Spermatogenesis reduces chromosome number, then reshapes the cell","highYield":"Mitosis preserves the germ-cell line; meiosis produces haploid spermatids; maturation creates a streamlined sperm cell.","teach":["Spermatogonia near the outer wall of a seminiferous tubule divide by mitosis. Some remain as a renewing cell population, while others become primary spermatocytes. A primary spermatocyte completes meiosis I to form two secondary spermatocytes, and meiosis II produces four haploid spermatids.","Spermatids are not yet fully shaped sperm. During maturation, the nucleus becomes compact, an enzyme-containing acrosome forms over the head, mitochondria concentrate in the midpiece, and a flagellum develops for movement. This is a change in form and function after the chromosome-reduction divisions."],"keyPoints":["Mitosis replenishes spermatogonia and supplies cells for development.","Meiosis I and II reduce a diploid primary spermatocyte to haploid spermatids.","One primary spermatocyte can yield four spermatids.","Head, midpiece, and tail are specialized for genetic delivery, energy, and movement."],"visual":{"title":"From germ cell to sperm","kind":"flow","items":[{"label":"Spermatogonium","detail":"Diploid stem-line cell; divides by mitosis."},{"label":"Primary spermatocyte","detail":"Enters the first meiotic division."},{"label":"Secondary spermatocytes","detail":"Haploid products of meiosis I."},{"label":"Spermatids","detail":"Four products after meiosis II."},{"label":"Spermatozoa","detail":"Mature form with head, midpiece, and tail."}]},"mnemonic":{"title":"Grow, halve, halve, shape","cue":"Mitosis grows the line; meiosis halves twice; maturation shapes.","explanation":"This separates cell-number maintenance, chromosome reduction, and structural specialization."},"goodToKnow":"A mature sperm cell's midpiece is rich in mitochondria, but the cell's purpose is transport of paternal genetic material rather than general nutrient storage.","act":{"type":"choice","prompt":"What is produced directly by meiosis II during spermatogenesis?","options":[{"label":"Haploid spermatids","correct":true,"feedback":"Correct. Secondary spermatocytes complete meiosis II to form spermatids."},{"label":"Diploid spermatogonia","correct":false,"feedback":"Spermatogonia are maintained through mitosis."},{"label":"Seminal fluid","correct":false,"feedback":"Accessory glands contribute most seminal fluid."}]}},{"id":"l19-mod1-order","title":"Put it in order: From germ cell to sperm","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Spermatogonium","detail":"Diploid stem-line cell; divides by mitosis."},{"label":"Primary spermatocyte","detail":"Enters the first meiotic division."},{"label":"Secondary spermatocytes","detail":"Haploid products of meiosis I."},{"label":"Spermatids","detail":"Four products after meiosis II."},{"label":"Spermatozoa","detail":"Mature form with head, midpiece, and tail."}]}},{"id":"l19-mod1-match","title":"Match it: Inside a testis","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Tunica albuginea forms a durable outer coat.","Septa divide the organ into compartments.","Seminiferous tubules contain developing sperm and Sertoli cells.","Leydig cells produce testosterone."],"items":[{"label":"Between tubules","category":3,"feedback":"Between tubules: Leydig cells produce testosterone."},{"label":"Tubules","category":2,"feedback":"Tubules: Seminiferous tubules contain developing sperm and Sertoli cells."},{"label":"Lobules","category":1,"feedback":"Lobules: Septa divide the organ into compartments."},{"label":"Capsule","category":0,"feedback":"Capsule: Tunica albuginea forms a durable outer coat."}]}},{"id":"l19-m3","chapter":"Male transport and seminal fluid","chapterSummary":"Trace sperm through the ducts and identify how accessory glands assemble the transport medium.","title":"Sperm follow a continuous transport route","highYield":"Seminiferous tubules → straight tubules → rete testis → efferent ductules → epididymis → ductus deferens → ejaculatory duct → urethra.","teach":["Newly formed sperm leave the convoluted seminiferous tubules, pass into straight tubules, cross the rete testis, and exit through efferent ductules. They then enter the epididymis, whose long coiled duct supports further maturation and storage while sperm gain motility.","During ejaculation, smooth-muscle contractions propel sperm into the ductus deferens, through an ejaculatory duct, and then into the urethra. The male urethra has prostatic, membranous, and spongy regions. Route questions become much easier when each segment is linked to its landmark."],"keyPoints":["The epididymis is a maturation and storage site, not the production site.","The ductus deferens carries sperm from the epididymis toward the pelvic cavity.","Ejaculatory ducts empty into the prostatic urethra.","The urethra provides the final passage to the exterior."],"visual":{"title":"Sperm route map","kind":"route","items":[{"label":"Produce","detail":"Seminiferous tubules."},{"label":"Collect","detail":"Straight tubules, rete testis, efferent ductules."},{"label":"Mature","detail":"Epididymis."},{"label":"Transport","detail":"Ductus deferens and ejaculatory duct."},{"label":"Exit","detail":"Prostatic → membranous → spongy urethra."}]},"mnemonic":{"title":"Sperm Take Roads, Exit, Drive, Enter, Use","cue":"Seminiferous → straight → rete → efferent → ductus epididymis → ductus deferens → ejaculatory → urethra.","explanation":"The phrase cues the major route in order; add details only after the sequence is secure."},"goodToKnow":"After a vasectomy, sperm production and testosterone secretion can continue; the procedure interrupts the ductus deferens rather than removing the testes.","act":{"type":"choice","prompt":"Where do sperm normally mature and develop motility after leaving the testis?","options":[{"label":"Epididymis","correct":true,"feedback":"Correct. The coiled epididymal duct supports maturation and storage."},{"label":"Seminal vesicle","correct":false,"feedback":"The seminal vesicle adds fluid but is not a sperm-maturation site."},{"label":"Urinary bladder","correct":false,"feedback":"The bladder stores urine, not sperm."}]}},{"id":"l19-m4","chapter":null,"chapterSummary":null,"title":"Accessory glands build the transport medium","highYield":"Semen combines sperm with secretions from seminal vesicles, prostate, and bulbourethral glands.","teach":["Sperm make up only part of semen. Seminal vesicles contribute much of the fluid and include fructose that can support sperm movement. The prostate adds fluid around the first portion of the urethra, and bulbourethral glands add a mucus-like secretion that lubricates the urethral passage.","Together, these secretions provide a liquid transport medium and help buffer conditions encountered during passage. This is a useful structure–function example: glands placed along the route add components before the mixture leaves through the urethra."],"keyPoints":["Semen is sperm plus accessory-gland secretions.","Seminal-vesicle fluid contributes energy substrate and volume.","Prostatic fluid joins the ejaculatory-duct contents in the prostatic urethra.","Bulbourethral secretion lubricates the urethra before ejaculation."],"visual":{"title":"What enters semen?","kind":"contributions","items":[{"label":"Testes/epididymides","detail":"Sperm cells."},{"label":"Seminal vesicles","detail":"Large fluid contribution with fructose."},{"label":"Prostate","detail":"Additional glandular fluid around the urethral route."},{"label":"Bulbourethral glands","detail":"Lubricating mucus-like secretion."}]},"mnemonic":{"title":"Cells plus three secretions","cue":"Sperm + seminal vesicle + prostate + bulbourethral.","explanation":"Think of semen as a mixture assembled along a route, not a product made in one organ."},"goodToKnow":"Fructose in seminal fluid is a local energy substrate for sperm movement; it does not mean that eating more sugar predictably improves fertility.","act":{"type":"choice","prompt":"Which statement best describes semen?","options":[{"label":"A mixture of sperm and several accessory-gland secretions","correct":true,"feedback":"Correct. Multiple structures contribute to the final fluid."},{"label":"A hormone made only by Leydig cells","correct":false,"feedback":"Leydig cells make testosterone, not semen."},{"label":"Fluid stored in the urinary bladder","correct":false,"feedback":"The urinary bladder stores urine."}]}},{"id":"l19-mod2-order","title":"Put it in order: Sperm route map","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Produce","detail":"Seminiferous tubules."},{"label":"Collect","detail":"Straight tubules, rete testis, efferent ductules."},{"label":"Mature","detail":"Epididymis."},{"label":"Transport","detail":"Ductus deferens and ejaculatory duct."},{"label":"Exit","detail":"Prostatic → membranous → spongy urethra."}]}},{"id":"l19-mod2-match","title":"Match it: What enters semen?","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Sperm cells.","Large fluid contribution with fructose.","Additional glandular fluid around the urethral route.","Lubricating mucus-like secretion."],"items":[{"label":"Bulbourethral glands","category":3,"feedback":"Bulbourethral glands: Lubricating mucus-like secretion."},{"label":"Prostate","category":2,"feedback":"Prostate: Additional glandular fluid around the urethral route."},{"label":"Seminal vesicles","category":1,"feedback":"Seminal vesicles: Large fluid contribution with fructose."},{"label":"Testes/epididymides","category":0,"feedback":"Testes/epididymides: Sperm cells."}]}},{"id":"l19-m5","chapter":"Female reproductive organization and cycles","chapterSummary":"Connect ovarian events, oocyte development, uterine anatomy, and endometrial change across a cycle.","title":"Oogenesis produces one large functional cell","highYield":"Unequal meiotic divisions preserve cytoplasm in one oocyte while small polar bodies receive little cytoplasm.","teach":["Oogonia form primary oocytes before birth, and those primary oocytes remain arrested until later reproductive cycles. When a selected oocyte resumes meiosis, the first division produces a large secondary oocyte and a small polar body rather than two equal cells.","The secondary oocyte is released at ovulation. In the usual sequence, meiosis II completes only if fertilization occurs, producing an ovum and another polar body. The unequal allocation retains organelles and cytoplasm in the cell that could support the first divisions after fertilization."],"keyPoints":["Primary oocytes form before birth and later resume development.","Meiosis I yields a secondary oocyte plus a polar body.","The secondary oocyte is the cell released at ovulation.","Meiosis II usually completes in association with fertilization."],"visual":{"title":"Unequal meiotic divisions","kind":"flow","items":[{"label":"Oogonium","detail":"Diploid precursor in fetal development."},{"label":"Primary oocyte","detail":"Begins meiosis and remains arrested."},{"label":"Secondary oocyte + polar body","detail":"Unequal products of meiosis I."},{"label":"Ovum + polar bodies","detail":"Completion of meiosis II if fertilization occurs."}]},"mnemonic":{"title":"One keeps the kitchen","cue":"One oocyte keeps most cytoplasm; polar bodies carry chromosomes with little cytoplasm.","explanation":"The image explains why the divisions are genetically ordered but physically unequal."},"goodToKnow":"Oogenesis and spermatogenesis both use meiosis, but they differ in timing, equality of cell division, and the number of functional gametes produced.","act":{"type":"choice","prompt":"Why is a secondary oocyte much larger than its polar body?","options":[{"label":"Meiosis divides chromosomes but allocates most cytoplasm to the oocyte","correct":true,"feedback":"Correct. The divisions are unequal in cytoplasmic volume."},{"label":"The polar body contains twice as many chromosomes","correct":false,"feedback":"Both products are haploid after meiosis I; size reflects cytoplasmic allocation."},{"label":"The oocyte has already implanted","correct":false,"feedback":"Implantation occurs after fertilization and early cell divisions."}]}},{"id":"l19-m6","chapter":null,"chapterSummary":null,"title":"The ovarian and uterine cycles are synchronized","highYield":"Follicle growth and ovulation in the ovary align with menstrual, proliferative, and secretory changes in the endometrium.","teach":["During the follicular portion of the ovarian cycle, follicles develop and one usually becomes dominant. Rising estrogen is associated with repair and growth of the uterine endometrium. Ovulation releases the secondary oocyte, which is guided toward a uterine tube by the fimbriae and ciliary movement.","After ovulation, the emptied follicle becomes the corpus luteum and secretes progesterone as well as estrogen. These hormones support a secretory endometrium prepared for possible implantation. If implantation does not occur, the corpus luteum regresses, hormone support falls, and another menstrual phase begins."],"keyPoints":["Menstrual phase sheds the functional endometrial lining.","Proliferative phase rebuilds the lining as a follicle matures.","Ovulation separates the preovulatory and postovulatory portions of the cycle.","Secretory phase is supported by corpus-luteum hormones.","Cycle length and timing vary among individuals and across life stages."],"visual":{"title":"Two cycles, one timeline","kind":"timeline","items":[{"label":"Menstrual / early follicular","detail":"Endometrium sheds while follicles begin developing."},{"label":"Proliferative / follicular","detail":"Estrogen rises and the lining rebuilds."},{"label":"Ovulation","detail":"Secondary oocyte leaves the mature follicle."},{"label":"Secretory / luteal","detail":"Corpus luteum hormones support a receptive lining."},{"label":"No implantation","detail":"Corpus luteum regresses and the cycle resets."}]},"mnemonic":{"title":"Shed, spread, secrete","cue":"Menstrual sheds · proliferative spreads new lining · secretory enriches it.","explanation":"This anchors the three uterine phases without assuming an identical day count for everyone."},"goodToKnow":"The textbook's day numbers are a teaching model; real cycles vary. Phase relationships are more reliable than memorizing one universal calendar.","act":{"type":"choice","prompt":"Which ovarian structure chiefly supports the postovulatory secretory phase?","options":[{"label":"Corpus luteum","correct":true,"feedback":"Correct. It secretes progesterone and estrogen after ovulation."},{"label":"Fimbria","correct":false,"feedback":"Fimbriae help guide the oocyte toward the uterine tube."},{"label":"Polar body","correct":false,"feedback":"A polar body is a small meiotic product, not a hormone-secreting ovarian structure."}]}},{"id":"l19-mod3-order","title":"Put it in order: Unequal meiotic divisions","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Oogonium","detail":"Diploid precursor in fetal development."},{"label":"Primary oocyte","detail":"Begins meiosis and remains arrested."},{"label":"Secondary oocyte + polar body","detail":"Unequal products of meiosis I."},{"label":"Ovum + polar bodies","detail":"Completion of meiosis II if fertilization occurs."}]}},{"id":"l19-m7","chapter":"Fertilization, development, birth, and lactation","chapterSummary":"Follow the biological sequence from gamete union through implantation, placental exchange, labor, and milk delivery.","title":"Fertilization starts a sequence of transport and implantation","highYield":"Fertilization usually occurs in a uterine tube; the dividing conceptus reaches the uterus and implants in the endometrium.","teach":["The uterine tubes receive the ovulated secondary oocyte through the infundibulum and fimbriae. Cilia and smooth-muscle contractions move it toward the uterus. When fertilization occurs, sperm and oocyte genetic material combine to restore the diploid chromosome number in the zygote.","The zygote undergoes repeated mitotic divisions while traveling toward the uterine cavity, developing into a blastocyst. Its outer cells participate in implantation and formation of chorionic villi, while the inner cell mass gives rise to the embryo. Ectoderm, mesoderm, and endoderm then provide the foundational tissue layers."],"keyPoints":["Fertilization most often occurs in the uterine tube, not the uterus.","A zygote divides by mitosis while moving toward the uterine cavity.","Implantation occurs in the endometrium.","The inner cell mass forms the embryo; trophoblast-related tissues support implantation and placenta formation.","Three germ layers give rise to the body's tissues and organs."],"visual":{"title":"Early development route","kind":"route","items":[{"label":"Ovulation","detail":"Secondary oocyte enters the vicinity of a uterine tube."},{"label":"Fertilization","detail":"Gametes unite in the tube and form a zygote."},{"label":"Cleavage","detail":"Mitotic divisions occur during transport."},{"label":"Blastocyst","detail":"Outer support cells and an inner cell mass become distinct."},{"label":"Implantation","detail":"The conceptus embeds in uterine endometrium."}]},"mnemonic":{"title":"Tube, travel, touch down","cue":"Fertilize in the tube · divide while traveling · implant in the uterus.","explanation":"The phrase distinguishes the usual sites of fertilization, early transport, and implantation."},"goodToKnow":"Placental and maternal blood normally remain in separate circulations; exchange occurs across a thin interface rather than by directly mixing the two blood supplies.","act":{"type":"choice","prompt":"Which sequence is anatomically correct?","options":[{"label":"Fertilization in uterine tube → mitotic divisions → implantation in endometrium","correct":true,"feedback":"Correct. The early conceptus divides while moving to the uterus."},{"label":"Implantation in ovary → fertilization in cervix → cleavage in vagina","correct":false,"feedback":"Those locations reverse the normal pathway."},{"label":"Fertilization in bladder → implantation in ureter","correct":false,"feedback":"Those are urinary, not reproductive, structures."}]}},{"id":"l19-m8","chapter":null,"chapterSummary":null,"title":"Placenta, labor, and mammary glands support the transition to birth","highYield":"The placenta supports exchange during pregnancy; labor progresses through dilation, expulsion, and placental stages; mammary lobules produce milk.","teach":["Chorionic villi and uterine tissue contribute to the placenta, which supports exchange of oxygen, nutrients, and wastes between maternal and fetal circulations. The amnion surrounds the developing embryo or fetus with fluid, and the umbilical cord links fetal circulation to the placenta. These are coordinated support structures, not interchangeable names for one organ.","Labor is commonly organized into cervical dilation, expulsion of the baby, and delivery of the placenta. After birth, milk is produced by secretory alveoli grouped within mammary lobules. Milk moves through branching ducts toward widened regions and then through lactiferous ducts that open at the nipple."],"keyPoints":["The placenta is an exchange and endocrine interface during pregnancy.","The amnion encloses the developing fetus in fluid.","The umbilical cord connects fetal vessels to the placenta.","Labor progresses through dilation, expulsion, and placental stages.","Mammary alveoli make milk; ducts carry it toward the nipple."],"visual":{"title":"Support before and after birth","kind":"paired-flow","items":[{"label":"Pregnancy","detail":"Placenta exchanges; amnion cushions; cord connects."},{"label":"Dilation","detail":"Cervix opens as uterine contractions progress."},{"label":"Expulsion","detail":"Baby passes through the birth canal."},{"label":"Placental stage","detail":"Placenta separates and is delivered."},{"label":"Lactation","detail":"Alveoli produce milk and ducts convey it outward."}]},"mnemonic":{"title":"Open, out, after","cue":"Dilation opens · expulsion moves baby out · placental stage delivers afterbirth.","explanation":"A three-word cue for the major stages of labor."},"goodToKnow":"The mammary glands are organized into lobes, lobules, secretory alveoli, and ducts. Breast size mostly reflects adipose tissue and does not by itself indicate milk-making capacity.","act":{"type":"choice","prompt":"Where is milk produced within a lactating mammary gland?","options":[{"label":"Secretory alveoli in lobules","correct":true,"feedback":"Correct. Alveolar cells produce milk, which then enters the duct system."},{"label":"Placental villi","correct":false,"feedback":"Placental villi support exchange during pregnancy, not milk production."},{"label":"Uterine endometrium","correct":false,"feedback":"The endometrium lines the uterus and supports implantation."}]}},{"id":"l19-mod4-order","title":"Put it in order: Early development route","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Ovulation","detail":"Secondary oocyte enters the vicinity of a uterine tube."},{"label":"Fertilization","detail":"Gametes unite in the tube and form a zygote."},{"label":"Cleavage","detail":"Mitotic divisions occur during transport."},{"label":"Blastocyst","detail":"Outer support cells and an inner cell mass become distinct."},{"label":"Implantation","detail":"The conceptus embeds in uterine endometrium."}]}}],"flashcards":[{"front":"Seminiferous tubule","back":"Coiled testicular tubule where spermatogenesis occurs."},{"front":"Sertoli cell","back":"Support cell within seminiferous tubules that nourishes and regulates developing sperm."},{"front":"Leydig cell","back":"Interstitial testicular cell that secretes testosterone."},{"front":"Epididymis","back":"Coiled duct where sperm mature, gain motility, and are stored."},{"front":"Sperm route","back":"Seminiferous tubules → straight tubules → rete testis → efferent ductules → epididymis → ductus deferens → ejaculatory duct → urethra."},{"front":"Semen","back":"Sperm combined with secretions from the seminal vesicles, prostate, and bulbourethral glands."},{"front":"Oogenesis","back":"Formation and maturation of the female gamete through unequal meiotic divisions."},{"front":"Ovulation","back":"Release of a secondary oocyte from a mature ovarian follicle."},{"front":"Corpus luteum","back":"Postovulatory ovarian structure that secretes progesterone and estrogen."},{"front":"Endometrium","back":"Inner uterine layer that changes across the cycle and receives an implanting conceptus."},{"front":"Blastocyst","back":"Early hollow-stage conceptus with an outer trophoblast and inner cell mass."},{"front":"Placenta","back":"Temporary maternal–fetal interface for exchange and hormone production during pregnancy."},{"front":"Three labor stages","back":"Dilation, expulsion, and placental stages."},{"front":"Mammary alveoli","back":"Secretory structures in lobules that produce milk."}],"quiz":[],"caseStudy":{"title":"A cycle change is not a one-nutrient diagnosis","scenario":"A physically active client reports that menstrual cycles have become less regular while training volume increased and meals became more restrictive. They ask for one supplement to restore fertility immediately and want reassurance that no medical assessment is needed.","prompts":["Which ovarian and uterine events must coordinate for a typical cycle?","What intake, training, stress, medication, reproductive, and health-history questions are relevant without assuming a cause?","Why would one supplement be unable to guarantee ovulation, implantation, or fertility?","Which scope and referral language would support the client without diagnosing them?"],"takeaway":"Cycle changes can reflect many interacting reproductive, endocrine, energy-availability, medication, stress, and health factors. A nutrition professional can assess intake patterns and support adequacy while recommending timely clinical evaluation rather than assigning a cause or promising a fertility outcome."}}]};
